\begin{example}[Baumann-Spanring \cite{BS-unrestricted}]
The example in Figure \ref{BS-example} illustrates an AF $\F$ for which the notion of a $\cft$ or $\stgt$ extension is \emph{not} well-defined. For concreteness, we consider the case of  $\cft$ (the case of $\stgt$ is analogous). Observe that $\F$ consists of two strongly connected components: $\{b_1\}$ and $A_\F \smallsetminus \{b_1\}$. Now, let $B=\{b_i : i\in \nat\}$. By definition,  
    \[    B\in \cft \Leftrightarrow B\smallsetminus \{b_1\}\in \cf2(\F\restriction_{A_\F\smallsetminus \{b_1,a_1\}}).  
    \]
    The restricted framework $\F\restriction_{A_\F\smallsetminus \{b_1,a_1\}}$ again contains only two strongly connected components, one of which is the singleton $\{b_2\}$.
    Iterating this process, we repeatedly remove pairs $b_i$ and $a_i$ from the frameworks.  However, we never reach a stage where only a single strongly connected component remains. As a result, the recursion underlying the definition of $\cft$ does not terminate, and such a semantics is not well-defined for $\F$.
\end{example}



\section{SCC-recursiveness in the infinite setting}\label{sec:defining semantics}
In this section, we propose two novel approaches to extending the concept of SCC-recursive semantics to the infinite setting. The first approach relaxes the requirement that the recursion must terminate after finitely many steps, instead allowing the process to continue transfinitely along the ordinals.

\subsection{Use transfinite recursion}
We begin by inductively defining the strongly connected component of an element $a\in A_\F$ at  ordinal stages.

\begin{definition}
    Let $\F$ be an AF and let $S\subseteq A_\F$. For $a\in A_\F$ and all ordinals $\alpha$, define $C_S^\alpha(a)$ inductively as follows: 
    \begin{itemize}
        \item   $C_S^0(a)=\SCC(a)$;
        \item $C_S^{\alpha+1}(a)$ is the strongly connected component of $a$ in $C_S^\alpha(a)\smallsetminus D_S(C_S^\alpha(a))$;
        \item finally, for limit ordinals $\lambda$, $C_S^\lambda(a)$ is the strongly connected component of $a$ in $\bigcap_{\alpha<\lambda}C_S^\alpha(a)$.
    \end{itemize}   
        For $a\in A_\F$ and $S\subseteq A_\F$, we let the \emph{\compordinal} of $a$ over $S$, written $\alpha_S(a)$,  be the least $\alpha$ so that either $a\notin C_S^\alpha(a)$ or $C_S^{\alpha+1}(a)=C_S^\alpha(a)$.
\end{definition}

We are now ready to define the semantics that extend $\cft$ and 
$\stgt$ transfinitely; we denote these by 
$\icft$ and $\istgt$, respectively.


\begin{definition}\label{def:icft}\label{def:istgt}
Let $\F=(A_\F,R_\F)$ and let $S\in \cf(\F)$. Then, 

\begin{itemize}
    \item $S\in\icft(\F)$ iff, for each $a\in \F$, either $a\notin C_S^{\alpha_S(a)}(a)$ or $S\cap C_S^{\alpha_S(a)}(a)$ is a naive extension of $\F\restriction_{C_S^{\alpha_S(a)}(a)}$;
    \item $S\in \istgt(\F)$ iff, for each $a\in \F$, either $a\notin C_S^{\alpha_S(a)}(a)$ or $S\cap C_S^{\alpha_S(a)}(a)$ is a stage extension of $\F\restriction_{C_S^{\alpha_S(a)}(a)}$.
\end{itemize}
    %$S$ is an \icft extension in $\F$ if $S$ is conflict-free and for each $a\in \F$ either $a\notin C_S^{\alpha_S(a)}(a)$ or $S\cap C_S^{\alpha_S(a)}(a)$ is a naive extension of $C_S^{\alpha_S(a)}(a)$.
\end{definition}

%\begin{definition}\label{def:istgt}
    %We say that $S$ is an \istgt extension in $\F$ if $S$ is conflict-free and for each $a\in \F$ either $a\notin C_S^{\alpha_S(a)}(a)$ or $S\cap C_S^{\alpha_S(a)}(a)$ is a stage extension of $C_S^{\alpha_S(a)}(a)$.
%\end{definition}


\begin{remark}
Following the same pattern but using the semantics $\sigma$ instead of naive or stage, one may define, for any base semantics $\sigma$, a new semantics \textit{tf$\sigma$2} which transfinitely extends the SCC-recursive semantics $\sigma2$. However, in this paper we restrict our attention to the specific cases of $\icft$ and $\istgt$.\footnote{We note with this general definition, \icft should be called \textit{tfna2}, but we choose to follow the standard terminology from the finite setting.}
\end{remark}

