\section{Properties of these semantics}\label{sec:properties}
To clarify the relative advantages of the semantics under consideration, we adopt the following naive-based evaluation criteria introduced by Baroni and Giacomin \cite{BaroniGiacomin}: %We also add a some criteria focusing on finitary AFs that capture some distinctions in these semantics.

\begin{definition}
A semantics $\sigma$ satisfies:
\begin{itemize}
    \item \textbf{I-maximality criterion} if, for each AF $\F$ and for each $S_1, S_2 \in \sigma(\F)$, $S_1 \subseteq S_2$ implies $S_1 = S_2$;
    \item \textbf{Reinstatement criterion} if, for each AF  $\F$ and for each $S \in \sigma(\F)$, if $S$ defends some argument $a$, then $a \in S$;
    \item \textbf{Weak reinstatement criterion} if, for each AF $\F$ and for each $S \in \sigma(\F)$, $S$ contains the grounded extension of $\F$;
    \item \textbf{CF-reinstatement criterion} if, for each AF $\F$ and for each $S \in \sigma(\F)$, whenever $S$ defends $a$ and $S\cup \{a\}$ is conflict-free, then $a \in S$;    
    \item \textbf{Directionality criterion} if, for each AF $\F$ and $U\subseteq A_\F$ which is not attacked from outside $U$, $\sigma(\F\restriction_U) = \{ S \cap U : S \in \sigma(\F) \}$.
\end{itemize}
\end{definition}


% In the literature, the concept of ``skepticism''  has often been used as a comparative criterion among different semantics. Roughly speaking, a semantics $\sigma$
%  is said to be more skeptical than another semantics
%  if it assigns the status \emph{undecided} to a larger number of arguments---i.e., it refrains from committing to their acceptance or rejection. To rigorously capture this intuitive notion of relative skepticism, Baroni and Giacomin introduced the following general orderings over sets of extensions:

Baroni and Giacomin \cite[Proposition 63]{BaroniGiacomin} show that in the finite setting, $\cft$ satisfies the properties of elementary and weak skepticism adequacy, which we now define. We will examine below which variants of $\cft$ or $\stgt$ satisfy these conditions in the infinite setting.


\begin{definition}
Let $\tau_1$ and $\tau_2$ be two sets of extensions of an AF $\F$. Then:
\begin{itemize}
    \item The \textbf{elementary skepticism relation}, denoted $\tau_1 \preceq^E_\cap \tau_2$, holds iff
    \[
    \bigcap_{S_1 \in \tau_1} S_1 \subseteq \bigcap_{S_2 \in \tau_2} S_2;
    \]
    \item The \textbf{weak skepticism relation}, denoted $\tau_1\preceq^E_W \tau_2$, holds iff
    $(\forall S_2 \in \tau_2 \; \exists S_1 \in \tau_1)(S_1 \subseteq S_2)$.
\end{itemize}
\end{definition}


\begin{definition}
 For $\F=(A_\F,R_\F)$, let $\text{conf}(\F)$ be the set of conflicting pairs in $\F$: i.e., $\text{conf}(\F)=\{(x,y)\mid (x,y)\in R\text{ or }(y,x)\in R\}$.  Next, let $\sigma$ be a semantics:
\begin{itemize}
    \item For each of the skepticism relations $\preceq$, we say that $\sigma$ is \textbf{$\preceq$-skepticism adequate}, if $\F=(A_{F},R_\F)$ and $\G=(A_\G,R_\G)$ with $R_\F\supseteq R_\G$ and $\text{conf}(F)=\text{conf}(G)$ implies that $\sigma(\F)\preceq \sigma(\G)$.
\end{itemize}
\end{definition}


