\section{Detailed explanation of Remark \ref{rmk:Equivalence With Gaggl}}\label{sec:equivalence}

We recall the following definitions from Gaggl and Woltran \cite[Definitions 3.6, 3.7]{Gaggl-Woltran-cf2}:
\begin{definition}
    Let $\F$ be an AF, $a,b$ be arguments and $B\subseteq A_\F$. We say $b$ is \emph{reachable from $a$ modulo $B$}, written $a\Rightarrow^B_\F b$, if there is a path from $a$ to $b$ in $\F\vert_B$. 
\end{definition}

\begin{definition}
    For an AF $\F$ and $D, S\subseteq A_\F$: 
    $$\Delta_{\F,S}(D)=\{a\in A_\F \mid \exists b\in S (b\att a \wedge a\not\Rightarrow_\F^{A_\F\smallsetminus D} b)\}.$$
\end{definition}

The following definition was given for finite ordinals, which we expand to infinite ordinals as well (we note a small change in the definition at index 0, which only shifts the indices by 1):
\begin{definition}
    $\Delta^0_{\F,S}=\emptyset$.
    % \footnote{This is a small change from the definition given in \cite{Gaggl-Woltran} in order to make the indices line up well.}.

    $\Delta^{\alpha+1}_{\F,S}=\Delta_{\F,S}(\Delta^\alpha_{\F,S})$.

    $\Delta^\lambda_{\F,S}=\bigcup_{\alpha<\lambda} \Delta^\alpha_{\F,S}$.
\end{definition}

We note that this is a situation of a familiar lattice-theoretic phenomenon:

\begin{definition}\label{def:lattice theoretic sequence}
    Let $L$ be a complete lattice and $f:L\to L$ be any function. For all ordinals $\alpha$ and $u\in L$, the \emph{$\alpha$-iteration of $f$} is inductively defined as follows:
    \begin{itemize}
        \item $f^0(u)=u$;
        \item If $\alpha=\beta+1$, then $f^\alpha(u)=f(f^\beta(u))$;
        \item If $\alpha$ is a limit ordinal, then $f^\alpha(u)=\bigvee_{\beta < \alpha} f^\beta(u)$.
    \end{itemize}
\end{definition}

\begin{theorem}[see, e.g., \protect{\cite[Corollary 3.7]{venema2008lectures}}]\label{thm:lattice-theory approximation}
    Let $L$ be a complete lattice with bottom element $0_L$, equipped with a monotone function $f:L\to L$. Then, there is an ordinal $\alpha$ so that the least fixed point of $f$ coincides with $f^\alpha(0_L)$.
\end{theorem}


Since $\Delta_{\F,S}$ is monotonic, it follows that $\Delta_{\F,S}$ has a least fixed point and it equals $\Delta^\alpha_{\F,S}$ for some $\alpha$ of cardinality no more than the cardinality of $\F$. We call this least fixed point $\Delta_{\F,S}$.

Note that every element of $\Delta_{\F,S}$ is attacked by some element of $S$.

% (\texttt{Maybe insert discussion of general fixed-point theory from the LICS submission of the grounded paper})


\begin{lemma}\label{lem:connect C's to Deltas}
    For each $a$ and $\alpha$, $C_S^\alpha(a)=\{b \mid a\Rightarrow^{\A_\F\smallsetminus \Delta^\alpha_{\F,S}}_\F b \wedge b\Rightarrow^{\A_\F\smallsetminus \Delta^\alpha_{\F,S}}_\F a\}$
    % $a\notin C_S^\alpha(a)$ if and only if $a\in \Delta^\alpha_{\F,S}$.
\end{lemma}
\begin{proof}
    For $\alpha=0$, every $C_S^0(a)$ is the strongly connected component of $a$ is exactly $\{b \mid a\Rightarrow^{\A_\F\smallsetminus \Delta^0_{\F,S}}_\F b \wedge b\Rightarrow^{\A_\F\smallsetminus \Delta^0_{\F,S}}_\F a\}$ since $\Delta^0_{\F,S}=\emptyset$.

    Recall $C_S^{\alpha+1}(a)$ is the strongly connected component of $a$ in $C^\alpha_S(a)\smallsetminus \{x \mid \exists y\in S\smallsetminus C_S^\alpha(a)(y\att x)\}$. This is exactly saying that $b\in C^{\alpha+1}_S(a)$ if and only if there is a path from $a$ to $b$ and a path from $b$ to $a$ each avoiding the elements attacked from outside $C_S^\alpha(a)$. By inductive hypothesis, $C_S^\alpha(a)$ is $\{b \mid a\Rightarrow^{\A_\F\smallsetminus \Delta^\alpha_{\F,S}}_\F b \wedge b\Rightarrow^{\A_\F\smallsetminus \Delta^\alpha_{\F,S}}_\F a\}$. Thus if $d\in S$ attacks $c$ and $d$ is outside $C_S^\alpha(a)$, then $c\not\Rightarrow^{\A_\F\smallsetminus \Delta^\alpha_{\F,S}} d$, i.e., $c\in \Delta^{\alpha+1}_{\F,S}$. Thus $C_S^{\alpha+1}(a)$ if and only if $a\Rightarrow^{\A_\F\smallsetminus \Delta^{\alpha+1}_{\F,S}}_\F b \wedge b\Rightarrow^{\A_\F\smallsetminus \Delta^{\alpha+1}_{\F,S}}_\F a$.

    % Suppose that $a\in \Delta^{\alpha+1}_{\F,S}$. Then there is some $b\in S$ which attacks $a$ and there is no path from $a$ to $b$ which avoids $\Delta^\alpha_{\F,S}$. In particular, any path from $a$ to $b$ goes through an element $c$ so that $c\notin C_S^\alpha$. Thus $b$ is not in $C_S^\alpha(a)$. This implies that $a$ is not in $C_S^{\alpha+1}(a)$. 

    % If $a\notin C_S^{\alpha+1}(a)$ then there is some $b\in S$ outside of $C_S^{\alpha}(a)$ which attacks $a$. 

    Finally, $C^\lambda_S(a)$ is the connected component of $a$ in $\bigcap_{\alpha<\lambda}C_S^\alpha(a)$. By inductive hypothesis,  $\Delta_{\F,S}^\alpha(a)\cap C_S^\alpha(a)=\emptyset$. Thus for $b$ to be in $C^\lambda_S(a)$, there must be a path from $a$ to $b$ and back which avoids $\bigcup_{\alpha<\lambda} \Delta^\alpha_{\F,S}$, i.e, avoids $\Delta^{\lambda}_{\F,S}$. Thus $C_S^\lambda(a)\subseteq \{b \mid a\Rightarrow^{\A_\F\smallsetminus \Delta^\lambda_{\F,S}}_\F b \wedge b\Rightarrow^{\A_\F\smallsetminus \Delta^\lambda_{\F,S}}_\F a\}$.
    On the other hand, if a path from $b$ to $a$ is entirely in $\A_\F\smallsetminus \Delta^\lambda_{\F,S}$, then it is also contained in $\A_\F\smallsetminus \Delta^\alpha_{\F,S}$ for each $\alpha$. Thus it is entirely in $\bigcap_{\alpha<\lambda}C_S^\alpha(a)$. Thus $C_S^\lambda(a)\supseteq \{b \mid a\Rightarrow^{\A_\F\smallsetminus \Delta^\lambda_{\F,S}}_\F b \wedge b\Rightarrow^{\A_\F\smallsetminus \Delta^\lambda_{\F,S}}_\F a\}$.
\end{proof}

\begin{lemma}
       If $\beta > \alpha_S(a)$ for every $a\in \F$, then $\Delta_{\F,S}=\Delta_{\F,S}^\beta$. 
\end{lemma}
\begin{proof}
    It follows from Lemma \ref{lem:connect C's to Deltas} that whenever $a\in \Delta^{\alpha+1}_{\F,S}\smallsetminus \Delta^\alpha_{\F,S}$, then $a\in C_S^\alpha(a)$ and $a\notin C_S^{\alpha+1}(a)$. Thus $\alpha+1=\alpha_S(a)$, showing that $\beta >\alpha+1$. In particular, we cannot have any $a\in \Delta^{\beta+1}_{\F,S}\smallsetminus\Delta^\beta_{\F,S}$. That is, $\Delta^{\beta+1}_{\F,S}=\Delta^\beta_{\F,S}$ 
\end{proof}

Recall \cite[Definition 3.1]{Gaggl-Woltran-cf2} that for an AF $\F$, $[[\F]]$ is the separation of $\F$, defined by removing attacks between elements of different strongly connected components in $\F$. 

\begin{theorem}\label{thm:icft-theequivalence}
    An extension $S$ is in \icft$(\F)$ if and only if $S$ is conflict-free and $S\in \na([[\F\smallsetminus \Delta_{\F,S}]])$.
\end{theorem}
\begin{proof}
    Let $\beta$ be large enough that $\beta > \alpha_S(a)$ for each $a\in A_\F$. Then $S\in \icft$ if it is conflict-free and, for each non-empty $C_S^\beta(a)$, $S\cap C_S^\beta(a)$ is a naive extension in $C_S^\beta(a)$. By Lemma \ref{lem:connect C's to Deltas}, the sets $C_S^\beta(a)$ are exactly the connected components in $\F\smallsetminus \Delta^\beta_{\F,S}=\F\smallsetminus \Delta_{\F,S}$. Being a naive extension in each of these connected components is the same as being a naive extension in $[[\F\smallsetminus \Delta_{\F,S}]]$.
\end{proof}

\begin{theorem}\label{thm:istgt-theequivalence}
    An extension $S$ is in \istgt$(\F)$ if and only if $S$ is conflict-free and $S\in \stg([[\F\smallsetminus \Delta_{\F,S}]])$.
\end{theorem}
\begin{proof}
    Let $\beta$ be large enough that $\beta > \alpha_S(a)$ for each $a\in A_\F$. Then $S\in \istgt$ if it is conflict-free and, for each non-empty $C_S^\beta(a)$, $S\cap C_S^\beta(a)$ is a stage extension in $C_S^\beta(a)$. By Lemma \ref{lem:connect C's to Deltas}, the sets $C_S^\beta(a)$ are exactly the connected components in $\F\smallsetminus \Delta^\beta_{\F,S}=\F\smallsetminus \Delta_{\F,S}$. Being a stage extension in each of these connected components is the same as being a stage extension in $[[\F\smallsetminus \Delta_{\F,S}]]$.
\end{proof}

