\subsection*{Well-definedness} For well-definedness, we note that the non-well-definedness of the cf2 and stg2 semantics are established in \cite{BS-unrestricted}, as in Example \ref{BS-example}. The definitions are not recursive in \cfo and \stgo, so these are well-defined. Finally, the well-definedness for \icft and \istgt follows from Theorems \ref{thm:icft-theequivalence} and \ref{thm:istgt-theequivalence}. Since $\Delta$ is a monotone operator, Theorem \ref{thm:lattice-theory approximation} guarantees the existence of a least fixed-point and the conditions in Theorems \ref{thm:icft-theequivalence} and \ref{thm:istgt-theequivalence} are clearly well-defined. Alternatively, this follows since each $C_S^\alpha(a)$ must stabilize at some ordinal of size no more than the size of $A_\F$. This is because whenever $C^{\alpha+1}_S(a)\subsetneq C^\alpha_S(a)$, some element has left $C^{\alpha}_S(a)$. This can happen at most at $\vert C^0_S(a) \vert$ many ordinals. Thus $\alpha_S(a)$ is well-defined, showing that the notions of \icft and \istgt are well-defined.

\subsection*{I-maximality and CF-reinstatement}
Dvo\v r\'ak and Gaggl \cite[Proposition 3.12]{Dvorak-Gaggl-stg2} show that any semantics $\sigma$ so that $\sigma(\F)\subseteq \na(\F)$ satisfies I-maximality and CF-reinstatement. This shows that na and stg satisfy I-maximality and CF-reinstatement.

\begin{theorem}
    Let $\sigma$ be one of the semantics cf2, stg2, \icft, \cfo, \istgt, \stgo. Then $\sigma(\F)\subseteq \na(\F)$. Thus $\sigma$ satisfies I-maximality and CF-reinstatement.
\end{theorem}
\begin{proof}
    For cf2, stg2, \icft, \istgt, Theorem \ref{thm:icft-theequivalence} and Theorem \ref{thm:istgt-theequivalence}, in addition to the results of Gaggl and Woltran \cite[Theorem 3.11]{Gaggl-Woltran-cf2} and  Dvo\v r\'ak and Gaggl \cite[Proposition 3.2]{Dvorak-Gaggl-stg2}, show that any $\sigma$-extension is naive. In particular, every element of $\Delta_{\F,S}$ is attacked by an element of $S$ and every other element $a$ is part of its final strongly connected component $C_S^{\alpha_S(a)}(a)$ where $S$ is either naive or stage. Since stage extensions are all naive, $S$ is always naive in $C_S^{\alpha_S(a)}(a)$. 

    The same analysis works for \cfo and \stgo, except that we do not need to find a final strongly connected component. By definition, to be a \cfo extension, $S$ must be naive on $X\smallsetminus \{a\in X \mid \exists y\in (S\smallsetminus X) (y\att a\}$. Thus again every element not in $S$ is in conflict with $S$, showing that $S$ is naive. Since stage extensions are naive, the same argument works for \stgo.

    It follows from Dvo\v r\'ak and Gaggl \cite[Proposition 3.12]{Dvorak-Gaggl-stg2} that $\sigma$ satisfies I-maximality and CF-reinstatement.
\end{proof}

\subsection*{Reinstatement and Weak Reinstatement}

\begin{theorem}
    na, stg, cf2, \icft, \cfo, stg2, \istgt, \stgo do not satisfy reinstatement.
\end{theorem}
\begin{proof}
    Consider the AF of a 3-cycle: $a\att b\att c\att a$. In each of these semantics, $\{a\}$ is an accepted extension. But $\{a\}$ defends $c$.
\end{proof}

That the naive and stage semantics do not satisfy weak reinstatement is established in Gaggl \cite{GagglDissertation}.

\begin{theorem}\label{thm: icft istgt have weak reinstatement}
    \icft and \istgt satisfy weak reinstatement.
\end{theorem}
\begin{proof}
	We use the recursive definition of the grounded extension as in Theorem \ref{thm:lattice-theory approximation}. In particular, $\G_0=\emptyset$, $\G_{\alpha+1}=f_{\F}(G_{\alpha})$, and $\G_\lambda = \bigcup_{\alpha<\lambda} \G_\alpha$ for limit ordinals $\lambda$. Then $\G=\bigcup_{\alpha} \G_\alpha=\G_\beta$ for some countable ordinal $\beta$.

    We show by induction that
    $a\in \G_\alpha$ implies that $a\in S$ and $\C^\alpha_S(a)=\{a\}$. This is clearly true for $G_\emptyset$, which is empty by definition. Since $G_\lambda = \bigcup_{\alpha<\lambda} \G_\alpha$ for limit ordinals $\lambda$, the induction for limit ordinals is immediate. Suppose that $a\in \G_{\beta+1}$. Then we know that every element of $\G_\beta$ is in $S$. Further, $C^\beta_S(x)=\{x\}$ for each $x\in \G_\beta$. Then any element $b$ which attacks $a$ is defended by $\G_\beta$, thus is attacked from an element not in $C^\beta_S(b)$. Thus $C^{\beta+1}_S(a)=\{a\}$ since no attacker of $a$ can be in $C^{\beta+1}_S(a)$. Since every element which attacks $a$ is attacked from above by $S$, $C^{\gamma}_S(a)=\{a\}$ for all $\gamma>\beta$ showing that $\alpha_S(a)=\beta+1$. Finally, since $S\cap C^{\alpha_S(a)}_S(a)$ is a naive or stage extension in $C^{\alpha_S(a)}_S(a)$, it follows that $a\in S$. 
\end{proof}

\begin{corollary}
    The semantics cf2 and stg2 satisfy weak reinstatement.
\end{corollary}
\begin{proof}
    If $S$ is a cf2 or stg2 extension, then by Theorem \ref{thm:when defined cf2 and icft agree}, they are also an $\icft$ or $\istgt$ extension, thus must contain the grounded extension by Theorem \ref{thm: icft istgt have weak reinstatement}.
\end{proof}

