\subsection*{Skepticism Adequacy}

That the naive semantics satisfies and the stage semantics does not satisfy $\preceq^E_\cap$- and $\preceq^E_W$-skepticism adequacy are established in Gaggl \cite{GagglDissertation}. 

We note that the proof in \cite{BaroniGiacomin} that cf2 satisfies $\preceq^E_W$-skepticism adequacy assumes a finite AF, since it only considers expanding the attack relation by one extra attack at a time. In fact, \cite[Proposition 2]{BaroniGiacomin} shows the following: 

\begin{proposition}[{\cite[Proposition 2]{BaroniGiacomin}}]\label{prop:BG-skep-ad}
    Suppose that $F=(A,R)$ and $G=(A,R')$ are \emph{finite AFs} with $R\subseteq R'$ where $\text{conf}(F)=\text{conf}(G)$. Let $S\in \cft(\F)$. Then $S\in \cft(\G)$.
\end{proposition}

Yet the following example shows Proposition \ref{prop:BG-skep-ad}, as well as both $\preceq^E_\cap$- and $\preceq^E_W$-skepticism adequacy fail in the infinite setting.

\begin{theorem}
    Both $\preceq^E_\cap$ and $\preceq^E_W$-skepticism adequacy fail for cf2.
\end{theorem}
\begin{proof}
    Let $G$ be Example \ref{BS-example} with one added argument $c$ so that $c\att a_i$ for all $i$. Note that $\{b_i \mid i\in \nat\}\cup \{c\}$ is a cf2 extension. Let $G'$ be as in $G$ except that we add the attacks $a_i\att c$. Note that just as in Example \ref{BS-example}, $G'$ does not have any cf2 extensions. Thus both $\preceq^E_\cap$- and $\preceq^E_W$-skepticism adequacy fail for cf2 in this example. This example can also be made finitary by adding, instead of one $c$, an infinite set of $c_i$ so that $c_i\att a_i$ in $G$ and also $a_i\att c_i$ in $G'$.
\end{proof}




\begin{theorem}\label{thm:icft skep ad}
    Suppose that $F=(A,R)$ and $G=(A,R')$ with $R\subseteq R'$ where $\text{conf}(F)=\text{conf}(G)$. Let $S\in \icft(\F)$. Then $S\in \icft(\G)$.

    In particular, \icft satisfies $\preceq^E_\cap$- and $\preceq^E_W$-skepticism adequacy. 
\end{theorem}
\begin{proof}
    Observe that $\Delta_{G,S}^\alpha\subseteq \Delta_{F,S}^\alpha$ for all $\alpha$ since reachability in $F$ implies reachability in $G$.
    It follows that if $a$ and $b$ are in the same strongly connected component in $[[F-\Delta_{F,S}]]$ then they are in the same strongly connected component in $[[G-\Delta_{G,S}]]$.
    We must show that $S$ is naive in $[[G-\Delta_{G,S}]]$. We consider a single strongly connected component $X$ in $G-\Delta_{G,S}$. 
    We can partition $X$ into two pieces: The elements in $\Delta_{F,S}$ and the remaining elements. These remaining elements are a union of strongly connected components in $[[F-\Delta_{F,S}]]$. We know that $S$ is naive on each strongly connected component in $[[F-\Delta_{F,S}]]$. For each element $x\in X$, either $x\in \Delta_{F,S}$ in which case it is attacked by an element of $S$ or it is either a self-attacker or is in conflict with some element in $S$ in its strongly connected component in $[[F-\Delta_{F,S}]]$. Thus $S$ is naive on $X$, showing that $S$ is in $\icft(\G)$.
\end{proof}



\begin{theorem}
    Suppose that $F=(A,R)$ and $G=(A,R')$ with $R\subseteq R'$ where $\text{conf}(F)=\text{conf}(G)$. Let $S\in \cfo(F)$. Then $S\in \cfo(G)$.

    In particular, \cfo satisfies $\preceq^E_\cap$- and $\preceq^E_W$-skepticism adequacy. 
\end{theorem}
\begin{proof}
    Let $X$ be a strongly connected component in $G$. Then $X$ is a union of strongly connected components in $F$. Let $\Theta$ be the set of strongly connected components in $F$ so that $X=\bigcup_{Y\in \Theta} Y$. We need to check that $S$ is a naive extension of $X\smallsetminus \{a\in X \mid \exists y\in S\smallsetminus X (y\att a)\}$.  For each $Z\in \Theta$, we know that $S$ is a naive extension of $Z\smallsetminus \{a\in Z \mid \exists y\in S\smallsetminus Z (y\att a)\}$. Thus, for each element $x\in X$, either $x$ is attacked by an element of $S$ or it is in one of the sets $Z\smallsetminus \{a\in Z \mid \exists y\in S\smallsetminus Z (y\att a)\}$ for $Z\in \Theta$. In this latter case, it is either in $S$ or it is a self-attacker or it is in conflict with an element of $S\cap Z\subseteq S\cap X$. It follows that $S$ is naive on $X\smallsetminus \{a\in X \mid \exists y\in S\smallsetminus X (y\att a)\}$.
\end{proof}


