\subsection{Proof of Theorem 1}
\begin{proof} 
To establish that the equilibrium \(\fractiontruthful^\degreeidx_* = [1, 0, 0]^T\) for all \(\degreeidx\) is locally asymptotically stable, we employ the Lyapunov stability theorem. This requires constructing a Lyapunov function \(\lyuponov(\fractiontruthful)\) that is positive definite near the equilibrium and demonstrating that its time derivative \(\frac{d}{d\timeindexalt} \fractiontruthful(\fractiontruthful)\) is negative definite in a neighborhood of \(\fractiontruthful\) for all $\degreeidx$.

\textbf{Step 1: Define the Lyapunov Function}
Consider the candidate Lyapunov function for each degree \(\degreeidx\):
\begin{align*}
    \lyuponov^\degreeidx(\fractiontruthful^\degreeidx) = \fractiontruthful_\hallucinating^\degreeidx + \fractiontruthful_\dontknow^\degreeidx 
\end{align*}
Since \(\fractiontruthful_\hallucinating^\degreeidx \geq 0\) and \(\fractiontruthful_\dontknow^\degreeidx  \geq 0\), we have \(\lyuponov^\degreeidx(\fractiontruthful)\geq 0\). Moreover, \(\lyuponov^\degreeidx(\fractiontruthful) = 0\) if and only if \(\fractiontruthful_\hallucinating^\degreeidx\) and \(\fractiontruthful_\dontknow^\degreeidx  = 0\), which, given the constraint \(\sum \fractiontruthful_\latentstate^\degreeidx = 1\), implies \(\fractiontruthful_\truthful^\degreeidx = 1\). Thus, \(\lyuponov^\degreeidx(\fractiontruthful^\degreeidx)  = 0\) at the equilibrium \(\fractiontruthful\degreeidx^*\).
For the entire system, define:
\[
\lyuponov(\fractiontruthful)  = \sum_\degreeidx \degreedistvect_\degreeidx \lyuponov^\degreeidx(\fractiontruthful^\degreeidx).
\]
Clearly, \(\lyuponov(\fractiontruthful) \geq 0\), and \(\lyuponov(\fractiontruthful) = 0\) if and only if \(\fractiontruthful_\hallucinating^\degreeidx = 0\) and \(\fractiontruthful_\dontknow^\degreeidx = 0\) for all \(\degreeidx\), i.e., \(\mathbf{\rho} = \mathbf{\rho}_*\). Hence, \(\lyuponov(\fractiontruthful)\) is positive definite around the equilibrium.

\textbf{Step 2: Compute the Time Derivative}
Next, compute the time derivative of the Lyapunov function:
\begin{align*}
\frac{d}{dt} \lyuponov(\fractiontruthful) =\sum_\degreeidx \degreedistvect_\degreeidx \left( \frac{d}{dt} \fractiontruthful_\hallucinating^\degreeidx + \frac{d}{dt} \fractiontruthful_\dontknow^\degreeidx \right).
\end{align*}
The specific dynamics are given as:
\begin{align*}
\frac{d}{dt} \fractiontruthful_\hallucinating^\degreeidx &= \avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx \fractiontruthful_\truthful^\degreeidx +\avgprobabilitytransition{\dontknow}{\hallucinating}^\degreeidx \fractiontruthful_\dontknow^\degreeidx - (\avgprobabilitytransition{\hallucinating}{\truthful}^\degreeidx  + \avgprobabilitytransition{\hallucinating}{\dontknow}^\degreeidx)\fractiontruthful_\hallucinating^\degreeidx,\\
\frac{d}{dt} \fractiontruthful_\dontknow^\degreeidx &= \avgprobabilitytransition{\truthful}{\dontknow}^\degreeidx \fractiontruthful_\truthful^\degreeidx +\avgprobabilitytransition{\hallucinating}{\dontknow}^\degreeidx \fractiontruthful_\hallucinating^\degreeidx - (\avgprobabilitytransition{\dontknow}{\truthful}^\degreeidx  + \avgprobabilitytransition{\dontknow}{\hallucinating}^\degreeidx)\fractiontruthful_\dontknow^\degreeidx.
\end{align*}
Summing these and plugging $\fractiontruthful_\truthful^\degreeidx = 1 - \fractiontruthful_\hallucinating^\degreeidx- \fractiontruthful_\dontknow^\degreeidx$:
\begin{align*}
\frac{d}{dt} (\fractiontruthful_\hallucinating^\degreeidx + \fractiontruthful_\dontknow^\degreeidx) &= \avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx (1 - \fractiontruthful_\hallucinating^\degreeidx- \fractiontruthful_\dontknow^\degreeidx) +\avgprobabilitytransition{\dontknow}{\hallucinating}^\degreeidx \fractiontruthful_\dontknow^\degreeidx \\&- (\avgprobabilitytransition{\hallucinating}{\truthful}^\degreeidx  + \avgprobabilitytransition{\hallucinating}{\dontknow}^\degreeidx)\fractiontruthful_\hallucinating^\degreeidx+ \avgprobabilitytransition{\truthful}{\dontknow}^\degreeidx (1 - \fractiontruthful_\hallucinating^\degreeidx- \fractiontruthful_\dontknow^\degreeidx) \\&+\avgprobabilitytransition{\hallucinating}{\dontknow}^\degreeidx \fractiontruthful_\hallucinating^\degreeidx - (\avgprobabilitytransition{\dontknow}{\truthful}^\degreeidx  + \avgprobabilitytransition{\dontknow}{\hallucinating}^\degreeidx)\fractiontruthful_\dontknow^\degreeidx
\end{align*}
And we can write the change in the Lyuponov function as, 
\begin{align*}
\frac{d}{dt} \lyuponov(\fractiontruthful) &= \sum_\degreeidx \degreedistvect_\degreeidx \left[ (\avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx +\avgprobabilitytransition{\truthful}{\dontknow}^\degreeidx) (1 - \fractiontruthful_\hallucinating^\degreeidx- \fractiontruthful_\dontknow^\degreeidx)  \right.\\&\left.- \avgprobabilitytransition{\hallucinating}{\truthful}^\degreeidx \fractiontruthful_\hallucinating^\degreeidx - \avgprobabilitytransition{\dontknow}{\truthful}^\degreeidx \fractiontruthful_\dontknow^\degreeidx   \right].
\end{align*}
\textbf{Step 3: Analyze Near the Equilibrium }
Evaluate the behavior near $\rho_*$, where $\rho_\truthful^\degreeidx = 1$, $\rho_\hallucinating^\degreeidx = 0$, $\rho_\dontknow^\degreeidx = 0$, so $\theta_\truthful = 1$, $\theta_\hallucinating = 0$, $\theta_\dontknow = 0$. The transition rate is given by~\eqref{eq:G}.
% \begin{align*}
% \avgprobabilitytransition{\latentstate_1}{\latentstate_2}^\degreeidx(\mathbf{q}, \control) = \sum_{i=0}^\degreeidx \sum_{j=0}^{\degreeidx-i} \functiontransition_{\latentstate_1 \latentstate_2}(\control, \degreeidx, i, j) \binom{\degreeidx}{i, j} (\theta_\truthful)^i (\theta_\hallucinating)^j (\theta_\dontknow)^{\degreeidx - i - j}.
% \end{align*}

\subsubsection*{At the Equilibrium}
When $\theta_\truthful = 1$, $\theta_\hallucinating = 0$, $\theta_\dontknow = 0$, only the term with $i = \degreeidx$, $j = 0$ contributes (since $(\theta_\truthful)^\degreeidx = 1$, and $1 - \theta_\truthful - \theta_\hallucinating = 0$):
\begin{align*}
\avgprobabilitytransition{\latentstate_1}{\latentstate_2}^\degreeidx = \functiontransition_{\latentstate_1 \latentstate_2}(\control, \degreeidx, \degreeidx, 0).
\end{align*}
By (A1), $\functiontransition_{\truthful\hallucinating}(\control, \degreeidx, \degreeidx, 0) = 0$, $\functiontransition_{\truthful\dontknow}(\control, \degreeidx, \degreeidx, 0) = 0$, so $\avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx = 0$, $\avgprobabilitytransition{\truthful}{\dontknow}^\degreeidx = 0$.
By (A2), $\functiontransition_{\hallucinating}{\truthful}(\control, \degreeidx, \degreeidx, 0) > 0$, $\functiontransition_{\dontknow\truthful}(\control, \degreeidx, \degreeidx, 0) > 0$, so define:
\begin{align*}
\alpha_{\hallucinating\truthful}^\degreeidx = \functiontransition_{\hallucinating\truthful}(\control, \degreeidx, \degreeidx, 0) > 0, \quad \alpha_{\dontknow\truthful}^\degreeidx = \functiontransition_{\dontknow\truthful}(\control, \degreeidx, \degreeidx, 0) > 0,
\end{align*}
thus $\avgprobabilitytransition{\hallucinating}{\truthful}^\degreeidx = \alpha_{\hallucinating\truthful}^\degreeidx$, $\avgprobabilitytransition{\dontknow}{\truthful}^\degreeidx = \alpha_{\dontknow\truthful}^\degreeidx$.

\subsubsection*{Near the Equilibrium}

Consider small perturbations: $\rho_\hallucinating^\degreeidx = \epsilon_\hallucinating^\degreeidx$, $\rho_\dontknow^\degreeidx = \epsilon_\dontknow^\degreeidx$, where $\epsilon_\hallucinating^\degreeidx, \epsilon_\dontknow^\degreeidx \geq 0$ are small, so $\rho_\truthful^\degreeidx = 1 - \epsilon_\hallucinating^\degreeidx - \epsilon_\dontknow^\degreeidx$. 

% Compute $\theta_\latentstate$:
% \begin{align*}
% \theta_\truthful = \frac{1}{\mathbb{E}[\degreeidx]} \sum_\degreeidx \degreeidx \mathbf{q}_\degreeidx (1 - \epsilon_\hallucinating^\degreeidx - \epsilon_\dontknow^\degreeidx) = 1 - \frac{1}{\mathbb{E}[\degreeidx]} \sum_\degreeidx \degreeidx \mathbf{q}_\degreeidx (\epsilon_\hallucinating^\degreeidx + \epsilon_\dontknow^\degreeidx),
% \end{align*}
% \begin{align*}
% \theta_\hallucinating = \frac{1}{\mathbb{E}[\degreeidx]} \sum_\degreeidx \degreeidx \mathbf{q}_\degreeidx \epsilon_\hallucinating^\degreeidx, \quad \theta_\dontknow = \frac{1}{\mathbb{E}[\degreeidx]} \sum_\degreeidx \degreeidx \mathbf{q}_\degreeidx \epsilon_\dontknow^\degreeidx.
% \end{align*}
% Define:
% \begin{align*}
% \epsilon_\hallucinating = \frac{1}{\mathbb{E}[\degreeidx]} \sum_\degreeidx \degreeidx \mathbf{q}_\degreeidx \epsilon_\hallucinating^\degreeidx, \quad \epsilon_\dontknow = \frac{1}{\mathbb{E}[\degreeidx]} \sum_\degreeidx \degreeidx \mathbf{q}_\degreeidx \epsilon_\dontknow^\degreeidx,
% \end{align*}
Let $\frac{\epsilon}{2}= \min_l \max(\epsilon_\hallucinating, \epsilon_\dontknow)$ According to A3,
\begin{align*}
\theta_\truthful = 1 - \epsilon_\hallucinating - \epsilon_\dontknow, \quad \theta_\hallucinating = \epsilon_\hallucinating, \quad \theta_\dontknow = \epsilon_\dontknow,
\end{align*}
where $\epsilon_\hallucinating, \epsilon_\dontknow$ are small constants $<\epsilon$.
We now calculate the different transition probabilities.
\begin{align*}
\avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx = \sum_{i=0}^\degreeidx \sum_{j=0}^{\degreeidx-i} \functiontransition_{\truthful\hallucinating}(\control, \degreeidx, i, j) \binom{\degreeidx}{i, j} (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^i \epsilon_\hallucinating^j \epsilon_\dontknow^{\degreeidx - i - j}.
\end{align*}
Since $\functiontransition_{\truthful\hallucinating}(\control, \degreeidx, \degreeidx, 0) = 0$, the $i = \degreeidx$, $j = 0$ term is zero. Significant terms are:
$i = \degreeidx-1$, $j = 1$:
\begin{align*}
\binom{\degreeidx}{\degreeidx-1, 0} (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^{\degreeidx-1} \epsilon_\dontknow = \degreeidx (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^{\degreeidx-1} \epsilon_\dontknow,
\end{align*}
$i = \degreeidx-1$, $j = 1$
\begin{align*}
\binom{\degreeidx}{\degreeidx-1, 1} (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^{\degreeidx-1} \epsilon_\hallucinating = \degreeidx (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^{\degreeidx-1} \epsilon_\hallucinating.
\end{align*}
Next we calculate $\avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx$, $\avgprobabilitytransition{\truthful}{\dontknow}^\degreeidx$, $\avgprobabilitytransition{\hallucinating}{\truthful}^\degreeidx$ and $\avgprobabilitytransition{\dontknow}{\truthful}^\degreeidx$: 
Define $\beta_{\truthful\hallucinating}^\degreeidx = \degreeidx \functiontransition_{\truthful\hallucinating}(\control, \degreeidx, \degreeidx-1, 0)$, $\gamma_{\truthful\hallucinating}^\degreeidx = \degreeidx \functiontransition_{\truthful\hallucinating}(\control, \degreeidx, \degreeidx-1, 1)$, $\beta_{\truthful\dontknow}^\degreeidx = \degreeidx \functiontransition_{\truthful\dontknow}(\control, \degreeidx, \degreeidx-1, 0)$, $\gamma_{\truthful\dontknow}^\degreeidx = \degreeidx \functiontransition_{\truthful\dontknow}(\control, \degreeidx, \degreeidx-1, 1)$, and let $\epsilon_\truthful = 1- \epsilon_\dontknow-\epsilon_\truthful$ so:
\begin{align*}
\avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx &= \beta_{\truthful\hallucinating}^\degreeidx (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\dontknow + \gamma_{\truthful\hallucinating}^\degreeidx (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\hallucinating + R_{\truthful\hallucinating}^\degreeidx,\\
\avgprobabilitytransition{\truthful}{\dontknow}^\degreeidx &= \beta_{\truthful\dontknow}^\degreeidx (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\dontknow + \gamma_{\truthful\dontknow}^\degreeidx (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\hallucinating + R_{\truthful\dontknow}^\degreeidx,
\end{align*}
where $R_{\truthful\hallucinating}^\degreeidx$ includes higher-order terms (e.g., $i \leq \degreeidx-2$) bounded by $C_{\truthful\hallucinating}^\degreeidx (\epsilon_\hallucinating + \epsilon_\dontknow)^2$ for some constant $C_{\truthful\hallucinating}^\degreeidx$ and $R_{\truthful\dontknow}^\degreeidx \leq C_{\truthful\dontknow}^\degreeidx (\epsilon_\hallucinating + \epsilon_\dontknow)^2$.
\begin{align*}
\avgprobabilitytransition{\hallucinating}{\truthful}^\degreeidx &= \alpha_{\hallucinating\truthful}^\degreeidx (\epsilon_\truthful)^\degreeidx + \degreeidx \functiontransition_{\hallucinating\truthful}(\control, \degreeidx, \degreeidx-1, 0) (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\dontknow \\&+ \degreeidx \functiontransition_{\hallucinating\truthful}(\control, \degreeidx, \degreeidx-1, 1) (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\hallucinating + R_{\hallucinating\truthful}^\degreeidx,\\
\avgprobabilitytransition{\dontknow}{\truthful}^\degreeidx &= \alpha_{\dontknow\truthful}^\degreeidx (\epsilon_\truthful)^\degreeidx + \degreeidx \functiontransition_{\dontknow\truthful}(\control, \degreeidx, \degreeidx-1, 0) (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\dontknow \\&+ \degreeidx \functiontransition_{\dontknow\truthful}(\control, \degreeidx, \degreeidx-1, 1) (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\hallucinating + R_{\dontknow\truthful}^\degreeidx,
\end{align*}
where $R_{\hallucinating\truthful}^\degreeidx \leq C_{\hallucinating\truthful}^\degreeidx (\epsilon_\hallucinating + \epsilon_\dontknow)^2$ and $R_{\dontknow\truthful}^\degreeidx \leq C_{\dontknow\truthful}^\degreeidx (\epsilon_\hallucinating + \epsilon_\dontknow)^2$.
All these terms are needed in our computation of the next step.  
\subsubsection*{Derivative Near the Equilibrium} when $\rho_\truthful^\degreeidx  = 1 - \epsilon_\hallucinating^\degreeidx - \epsilon_\dontknow^\degreeidx$, we need to compute the following terms,
\begin{align*}
&(\avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx + \avgprobabilitytransition{\truthful}{\dontknow}^\degreeidx) (1 - \epsilon_\hallucinating^\degreeidx - \epsilon_\dontknow^\degreeidx) = \left[ (\beta_{\truthful\hallucinating}^\degreeidx + \beta_{\truthful\dontknow}^\degreeidx) \epsilon_\dontknow \right.\\&\left.+ (\gamma_{\truthful\hallucinating}^\degreeidx + \gamma_{\truthful\dontknow}^\degreeidx) \epsilon_\hallucinating + R_{\truthful\hallucinating}^\degreeidx + R_{\truthful\dontknow}^\degreeidx \right] (1 - \epsilon_\hallucinating^\degreeidx - \epsilon_\dontknow^\degreeidx) (\epsilon_\truthful)^{\degreeidx-1},\\
\end{align*}
\begin{align*}
&-\avgprobabilitytransition{\hallucinating}{\truthful}^\degreeidx \rho_\hallucinating^\degreeidx  = -\alpha_{\hallucinating\truthful}^\degreeidx (\epsilon_\truthful)^\degreeidx \epsilon_\hallucinating^\degreeidx \\&- \degreeidx \functiontransition_{\hallucinating\truthful}(\control, \degreeidx, \degreeidx-1, 0) (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\dontknow \epsilon_\hallucinating^\degreeidx \\&- \degreeidx \functiontransition_{\hallucinating}{\truthful}(\control, \degreeidx, \degreeidx-1, 1) (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\hallucinating \epsilon_\hallucinating^\degreeidx - R_{\hallucinating\truthful}^\degreeidx \epsilon_\hallucinating^\degreeidx,\\
-&\avgprobabilitytransition{\dontknow}{\truthful}^\degreeidx \rho_\dontknow^\degreeidx = -\alpha_{\dontknow\truthful}^\degreeidx (\epsilon_\truthful)^\degreeidx \epsilon_\dontknow^\degreeidx \\&- \degreeidx \functiontransition_{\dontknow}{\truthful}(\control, \degreeidx, \degreeidx-1, 0) (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\dontknow \epsilon_\dontknow^\degreeidx \\&- \degreeidx \functiontransition_{\dontknow}{\truthful}(\control, \degreeidx, \degreeidx-1, 1) (\epsilon_\truthful)^{\degreeidx-1} \epsilon_\hallucinating \epsilon_\dontknow^\degreeidx - R_{\dontknow\truthful}^\degreeidx \epsilon_\dontknow^\degreeidx.
\end{align*}
Assume $\avgprobabilitytransition{\dontknow}{\hallucinating}^\degreeidx, \avgprobabilitytransition{\hallucinating}{\dontknow}^\degreeidx$ are bounded by $M$, $|\avgprobabilitytransition{\dontknow}{\hallucinating}^\degreeidx| \leq M$, $|\avgprobabilitytransition{\hallucinating}{\dontknow}^\degreeidx| \leq M$, so:
$|\avgprobabilitytransition{\dontknow}{\hallucinating}^\degreeidx \rho_\dontknow^\degreeidx - \avgprobabilitytransition{\hallucinating}{\dontknow}^\degreeidx \rho_\hallucinating^\degreeidx| \leq M (\epsilon_\dontknow^\degreeidx + \epsilon_\hallucinating^\degreeidx).
$
Combining and plugging $\epsilon_\truthful$ we obtain, 
\begin{align*}
\frac{d}{dt} \lyuponov(\fractiontruthful) = \sum_\degreeidx \mathbf{q}_\degreeidx&\left[ -\alpha_{\hallucinating\truthful}^\degreeidx (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^\degreeidx \epsilon_\hallucinating^\degreeidx\right.\\& \left. - \alpha_{\dontknow\truthful}^\degreeidx (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^\degreeidx \epsilon_\dontknow^\degreeidx + P_\degreeidx \right],
\end{align*}
where $P_\degreeidx$ includes positive and negative terms:
\begin{align*}
P_\degreeidx &= (\avgprobabilitytransition{\truthful}{\hallucinating}^\degreeidx + \avgprobabilitytransition{\truthful}{\dontknow}^\degreeidx) (1 - \epsilon_\hallucinating^\degreeidx - \epsilon_\dontknow^\degreeidx) \\&- \degreeidx \functiontransition_{\hallucinating}{\truthful}(\control, \degreeidx, \degreeidx-1, 0) (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^{\degreeidx-1} \epsilon_\dontknow \epsilon_\hallucinating^\degreeidx \\&- \degreeidx \functiontransition_{\hallucinating}{\truthful}(\control, \degreeidx, \degreeidx-1, 1) (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^{\degreeidx-1} \epsilon_\hallucinating \epsilon_\hallucinating^\degreeidx \\&- R_{\hallucinating\truthful}^\degreeidx \epsilon_\hallucinating^\degreeidx - \degreeidx \functiontransition_{\dontknow}{\truthful}(\control, \degreeidx, \degreeidx-1, 0) (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^{\degreeidx-1} \epsilon_\dontknow \epsilon_\dontknow^\degreeidx \\& - \degreeidx \functiontransition_{\dontknow}{\truthful}(\control, \degreeidx, \degreeidx-1, 1) (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^{\degreeidx-1} \epsilon_\hallucinating \epsilon_\dontknow^\degreeidx \\&- R_{\dontknow\truthful}^\degreeidx \epsilon_\dontknow^\degreeidx + (\avgprobabilitytransition{\dontknow}{\hallucinating}^\degreeidx \rho_\dontknow^\degreeidx - \avgprobabilitytransition{\hallucinating}{\dontknow}^\degreeidx \rho_\hallucinating^\degreeidx).
\end{align*}

Since $\epsilon_\hallucinating, \epsilon_\dontknow, \epsilon_\hallucinating^\degreeidx, \epsilon_\dontknow^\degreeidx$ are small, and from the previous step $\avgprobabilitytransition{\latentstate_1}{\latentstate_2}^\degreeidx$ for $\latentstate_2\neq \truthful$ are $\orderof(\epsilon)$, $P_\degreeidx$ is of order $\orderof(\epsilon^2)$ (products of small terms), while the leading terms $-\alpha_{\hallucinating\truthful}^\degreeidx (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^\degreeidx \epsilon_\hallucinating^\degreeidx - \alpha_{\dontknow\truthful}^\degreeidx (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^\degreeidx \epsilon_\dontknow^\degreeidx$ are of order $\orderof(\epsilon)$. For small perturbations ($\epsilon_\hallucinating + \epsilon_\dontknow < 1$), $(1 - \epsilon_\hallucinating - \epsilon_\dontknow)^\degreeidx > 0$, and since $\alpha_{\hallucinating\truthful}^\degreeidx > 0$, $\alpha_{\dontknow\truthful}^\degreeidx > 0$, the negative terms dominate when $\epsilon_\hallucinating^\degreeidx > 0$ or $\epsilon_\dontknow^\degreeidx > 0$.
Define $m = \min_\degreeidx \{\alpha_{\hallucinating\truthful}^\degreeidx, \alpha_{\dontknow\truthful}^\degreeidx\}$, $M_P = \max_\degreeidx \{|P_\degreeidx| / (\epsilon_\hallucinating^\degreeidx + \epsilon_\dontknow^\degreeidx)\}$. Then:
\begin{align*}
\frac{d}{dt} \lyuponov(\fractiontruthful) \leq \sum_\degreeidx \mathbf{q}_\degreeidx \left[ -m (\epsilon_\truthful)^\degreeidx (\epsilon_\hallucinating^\degreeidx + \epsilon_\dontknow^\degreeidx) + M_P (\epsilon_\hallucinating^\degreeidx + \epsilon_\dontknow^\degreeidx) \right].
\end{align*}
For $\epsilon_\hallucinating + \epsilon_\dontknow < \delta < 1$, $\epsilon_\truthful^\degreeidx = (1 - \epsilon_\hallucinating - \epsilon_\dontknow)^\degreeidx \geq (1 - \delta)^\degreeidx$, and $M_P \to 0$ as $\epsilon_\hallucinating, \epsilon_\dontknow \to 0$. Choose $\delta$ small enough that $m (1 - \delta)^\degreeidx > M_P$, ensuring for a small region around $\fractiontruthful_*$:
\begin{align*}
\frac{d}{dt} \lyuponov(\fractiontruthful) < 0 \text{ for } \fractiontruthful \neq \fractiontruthful_*.
\end{align*}
The Lyapunov function \(\lyuponov(\fractiontruthful) = \sum_\degreeidx \degreedistvect_\degreeidx (\fractiontruthful_\hallucinating^\degreeidx + \fractiontruthful_\dontknow^\degreeidx)\) is positive near \(\fractiontruthful_*^\degreeidx\), and its derivative \(\frac{d}{d\timeindexalt} \lyuponov(\fractiontruthful) < 0\) for \(\fractiontruthful \neq \fractiontruthful_*\) in a neighborhood of the equilibrium, under the given conditions. By the Lyapunov stability theorem, the equilibrium \(\fractiontruthful_* = [1, 0, 0]^\transpose \) for all \(\degreeidx\) is locally asymptotically stable.
\end{proof}
