\begin{document}

\title{Local Equivariance Error-Based Metrics for Evaluating Sampling-Frequency-Independent Property of Neural Network
\thanks{This work was supported by JSPS KAKENHI under Grant JP23K28108 and JST ACT-X under Grant JPMJAX210G.}
}

\author{\IEEEauthorblockN{Kanami Imamura$^{1,2}$,  Tomohiko Nakamura$^2$, Norihiro Takamune$^1$, Kohei Yatabe$^3$, and Hiroshi Saruwatari$^1$}
\IEEEauthorblockA{$^1$ Graduate School of Information Science and Technology, The University of Tokyo, Tokyo, Japan}
