\subsection{Outline}

Section~\ref{sec:abstract} focuses on abstract graphs and presents complexity results on the MAX-MST-ratio problem. Section~\ref{sec:geometry} addresses the geometric setting, establishing bounds for the maximum MST-ratio and providing complexity results for MAX-EMST-ratio problem. Section~\ref{sec:average} explores the average EMST-ratio across all colorings of a point set. Section~\ref{sec:discussion} concludes with open questions to deepen understanding of the MST-ratio. Section~\ref{sec:experiments} presents experimental results regarding the maximum, average, and bipartite EMST-ratio for random point sets.

\section{Maximum MST-ratio of Abstract Graphs}\label{sec:abstract}
In this section, we study the complexity of finding the maximum MST-ratio for abstract graphs. Throughout this section and the subsequent sections, we call an edge \textit{colorful} if the two endpoints of it have different colors; otherwise, we call it \textit{monochromatic}. 

As the main result of this section, we show that not only MAX-MST-ratio is NP-hard, but it is extremely hard to approximate. In Section~\ref{sec:geometry}, we will use the NP-hardness of the MAX-MST-ratio to demonstrate that the geometric version of the problem (i.e., the MAX-EMST-ratio) is also NP-hard. Theorem~\ref{thm:graphsuperhard} presents a strong inapproximability result for the MAX-MST-ratio problem.


% \begin{theorem}\label{thm:graphnphard}
%     The problem MAX-MST-ratio is NP-hard \textcolor{red}{even if the weights belong to $\{1,2\}$}.
% \end{theorem}


% The proof of Theorem~\ref{thm:graphnphard} appears in Section~\ref{subsec:graphnphardproof} of the Appendix. 




\begin{theorem}\label{thm:graphsuperhard}
    For every $0<\varepsilon\le 1$, there is no polynomial-time $O(n^{1-\varepsilon})$-approximation with weights restricted to $1$ and $n$ for MAX-MST-ratio problem, unless P=NP.
\end{theorem}


\begin{proof}
    We prove that given an $\alpha$-approximation for MAX-MST-ratio, one can obtain a $2\alpha$-approximation for the MAX-Clique problem.
    Let $G=(V,E)$ be a graph on $n$ vertices on which we wish to find the maximum clique. From this, we create an instance of MAX-MST-ratio with the input graph $G'$, where $G'$ is a complete graph with $V(G')=V$ and the weight of any edge $e \in E(G')$ is $n$ if $e\in E$, and it is $1$ otherwise. Given a bi-partition of vertices into sets $R$ and $B$, we refer to $|\text{MST}(R)|+|\text{MST}(B)|$ as the \textit{value} of this bi-partition.%Given a coloring of $G$ into $R$ and $B$, we refer to $|MST(R)|+|MST(B)|$ as the value of this coloring.

    Given a clique $C$ of size $\ell$ in $G$, we can find a coloring of value $k$
     for $G'$ in polynomial time, where $\ell\le \lfloor \frac{k}{n}\rfloor+2$. This is trivial if $\ell\le 2$, and for $\ell\ge 3$ it is sufficient to color all but one of the vertices in $C$ by red, and the remaining vertices by blue. In this case, the weight of any MST of the red vertices is $(\ell -2) \cdot n$ %and for the blue vertices the MST has exactly $(n-\ell)$ many edges and hence the claim follows as $k\ge (\ell -2)n+(n-\ell)$ 
     and thus $\ell\le \lfloor \frac{k}{n}\rfloor+2$.

    Conversely, given a coloring $Q$ of value $k$ for $G'$, we show that we can find a clique of size at least $\frac{\lfloor k/n\rfloor}{2}+1$ in $G$ in polynomial time. Let $R_Q$ and $B_Q$ denote a red MST and a blue MST of $G$, respectively, in the coloring $Q$. Given that the weights in $G'$ belong to $\{1,n\}$ and since $R_Q \cup B_Q$ has exactly $n-2$ edges, then $R_Q \cup B_Q$ has exactly $\lfloor k/n\rfloor$ edges of weight $n$.
    W.l.o.g, we can assume that $R_Q$ has at least $ \frac{\lfloor k/n\rfloor}{2}$ edges of weight $n$. Consider $F:=(V(R_Q),E'')$, where $E''$ is the set of edges of weight $1$ in $R_Q$. Let $C_1,\ldots,C_r$ be the connected components of $F$. Clearly, we have $r\ge \frac{\lfloor k/n\rfloor}{2}+1$. For every $1\le i\le r$, let $u_i$ be a vertex in $C_i$. As $R_Q$ is an MST on the set of red vertices, then for every $i<j$, the weight of the edge $u_iu_j$ in $G$ is $n$. Hence, $\{u_1,u_2,\ldots,u_r\}$ is a clique of size $r\ge \frac{\lfloor k/n\rfloor}{2}+1$~in~$G$.

    Altogether, this shows that one can use an $\alpha$-approximation algorithm for the MAX-MST-ratio problem to find a $2\alpha$-approximation for the MAX-Clique problem. Zuckerman~\cite{Z06} proved that there exists no  $O(n^{1-\varepsilon})$-approximation for MAX-Clique problem, unless $P=NP$. Therefore, there exists no $O(n^{1-\varepsilon})$-approximation for MAX-MST-ratio, unless $P=NP$.
    \qedhere
\end{proof}





\section{Maximum MST-ratio of Geometric Point Sets}\label{sec:geometry}
We show that MAX-EMST-ratio problem is NP-hard. We remark that, a weighted complete graph does not necessarily correspond to the distance graph of a point set in $\mathbb{R}^d$. A weighted complete graph $G$ on $n$ vertices is \textit{realizable} in $\mathbb{R}^d$ if there exist $n$ points in $\mathbb{R}^d$ such that the distance graph of these points is isomorphic to $G$.
