\begin{lemma}\cite[Theorem 2]{DW87}\label{lem:nearregular}
    For every positive integer $n>0$ there exists a real number $ \lambda_n = \sqrt{1-\frac{1}{\Theta(n)}}$ such that every complete graph $G$ on $n$ vertices whose all edges have weights in $[\lambda_n \cdot \ell,\ell]$, for a positive real number $\ell$ is realizable in $\Rspace^{n-1}$. 
\end{lemma}

We use the above lemma to increase all the weights of an instance in Theorem~\ref{thm:graphsuperhard} by a fixed number in order to make it realizable in Euclidean space.

\begin{lemma}\label{lem:increase}
    Let $G$ be a weighted complete graph $G$ on $n$ vertices. Let $w_1$ and $w_2$ be the minimum and maximum weights of the edges of $G$ and let $\lambda_n$ be as defined in Lemma~\ref{lem:nearregular}.
For every $N$ such that $N\ge \max\{|w_1|,\frac{\lambda_nw_2-w_1}{1-\lambda_n}\}$, by increasing the weight of all edges in $G$ by $N$, we obtain a realizable graph in $\Rspace^{n-1}$.
\end{lemma}
\begin{proof}
     Increasing the weights of the edges in $G$ by $N$ results in a graph $G'$ with positive weights in which the minimum and maximum weights are $N+w_1$ and $N+w_2$. As $N> \frac{\lambda_nw_2-w_1}{1-\lambda_n}$ then $N+w_1 \geq \lambda_n(N+w_2)$ and hence by Lemma~\ref{lem:nearregular}, $G'$ is realizable in $\Rspace^{n-1}$.
     \qedhere
\end{proof}
\begin{theorem}\label{thm:emstnphard}
    The MAX-EMST-ratio problem is NP-hard.
\end{theorem}
\begin{proof}
    By Lemma~\ref{lem:increase}, the instances of the MAX-MST-ratio problem with weights $1$ and $n$ can be turned into a geometric graph by increasing the weights of all edges by a fixed amount. Note that this action does not change the optimal coloring of the graph in terms of the maximum MST-ratio. This is because the total number of edges in the MSTs of the two colors is always $n-2$. Moreover, the amount we add is $O(n^2)$, according to Lemma~\ref{lem:increase}. Thus, from any instance of the MAX-MST-ratio with weights $1$ and $n$, we can construct an instance of the MAX-EMST-ratio problem in polynomial time and hence by Theorem~\ref{thm:graphsuperhard}.
    \qedhere
\end{proof}

As established in Theorem~\ref{thm:emstnphard}, determining the maximum EMST-ratio is NP-hard. We conjecture that the problem remains NP-hard even when restricted to a specific dimension. In particular, we are interested in $\Rspace^2$ and $\Rspace^3$, as they are relevant for practical applications.
\begin{conjecture}
    % The problems $2$-MAX-EMST-ratio and $3$-MAX-EMST-ratio are NP-hard.
    The $k$-MAX-EMST-ratio problem for $k \in \{2,3\}$ is NP-hard.
\end{conjecture}




Theorem~\ref{thm:graphsuperhard} shows that it is even hard to approximate the maximum MST-ratio for general graphs. However, in Euclidean space, it is not difficult to approximate the maximum EMST-ratio as it cannot be too large. We show a general upper bound for the maximum MST-ratio in any metric space that leads to a simple $3$-approximation algorithm for the MAX-EMST-ratio problem. In the proof, we use the following well-known fact about the path double cover of trees.

\begin{lemma}[\cite{PDC14}]\label{lem:PartitionToPaths}
    Given a tree $T$ with $\ell$ leaves, there exist $\ell$ (not necessarily distinct) paths in $T$ such that each edge of $T$ is in precisely two of these paths.
\end{lemma}

