\section{Auxiliary Facts and Notations}
\begin{definition}[Rand$K$]
    \label{def:rand_k}
    Assume that $S$ is a random subset of $[d]$ such that $|S| = K$ for some $K \in [d]$. A stochastic mapping $\cC\,:\, \R^d \times \mathbb{S}_{\nu} \rightarrow \R^d$ is called Rand$K$ if
\begin{align*}
\cC(x;S) = \frac{d}{K} \sum_{j \in S} x_j e_j,
\end{align*}
where $\{e_i\}_{i=1}^d$ denotes the standard unit basis. The set $S$ can be produced with a uniform sampling of $[d]$ without replacement.
\end{definition}

\subsection{Notations}

$\N \eqdef \{1, 2, \dots\};$ $\norm{x}$ is the output of the standard Euclidean norm for all $x \in \R^d$; $\inp{x}{y} = \sum_{i=1}^{d} x_i y_i$ is the standard dot product; $\norm{A}$ is the standard spectral/operator norm for all $A \in \R^{d \times d};$ $g = \cO(f):$ exist $C > 0$ such that $g(z) \leq C \times f(z)$ for all $z \in \mathcal{Z};$ $g = \Omega(f):$ exist $C > 0$ such that $g(z) \geq C \times f(z)$ for all $z \in \mathcal{Z};$ $g = \Theta(f):$ $g = \cO(f)$ and $g = \Omega(f);$ $g = \widetilde{\cO}(f), g = \widetilde{\Omega}(f), g = \widetilde{\Theta}(f):$ the same as $g = \cO(f), g = \Omega(f), g = \Theta(f),$ respectively, but up to logarithmic factors; $g \simeq h:$ $g$ and $h$ are equal up to universal positive constants; $g \gtrsim h:$ $g$ greater or equal to $h$ up to universal positive constants.

\section{Lower Bound}
\label{sec:lower_bound}
\subsection{New Construction}
\label{sec:const}
For any $T, K \in \N,$ and $e \geq a > 1$ we define the function $F_{T,K,a} \,:\, \R^T \to \R$ such that
\begin{align}
  \label{eq:worst_case_copy}
  F_{T,K,a}(x) = -\sum_{i=1}^T \Psi_a(x_{i-K}) \dots \Psi_a(x_{i-2}) \Psi_a(x_{i-1})\Phi(x_i) + \sum_{i=1}^T \Gamma(x_i),
\end{align}
where $x_i$ is the $i$\textsuperscript{th} coordinate of a vector $x \in \R^T$ and
\begin{align*}
    \Psi_a(x) = \begin{cases}
        0, & x \leq 1/2, \\
        \exp\left(\log a \cdot \left(1 - \frac{1}{(2x - 1)^2}\right)\right), & x > 1/2,
    \end{cases}
    \qquad
    \Phi(x) = \sqrt{e} \int_{-\infty}^{x}e^{-\frac{1}{2}t^2}dt,
\end{align*}
and
\begin{align*}
  \Gamma(x) = \begin{cases}
    -x e^{1/x + 1},& x < 0, \\
    0, & x \geq 0.
\end{cases}
\end{align*}
We assume that $x_{0} = \dots = x_{-K + 1} \equiv 1.$ Importantly, throughout the lower bound analysis, we assume that $e \geq a > 1$, even if this assumption is not explicitly stated in all theorems.

We additionally define 
\begin{align*}
  &\textnormal{prog}^K(x) \eqdef \max \{i \geq 0\,|\,x_i \neq 0, x_{i - 1} \neq 0, \dots, x_{i - K + 1} \neq 0\} \\
  &(x_{0} = \dots = x_{-K + 1} \equiv 1),
\end{align*}
which extends $\textnormal{prog}(x) \equiv \textnormal{prog}^1(x) \eqdef \max \{i \geq~0\,|\,x_i \neq 0\} \,\, (x_0 \equiv 1).$

\subsection{Auxiliary Lemmas}
In this section, we list useful properties of the functions $\Phi,$ $\Gamma,$ $\Psi_a,$ and $F_{T,K,a}.$ We prove them in Section~\ref{sec:l_proof}.

\begin{lemma}[\citet{carmon2020lower}]
  \label{lemma:phi}
  Function $\Phi$ is twice differentiable and satisfies
  \begin{align*}
    0 \leq \Phi(x) \leq \sqrt{2 \pi e}, \quad 0 \leq \Phi'(x) \leq \sqrt{e}, \textnormal{ and } \abs{\Phi''(x)} \leq 27
  \end{align*}
  for all $x \in \R.$ Moreover, $\Phi'(x) > 1$ for all $-1 < x < 1.$
\end{lemma}

\begin{restatable}{lemma}{LEMMAONE}
  \label{lemma:gamma}
  Function $\Gamma$ is twice differentiable and satisfies
  \begin{align*}
    0 \leq \Gamma(x), \quad -e < \Gamma'(x) \leq 0, \textnormal{ and } 0 \leq \Gamma''(x) \leq 27 e^{-2}
  \end{align*}
  for all $x \in \R.$ Moreover, $\Gamma'(x) \leq -2$ for all $x \leq -1.$
\end{restatable}


\begin{restatable}{lemma}{LEMMATWO}
  \label{lemma:psi}
  Function $\Psi_a$ is twice differentiable and satisfies
  \begin{align*}
    0 \leq \Psi_a(x) < a, \quad 0 \leq \Psi_a'(x) \leq \frac{2 e}{\sqrt{\log a}}, \textnormal{ and } \abs{\Psi''_a(x)} \leq \frac{56 e}{\log a}
  \end{align*}
  for all $x \in \R$ and $1 < a \leq e.$ Moreover, $\Psi_a(x) \geq 1$ for all $x \geq 1$ and $1 < a \leq e.$
\end{restatable}

\begin{restatable}{lemma}{LEMMATHREE}
  \label{lemma:prog}
  For all $x \in \R^T,$ $\textnormal{prog}^1(\nabla F_{T,K,a}(x)) \leq \max\{\textnormal{prog}^K(x) + 1,\textnormal{prog}^1(x)\}.$
\end{restatable}

\begin{restatable}{lemma}{LEMMAFOUR}
  \label{lemma:worst_function_general}
  For all $x \in \R^T,$ if $\textnormal{prog}^K(x) < T,$ then $\norm{\nabla F_{T,K,a}(x)} > 1.$
\end{restatable}

\begin{restatable}{lemma}{LEMMAFIVE}
  \label{lemma:delta}
  Function $F_{T,K,a}$ satisfies
  \begin{align*}
    F_{T,K,a}(0) - \inf_{x \in \R^T} F_{T,K,a}(x) \leq \Delta^0(K, a) \cdot T,
  \end{align*}
  where $\Delta^0(K, a) \eqdef \sqrt{2 \pi e} \cdot a^K.$
\end{restatable}

\begin{restatable}{lemma}{LEMMASIX}
  \label{lemma:bound_grad}
  For all $x \in \R^T,$ $\norm{\nabla F_{T,K,a}(x)}_{\infty} \leq \gamma_{\infty}(K,a),$ where $\gamma_{\infty}(K,a) \eqdef 6 \sqrt{2 \pi} e^{3/2} \cdot \frac{K a^K}{\sqrt{\log a}}.$
\end{restatable}

\begin{restatable}{lemma}{LEMMASEVEN}
  \label{lemma:smooth}
  The function $F_{T,K,a}$ is $\ell_1(K, a)$--smooth, i.e., $\norm{\nabla^2 F_{T,K,a}(x)} \leq \ell_1(K, a)$
  for all $x \in \R^T,$ where $\ell_1(K, a) \eqdef 12 \sqrt{2 \pi} e^{5/2} \cdot \frac{K^2 a^{K}}{\log a}.$
\end{restatable}

\subsection{Proof of lemmas}
\label{sec:l_proof}

\LEMMAONE*

\begin{proof}
  The first fact is due to $\lim\limits_{\Delta \to 0} \frac{\Gamma(\Delta)}{\Delta} = 0,$ $\Gamma'(0) = 0,$ and $\lim\limits_{\Delta \to 0} \frac{\Gamma'(\Delta)}{\Delta} = 0.$ $\Gamma$ is clearly non-negative. Next, for all $x \leq 0,$
  \begin{align*}
    \Gamma'(x) = - e^{1/x + 1} + \frac{e^{1/x + 1}}{x}
  \end{align*}
  and
  \begin{align*}
    \Gamma''(x) = - \frac{e^{1/x + 1}}{x^3}.
  \end{align*}
  Thus, $\Gamma'$ is strongly increasing for all $x \leq 0,$ and $\lim\limits_{x \to -\infty} \Gamma'(x) = -e < \Gamma'(x) \leq 0.$ Next, $\Gamma''(x) \geq 0$ for all $x \leq 0,$ and $\max\limits_{x \leq 0} \Gamma''(x) = 27 e^{-2}$ for all $x \leq 0.$
\end{proof}

\LEMMATWO*

\begin{proof}
  The differentiability at $x = \frac{1}{2}$ follows from $\lim\limits_{\Delta \to 0} \frac{\Psi_a(\frac{1}{2} + \Delta)}{\Delta} = 0$ for all $a > 1.$ For all $x \leq \frac{1}{2},$ $\Psi'_a(x) = 0.$ For all $x > \frac{1}{2},$ we get
  \begin{align*}
    0 \leq \Psi'_a(x) 
    &= \frac{4 \log a}{(2 x - 1)^3}\exp\left(\log a \left(1 - \frac{1}{(2x - 1)^2}\right)\right) \\
    &= \frac{4 a}{\sqrt{\log a}} \times \frac{\log^{3/2} a}{(2 x - 1)^3}\exp\left(- \frac{\log a}{(2x - 1)^2}\right).
  \end{align*}
  Taking $t = \frac{\log^{1/2} a}{(2x - 1)} > 0$ and using $t^3 e^{-t^2} \leq \frac{1}{2},$ we get 
  \begin{align*}
    \Psi'_a(x) &\leq \frac{4 a}{\sqrt{\log a}} \times \frac{1}{2} \leq \frac{2 e}{\sqrt{\log a}}
  \end{align*}
  since $a \leq e.$ 

  Clearly, $\Psi_a(x) \geq 0$ for all $x \in \R,$ and $\Psi_a$ is non-decreasing. Moreover it is strongly monotonic for all $x > \frac{1}{2}.$ Thus $\Psi_a(x) < \lim\limits_{x \to \infty} \Psi_a(x) = a$ for all $x \in \R.$

  The twice differentiability at $x = \frac{1}{2}$ follows from $\lim\limits_{\Delta \to 0} \frac{\Psi'_a(\frac{1}{2} + \Delta)}{\Delta} = 0$ for all $a > 1.$ For all $x \leq \frac{1}{2},$ $\Psi''_a(x) = 0.$ For all $x > \frac{1}{2},$ taking the second derivative and using simple algebra, we get
  \begin{align*}
    \abs{\Psi''_a(x)} 
    &= \abs{-\frac{8 \log a \times (3 (2 x - 1)^2 - 2 \log a)}{(2 x - 1)^6}\exp\left(\log a \left(1 - \frac{1}{(2x - 1)^2}\right)\right)} \\
    &= \abs{\frac{8 a \log a \times (3 (2 x - 1)^2 - 2 \log a)}{(2 x - 1)^6}\exp\left(- \frac{\log a}{(2x - 1)^2}\right)} \\
    &\leq \abs{\frac{24 a \log a}{(2 x - 1)^4}\exp\left(- \frac{\log a}{(2x - 1)^2}\right)} + \abs{\frac{16 a \log^2 a}{(2 x - 1)^6}\exp\left(- \frac{\log a}{(2x - 1)^2}\right)} \\
    &= \frac{24 a}{\log a} \times \frac{\log^2 a}{(2 x - 1)^4}\exp\left(- \frac{\log a}{(2x - 1)^2}\right) + \frac{16 a}{\log a} \times \frac{\log^3 a}{(2 x - 1)^6}\exp\left(- \frac{\log a}{(2x - 1)^2}\right).
  \end{align*}
  Taking $t = \frac{\log a}{(2x - 1)^2} > 0$ and using $t^2 e^{-t} \leq 1$ and $t^3 e^{-t} \leq 2,$
  \begin{align*}
    \abs{\Psi''_a(x)} \leq \frac{24 a}{\log a} \times 1 + \frac{16 a}{\log a} \times 2 \leq \frac{56 e}{\log a}
  \end{align*}
  since $a \leq e.$
\end{proof}

\LEMMATHREE*

\begin{proof}
  Let $j = \textnormal{prog}^K(x)$ and $p = \textnormal{prog}^1(x),$ then
  \begin{align*}
    F_{T,K,a}(x) 
    &= -\sum_{i=1}^{j + 1} \Psi_a(x_{i-K}) \dots \Psi_a(x_{i-2}) \Psi_a(x_{i-1})\Phi(x_i) \\
    &\quad -\sum_{i=j+2}^{T} \Psi_a(x_{i-K}) \dots \Psi_a(x_{i-2}) \Psi_a(x_{i-1})\Phi(x_i) \\
    &\quad + \sum_{i=1}^{p} \Gamma(x_i) + \sum_{i=p+1}^{T} \Gamma(x_i).
  \end{align*}
  Since $j = \textnormal{prog}^K(x),$ for all $i \geq j + 2,$ at least one of the values $x_{i-K}, \dots, x_{i-2}, x_{i-1}$ is zero. Noting that $\Psi_a(0) = \Psi_a'(0) = 0,$ the gradient of the second sum is zero. The first sum depends only on the first $j + 1$ coordinates; thus, the gradient of the first sum is non-zero in at most the $(j + 1)$\textsuperscript{th} coordinate.

  Since $p = \textnormal{prog}^1(x),$ the gradient of the last sum is zero because $\Gamma'(0) = 0.$ And the gradient of the third sum has a non-zero value in at most the $p$\textsuperscript{th} coordinate.
\end{proof}

\LEMMAFOUR*

\begin{proof}
  For all $j \in [T],$ the partial derivative of $F_{T,K,a}$ with respect to $x_j$ is 
  \begin{equation}
  \label{eq:grad}
  \begin{aligned}
    \frac{\partial F_{T,K,a}}{\partial x_j}(x) = 
    \Big[
      & - \Psi_a(x_{j-K})  \dots \Psi_a(x_{j-1})\Phi'(x_j) \\
      &- \Psi_a(x_{j-K+1})  \dots  \Psi_a(x_{j-1}) \Psi'_a(x_{j})\Phi(x_{j+1}) \\
      &-\dots\\
      &- \Psi'_a(x_{j}) \Psi_a(x_{j+1})  \dots  \Psi_a(x_{\min\{j + K, T\} - 1}) \Phi(x_{\min\{j + K, T\}})\Big] + \Gamma'(x_j).
  \end{aligned}
  \end{equation}
  We now take the smallest $j \in [T]$ for which $x_j < 1$ and ${x_{j - 1}} \geq 1, \dots, {x_{j - K}} \geq 1.$ 

  If such $j$ does not exists, then ${x_1} \geq 1$ due to ${x_{0}} = \dots = {x_{-K + 1}} \equiv 1.$ Then ${x_2} \geq 1,$ and so on. Meaning that ${x_j} \geq 1$ for all $j \in [T],$ which contradicts the assumption of the theorem that $\textnormal{prog}^K(x) < T.$

  Fixing such $j,$ consider \eqref{eq:grad}.
  There are two cases. \\
  \emph{Case 1: $x_j > -1.$} Note that $\Psi, \Phi, \Psi', \Phi' \geq 0$ are non-negative and $\Gamma' \leq 0$ is non-positive. Thus 
  \begin{align*}
    \frac{\partial F_{T,K,a}}{\partial x_j}(x) \leq - \Psi_a(x_{j-K})  \dots  \Psi_a(x_{j-2}) \Psi_a(x_{j-1})\Phi'(x_j).
  \end{align*}
  Since ${x_{j - 1}} \geq 1, \dots, {x_{j - K}} \geq 1$ and $1 > x_j > -1$ (see Lemmas~\ref{lemma:phi} and \ref{lemma:psi}), we get
  \begin{align*}
    \frac{\partial F_{T,K,a}}{\partial x_j}(x) < -1.
  \end{align*}
  \emph{Case 2: $x_j \leq -1.$} Note that $\Psi, \Phi, \Psi', \Phi' \geq 0$ are non-negative. Thus
  \begin{align*}
    \frac{\partial F_{T,K,a}}{\partial x_j}(x) \leq \Gamma'(x_j).
  \end{align*}
  Since $x_j \leq -1$ (see Lemma~\ref{lemma:gamma}), we get
  \begin{align*}
    \frac{\partial F_{T,K,a}}{\partial x_j}(x) < -1.
  \end{align*}
  Finally, we can conclude that
  \begin{align*}
    \norm{\nabla F_{T,K,a}(x)} \geq \abs{\frac{\partial F_{T,K,a}}{\partial x_j}(x)} > 1.
  \end{align*}
\end{proof}

\LEMMAFIVE*

\begin{proof}
  Since $\Gamma(0) = 0$ and $\Psi_a, \Phi \geq 0,$ we get $F_{T,K,a}(0) \leq 0.$
  Next, due to $\Gamma(x) \geq 0,$ $0 \leq \Phi(x) \leq \sqrt{2 \pi e}$ and $0 \leq \Psi_a(x) \leq a$ for all $x \in \R^d,$
  \begin{align*}
    F_{T,K,a}(x) \geq -\sum_{i=1}^T \Psi_a(x_{i-K}) \dots \Psi_a(x_{i-2}) \Psi_a(x_{i-1})\Phi(x_i) \geq - T \sqrt{2 \pi e} \cdot a^K
  \end{align*}
  for all $x \in \R^T.$
\end{proof}

\LEMMASIX*

\begin{proof}
  Using \eqref{eq:grad},
  \begin{equation}
  \begin{aligned}
    \abs{\frac{\partial F_{T,K,a}}{\partial x_j}(x)} \leq 
    \Big|
      & \Psi_a(x_{j-K})  \dots \Psi_a(x_{j-1})\Phi'(x_j) \\
      & + \Psi_a(x_{j-K+1})  \dots  \Psi_a(x_{j-1}) \Psi'_a(x_{j})\Phi(x_{j+1}) \\
      &+ \dots\\
      &+ \Psi'_a(x_{j}) \Psi_a(x_{j+1})  \dots  \Psi_a(x_{\min\{j + K, T\} - 1}) \Phi(x_{\min\{j + K, T\}})\Big| + \abs{\Gamma'(x_j)}.
  \end{aligned}
  \end{equation}
  Thus, 
  \begin{equation}
  \begin{aligned}
    \abs{\frac{\partial F_{T,K,a}}{\partial x_j}(x)} \leq a^K \sqrt{e} + K a^{K-1} \sqrt{2 \pi e} \frac{2 e}{\sqrt{\log a}} + e \leq 6 \sqrt{2 \pi} e^{3/2} \frac{K a^K}{\sqrt{\log a}}
  \end{aligned}
  \end{equation}
  due to Lemmas~\ref{lemma:phi}, \ref{lemma:gamma}, and \ref{lemma:psi}.
\end{proof}

\LEMMASEVEN*

\begin{proof}
  Taking the second partial derivative in \eqref{eq:grad},
  \begin{equation}
  \begin{aligned}
      \frac{\partial^2 F_{T,K,a}}{\partial x_j^2}(x) = 
      \Big[
        & - \Psi_a(x_{j-K})  \dots  \Psi_a(x_{j-1}) \Phi''(x_j) \\
        &- \Psi_a(x_{j-K+1})  \dots  \Psi_a(x_{j-1}) \Psi''_a(x_{j})\Phi(x_{j+1}) \\
        &-\dots\\
        &- \Psi''_a(x_{j}) \Psi_a(x_{j+1})  \dots \Psi_a(x_{\min\{j + K, T\} - 1})\Phi(x_{\min\{j + K, T\}})\Big] + \Gamma''(x_j).
    \end{aligned}
    \end{equation}
Due to Lemmas~\ref{lemma:phi}, \ref{lemma:gamma}, and \ref{lemma:psi},
\begin{align}
  \abs{\frac{\partial^2 F_{T,K,a}}{\partial x_j^2}(x)} \leq \left[27 a^K + K \times \frac{56 \sqrt{2 \pi} e^{3/2} a^{K-1}}{\log a}\right] + 27 e^{-2} 
  \leq 168 \sqrt{2 \pi} e^{3/2} \cdot \frac{K a^{K}}{\log a}
  \label{eq:flsmMD}
\end{align}
Clearly, for all $\min\{j + K, T\} < i \leq T,$ 
\begin{align}
  \label{eq:kFpjo}
  \frac{\partial^2 F_{T,K,a}}{\partial x_j \partial x_{i}}(x) = 0
\end{align}
due to the construction of $F_{T,K,a}.$ 
Next, for all $j < i \leq \min\{j + K, T\},$
\begin{equation*}
\begin{aligned}
  \frac{\partial^2 F_{T,K,a}}{\partial x_j \partial x_i}(x) = 
  \Big[
    &- \Psi_a(x_{i-K})  \dots \Psi_a(x_{j-1}) \Psi'_a(x_{j}) \Psi_a(x_{j+1}) \dots \Psi_a(x_{i-1}) \Phi'(x_{i}) \\
    &- \Psi_a(x_{i-K+1})  \dots  \Psi_a(x_{j - 1}) \Psi'_a(x_{j}) \Psi_a(x_{j + 1}) \dots \Psi_a(x_{i - 1}) \Psi'_a(x_{i}) \Phi(x_{i+1}) \\
    &-\dots\\
    &- \Psi'_a(x_{j}) \Psi_a(x_{j + 1}) \dots \Psi_a(x_{i - 1}) \Psi'_a(x_{i}) \Psi_a(x_{i + 1}) \dots \Psi_a(x_{\min\{j + K, T\} - 1})\Phi(x_{\min\{j + K, T\}})\Big],
\end{aligned}
\end{equation*}
and 
\begin{align}
  \label{eq:DJnuJLUfxG}
  \abs{\frac{\partial^2 F_{T,K,a}}{\partial x_j \partial x_i}(x)} \leq \frac{2 e^{3/2} a^{K-1}}{\sqrt{\log a}} + (K - 1) \times \frac{4 \sqrt{2 \pi} e^{5/2} a^{K-2}}{\log a} \leq 4 \sqrt{2 \pi} e^{5/2} \cdot \frac{K a^{K}}{\log a}
\end{align}
for all $i \neq j \in [T]$ due to Lemmas~\ref{lemma:phi} and \ref{lemma:psi} and $e \geq a > 1$


Notice that $\nabla^2 F_{T,K,a}$ is $(2 K + 1)$--diagonal Hessian. Repeating a textbook analysis for completeness and denoting temporary $\mH \eqdef \nabla^2 F_{T,K,a}$, we will show that 
\begin{align}
  \label{eq:wFKcpfOWeaU}
  \norm{\nabla^2 F_{T,K,a} (x)} \leq (2 K + 1) \max_{i,j \in [T]} \abs{\frac{\partial^2 F_{T,K,a}}{\partial x_j \partial x_i}(x)}.
\end{align}
for all $x \in \R^T.$ Indeed, for all $x \in \R^T$ such that $\norm{x} \leq 1,$ 
\begin{align*}
  \abs{x^{\top} \mH x} = \abs{\sum_{i=1}^{T} x_i \sum_{j=1}^{T} x_j \mH_{ij}} = \abs{\sum_{i=1}^{T} x_i \sum_{j=\max\{i - K, 1\}}^{\min\{i + K, T\}} x_j \mH_{ij}} \leq \max_{i,j \in [T]} \abs{\mH_{ij}} \left(\sum_{i=1}^{T} \abs{x_i} \sum_{j=\max\{i - K, 1\}}^{\min\{i + K, T\}} \abs{x_j}\right),
\end{align*}
where the second equality due to $\mH$ is $(2 K + 1)$--diagonal. Using the Cauchy–Schwarz inequality,
\begin{align*}
  \abs{x^{\top} \mH x} \leq \max_{i,j \in [T]} \abs{\mH_{ij}} \sqrt{\sum_{i=1}^{T} x_i^2 \sum_{i=1}^{T} \left(\sum_{j=\max\{i - K, 1\}}^{\min\{i + K, T\}} \abs{x_j}\right)^2} \leq \max_{i,j \in [T]} \abs{\mH_{ij}} \sqrt{\sum_{i=1}^{T} \left(\sum_{j=\max\{i - K, 1\}}^{\min\{i + K, T\}} \abs{x_j}\right)^2}
\end{align*}
since $\norm{x} \leq 1.$ Next, using Jensen's inequality and $\norm{x} \leq 1,$
\begin{align*}
  \abs{x^{\top} \mH x} 
  &\leq \max_{i,j \in [T]} \abs{\mH_{ij}} \sqrt{(2 K + 1)\sum_{i=1}^{T} \sum_{j=\max\{i - K, 1\}}^{\min\{i + K, T\}} x_j^2} \leq \max_{i,j \in [T]} \abs{\mH_{ij}} \sqrt{(2 K + 1)^2 \sum_{i=1}^{T} x_i^2} \\
  &\leq (2 K + 1) \max_{i,j \in [T]} \abs{\mH_{ij}}.
\end{align*}
We have proved \eqref{eq:wFKcpfOWeaU}. It is left to combine \eqref{eq:wFKcpfOWeaU}, \eqref{eq:DJnuJLUfxG}, and \eqref{eq:flsmMD}.



\end{proof}

\section{Proof of Theorem~\ref{thm:main}}


\MAINTHEOREM*


\begin{proof}
  \textbf{(Step 1: Construction).} Using the construction from Section~\ref{sec:const}, we define a scaled version of it.
  Let us take any $\lambda > 0,$ $d, T \in \N,$ $d \geq T,$ and take the function $f\,:\,\R^d \to \R$ such that
  $$f(x) \eqdef \frac{L \lambda^2}{\ell_1(K, a)} F_{T,K,a}\left(\frac{x_{[T]}}{\lambda}\right),$$ where $\ell_1(K, a)$ is defined in Lemma~\ref{lemma:smooth} and 
  $x_{[T]} \in \R^T$ is the vector with the first $T$ coordinates of $x \in \R^d.$ Notice that the last $d - T$ coordinates are artificial.


  First, we have to show that $f$ is $L$-smooth and $f(0) - \inf_{x \in \R^d} f(x) \leq \Delta,$ Using Lemma~\ref{lemma:smooth},
  \begin{align*}
      \norm{\nabla f(x) - \nabla f(y)} 
      &= \frac{L \lambda}{\ell_1(K, a)} \norm{\nabla F_{T,K,a}\left(\frac{x_{[T]}}{\lambda}\right) - \nabla F_{T,K,a}\left(\frac{y_{[T]}}{\lambda}\right)} \leq L \lambda \norm{\frac{x_{[T]}}{\lambda} - \frac{y_{[T]}}{\lambda}} \\
      &= L \norm{x_{[T]} - y_{[T]}} \leq L \norm{x - y} \quad \forall x, y \in \R^d.
  \end{align*}
  Let us take $$T = \left\lfloor\frac{\Delta \cdot \ell_1(K, a)}{L \lambda^2 \cdot \Delta^0(K, a)}\right\rfloor.$$ Due to Lemma~\ref{lemma:delta},
  \begin{align*}
      f(0) - \inf_{x \in \R^d} f(x) = \frac{L \lambda^2}{\ell_1(K, a)} (F_{T,K,a}\left(0\right) - \inf_{x \in \R^T} F_{T,K,a}(x)) \leq \frac{L \lambda^2 \Delta^0(K, a) T}{\ell_1(K, a)} \leq \Delta,
  \end{align*}
  where $\Delta^0(K, a)$ is defined in Lemma~\ref{lemma:delta}.
  We also choose
  \begin{align}
  \label{eq:lambda}
  \lambda = \frac{\sqrt{2 \varepsilon} \ell_1(K, a)}{L}
  \end{align}
  to ensure that
  \begin{align}
    \label{eq:ElKnuvDAUgPNjjaLAn}
    \norm{\nabla f(x)}^2 = \frac{L^2 \lambda^2}{\ell_1^2(K, a)}\norm{\nabla F_{T,K,a} \left(\frac{x_{[T]}}{\lambda}\right)}^2 = 2 \varepsilon \norm{\nabla F_{T,K,a} \left(\frac{x_{[T]}}{\lambda}\right)}^2 > 2 \varepsilon \cdot \mathbbm{1}\left[\textnormal{prog}^K(x_{[T]}) < T\right],
  \end{align} 
  where the last inequality due to Lemma~\ref{lemma:worst_function_general}. Note that
  \begin{align}
    \label{eq:WzHRTJlPowGgA}
    T = \left\lfloor\frac{L \Delta}{2 \Delta^0(K, a) \cdot \ell_1(K, a) \cdot \varepsilon}\right\rfloor.
  \end{align}\\
  \textbf{(Step 2: Stochastic Oracle).} \\
  We take the stochastic oracle construction form \citep{arjevani2022lower}. For all $j \in [d],$
  \begin{align}
    \label{eq:stoch_constr}
    [\nabla f(x; \xi)]_j \eqdef \nabla_j f(x) \left(1 + \mathbbm{1}\left[j > \textnormal{prog}^1(x)\right]\left(\frac{\xi}{p_{\sigma}} - 1\right)\right) \quad \forall x \in \R^d,
  \end{align} and $\mathcal{D}_{\xi} = \textnormal{Bernouilli}(p_{\sigma})$ for all $j \in [n],$ where $p_{\sigma} \in (0, 1].$ 
  We denote $[x]_j$ as the $j$\textsuperscript{th} index of a vector $x \in \R^d.$
  It is left to show this mapping is unbiased and $\sigma^2$-variance-bounded. Indeed, $$\Exp{[\nabla f(x, \xi)]_i} = \nabla_i f(x) \left(1 + \mathbbm{1}\left[i > \textnormal{prog}^1(x)\right]\left(\frac{\Exp{\xi}}{p_{\sigma}} - 1\right)\right) = \nabla_i f(x)$$ for all $i \in [d],$ and
  \begin{align*}
      \Exp{\norm{\nabla f(x; \xi) - \nabla f(x)}^2} \leq \max_{j \in [d]} \left|\nabla_j f(x)\right|^2\Exp{\left(\frac{\xi}{p_{\sigma}} - 1\right)^2}
  \end{align*}
  because the difference is non-zero only in one coordinate. Thus
  \begin{align*}
      \Exp{\norm{\nabla f(x, \xi) - \nabla f(x)}^2} &\leq \frac{\norm{\nabla f(x)}_{\infty}^2(1 - p_{\sigma})}{p_{\sigma}} = \frac{L^2 \lambda^2 \norm{F_{T,K,a}\left(\frac{x_{[T]}}{\lambda}\right)}_{\infty}^2(1 - p_{\sigma})}{\ell^2_1(K, a) p_{\sigma}} \\
      &\leq \frac{L^2 \lambda^2 \gamma_{\infty}^2(K, a) (1 - p_{\sigma})}{\ell^2_1(K, a) p_{\sigma}},
  \end{align*}
  where we use Lemma~\ref{lemma:bound_grad} in the last inequality. Taking
  \begin{align}
  p_{\sigma} = \min\left\{\frac{L^2 \lambda^2 \gamma_{\infty}^2(K, a)}{\sigma^2 \ell_1^2(K, a)}, 1\right\} \overset{\eqref{eq:lambda}}{=} \min\left\{\frac{2 \varepsilon \gamma_{\infty}^2(K, a)}{\sigma^2}, 1\right\},
  \label{eq:JvLFTLPbL}
  \end{align}
  we ensure that $\Exp{\norm{\nabla f(x, \xi) - \nabla f(x)}^2} \leq \sigma^2.$

  \textbf{(Step 3: Reduction to the Analysis of Concentration).} 
  At the beginning, due to Definition~\ref{def:zero}, $s^0_i = 0$ for all $i \in [n].$ Thus, if $k = 0,$ all workers can receive zero vectors from the server. Thus, at the beginning, all workers can only calculate stochastic gradients at the point zero.

  Let $t^{1,i}$ denote the earliest time at which all of the first $K$ coordinates become non-zero in the local information available to worker~$i$. In other words, $t^{1,i}$ is the first time when worker~$i$ has \emph{discovered} all of the first $K$ coordinates. Consequently, prior to time 
  \begin{align}
    \label{eq:time_1}
    t_{1} \eqdef \min_{i \in [n]} t_{1,i}
  \end{align}
  neither the server nor any worker is able to discover (filled with non-zero values) the $(K + 1)$\textsuperscript{th} and subsequent coordinates due to Lemma~\ref{lemma:prog}.

  \textbf{There are two options by which a worker may discover a new non-zero coordinate: through local stochastic computations or through communication from the server.}\\~\\
  \textbf{Option 1:} In the first option, a worker computes a stochastic gradient, which takes $h$ seconds. However, due to the construction of stochastic gradients, even if the computation is completed, the worker will not make progress or discover a new non-zero coordinate, as it will be zeroed out with probability $p_{\sigma}$. 
  Let $\eta_{1,i,1}$ be the number of stochastic gradients computations\footnote{It is possible that $\Prob{\eta_{1,i,1} = \infty} > 0$ if, for instance, the algorithm decides to stop calculating stochastic gradients. And even $\Prob{\eta_{1,i,1} = \infty} = 1$ if it does not calculate at all.} until the first moment when a coordinate is not zeroed out in \eqref{eq:stoch_constr} in worker $i.$ Assume that $\xi_1, \xi_2, \dots$ is a stream of i.i.d. random Bernoulli variables from \eqref{eq:stoch_constr} in  worker $i$ (all workers have different streams), then
  \begin{align*}
    \Prob{\eta_{1,i,1} \leq t} 
    &\leq \sum_{k=1}^{\flr{t}} \Prob{\xi_k = 1, \xi_{k-1} = 0, \dots, \xi_{1} = 0} = \sum_{k=1}^{\flr{t}} p_{\sigma} (1 - p_{\sigma})^{j - 1} \leq t p_{\sigma}.
  \end{align*}
  for all $t \geq 0.$ Similarly, let $\eta_{1,i,k}$ denote the number of stochastic gradient computations until the first moment when a coordinate is not zeroed out in \eqref{eq:stoch_constr}, after the moment when the $(k - 1)$\textsuperscript{th} coordinate is no longer zeroed out in worker $i.$ In other words, worker $i$ should calculate $\eta_{1,i,1}$ stochastic gradients to discover the first coordinate, calculate $\eta_{1,i,2}$ stochastic gradients to discover the second coordinate, and so on. Since the draws of $\xi$ in \eqref{eq:stoch_constr} are i.i.d., we can conclude that
  \begin{align*}
    \ProbCond{\eta_{1,i,k} \leq t}{\eta_{1,i,k-1}, \dots, \eta_{1,i,1}} \leq t p_{\sigma}
  \end{align*}
  for all $k \geq 1$ and $t \geq 0.$
  \\~\\
  \textbf{Option 2:} In the second option, worker $i$ receives $P \in \{0, \dots, d\}$ random coordinates with the set of indices $\{\nu_{1,1}, \dots, \nu_{1,P}\}$ \emph{without replacement}, where it takes $\tau_{\textnormal{s}}$ seconds to receive one coordinate. Then, the worker receives $\bar{P} \in \{0, \dots, d\}$ random coordinates with the set of indices $\{\nu_{2,1}, \dots, \nu_{2,\bar{P}}\}$ \emph{without replacement}, and so on (all workers get different sets; we drop the indices of the workers in the notations).

  Consequently, the worker receives a stream of coordinate indices
  $(\nu_1, \nu_2, \dots)$ 
  where we concatenated the sets of indices, preserving the exact order in which the server sampled them. Note that all workers have different streams, and we now focus on one worker.

  Notice that 
  \begin{align*}
    \Prob{\nu_1 \in [K]} = \frac{K}{d}
  \end{align*}
  since $\nu_1$ is uniformly random coordinate from the set $[d].$ Next, 
  \begin{align*}
    \ProbCond{\nu_2 \in [K]}{\nu_1} \leq \frac{K}{d - 1},
  \end{align*}
  because either $\nu_1 \in [K]$, in which case the probability is $\frac{K - 1}{d - 1}$, or $\nu_1 \not\in [K]$, in which case the probability is $\frac{K}{d - 1}$. Using the same reasoning, 
  \begin{align*}
    \ProbCond{\nu_i \in [K]}{\nu_1, \dots, \nu_{i - 1}} \leq \frac{K}{d - i + 1}.
  \end{align*}
  for all $i \leq d.$ 

  Hence, the worker receives a stream of coordinates $\nu_1, \nu_2, \dots$ such that $\ProbCond{\nu_i \in [K]}{\nu_1, \dots, \nu_{i - 1}} \leq \frac{K}{d - i + 1}$ for all $i \leq d.$  
  Let $\mu_{1,i,1}$ be the number of received coordinates until the moment when the last received coordinate belongs to $[K]$ in worker $i.$
  Similarly, let $\mu_{1,i,k}$ be the number of received coordinates until the moment when the last received coordinate belongs to $[K]$, after the $(k - 1)$\textsuperscript{th} time this has happened in worker $i.$ In other words, worker $i$ should receive $\mu_{1,i,1}$ coordinates to obtain a coordinate that belongs to $[K]$. To get the next coordinate that belongs to $[K]$, the worker should receive $\mu_{1,i,2}$ coordinates, and so on. 
  Then,
  \begin{align*}
    \Prob{\mu_{1,i,1} = j} 
    &= \Prob{\nu_j \in [K], \nu_{j-1} \not\in [K], \dots, \nu_{1} \not\in [K]} \\
    &= \ProbCond{\nu_j \in [K]}{\nu_{j-1} \not\in [K], \dots, \nu_{1} \not\in [K]} \Prob{\nu_{j-1} \not\in [K], \dots, \nu_{1} \not\in [K]} \leq \frac{K}{d - j + 1}
  \end{align*}
  for all $1 \leq j \leq d,$ and 
  \begin{align}
    \label{eq:TXdhtULbbzaLGikrg}
    \Prob{\mu_{1,i,1} \leq t} = \sum_{j = 1}^{\flr{t}} \Prob{\mu_{1,i,1} = j} \leq \frac{K t}{d - t + 1}.
  \end{align}
  for all $0 \leq t \leq d.$
  Similarly,
  \begin{align*}
    &\ProbCond{\mu_{1,i,k} = j}{\mu_{1,i,k - 1}, \dots, \mu_{1,i,1}} \\
    &=\ProbCond{\nu_{u + j} \in [K], \nu_{u + j-1} \not\in [K], \dots, \nu_{u + 1} \not\in [K]}{\nu_{u} \in [K], \dots, \nu_{1} \not\in [K]} \\
    &\leq \frac{K}{\max\{d - u, 0\} - j + 1},
  \end{align*}
  where $u = \sum_{j = 1}^{k - 1}\mu_{1,i,j},$ for all $j \leq \max\{d - u, 0\}.$ Thus,
  \begin{align*}
    \ProbCond{\mu_{1,i,k} \leq t}{\mu_{1,i,k - 1}, \dots, \mu_{1,i,1}} \leq \frac{K t}{\max\{d - \sum_{j = 1}^{k - 1}\mu_{1,i,j}, 0\} - t + 1},
  \end{align*}
  for all $0 \leq t \leq \max\{d - \sum_{j = 1}^{k - 1}\mu_{1,i,j}, 0\}.$

  Recall that the workers can discover new non-zero coordinates only through the stochastic processes discussed above. To discover all of the first $K$ coordinates, either the first or the second process must uncover at least $\frac{K}{2}$ coordinates\footnote{At the end of the proof, we take $K \textnormal{ mod } 2 = 0.$}. If worker $i$ has discovered fewer than $\frac{K}{2}$ coordinates through stochastic gradient computations and fewer than $\frac{K}{2}$ coordinates through receiving coordinates from the server, then it will not be able to cover all $K$ coordinates. Hence,
  \begin{align*}
    t_1 \geq \min_{i \in [n]} \left\{\min\left\{h \sum_{k=1}^{\frac{K}{2}} \eta_{1,i,k}, \tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{1,i,k}\right\}\right\},
  \end{align*}
  where $t_1$ is defined in \eqref{eq:time_1}. This is because $h \sum_{k=1}^{\frac{K}{2}} \eta_{1,i,k}$ is the time required to obtain $\frac{K}{2}$ ``lucky'' stochastic gradients, those for which the coordinates are not zeroed out, and $\tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{1,i,k}$ is the time required to receive $\frac{K}{2}$ ``lucky'' coordinates that belong to $[K]$.

  Once the workers have discovered the first $K$ coordinates, the discovery process repeats for the set $\{K + 1, \dots, 2K\}$, which similarly requires at least
  \begin{align*}
    \min_{i \in [n]} \left\{\min\left\{h \sum_{k=1}^{\frac{K}{2}} \eta_{2,i,k}, \tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{2,i,k}\right\}\right\}
  \end{align*}
  seconds, where $\{\eta_{b,i,k}\}$ and $\{\mu_{b,i,k}\}$ are random variables such that
  \begin{align}
    \label{eq:kEAXDdRCaGsOmJWjx1}
    \ProbCond{\eta_{b,i,k} \leq t}{\eta_{b,i,k - 1}, \dots, \eta_{b,i,1}, \mathcal{G}_{b-1}} \leq t p_{\sigma}
  \end{align}
  for all $b \geq 1, k \geq 1,$ $i \in [n], t \geq 0,$ and
  \begin{align}
    \label{eq:kEAXDdRCaGsOmJWjx2}
    \ProbCond{\mu_{b,i,k} \leq t}{\mu_{b,i,k - 1}, \dots, \mu_{b,i,1}, \mathcal{G}_{b-1}} \leq \frac{K t}{\max\{d - \sum_{j=1}^{k-1} \mu_{b,i,j}, 0\} - t + 1}
  \end{align}
  for all $b \geq 1, k \geq 1,$ $i \in [n],$ and $t \leq \max\{d - \sum_{j=1}^{k-1} \mu_{b,i,j}, 0\},$ where $\mathcal{G}_{b-1}$ is the sigma-algebra generated by $\{\eta_{b',i,k}\}_{i \in [n], k \in [\frac{K}{2}], b' < b}$ and $\{\mu_{b',i,k}\}_{i \in [n], k \in [\frac{K}{2}], b' < b}$ and $u = \sum_{j=1}^{k-1} \mu_{b,i,j}.$ 

  More formally, $\eta_{2,i,k}$ can be defined as the number of stochastic gradient computations until the first moment when a coordinate is not zeroed out in \eqref{eq:stoch_constr}, after the moment when the $(k - 1)$\textsuperscript{th} coordinate is no longer zeroed out, when $\textnormal{prog}^K$ of the input points to the stochastic gradients is $\geq K,$ and $\mu_{2,i,k}$ be the number of received coordinates until the moment when the last received coordinate belongs to $\{K + 1, \dots, 2 K\}$, after the $(k - 1)$\textsuperscript{th} time this has happened, when $\textnormal{prog}^1$ of the input points to the compressor is $\geq K + 1,$ and so on.

  We define
  \begin{align}
    \label{eq:ybanDfAgA}
    p_{K} \eqdef \frac{2 K}{d}.
  \end{align}

  Finally, to discover the $T$\textsuperscript{th} coordinates it takes at least 
  \begin{align*}
    \sum_{b = 1}^{B} \min_{i \in [n]} \left\{\min\left\{h \sum_{k=1}^{\frac{K}{2}} \eta_{b,i,k}, \tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{b,i,k}\right\}\right\}
  \end{align*}
  seconds, where $B = \flr{\frac{T}{K}}.$ It it left to use the following lemma.
  \begin{restatable}{lemma}{MAINLEMMA}
    \label{lemma:main_concet_lemma}
    Let $\{\eta_{b,i,j}\}_{i,j,b \geq 0}$ and $\{\mu_{b,i,j}\}_{i,j,b \geq 0}$ be random variables such that
    \begin{align}
      \label{eq:kEAXDdRCaGsOmJWjx1new}
      \ProbCond{\eta_{b,i,k} \leq t}{\eta_{b,i,k - 1}, \dots, \eta_{b,i,1}, \mathcal{G}_{b-1}} \leq t p_{\sigma}
    \end{align}
    for all $b \geq 1, k \geq 1,$ $i \in [n], t \geq 0,$ and
    \begin{align}
      \label{eq:kEAXDdRCaGsOmJWjx2new}
      \ProbCond{\mu_{b,i,k} \leq t}{\mu_{b,i,k - 1}, \dots, \mu_{b,i,1}, \mathcal{G}_{b-1}} \leq \frac{K t}{\max\{d - \sum_{j=1}^{k-1} \mu_{b,i,j}, 0\} - t + 1},
    \end{align}
    for all $b \geq 1, k \geq 1,$ $i \in [n],$ $0 \leq t \leq \max\{d - \sum_{j=1}^{k-1} \mu_{b,i,j}, 0\},$ and $1 \leq K \leq d,$ where $\mathcal{G}_{b-1}$ is the sigma-algebra generated by $\{\eta_{b',i,k}\}_{i \in [n], k \in [\frac{K}{2}], b' < b}$ and $\{\mu_{b',i,k}\}_{i \in [n], k \in [\frac{K}{2}], b' < b}.$ Then
    \begin{align*}
      \Prob{\sum_{b = 1}^{B} \min_{i \in [n]} \left\{\min\left\{h \sum_{k=1}^{\frac{K}{2}} \eta_{b,i,k}, \tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{b,i,k}\right\}\right\} \leq \bar{t}} \leq \delta
    \end{align*}
    with 
    \begin{align}
      \label{eq:T}
      \bar{t} \eqdef \frac{B K + \log \delta}{e^{4} (2 n)^{2 / K} (4 + \frac{2}{K} \log (2n))} \min\left\{\frac{h}{p_{\sigma}}, \frac{\tau_{\textnormal{s}}}{p_{K}}\right\},
    \end{align}
    where 
    \begin{align*}
      p_{K} \eqdef \frac{2 K}{d}.
    \end{align*}
  \end{restatable}
  \textbf{(Step 4: Endgame).} 
  Thus, with probability at least $1 - \delta$, any zero-respecting algorithm requires at least $\bar{t}$ seconds to discover the $T$\textsuperscript{th} coordinate. Since $\textnormal{prog}^K(x) \leq \textnormal{prog}^1(x)$ for all $x \in \R^T$, and due to \eqref{eq:ElKnuvDAUgPNjjaLAn},
  \begin{align*}
  \inf_{y \in S_{t}} \norm{\nabla f(y)}^2 > 2 \varepsilon \inf_{y \in S_{t}} \mathbbm{1}\left[\textnormal{prog}^1(y_{[T]}) < T\right],
  \end{align*}
  where $S_{t}$ is the set of all possible candidate points to be an $\varepsilon$--stationary point up to time $t,$ which can be computed by $A.$ Taking $\delta = \frac{1}{2},$
  \begin{align*}
    \Exp{\inf_{y \in S_{t}} \norm{\nabla f(y)}^2} > 2 \varepsilon \Exp{\inf_{y \in S_{t}} \mathbbm{1}\left[\textnormal{prog}^1(y_{[T]}) < T\right]} \geq \varepsilon,
  \end{align*}
  for $t = \frac{1}{2} \bar{t}$ because $\textnormal{prog}^1(y_{[T]}) < T$ for all $y \in S_{t}$ with probability at least $\frac{1}{2}.$

  It is left to choose $K$ and $a,$ and substitute all quantities to $\bar{t}.$ Using $B = \flr{\frac{T}{K}},$
  \begin{align*}
    \bar{t} 
    = \frac{\flr{\frac{T}{K}} K - \log 8}{e^{4} (2 n)^{2 / K} (4 + \frac{2}{K} \log (2n))} \min\left\{\frac{h}{p_{\sigma}}, \frac{\tau_{\textnormal{s}}}{p_{K}}\right\} \\
    \geq \frac{T - K - \log 8}{e^{4} (2 n)^{2 / K} (4 + \frac{2}{K} \log (2n))} \min\left\{\frac{h}{p_{\sigma}}, \frac{\tau_{\textnormal{s}}}{p_{K}}\right\}.
  \end{align*}
  Due to \eqref{eq:WzHRTJlPowGgA}, \eqref{eq:JvLFTLPbL}, and \eqref{eq:ybanDfAgA},
  \begin{align*}
    \bar{t} 
    \geq \frac{\left\lfloor\frac{L \Delta}{2 \Delta^0(K, a) \cdot \ell_1(K, a) \cdot \varepsilon}\right\rfloor - K - \log 8}{e^{4} (2 n)^{2 / K} (4 + \frac{2}{K} \log (2n))} \min\left\{\max\left\{h, \frac{h \sigma^2}{2 \varepsilon \gamma_{\infty}^2(K, a)}\right\}, \frac{\tau_{\textnormal{s}} d}{2 K}\right\}.
  \end{align*}
  Using the definitions of $\Delta^0(K, a),$ $\gamma_{\infty}(K,a),$ and $\ell_1(K, a),$
  \begin{align*}
    \bar{t} 
    &\geq \left(e^{4} (2 n)^{2 / K} \left(4 + \frac{2}{K} \log (2n)\right)\right)^{-1}\left(\left\lfloor\frac{L \Delta \log a}{48 \pi e^{3} K^2 a^{2 K} \varepsilon}\right\rfloor - K - \log 8\right) \min\left\{\max\left\{h, \frac{h \sigma^2 \log a}{144 \pi e^{3} K^2 a^{2 K} \varepsilon}\right\}, \frac{\tau_{\textnormal{s}} d}{2 K}\right\}.
  \end{align*}
  We can take any $a$ from the interval $(1, e].$ We choose $a = 1 + \frac{1}{K},$ then $\log a = \log\left(1 + \frac{1}{K}\right) \geq \frac{1}{2 K}$ for all $K \geq 1,$ $a^{2 K} \leq e^2$ for all $K \geq 1,$ and 
  \begin{align*}
    \bar{t} 
    &\geq \left(e^{4} (2 n)^{2 / K} \left(4 + \frac{2}{K} \log (2n)\right)\right)^{-1}\left(\left\lfloor\frac{L \Delta}{96 \pi e^{5} K^3 \varepsilon}\right\rfloor - K - \log 8\right) \min\left\{\max\left\{h, \frac{h \sigma^2}{288 \pi e^{5} K^3 \varepsilon}\right\}, \frac{\tau_{\textnormal{s}} d}{2 K}\right\}.
  \end{align*}
  Taking $K = 2 \ceil{2 \log (2 n)},$ $(2 n)^{2 / K} \leq e,$ $K \leq 16 \log (n + 1)$ and
  \begin{align*}
    \bar{t} 
    &\geq \frac{1}{5 e^{5}} \left(\left\lfloor\frac{L \Delta}{96 \cdot 8^4 \pi e^{5} \log^3 (n + 1) \varepsilon}\right\rfloor - 32 \log (n + 1)\right) \min\left\{\max\left\{h, \frac{h \sigma^2}{288 \cdot 8^4 \pi e^{5} \log^3 (n + 1) \varepsilon}\right\}, \frac{\tau_{\textnormal{s}} d}{32 \log (n + 1)}\right\} \\
    &\geq \frac{1}{5 e^{5}} \left(\frac{L \Delta}{96 \cdot 8^4 \pi e^{5} \log^3 (n + 1) \varepsilon} - 36 \log (n + 1)\right) \min\left\{\max\left\{h, \frac{h \sigma^2}{288 \cdot 8^4 \pi e^{5} \log^3 (n + 1) \varepsilon}\right\}, \frac{\tau_{\textnormal{s}} d}{32 \log (n + 1)}\right\}.
  \end{align*}
  We assume $\frac{L \Delta}{\varepsilon} \geq \bar{c}_1 \log^4 (n + 1)$ for a universal constant $\bar{c}_1.$ Taking $\bar{c}_1$ large enough, one can see that
  \begin{align*}
    \bar{t} 
    &\geq \frac{1}{5 e^{5}} \left(\frac{L \Delta}{2 \cdot 96 \cdot 8^4 \pi e^{5} \log^3 (n + 1) \varepsilon}\right) \min\left\{\max\left\{h, \frac{h \sigma^2}{288 \cdot 8^4 \pi e^{5} \log^3 (n + 1) \varepsilon}\right\}, \frac{\tau_{\textnormal{s}} d}{32 \log (n + 1)}\right\}.
  \end{align*}
  For a small enough universal $\bar{c}_2,$ we get the inequality
  \begin{align*}
    \bar{t} 
    &\geq \bar{c}_2 \times \left(\frac{L \Delta}{\log^3 (n + 1) \varepsilon}\right) \min\left\{\max\left\{h, \frac{h \sigma^2}{\log^3 (n + 1) \varepsilon}\right\}, \frac{\tau_{\textnormal{s}} d}{\log (n + 1)}\right\},
  \end{align*}
  which finishes the proof. Notice that we can take
  \begin{align*}
    d \geq T = \left\lfloor\frac{L \Delta \log a}{48 \pi e^{3} K^2 a^{2K} \varepsilon}\right\rfloor = \Theta\left(\frac{L \Delta}{\log^3(n + 1) \varepsilon}\right).
  \end{align*}






\end{proof}

\subsection{Main Concentration Lemma}
\MAINLEMMA*

\begin{proof}
  Let us temporarily define $\beta_{b,i} \eqdef \min\left\{h \sum_{k=1}^{\frac{K}{2}} \eta_{b,i,k}, \tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{b,i,k}\right\}.$ Using Chernoff's method, we get
  \begin{equation}
  \label{eq:GQkgle}
  \begin{aligned}
    &\Prob{\sum_{b = 1}^{B} \min_{i \in [n]} \beta_{b,i} \leq \bar{t}} = \Prob{\exp\left(-\sum_{b = 1}^{B} \lambda \min_{i \in [n]} \beta_{b,i}\right) \geq \exp\left(-\lambda \bar{t}\right)} \\
    &\leq \exp\left(\lambda \bar{t}\right) \Exp{\exp\left(-\sum_{b = 1}^{B} \lambda \min_{i \in [n]} \beta_{b,i}\right)} \\
    &= \exp\left(\lambda \bar{t}\right) \Exp{\ExpCond{\exp\left(-\lambda \min_{i \in [n]} \beta_{B,i}\right)}{\mathcal{G}_{B-1}} \exp\left(- \sum_{b = 1}^{B - 1} \lambda \min_{i \in [n]} \beta_{b,i}\right)}
  \end{aligned}
  \end{equation}
  for all $\lambda > 0$ since $\beta_{1,i}, \dots, \beta_{B-1,i}$ are $\mathcal{G}_{B-1}$--measurable. Consider the inner expectation separately:
  \begin{align*}
    \ExpCond{\exp\left(-\lambda \min_{i \in [n]} \beta_{B,i}\right)}{\mathcal{G}_{B-1}} = \ExpCond{\max_{i \in [n]} \exp\left(-\lambda \beta_{B,i}\right)}{\mathcal{G}_{B-1}} \leq \sum_{i=1}^{n} \ExpCond{\exp\left(-\lambda \beta_{B,i}\right)}{\mathcal{G}_{B-1}},
  \end{align*}
  where we bound $\max$ by $\sum.$ Using the temporal definitions of $\{\beta_{B,i}\},$
  \begin{equation}
  \label{eq:dTcxdO}
  \begin{aligned}
    &\ExpCond{\exp\left(-\lambda \min_{i \in [n]} \beta_{B,i}\right)}{\mathcal{G}_{B-1}} \\
    &\leq \sum_{i=1}^{n} \ExpCond{\exp\left(-\lambda \min\left\{h \sum_{k=1}^{\frac{K}{2}} \eta_{B,i,k}, \tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{B,i,k}\right\}\right)}{\mathcal{G}_{B-1}} \\
    &= \sum_{i=1}^{n} \ExpCond{\max\left\{\exp\left(-\lambda h \sum_{k=1}^{\frac{K}{2}} \eta_{B,i,k}\right), \exp\left(-\lambda \tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{B,i,k}\right)\right\}}{\mathcal{G}_{B-1}} \\
    &\leq \underbrace{\sum_{i=1}^{n} \ExpCond{\exp\left(-\lambda h \sum_{k=1}^{\frac{K}{2}} \eta_{B,i,k}\right)}{\mathcal{G}_{B-1}}}_{I_1 \eqdef} + \underbrace{\sum_{i=1}^{n} \ExpCond{\exp\left(-\lambda \tau_{\textnormal{s}} \sum_{k=1}^{\frac{K}{2}} \mu_{B,i,k}\right)}{\mathcal{G}_{B-1}}}_{I_2^{\frac{K}{2}} \eqdef}.
  \end{aligned}
  \end{equation}
  Using the tower property,
  \begin{align}
    \label{eq:puvNyZQmYzl}
    I_1 = \sum_{i=1}^{n} \ExpCond{\underbrace{\ExpCond{\exp\left(-\lambda h \eta_{B,i,\frac{K}{2}}\right)}{\eta_{B,i,\frac{K}{2} - 1}, \dots, \eta_{B,i,1}, \mathcal{G}_{B-1}}}_{J_1 \eqdef} \exp\left(-\lambda h \sum_{k=1}^{\frac{K}{2} - 1} \eta_{B,i,k}\right)}{\mathcal{G}_{B-1}}.
  \end{align}
  Next,
  \begin{align*}
    J_1 
    &\eqdef \ExpCond{\exp\left(-\lambda h \eta_{B,i,\frac{K}{2}}\right)}{\eta_{B,i,\frac{K}{2} - 1}, \dots, \eta_{B,i,1}, \mathcal{G}_{B-1}} \\
    &\leq \exp\left(-\lambda t\right) \ProbCond{h \eta_{B,i,\frac{K}{2}} > t}{\eta_{B,i,\frac{K}{2} - 1}, \dots, \eta_{B,i,1}, \mathcal{G}_{B-1}} \\
    &\quad + \ProbCond{h \eta_{B,i,\frac{K}{2}} \leq t}{\eta_{B,i,\frac{K}{2} - 1}, \dots, \eta_{B,i,1}, \mathcal{G}_{B-1}} \\
    &= \exp\left(-\lambda t\right) + (1 - \exp\left(-\lambda h t\right)) \ProbCond{h \eta_{B,i,\frac{K}{2}} \leq t}{\eta_{B,i,\frac{K}{2} - 1}, \dots, \eta_{B,i,1}, \mathcal{G}_{B-1}} \\
    &\leq \exp\left(-\lambda t\right) + \ProbCond{h \eta_{B,i,\frac{K}{2}} \leq t}{\eta_{B,i,\frac{K}{2} - 1}, \dots, \eta_{B,i,1}, \mathcal{G}_{B-1}} \\
    &= \exp\left(-\lambda t\right) + \ProbCond{\eta_{B,i,\frac{K}{2}} \leq \frac{t}{h}}{\eta_{B,i,\frac{K}{2} - 1}, \dots, \eta_{B,i,1}, \mathcal{G}_{B-1}}
  \end{align*}
  for all $t \geq 0.$ Due to \eqref{eq:kEAXDdRCaGsOmJWjx1new},
  \begin{align*}
    J_1 \leq \exp\left(-\lambda t\right) + \frac{t p_{\sigma}}{h}.
  \end{align*}
  Substituting to \eqref{eq:puvNyZQmYzl},
  \begin{align*}
    I_1 \leq \sum_{i=1}^{n} \left(\exp\left(-\lambda t\right) + \frac{t p_{\sigma}}{h}\right) \ExpCond{\exp\left(-\lambda h \sum_{k=1}^{\frac{K}{2} - 1} \eta_{B,i,k}\right)}{\mathcal{G}_{B-1}}.
  \end{align*}
  Using the same arguments $\frac{K}{2} - 1$ times, we obtain
  \begin{align}
    \label{eq:Hqaut}
    I_1 \leq n \left(\exp\left(-\lambda t\right) + \frac{t p_{\sigma}}{h}\right)^{\frac{K}{2}}
  \end{align}
  for all $t \geq 0.$ The analysis of $I_2^{K / 2}$ a little bit more evolved. For all $1 \leq j \leq \frac{K}{2},$ 
  \begin{align*}
    I_2^{j} 
    &\eqdef \sum_{i=1}^{n} \ExpCond{ \exp\left(-\lambda \tau_{\textnormal{s}} \sum_{k=1}^{j} \mu_{B,i,k}\right)}{\mathcal{G}_{B-1}} \\
    &= \sum_{i=1}^{n} \ExpCond{\underbrace{\ExpCond{\exp\left(-\lambda \tau_{\textnormal{s}} \mu_{B,i,j}\right)}{\mu_{B,i,j - 1}, \dots, \mu_{B,i,1}, \mathcal{G}_{B-1}} \exp\left(-\lambda \tau_{\textnormal{s}} \sum_{k=1}^{j - 1} \mu_{B,i,k}\right)}_{K_2 \eqdef}}{\mathcal{G}_{B-1}}
  \end{align*}
  and $I_2^{0} = n.$
  Let us define $u = \sum_{k=1}^{j - 1} \mu_{B,i,k}.$ If $u \geq \frac{d}{2},$ then
  \begin{align*}
    K_2 = \ExpCond{\exp\left(-\lambda \tau_{\textnormal{s}} \mu_{B,i,j}\right)}{\mu_{B,i,j - 1}, \dots, \mu_{B,i,1}, \mathcal{G}_{B-1}} \exp\left(-\lambda \tau_{\textnormal{s}} u\right) \leq \exp\left(-\frac{\lambda \tau_{\textnormal{s}} d}{2}\right)
  \end{align*}
  Otherwise, if $u < \frac{d}{2},$ then, for all $t \geq 0,$
  \begin{align*}
    &\ExpCond{\exp\left(-\lambda \tau_{\textnormal{s}} \mu_{B,i,j}\right)}{\mu_{B,i,j - 1}, \dots, \mu_{B,i,1}, \mathcal{G}_{B-1}} \\
    &\leq \exp\left(- \lambda t\right) + \ProbCond{\mu_{B,i,j} \leq \frac{t}{\tau_{\textnormal{s}}}}{\mu_{B,i,j - 1}, \dots, \mu_{B,i,1}, \mathcal{G}_{B-1}} \\
    &\leq \exp\left(- \lambda t\right) + \frac{K \frac{t}{\tau_{\textnormal{s}}}}{d - u - \frac{t}{\tau_{\textnormal{s}}} + 1} \leq \exp\left(- \lambda t\right) + \frac{2 K t}{\tau_{\textnormal{s}} d - 2 t}
  \end{align*}
  due to \eqref{eq:kEAXDdRCaGsOmJWjx2new} and $u < \frac{d}{2}.$ Combining both cases,
  \begin{align*}
    K_2 \leq \max\left\{\left(\exp\left(- \lambda t\right) + \frac{2 K t}{\tau_{\textnormal{s}} d - 2 t}\right) \exp\left(-\lambda \tau_{\textnormal{s}} \sum_{k=1}^{j - 1} \mu_{B,i,k}\right), \exp\left(-\frac{\lambda \tau_{\textnormal{s}} d}{2}\right)\right\}
  \end{align*}
  for all $t < \frac{\tau_{\textnormal{s}} d}{2}$ and $u \geq 0,$ and
  \begin{align}
    I_2^{j} &\leq \left(\exp\left(- \lambda t\right) + \frac{2 K t}{\tau_{\textnormal{s}} d - 2 t}\right) \sum_{i=1}^{n} \ExpCond{\exp\left(-\lambda \tau_{\textnormal{s}} \sum_{k=1}^{j - 1} \mu_{B,i,k}\right)}{\mathcal{G}_{B-1}} + n \exp\left(-\frac{\lambda \tau_{\textnormal{s}} d}{2}\right) \nonumber \\
    &= \left(\exp\left(- \lambda t\right) + \frac{2 K t}{\tau_{\textnormal{s}} d - 2 t}\right) I_2^{j - 1} + n \exp\left(-\frac{\lambda \tau_{\textnormal{s}} d}{2}\right), \label{eq:JrAURKAjmWiP}
  \end{align}
  where we use the inequality $\max\{a, b\} \leq a + b$ for all $a, b \geq 0.$ 
  Substituting \eqref{eq:Hqaut} to \eqref{eq:dTcxdO},
  \begin{align*}
    \ExpCond{\exp\left(-\lambda \min_{i \in [n]} \beta_{B,i}\right)}{\mathcal{G}_{B-1}} \leq n \left(\exp\left(-\lambda t\right) + \frac{t p_{\sigma}}{h}\right)^{\frac{K}{2}} + I_2^{\frac{K}{2}},
  \end{align*}
  where $t, \lambda \geq 0$ are free parameters. Taking $t = \frac{4 + \frac{2}{K} \log (2 n)}{\lambda},$
  \begin{align*}
    \ExpCond{\exp\left(-\lambda \min_{i \in [n]} \beta_{B,i}\right)}{\mathcal{G}_{B-1}} \leq n \left(\frac{e^{-4}}{(2n)^{2/K}} + \frac{(4 + \frac{2}{K} \log(2 n))p_{\sigma}}{\lambda h} \right)^{\frac{K}{2}} + I_2^{\frac{K}{2}}.
  \end{align*}
  Choosing $\lambda = e^{4} (2 n)^{2 / K} (4 + \frac{2}{K} \log (2n)) \max\left\{\frac{p_{\sigma}}{h}, \frac{p_{K}}{\tau_{\textnormal{s}}}\right\},$
  \begin{align*}
    \ExpCond{\exp\left(-\lambda \min_{i \in [n]} \beta_{B,i}\right)}{\mathcal{G}_{B-1}} \leq n \left(\frac{2 e^{-4}}{(2n)^{2/K}}\right)^{\frac{K}{2}} + I_2^{\frac{K}{2}} = \frac{1}{2} \left(2 e^{-4}\right)^{\frac{K}{2}} + I_2^{\frac{K}{2}}.
  \end{align*}
  With this choice of $\lambda$ and $t$ in \eqref{eq:JrAURKAjmWiP}, we get
  \begin{align*}
    I_2^{j} 
    &\leq \left(\frac{3 e^{-4}}{(2 n)^{2 / K}}\right) I_2^{j - 1} + n \exp\left(-e^{4} (2 n)^{2 / K} (4 K + 2 \log (2n))\right) \\
    &\leq \left(\frac{3 e^{-4}}{(2 n)^{2 / K}}\right) I_2^{j - 1} + e^{-4 e^4 K} \leq n \left(\frac{3 e^{-4}}{(2 n)^{2 / K}}\right)^{j} + 2 e^{-4 e^4 K}
  \end{align*}
  for all $j \geq 1$ because $t \leq \frac{\tau_{\textnormal{s}} d}{2 e^{4} (2 n)^{2 / K} K},$ $\lambda = \frac{4 + \frac{2}{K} \log (2 n)}{t} \geq 2 e^{4} (2 n)^{2 / K} (4 + \frac{2}{K} \log (2n)) \frac{K}{\tau_{\textnormal{s}} d}.$ In the third inequality, we unrolled the recursion with $I^0_2 = n$ and use $\sum_{j=0}^{\infty} \left(\frac{3 e^{-4}}{(2 n)^{2 / K}}\right)^j \leq 2.$

  Finally, $I_2^{K / 2} \leq \frac{1}{2} \left(3 e^{-4}\right)^{\frac{K}{2}} + 2 e^{-2 e^4 K} \leq \frac{1}{2} e^{-K}$ and 
  \begin{align*}
    \ExpCond{\exp\left(-\lambda \min_{i \in [n]} \beta_{B,i}\right)}{\mathcal{G}_{B-1}} \leq \frac{1}{2} \left(2 e^{-4}\right)^{\frac{K}{2}} + I_2^{K / 2} \leq \frac{1}{2} e^{-K} + \frac{1}{2} e^{-K} \leq e^{-K}.
  \end{align*}
  Substituting the last inequality to \eqref{eq:GQkgle} and repeating the steps $B - 1$ more times, we get
  \begin{align*}
    &\Prob{\sum_{b = 1}^{B} \min_{i \in [n]} \beta_{b,i} \leq \bar{t}} \leq \exp\left(\lambda \bar{t} - B K\right).
  \end{align*}
  It is left to take $\bar{t} = \frac{B K + \log \delta}{\lambda}.$
\end{proof}

