\section{Main Theorem with Worker-to-Server Communication}
\label{sec:combined_app}
\begin{protocol}[t]
  \caption{}
  \label{alg:simplified_time_multiple_oracle_protocol_two}
  \begin{algorithmic}[1]
  \STATE \textbf{Input:} Algorithm $A \in \mathcal{A}_{\textnormal{zr}}$
  \STATE Init $I = \emptyset$ (all available information) on the server
  \STATE Init $I_i = \emptyset$ (all available information) on worker $i$ for all $i \in [n]$
  \STATE Run the following three loops in parallel. The first two on the workers. The third on the server.
  \FOR{$i = 1, \dots, n$ (in parallel on the workers)}
    \FOR{$k = 0, 1, \dots$}
    \STATE Algorithm $A$ calculates a new point $x$ based on local information $I_i$ \hfill (takes $0$ seconds)
    \STATE Calculate a stochastic gradient $\nabla f(x;\xi),$ $\quad \xi \sim \mathcal{D}_{\xi}$ \hfill (takes $h$ seconds)
    \STATE Add $\nabla f(x;\xi)$ to $I_i$ \hfill (takes $0$ seconds)
    \ENDFOR
  \ENDFOR
  \FOR{$i = 1, \dots, n$ (in parallel on the workers)}
  \FOR{$k = 0, 1, \dots$}
    \STATE \color{mydarkorange} Algorithm $A$ calculates new points $\{\bar{s}^k_i\}$ based on local information $I_i$ \hfill (takes $0$ seconds) \color{black}
    \STATE \color{mydarkorange} Send $\bar{\cC}^k_i(\bar{s}^k_i)$ to the server: add to $\bar{\cC}^k_i(\bar{s}^k_i)$ to $I$ \\ 
    (takes $\tau_{\textnormal{w}} \times \bar{P}^k_i$ seconds, where $\bar{P}^k_i$ is the number of coordinates retained by $\bar{\cC}^k_i(\bar{s}^k_i)$) \color{black}
  \ENDFOR
  \ENDFOR
  \FOR{$i = 1, \dots, n$ (in parallel on the server)}
    \FOR{$k = 0, 1, \dots$}
    \STATE Algorithm $A$ calculates new points $s_i^k$ based on local information $I$ \hfill (takes $0$ seconds)
    \STATE Algorithm $A$ compresses the points $\cC^k_i(s_i^k)$ \hfill (takes $0$ seconds)
    \STATE Send $\cC^k_i(s_i^k)$ to the worker $i$: add to $\cC^k_i(s_i^k)$ to $I_i$ \\ 
    (takes $\tau_{\textnormal{s}} \times P^k_i$ seconds, where $P^k_i$ is the number of coordinates retained by $\cC^k_i(s_i^k)$)
    \ENDFOR
  \ENDFOR
  \end{algorithmic}
\end{protocol}

In this section, we extend the result of Theorem~\ref{thm:main} by taking into account the communication time $\tau_{\textnormal{w}}.$ Instead of Protocol~\ref{alg:simplified_time_multiple_oracle_protocol}, we consider Protocol~\ref{alg:simplified_time_multiple_oracle_protocol_two}. However, in this section, we ignore the communication times from the server to the workers and assume that $\tau_{\textnormal{s}} = 0,$ which will be sufficient to obtain an almost tight lower bound if combined with Theorem~\ref{thm:main}.

\citet{tyurin2024shadowheart} consider a similar setup with $\tau_{\textnormal{s}} = 0.$ However, their protocol does not allow the workers to modify the iterate computed by the server and operates in the primal space. For instance, the workers are not allowed to run local steps. Moreover, $\bar{P}^k_i$ are fixed in their version of Protocol~\ref{alg:simplified_time_multiple_oracle_protocol_two}. We improve upon this in the following theorem:
\begin{theorem}
  \label{thm:main_two}
  Let $L, \Delta, \varepsilon, \sigma^2, n, d, \tau_{\textnormal{w}}, h > 0$ be any numbers such that $\varepsilon < c_1 L \Delta$ and $d \geq \frac{\Delta L}{c_2 \varepsilon}.$ Consider Protocol~\ref{alg:simplified_time_multiple_oracle_protocol_two}. For all $i \in [n]$ and $k \geq 0,$ compressor $\bar{\cC}^k_i$ selects and transmits $\bar{P}^k_i$ \emph{uniformly random coordinates without replacement, scaled by any constants},
  where $\bar{P}^k_i \in \{0, \dots, d\}$ may vary across each compressor.
  For any algorithm $A \in \cA_{\textnormal{zr}},$ there exists a function $f \,:\, \R^d \to \R$ such that $f$ is $L$-smooth, $f(0) - \inf_{x \in \R^d} f(x) \leq \Delta,$ exists a stochastic gradient oracle that satisfies Assumption~\ref{ass:stochastic_variance_bounded}, and 
  $\Exp{\inf_{y \in S_t}\norm{\nabla f(y)}^2} > \varepsilon$ 
  for all 
  $$t \leq c_3 \times \frac{L \Delta}{\varepsilon \log (n + 1)} \cdot \min\left\{\max\left\{\frac{h \sigma^2}{n \varepsilon}, \frac{\tau_{\textnormal{w}} d}{n}, \sqrt{\frac{h \sigma^2 \tau_{\textnormal{w}} d}{n \varepsilon}}, h, \tau_{\textnormal{w}}\right\}, \max\left\{\frac{h \sigma^2}{\varepsilon}, h\right\}\right\},$$
  where
  $S_t$ is the set of all possible points that can be constructed by $A$ up to time $t$ based on $I$ and $\{I_i\}.$ The quantities $c_1,$ $c_2,$ and $c_3$ are universal constants.
\end{theorem}
\begin{proof}
  The proof closely follows the analysis from \citep{tyurin2024shadowheart,tyurin2024optimal} and the proof of Theorem~\ref{thm:main}, but with some important modifications. In this proof, it is sufficient to work with \eqref{eq:worst_case_prev} and Lemmas~\ref{lemma:worst_function_1} and \ref{lemma:worst_function}.

  Let us fix $\lambda > 0$ and define the function $f \,:\, \R^d \to \R$ such that
  $$f(x) \eqdef \frac{L \lambda^2}{\ell_1} F_T\left(\frac{x_{[T]}}{\lambda}\right),$$ where the function $F_T$ is given in \eqref{eq:worst_case_prev} and $x_{[T]} \in \R^T$ is the vector with the first $T$ coordinates of $x \in \R^d.$ Notice that the last $d - T$ coordinates are artificial.

  First, we have to show that $f$ is $L$-smooth and $f(0) - \inf_{x \in \R^d} f(x) \leq \Delta.$ Using Lemma~\ref{lemma:worst_function},
  \begin{align*}
      \norm{\nabla f(x) - \nabla f(y)} 
      &= \frac{L \lambda}{\ell_1} \norm{\nabla F_{T}\left(\frac{x_{[T]}}{\lambda}\right) - \nabla F_{T}\left(\frac{y_{[T]}}{\lambda}\right)} \leq L \lambda \norm{\frac{x_{[T]}}{\lambda} - \frac{y_{[T]}}{\lambda}} \\
      &= L \norm{x_{[T]} - y_{[T]}} \leq L \norm{x - y} \quad \forall x, y \in \R^d.
  \end{align*}

  Taking
  \begin{align*}
    T = \left\lfloor\frac{\Delta \ell_1}{L \lambda^2 \Delta^0}\right\rfloor,
  \end{align*}
  \begin{align*}
      f(0) - \inf_{x \in \R^d} f(x) = \frac{L \lambda^2}{\ell_1} (F_{T}\left(0\right) - \inf_{x \in \R^T} F_{T}(x)) \leq \frac{L \lambda^2 \Delta^0 T}{\ell_1} \leq \Delta.
  \end{align*}
  due to Lemma~\ref{lemma:worst_function}.

  Next, we construct a stochastic gradient mapping. For our lower bound, we define
  \begin{align}
    [\nabla f(x; \xi)]_j \eqdef \nabla_j f(x) \left(1 + \mathbbm{1}\left[j > \textnormal{prog}(x)\right]\left(\frac{\xi}{p_{\sigma}} - 1\right)\right) \quad \forall x \in \R^d,
    \label{eq:clKdq}
  \end{align}
  and let $\mathcal{D}_{\xi} = \textnormal{\emph{Bernoulli}}(p_{\sigma})$ for all $j \in [n],$ where $p_{\sigma} \in (0, 1].$ 
  We denote $[x]_j$ as the $j$\textsuperscript{th} coordinate of a vector $x \in \R^d.$ 
  We choose
  $$p_{\sigma} \eqdef \min\left\{\frac{L^2 \lambda^2 \gamma_{\infty}^2}{\sigma^2 \ell_1^2}, 1\right\}.$$ 
  Then this mapping is unbiased and $\sigma^2$-variance-bounded.
  Indeed, $$\Exp{[\nabla f(x, \xi)]_i} = \nabla_i f(x) \left(1 + \mathbbm{1}\left[i > \textnormal{prog}(x)\right]\left(\frac{\Exp{\xi}}{p_{\sigma}} - 1\right)\right) = \nabla_i f(x)$$ for all $i \in [d],$ and
  \begin{align*}
      \Exp{\norm{\nabla f(x; \xi) - \nabla f(x)}^2} \leq \max_{j \in [d]} \left|\nabla_j f(x)\right|^2\Exp{\left(\frac{\xi}{p_{\sigma}} - 1\right)^2}
  \end{align*}
  because the difference is non-zero only in one coordinate. Thus
  \begin{align*}
      \Exp{\norm{\nabla f(x, \xi) - \nabla f(x)}^2} &\leq \frac{\norm{\nabla f(x)}_{\infty}^2(1 - p_{\sigma})}{p_{\sigma}} = \frac{L^2 \lambda^2 \norm{F_{T}\left(\frac{x_{[T]}}{\lambda}\right)}_{\infty}^2(1 - p_{\sigma})}{\ell^2_1 p_{\sigma}} \\
      &\leq \frac{L^2 \lambda^2 \gamma_{\infty}^2 (1 - p_{\sigma})}{\ell^2_1 p_{\sigma}} \leq \sigma^2,
  \end{align*}
  where we use Lemma~\ref{lemma:worst_function}.

  Taking
  $$\lambda = \frac{\sqrt{2 \varepsilon} \ell_1}{L},$$
  we ensure that 
  \begin{align}
    \label{eq:KDYUCCBClJMGi}
    \norm{\nabla f(x)}^2 = \frac{L^2 \lambda^2}{\ell_1^2}\norm{\nabla F_T \left(\frac{x_{[T]}}{\lambda}\right)}^2 > 2 \varepsilon \mathbbm{1}\left[\textnormal{prog}(x_{[T]}) < T\right]
  \end{align}
  for all $x \in \R^d,$ where we use Lemma~\ref{lemma:worst_function_1}. Thus
  \begin{align}
    \label{eq:13c6d540-5fae-5705-a665-b89fda334a29}
    T = \left\lfloor\frac{\Delta L}{2 \varepsilon \ell_1 \Delta^0}\right\rfloor
  \end{align}
  and
  $$p_{\sigma} = \min\left\{\frac{2 \varepsilon \gamma_{\infty}^2}{\sigma^2}, 1\right\}.$$

  Using the same reasoning as in \citet{tyurin2024shadowheart} and our Theorem~\ref{thm:main}, we define two sets of random variables. Let $\eta_{1,i}$ be the first computed stochastic gradient when the oracle draws a ``successful'' Bernoulli trial in \eqref{eq:clKdq} at worker $i.$ Then, 
  \begin{align*}
    \Prob{\eta_{1,i} \leq t} \leq \sum_{i=1}^{\flr{t}} (1 - p_{\sigma})^{i - 1} p_{\sigma} \leq p_{\sigma} \flr{t}
  \end{align*}
  for $t \geq 0,$ and 
  \begin{align*}
    \Prob{\eta_{1,i} \leq t} \leq \min\{p_{\sigma} \flr{t}, 1\}
  \end{align*}

  For all $i \in [n],$ the server receives a stream of coordinates from worker $i.$ Let $\mu_{1,i}$ be the number of received coordinates by the server from worker $i$ until the moment when the index of the last received coordinate is $1$. 
  Let us define 
  \begin{align*}
    p_{d} \eqdef \frac{2}{d}.
  \end{align*}
  Similarly to the proof of Theorem~\ref{thm:main} with $K = 1$ (see \eqref{eq:TXdhtULbbzaLGikrg}),
  \begin{align*}
    \ProbCond{\mu_{1,i} \leq t}{\eta_{1,i}} = \sum_{j = 1}^{\flr{t}} \Prob{\mu_{1,i,1} = j} \leq \frac{\flr{t}}{d - t + 1}.
  \end{align*}
  for all $t \leq d.$ Thus,
  \begin{align*}
    \ProbCond{\mu_{1,i} \leq t}{\eta_{1,i}} \leq \begin{cases} 
      \frac{\flr{t}}{d - t + 1}, & t \leq \frac{d}{2} \\
      1, & t > \frac{d}{2} \\
    \end{cases} \leq \begin{cases} 
      \flr{t} p_{d}, & t \leq \frac{d}{2} \\
      1, & t > \frac{d}{2}
    \end{cases} \leq \min\{2 \flr{t} p_{d}, 1\}
  \end{align*}
  for all $t \geq 0.$ 

  There are two ways in which worker $i$ can discover the first coordinate. Either the worker is ``lucky'' and draws a successful Bernoulli random variable locally, or it gets to discover the first coordinate through the server. Thus, worker $i$ requires at least 
  \begin{align*}
    y_{1,i} \eqdef \min\left\{h \eta_{1,i}, \min_{j \in [n], j\neq i} \left\{h \eta_{1,j} + \tau_{\textnormal{w}} \mu_{1,j}\right\}\right\} = \min_{j \in [n]} \left\{h \eta_{1,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{1,j}\right\}
  \end{align*}
  seconds because $h \eta_{1,i}$ is the minimal time to discover the first coordinate locally, and $\min_{j \in [n], j\neq i} \left\{h \eta_{1,j} + \tau_{\textnormal{w}} \mu_{1,j}\right\}$ is the minimal time to discover the first coordinate from other workers via the server, which can transmit (for free since $\tau_{\textnormal{s}} = 0$) it to worker $i.$ 

  Using the same reasoning, worker $i$ requires at least 
  \begin{align*}
    y_{k,i} \eqdef \min_{j \in [n]} \left\{h \eta_{k,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} + y_{k-1, j}\right\}
  \end{align*}
  seconds to discover the $k$\textsuperscript{th} coordinate for all $k \geq 2,$ where
  \begin{align}
    \ProbCond{\eta_{k,i} \leq t}{\mathcal{G}_{k-1}} \leq \min\{\flr{t} p_{\sigma}, 1\}
  \end{align}
  for all $k \geq 1,$ $i \in [n],$ and $t \geq 0,$ and
  \begin{align}
    \ProbCond{\mu_{k,i} \leq t}{\eta_{k,i}, \mathcal{G}_{k-1}} \leq \min\{2 \flr{t} p_{d}, 1\}
  \end{align}
  for all $k \geq 1,$ $i \in [n],$ and $t \geq 0,$ where $\mathcal{G}_{k-1}$ is the sigma-algebra generated by $\{\eta_{k',i}\}_{i \in [n], k' < k}$ and $\{\mu_{k',i}\}_{i \in [n], k' < k}.$ Thus, the first possible time when the workers and the server can discover the $T$\textsuperscript{th} coordinate is
  \begin{align*}
    y_{T} \eqdef \min_{i \in [n]} y_{T,i}.
  \end{align*}
  For this random variable, we prove the lemma below (see Section~\ref{sec:main_lemma_two}).
  \begin{restatable}{lemma}{MAINLEMMATWO}
  \label{lemma:main_concet_lemma_two}
  Let $\{\eta_{k,i}\}_{i,k \geq 0}$ and $\{\mu_{k,i}\}_{i,k \geq 0}$ be random variables such that
  \begin{align}
    \ProbCond{\eta_{k,i} \leq t}{\mathcal{G}_{k-1}} \leq \min\{\flr{t} p_{\sigma}, 1\}
    \label{eq:HkLrpsR}
  \end{align}
  for all $k \geq 1,$ $i \in [n],$ and $t \geq 0,$ and
  \begin{align}
    \ProbCond{\mu_{k,i} \leq t}{\eta_{k,i}, \mathcal{G}_{k-1}} \leq \min\{2 \flr{t} p_{d}, 1\},
    \label{eq:HkLrpsR2}
  \end{align}
  for all $k \geq 1,$ $i \in [n],$ and $t \geq 0,$ where $\mathcal{G}_{k-1}$ is the sigma-algebra generated by $\{\eta_{k',i}\}_{i \in [n], k' < k}$ and $\{\mu_{k',i}\}_{i \in [n], k' < k}.$ Then
  \begin{align*}
    \Prob{y_{T} \leq \bar{t}} \leq \delta
  \end{align*}
  with 
  \begin{align}
    \bar{t} \eqdef \frac{T - \log n + \log \delta}{32 \log (8n)} \cdot \min\left\{\max\left\{\frac{h}{p_{\sigma} n}, \frac{\tau_{\textnormal{w}}}{p_{d} n}, \frac{\sqrt{h \tau_{\textnormal{w}}}}{\sqrt{p_{\sigma} p_{d} n}}, h, \tau_{\textnormal{w}}\right\}, \frac{h}{p_{\sigma}}\right\},
  \end{align}
  where 
  \begin{align*}
    y_{T} \eqdef \min_{i \in [n]} y_{T,i},
  \end{align*}
  \begin{align*}
    y_{k,i} \eqdef \min_{j \in [n]} \left\{h \eta_{k,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} + y_{k-1, j}\right\}
  \end{align*}
  for all $k \geq 1, i \in [n]$ and $y_{0,i} = 0$ for all $i \in [n].$
\end{restatable}

Thus, with probability at least $1 - \delta$, any zero-respecting algorithm requires at least $\bar{t}$ seconds to discover the last coordinate. 
Due to \eqref{eq:KDYUCCBClJMGi},
  \begin{align*}
  \inf_{y \in S_{t}} \norm{\nabla f(y)}^2 > 2 \varepsilon \inf_{y \in S_{t}} \mathbbm{1}\left[\textnormal{prog}(y_{[T]}) < T\right],
  \end{align*}
  where $S_{t}$ is the set of all possible candidate points to be an $\varepsilon$--stationary point up to time $t,$ which can be computed by $A.$ Taking $\delta = \frac{1}{2},$
  \begin{align*}
    \Exp{\inf_{y \in S_{t}} \norm{\nabla f(y)}^2} > 2 \varepsilon \Exp{\inf_{y \in S_{t}} \mathbbm{1}\left[\textnormal{prog}(y_{[T]}) < T\right]} \geq \varepsilon,
  \end{align*}
  for $t = \frac{1}{2} \bar{t}$ because $\textnormal{prog}(y_{[T]}) < T$ for all $y \in S_{t}$ with probability at least $\frac{1}{2}.$ It is left to substitute all quantities:
  \begin{align*}
    t = \frac{\left\lfloor\frac{\Delta L}{2 \varepsilon \ell_1 \Delta^0}\right\rfloor - \log n + \log \frac{1}{2}}{64 \log (8n)} \cdot \min\left\{\max\left\{\frac{h}{n} \max\left\{\frac{\sigma^2}{2 \varepsilon \gamma_{\infty}^2}, 1\right\}, \frac{\tau_{\textnormal{w}} d}{2 n}, \frac{\sqrt{h d \tau_{\textnormal{w}}}}{\sqrt{2 n}} \sqrt{\frac{\sigma^2}{2 \varepsilon \gamma_{\infty}^2}}, h, \tau_{\textnormal{w}}\right\}, h \max\left\{\frac{\sigma^2}{2 \varepsilon \gamma_{\infty}^2}, 1\right\}\right\}.
  \end{align*}
  Since $\ell_1, \Delta^0, \gamma_{\infty}$ are universal constants, assuming $\varepsilon < c_1 L \Delta$ for some small universal $c_1 > 0,$ we get
  \begin{align*}
    t \geq c_3 \times \frac{L \Delta}{\varepsilon \log (n + 1)} \cdot \min\left\{\max\left\{\frac{h \sigma^2}{n \varepsilon}, \frac{\tau_{\textnormal{w}} d}{n}, \sqrt{\frac{h \sigma^2 \tau_{\textnormal{w}} d}{n \varepsilon}}, h, \tau_{\textnormal{w}}\right\}, \max\left\{\frac{h \sigma^2}{\varepsilon}, h\right\}\right\}
  \end{align*}
  for some small universal $c_3 > 0.$ Notice that we can take any dimension $d$ such that
  \begin{align*}
    d \geq T = \Theta\left(\frac{L \Delta}{\varepsilon}\right).
  \end{align*}
  \end{proof}
\subsection{Main Concentration Lemma}
\label{sec:main_lemma_two}
\MAINLEMMATWO*

\begin{proof}
Using the Chernoff method for any $s > 0$ and $k \geq 1$, we get
\begin{align*}
  \Prob{y_{k} \leq \bar{t}} 
  &= \Prob{- s y_{k} \geq - s \bar{t}} = \Prob{e^{- s y_{k}} \geq e^{- s \bar{t}}} \leq e^{s \bar{t}} \Exp{e^{- s y_{k}}} \\
  &= e^{s \bar{t}} \Exp{\exp\left(- s \min_{j \in [n]} y_{k,j}\right)} = e^{s \bar{t}} \Exp{\max_{j \in [n]} \exp\left(- s y_{k,j}\right)}.
\end{align*}
Bounding the maximum by the sum,
\begin{equation}
\begin{aligned}
  \Prob{y_{k} \leq t} 
  &\leq e^{s t} \sum_{j=1}^n \Exp{\exp\left(- s y_{k,j}\right)} \leq n e^{s t} \max_{j \in [n]} \Exp{\exp\left(- s y_{k,j}\right)}.
  \label{eq:iAeohfnTfnYY}
\end{aligned}
\end{equation}
We focus on the last exponent separately. For all $i \in [n],$
\begin{equation}
\begin{aligned}
  \Exp{\exp\left(- s y_{k, i}\right)} 
  &= \Exp{\exp\left(- s \min_{j \in [n]} \left\{h \eta_{k,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} + y_{k-1, j}\right\}\right)} \\
  &= \Exp{\max_{j \in [n]}\exp\left(- s \left(h \eta_{k,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} + y_{k-1, j}\right)\right)} \\
  &\leq \sum_{j=1}^n \Exp{\exp\left(- s \left(h \eta_{k,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} + y_{k-1, j}\right)\right)} \\
  &= \sum_{j=1}^n \Exp{\underbrace{\ExpCond{\exp\left(- s \left(h \eta_{k,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j}\right)\right)}{\mathcal{G}_{k-1}}}_{I_1 \eqdef } \exp\left(- s y_{k-1, j}\right)} \\
\end{aligned}
\label{eq:ErkxlMMOhR}
\end{equation}
Considering the inner expectation separately:
\begin{align*}
  I_1 
  &= \ExpCond{\exp\left(- s \left(h \eta_{k,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j}\right)\right)}{\mathcal{G}_{k-1}} \\
  &\leq \exp\left(- s t\right) + \ProbCond{h \eta_{k,j} + \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} \leq t}{\mathcal{G}_{k-1}}
\end{align*}
for all $t \geq 0.$ Using the properties of condition expectations,
\begin{align*}
  I_1 &\leq \exp\left(- s t\right) + \ProbCond{h \eta_{k,j} \leq t, \mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} \leq t}{\mathcal{G}_{k-1}} \\
  &= \exp\left(- s t\right) + \ExpCond{\mathbbm{1}\left[h \eta_{k,j} \leq t\right] \mathbbm{1}\left[\mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} \leq t\right]}{\mathcal{G}_{k-1}} \\
  &= \exp\left(- s t\right) + \ExpCond{\ExpCond{\mathbbm{1}\left[\mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} \leq t\right]}{\eta_{k,j}, \mathcal{G}_{k-1}} \mathbbm{1}\left[h \eta_{k,j} \leq t\right] }{\mathcal{G}_{k-1}} \\
  &= \exp\left(- s t\right) + \ExpCond{\ProbCond{\mathbbm{1}[i \neq j] \tau_{\textnormal{w}} \mu_{k,j} \leq t}{\eta_{k,j}, \mathcal{G}_{k-1}} \mathbbm{1}\left[h \eta_{k,j} \leq t\right] }{\mathcal{G}_{k-1}}.
\end{align*}
If $i = j,$ then we bound the probability by $1$ and get
\begin{align*}
  I_1 
  &\leq \exp\left(- s t\right) + \ExpCond{\mathbbm{1}\left[h \eta_{k,j} \leq t\right] }{\mathcal{G}_{k-1}} \\
  &= \exp\left(- s t\right) + \ProbCond{h \eta_{k,j} \leq t}{\mathcal{G}_{k-1}} \\
  &\leq \exp\left(- s t\right) + \flr{\frac{t}{h}} p_{\sigma},
\end{align*}
for all $t \geq 0,$ where we use \eqref{eq:HkLrpsR}. Otherwise, if $i \neq j,$ using \eqref{eq:HkLrpsR2} and \eqref{eq:HkLrpsR},
\begin{align*}
  I_1 
  &\leq \exp\left(- s t\right) + \ExpCond{\min\left\{1, 2\flr{\frac{t}{\tau_{\textnormal{w}}}} p_{d}\right\} \mathbbm{1}\left[h \eta_{k,j} \leq t\right] }{\mathcal{G}_{k-1}} \\
  &= \exp\left(- s t\right) + \min\left\{1, 2\flr{\frac{t}{\tau_{\textnormal{w}}}} p_{d}\right\} \ProbCond{h \eta_{k,j} \leq t}{\mathcal{G}_{k-1}} \\
  &\leq \exp\left(- s t\right) + \min\left\{1, 2\flr{\frac{t}{\tau_{\textnormal{w}}}} p_{d}\right\} \min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}
\end{align*}
for all $t \geq 0.$ Substituting the inequalities to \eqref{eq:ErkxlMMOhR},
\begin{align*}
  \Exp{\exp\left(- s y_{k, i}\right)} 
  &= \sum_{j\neq i} \left(\exp\left(- s t\right) + \min\left\{1, 2\flr{\frac{t}{\tau_{\textnormal{w}}}} p_{d}\right\} \min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}\right) \Exp{\exp\left(- s y_{k-1, j}\right)} \\
  &+\quad \left(\exp\left(- s t\right) + \min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}\right) \Exp{\exp\left(- s y_{k-1, i}\right)}.
\end{align*}
for all $i \in [n]$ and $t \geq 0.$ Thus,
\begin{align*}
  &\max_{i \in [n]} \Exp{\exp\left(- s y_{k, i}\right)}  \\
  &\leq \left[(n - 1) \left(\exp\left(- s t\right) + \min\left\{1, 2\flr{\frac{t}{\tau_{\textnormal{w}}}} p_{d}\right\} \min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}\right) + \left(\exp\left(- s t\right) + \min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}\right)\right] \\
  &\quad \times\max_{i \in [n]} \Exp{\exp\left(- s y_{k-1, i}\right)} \\
  &= \left[n \exp\left(- s t\right) + (n - 1)\left(\min\left\{1, 2\flr{\frac{t}{\tau_{\textnormal{w}}}} p_{d}\right\} \min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}\right) + \min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}\right] \max_{i \in [n]} \Exp{\exp\left(- s y_{k-1, i}\right)}.
\end{align*}
Taking $s = \frac{\log (8n)}{t},$ we get
\begin{equation}
\begin{aligned}
  &\max_{i \in [n]} \Exp{\exp\left(- s y_{k, i}\right)}  \\
  &\leq \left[\frac{1}{8} + \underbrace{(n - 1)\left(\min\left\{1, 2\flr{\frac{t}{\tau_{\textnormal{w}}}} p_{d}\right\} \min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}\right)}_{I_2 \eqdef} + \underbrace{\min\left\{1, \flr{\frac{t}{h}} p_{\sigma}\right\}}_{I_3 \eqdef}\right] \max_{i \in [n]} \Exp{\exp\left(- s y_{k-1, i}\right)}.
  \label{eq:lAtBuSDdbodJuIdq}
\end{aligned}
\end{equation}
Next, we take $t = \min\{t_1, t_2\},$ where
\begin{align*}
  t_1 \eqdef \max\left\{\frac{h}{32 p_{\sigma} n}, \frac{\tau_{\textnormal{w}}}{32 p_{d} n}, \frac{\sqrt{h \tau_{\textnormal{w}}}}{32 \sqrt{p_{\sigma} p_{d} n}}, \frac{h}{32}, \frac{\tau_{\textnormal{w}}}{32}\right\},
\end{align*}
and 
\begin{align*}
  t_2 \eqdef \frac{h}{32 p_{\sigma}}
\end{align*}
to ensure that $$I_3 \leq \min\left\{1, \frac{t_2 p_{\sigma}}{h}\right\} \leq \frac{1}{16}.$$ 
There are five possible values of $t_1.$ 

If $t_1 = \frac{h}{32 p_{\sigma} n},$ then
\begin{align*}
  I_2 \leq (n - 1) \min\left\{1, \frac{t_1 p_{\sigma}}{h}\right\} \leq \frac{1}{16},
\end{align*}
If $t_1 = \frac{\tau_{\textnormal{w}}}{32 p_{d} n},$ then
\begin{align*}
  I_2 \leq (n - 1) \min\left\{1, \frac{2 t_1 p_{d}}{\tau_{\textnormal{w}}}\right\} \leq \frac{1}{16}.
\end{align*}
If $t_1 = \frac{\sqrt{h \tau_{\textnormal{w}}}}{32 \sqrt{p_{\sigma} p_{d} n}},$ then
\begin{align*}
  I_2 \leq (n - 1)\frac{2 t_1^2 p_{d} p_{\sigma}}{\tau_{\textnormal{w}} h} \leq \frac{1}{16}.
\end{align*}
If $t_1 = \frac{h}{32},$ then
\begin{align*}
  I_2 \leq (n - 1) \min\left\{1, \flr{\frac{t_1}{h}} p_{\sigma}\right\} = 0.
\end{align*}
Finally, if $t_1 = \frac{\tau_{\textnormal{w}}}{32},$ then
\begin{align*}
  I_2 \leq (n - 1)\min\left\{1, 2\flr{\frac{t_1}{\tau_{\textnormal{w}}}} p_{d}\right\} = 0.
\end{align*}
Thus, using \eqref{eq:lAtBuSDdbodJuIdq}, we obtain
\begin{align*}
  &\max_{i \in [n]} \Exp{\exp\left(- s y_{k, i}\right)} \leq \left[\frac{1}{8} + \frac{1}{16} + \frac{1}{16}\right] \max_{i \in [n]} \Exp{\exp\left(- s y_{k-1, i}\right)} \leq e^{-1} \max_{i \in [n]} \Exp{\exp\left(- s y_{k-1, i}\right)}
\end{align*}
for our choice of $t.$ Unrolling the recursion and using $y_{0,i} = 0$ for all $i \in [n],$
\begin{align*}
  \max_{i \in [n]} \Exp{\exp\left(- s y_{k, i}\right)} \leq e^{-k}.
\end{align*}
We substitute it to \eqref{eq:iAeohfnTfnYY}, to get
\begin{align*}
  \Prob{y_{k} \leq \bar{t}} \leq e^{s \bar{t} + \log n - k}.
\end{align*}
It is left to choose $\bar{t} = \frac{k - \log n + \log \delta}{s}.$
\end{proof}

