\section{Preliminaries}
\label{sec:prelim}

\paragraph*{Sets, vectors and coordinates.}
For an integer $n$, we use $[n]$ to denote the set $\{1, 2, \ldots, n\}$.
We use the tuple notation for points in $\mathbb{R}^d$, i.e., a point is defined by the tuple $(a_1, a_2, \ldots, a_d)$, where $a_i \in \mathbb{R}$ is the respective coordinate for each $i \in [d]$. The variables $x_1$, $x_2$, \ldots, $x_d$ are used to denote the respective axes. We denote the origin by $O = (0, 0, \ldots, 0)$, and by $Ox_ix_j$, $i, j \in [d]$ we denote the plane spanned on the respective axes; the same notation is used for higher-dimensional subspaces too. For two points $A, B \in \mathbb{R}^d$, $\overrightarrow{AB}$ denotes the vector pointing from $A$ to $B$, its coordinates are expressed as $B - A$. We use $|| \cdot ||$ to denote the standard Euclidean norm in $\mathbb{R}^2$, therefore, $||B - A||$ is the Euclidean distance between the points $A$ and $B$, and also the length of the vector $\overrightarrow{AB}$.

\paragraph*{Unit ball graphs.}
Let $P = \{ p_1, \dots, p_n \}$ be a set of points in $\mathbb{R}^d$ and $B$ be a set of balls $b_i$ of radius $1$, centered at $p_i$.
A unit ball graph on $P$ is a graph over the vertex set $P$, in which two vertices $p_i$ and $p_j$ are adjacent if and only if the balls $b_i$ and $b_j$ intersect.

\paragraph*{Exponential-time hypothesis.}
The exponential-time hypothesis (\classETH), due to Impagliazzo, Paturi and Zane~\cite{ImpagliazzoP01, ImpagliazzoPZ01}, implies that there is no algorithm that solves \textsc{3-SAT} in $2^{o(n)}$ time, where $n$ is the number of variables in the formula. Since by the Sparsification Lemma~\cite{ImpagliazzoPZ01} this holds even for linearly-many clauses in the formula, \classETH also excludes $2^{o(n + m)}$-time algorithms for \textsc{3-SAT}, where $m$ is the number of clauses. By the standard linear-size reduction from \textsc{3-SAT} to \textsc{3-Coloring}, \classETH implies that \textsc{3-Coloring} does not admit a $2^{o(n + m)}$-time algorithm, where $n$ is the number of vertices and $m$ is the number of edges in the graph.

\paragraph*{Tree decomposition.}

For a graph $G = (V, E)$, a \emph{tree decomposition} is a pair $(T, \sigma)$, where $T = (V_T, E_T)$ is a tree and $\sigma \colon V_T \to 2^{V}$ such that
\begin{itemize}
    \item for each $uv \in E$, there exists $t \in V_T$ with $u, v \in \sigma(t)$, and 
    \item for each $v \in V$, the set of nodes $t \in V_T$ with $v \in \sigma(t)$ forms a connected subtree in $T$.
\end{itemize}
The \emph{width} of $(T, B)$ is $\max_{x \in V(T)}(|B(x)| - 1)$.
The \emph{tree-width} of $G$ is the minimum width of all tree decompositions of $G$.

A \emph{nice} tree decomposition is a tree decomposition more amenable to the design of dynamic programming algorithms.
Formally, a tree decomposition $(T = (V_T, E_T), \sigma)$ rooted at $r \in V_T$ is called \emph{nice} if $\sigma(r) = \emptyset$ and each node $t \in V_T$ is one of the following types:
\begin{description}
    \item[Leaf node.] $t$ is leaf in $T$ and $\sigma(t) = \emptyset$.
    \item[Introduce node.] $t$ has exactly one child $t'$, and $\sigma(t) = \sigma(t') \cup \{ v \}$ for a vertex $v$ in $G$.
    \item[Forget node.] $t$ has exactly one child $t'$, and $\sigma(t) = \sigma(t') \setminus \{ v \}$ for a vertex $v$ in $G$.
    \item[Join node.] $t$ has exactly two children $t', t''$, and $\sigma(t) = \sigma(t') = \sigma(t'')$. 
\end{description}
It is known that given a tree decomposition, a nice tree decomposition of the same width can be computed in polynomial time \cite{Bodlaender96}.

\section{Subexponential algorithm for unit disks}

In this section, we design a  subexponential-time algorithm for \probcliqueparition on unit disk graphs.

\subexpalgo*

To design a subexponential-time algorithm, let us introduce two known techniques.
We start with the ``separation theorem'' of Capoyleas, Rote and Woeginger~\cite{CapoyleasRW91}.
%As we noted in \todo{somewhere}, \probDiameter is the problem of finding
Recall that we aim to partition the vertex set of a given unit disk graph into a collection of $k$ cliques.
Each clique is defined by the convex hull of the centers of disks in the clique.
In principle, these convex hulls may arbitrarily intersect each other.
The following states that we may assume that they are disjoint in an optimal solution.

\begin{theorem}[Capoyleas, Rote and Woeginger~\cite{CapoyleasRW91}]
    \label{prop:separation}
    For \probcliqueparition on unit disk graphs, there exists an optimal solution $(C_1, \dots, C_{\ell})$ such that the convex hulls of the centers in $C_i$ are pairwise disjoint.
\end{theorem}

This was first proven by Capoyleas, Rote and Woeginger~\cite{CapoyleasRW91} but also by Dumitrescu and Pach~\cite{DumitrescuP11} and Pirwani and Salavatipour~\cite{PirwaniS12} later.
Theorem~\ref{prop:separation} relies crucially on the fact that for two intersecting convex polygons $P_1, P_2$ of diameter at most $d$, there exists two disjoint convex polygons $P_1', P_2'$ of diameter at most $d$ such that the vertices of $P_1$ and $P_2$ are contained in $P_1' \cup P_2'$.
In view of Theorem~\ref{prop:separation}, we will show that there are polynomially many ``relevant'' cliques in Lemma~\ref{lemma:clique-bound}.
To prove this, we will also use the following simple fact.
%TODO: rephrase so that it's clear that this is already proven

\begin{lemma}[Dumitresku and Pach, Lemma 2~\cite{DumitrescuP11}]
    \label{lemma:area-cover}
    Let $(G, \ell)$ be an instance of \probcliqueparition on unit disk graphs, and $(C_1, \dots, C_{\ell})$ be an optimal solution satisfying the condition of Theorem~\ref{prop:separation}.
    For a set $S$ of vertices contained in a square of constant side length, there are $O(1)$ cliques $C_i$ that intersect $S$.
\end{lemma}

See Dumitrescu and Pach~\cite{DumitrescuP11} for a concrete bound in the above lemma.
Now we prove a polynomial bound on the number of relevant cliques.

\begin{lemma}
    \label{lemma:clique-bound}
    Let $(G, \ell)$ be an instance of \probcliqueparition on unit disk graphs.
    Given $S \subseteq V(G)$,
    we can find in polynomial time a collection $\mathcal{R}$ of cliques in $G$ such that $|\mathcal{R}| \in |S|^{O(1)}$, and for each optimal solution $(C_1, \dots, C_{\ell})$ satisfying the condition of Theorem~\ref{prop:separation}, $S \cap C_i \in \mathcal{R}$ for all $i \in [\ell]$.
\end{lemma}
\begin{proof}
    Let $C = S \cap C_i$ be a clique with $C \ne \emptyset$.
    We will say that a clique $C_j$ is \emph{close} to $C$ if their closest vertices have distance at most two and \emph{far} from $C$ otherwise.

    We first show how to separate $C$ from far cliques, i.e., we find a collection of closed regions $P$ such that $C$ lies within $P$ and any far clique lies outside $P$.
    Suppose that $u, v \in C$ are two vertices with the largest distance $r \le 2$ in $C$.
    Then, $C$ is contained in the intersection of two disks of radius $r$ centered at $u$ and $v$, and every vertex of every far clique from $C$ is outside of these disks.
    For each $u, v \in S$, let $P_{u, v}$ be the intersection of such two disks, and let $R_{u, v}$ be the vertices of $S$ that lie in $P_{u, v}$.
    Let $\mathcal{R}'$ be the collection of vertex sets containing $R_{u, v}$ for each $u, v \in S$.
    We then have $|\mathcal{R}'| \in O(|S|^2)$, and for every $C = S \cap C_i$ there exists $R \in \mathcal{R}'$ that does not intersect any clique far from $C$.

    Next, we discuss how to separate $C$ from close cliques.
    By the above characterization, $C$ is contained in a $2 \times 4$-rectangle (not necessarily axis-aligned).
    For each close clique $C'$ of $C$, there exists a vertex $t$ in $C'$ with distance at most $2$ to a vertex in $C$, and every vertex in $C'$ has distance at most $2$ to $t$, so every vertex of $C'$ is at most at distance $4$ from some vertex of $C$.
    Therefore by extending the $2 \times 4$ rectangle containing $C$ by $4$ in every direction, we obtain a $10 \times 12$ rectangle that contains every close clique of $C$.
    Thus, by Lemma~\ref{lemma:area-cover}, there are $O(1)$ close cliques $C_j$ with $j \in [\ell]$.
    For a clique $C_j$, $j \in [\ell]$, since the convex hulls of $C$ and $C_j$ do not overlap by Theorem~\ref{prop:separation}, there is a line that separates $C$ and $C_j$, this line also separates the convex hulls of $C$ and $C_j \cap S$.
    Moving this line, we find two vertices on the boundary of the convex hull of $C$ or two vertices on on the boundary of the convex hull of $S \cap C_j$, such that the line through them separates $C$ and $S \cap C_j$ in the plane.
    Let $\mathcal{P}''$ be the collection of regions
    %\footnote{Technically, the collection of lines that separate $C$ from close cliques do not necessarily yield a closed region. However, lines through two vertices on the boundary of the convex hull of $C$ can be added to obtain a polygon.}
    obtained as the intersection of constantly\footnote{The constant depends on Lemma~\ref{lemma:area-cover}.} many open or closed semi-planes whose boundaries go through two points of $S$.
    Let $\mathcal{R}''$ be the collection of vertex sets such that for each region in $\mathcal{P}''$, there is a vertex set in $\mathcal{R}''$ containing exactly the vertices of $S$ lying in this region.

    % These lines separate $C$ from $C_$
    % A clique $C$ is then defined by the set of points of $S$ in the region enclosed by the lines, each separating $C$ and a clique $C_j$ close to $C$ (i.e., two cliques lie on the opposite side of the line).


    Finally, let $\mathcal{R}$ be the collection of intersections of $R'$ and $R''$ for $R' \in \mathcal{R}'$ and $R'' \in \mathcal{R}''$.
    Clearly, $|\mathcal{R}| \in |S|^{O(1)}$. By the above, we have that for $C = S \cap C_i$, 
    there exists $R' \in \mathcal{R}'$ that is disjoint from $S \cap C_j$ for every clique $C_j$ that is far from $C$, and there exists $R'' \in \mathcal{R}''$ that is disjoint from $S \cap C_h$ for every clique $C_h$ close to $C$; on the other hand, $R'$ and $R''$ contain $C$.
    Therefore, $R' \cap R''$ is disjoint from $S \cap C_j$ for every $j \ne i$, and contains $C$.
    Since $V(G) = C_1 \cup \ldots \cup C_\ell$ and $R', R'' \subseteq S \subseteq V(G)$, $R' \cap R''$ contains no vertices outside of $C$, and $C = R' \cap R'' \in \mathcal{R}$.
    Moreover, every $R \in \mathcal{R}$ is a clique since every $R' \in \mathcal{R}'$ is a clique.
    This completes the proof of the lemma.
\end{proof}

We will also use the framework of de Berg et al.~\cite{BergBKMZ20} for the design of subexponential-time algorithms for geometric intersection graphs.
First, let us introduce some terminology.
For a graph $G = (V, E)$ and $\kappa \in \mathbb{N}$, a \emph{$\kappa$-partition} of $G$ is a partition $(P_1, \dots, P_{\nu})$ of $V$ such that every $P_i$ induces a connected subgraph which is a union of at most $\kappa$ cliques.
For a $\kappa$-partition $\mathcal{P}$ of $G$, the \emph{$\mathcal{P}$-contraction} of $G$, denoted by $G_{\mathcal{P}}$, is the graph obtained by contracting every $P_i$ into a single vertex, that is, $V(G_{\mathcal{P}}) = \{ P_1, \dots, P_{\nu} \}$ and $E(G_{\mathcal{P}}) = \{ P_i P_j \mid \exists v_i \in P_i, v_j \in P_j \colon v_i v_j \in E(G)\}$.
Let $\gamma \colon \mathbb{N} \to \mathbb{N}$ be a weight function.
For a tree decomposition $(T, \sigma)$ of $G_{\mathcal{P}}$, its \emph{weighted width} with respect to $\gamma$ is defined by $\max_{t} \sum_{P_i \in \sigma(t)} \gamma(|P_i|)$, where the maximum is over the nodes $t$ of $T$.

The main technical step of the algorithmic framework of de Berg et al.\ is the following theorem, restricted to the case of unit disk graphs.

\begin{theorem}[\cite{BergBKMZ20}, Theorem 2.11 applied to unit disk graphs]\label{thm:framework}
    For a weight function $\gamma$ such that $\gamma(t) \in O(t^{1/2-\varepsilon})$ for $\varepsilon > 0$, there exists a $\kappa$-partition $\mathcal{P}$ for $\kappa \in O(1)$ such that $G_{\mathcal{P}}$ has weighted treewidth $O(\sqrt{n})$ that can be computed in $2^{O(\sqrt{n})}$ time.
\end{theorem}

% \ktodo[inline]{Mark the start and the end of the formal proof of Theorem 1 and put it in a proof environment. Some intuitive words can go before the start of the formal proof.}
As in Berg et al.~\cite{BergBKMZ20}, we will apply Theorem~\ref{thm:framework} with $\gamma(t) = O(\log t)$.
To design a $2^{O(\sqrt{n})}$-time algorithm, one essentially needs to show that there are $|P|^{O(1)}$ possibilities for each partition class $P \in \mathcal{P}$.
We obtain this polynomial bound from Lemma~\ref{lemma:clique-bound}.
Specifically, let $(C_1, \ldots, C_\ell)$ be an optimal solution satisfying the condition of Theorem~\ref{prop:separation}.
For $P \in \mathcal{P}$, let $\mathcal{R}(P)$ be the collection of cliques returned by Lemma~\ref{lemma:clique-bound}, applied to the subset $P \subseteq V(G)$.
By the lemma, for every $i \in [\ell]$, $P \cap C_i \in \mathcal{R}(P)$.
On the other hand, every clique is contained in a $2 \times 4$ rectangle, therefore by Lemma~\ref{lemma:area-cover}
only constantly many cliqes from $C_1$, \ldots, $C_\ell$ intersect this clique.
Since $P$ is covered by at most $\kappa$ cliques, 
it also holds that only constantly many cliqes from $C_1$, \ldots, $C_\ell$ intersect $P$, where the constant depends on $\kappa$ and Lemma~\ref{lemma:area-cover}; denote this constant by $\lambda$.
Later in the algorithm, we will characterize the solution $(C_1, \ldots, C_\ell)$ on $P$ by listing the $\lambda$ cliques from $\mathcal{R}(P)$ that result from intersecting $(C_1, \ldots, C_\ell)$ with $P$.
We now proceed to the proof of the theorem.

\begin{proof}[Proof of Theorem~\ref{theorem:subexpalgo}]
    We first apply Theorem~\ref{thm:framework} with $\gamma(t) = \varepsilon \log t + 1$ for a sufficiently small constant $\varepsilon > 0$, obtaining a $\kappa$-partition $\mathcal{P}$ of $G$, and a tree decomposition of $G_{\mathcal{P}}$ of weight at most $O(\sqrt{n})$.
%Let $t$ be a node of the weighted tree decomposition.
% Every partition class $P \in \mathcal{P}$ lies in a region of constant size, so it is divided into at most $O(1)$ cliques in an optimal solution by Lemma~\ref{lemma:area-cover}.
For $P \in \mathcal{P}$, let $\mathcal{R}(P)$ be a collection of relevant cliques in $P$ as per Lemma~\ref{lemma:clique-bound}.
We define a \emph{configuration} of $P$ by a pair $(\mathcal{C}, \chi)$ as follows.
%TODO: define configurations and relevant cliques a bit more formally
The first element, $\mathcal{C} \subseteq \mathcal{R}(P)$, is a collection of at most $\lambda$ cliques such that $\bigcup \mathcal{C} = P$.
%We may assume here that $|\mathcal{C}| \in O(1)$ by Lemma~\ref{lemma:area-cover}, since $P$ lies in a region of constant size by the definition of the $\kappa$-partition.
The second element, $\chi \colon \mathcal{C} \to \{ 0, 1 \}$, is a mapping, which we will use to indicate whether a clique $C \in \mathcal{C}$ has been covered.
We denote the set of configurations of $P$ by $\Gamma_P$.
Since $|\mathcal{R}(P)| \in |P|^{O(1)}$ by Lemma~\ref{lemma:clique-bound}, there are at most $\lambda \cdot |\mathcal{R}(P)|^{\lambda} \cdot 2^{\lambda} \in |P|^{O(1)}$ many configurations.
Thus, for a bag $t$, the number of all combinations of configurations of nodes in $t$ is at most
\begin{align*}
    \prod_{P \in \sigma(t)} |P|^{O(1)} = \exp \left( c \sum_{P \in \sigma(t)} \log |P| \right) \in 2^{O(\sqrt{n})}.
\end{align*}
Here, $c$ is a constant, and the second equality is due to the fact that the weighted treewidth is $O(\sqrt{n})$.
The running time will be dominated by this factor.

Our dynamic programming constructs a table $c_t$ for a bag $t$ indexed by a configuration for each $P \in \sigma(t)$ and an integer $\ell$.
% that counts the number of cliques that intersect ``child'' node.
We describe the configuration by a mapping $f$ that maps $P \in \sigma(t)$ to one of its configurations in $\Gamma_P$.
We use the notation $f(P) = (f_{\mathcal{C}}(P), f_{\chi}(P))$.
The table $c_t$ stores Boolean values, where the entry  $c_t[f, \ell]$ is true  if and only if there is a collection $(C_1, \dots, C_{\ell})$ of $\ell$ cliques such that
\begin{itemize}
    \item
        $\bigcup_{i \in [\ell]} C_i$ covers all vertices appearing strictly below $t$ (i.e., every vertex in $P \in \mathcal{P} \setminus \sigma(t)$ such that $P$ appears in the subtree rooted at $t$ is covered by $\bigcup_{i \in [\ell]} C_i$)%\ktodo{the ``i.e.'' part confused me more than it helped; T: I hope it's better},
    \item
    $\bigcup_{i \in [\ell]} C_i$ covers all cliques $C \in f_{\mathcal{C}}(P)$ with $P \in \sigma(t)$ and $f_{\chi}(P)(C) = 1$, and 
    \item
    every clique $C_i$, $i \in [\ell]$, contains a vertex appearing strictly below $t$.
\end{itemize}
Our dynamic programming will maintain this invariant.

Now we describe our dynamic programming procedure over a nice tree decomposition (see Section~\ref{sec:prelim} for the definition).
It follows from our invariants that the input graph admits a clique cover of size $\ell$ if and only if $c_r[f, \ell] = 1$ for the root $r$.
For a non-leaf node $t$, we will denote its children by $t', t''$ ($t'$ if $t$ has one child).

\proofsubparagraph{Leaf node.}
Suppose that $t$ is a leaf node, i.e., $\sigma(t) = \emptyset$.
Then, $c_t[f, \ell]$ is true if and only if $\ell = 0$.

\proofsubparagraph{Introduce node.}
Suppose that $t$ is an introduce node, i.e., $\sigma(t) = \sigma(t') \cup \{ P \}$.
\begin{align*}
    c_t[f, \ell] =
    \begin{cases}
        c_{t'} [f|_{\sigma(t')}, \ell] & \text{ if  $f_{\chi}(P)(C) = 0$ for every $C \in f_{\mathcal{C}}(P)$}, \\
        \text{false} & \text{ otherwise.}\\
    \end{cases}
\end{align*}
Here, $f|_{\sigma(t')}$ denotes the restriction of $f$ to $\sigma(t')$.
As we only consider cliques that intersect a node strictly below $t$, we set the table entry to false if $f_{\chi}(P)$ is not uniformly zero.

\proofsubparagraph{Forget node.}
Suppose that $t$ is a forget node, i.e., $\sigma(t) = \sigma(t') \setminus \{ P \}$.
We have the following recurrence:
\begin{align*}
    c_t[f, \ell] = \bigvee_{\ell' \in \{ 0, \dots, \ell \}, f'} c_{t'}[f', \ell']
\end{align*}
where $\bigvee$ ranges over all $f'$ and $\ell'$ that satisfy the following condition.
Let $H_{f'}$ be an auxiliary graph as follows.
% For $(\mathcal{C}, \chi) = f'(P)$, we construct $H_{f'}$ as follows.
For every $C \in f_{\mathcal{C}}'(P)$ with $f_{\chi}(P)(C) = 0$, we add a vertex $h_C$.
Moreover, for every $P' \in \sigma(t)$ and $C \in f_{\mathcal{C}}(P')$, we add a vertex $h_{C}$ to $H$ if (i) $C$ has not been covered at $t'$, i.e., $f_{\chi}'(P')(C) = 0$ and (ii) $C$ is covered at $t$, i.e., $f_{\chi}(P')(C) = 1$.
Two vertices $h_{C}$ and $h_{C'}$ are adjacent in $H_{f'}$ if and only if $C \cup C'$ is a clique in the graph $G$.
This concludes the construction of $H_{f'}$.
Note that $H_{f'}$ has size $O(\sqrt{n})$.
Then $\bigvee$ ranges over $f'$ and $\ell'$ such that $H_{f'}$ has a clique cover $(D_{1}, \dots, D_{\ell - \ell'})$ of size $\ell - \ell'$ such that every clique $D_i$ contains a vertex $h_{C}$ for $C \in f_{\mathcal{C}}'(P)$.
Whether $f'$ and $\ell'$ fulfills this condition can be checked in $2^{O(\sqrt{n})}$ time via dynamic programming.

Specifically, we proceed in a standard fashion for a \probColoring/\probcliqueparition subset-based dynamic programming.
For each subset $S \subseteq V(H_{f'})$ and each integer $k$, $0 \le k \le \ell - \ell'$, we compute the Boolean value $d[S, k]$
that is equal to true if and only if the subgraph $H_{f'}[S]$ admits a clique cover of size $k$, where additionally every clique contains a vertex $h_C$ for some $C \in f'_C(P)$.
We initialize by setting $d[\emptyset, 0] = $ true, $d[S, 0] = $ false for each $S \ne \emptyset$, and for each $S \subseteq V(H_{f'})$, $k \in [\ell - \ell']$,
compute $d[S, k] = \bigvee_{D \text{ is an admissible clique in } H_{f'}[S]} d[S \setminus D, k - 1]$.
Clearly, the dynamic programming table above is computed in time $2^{O(|V(H_{f'})|)} = 2^{O(\sqrt{n})}$.
As there are $2^{O(\sqrt{n})}$ many choices for the configuration $f'$, we can compute $c_t[f, \ell]$ in overall time $2^{O(\sqrt{n})}$.


% So a minimum clique cover of $H_{f'}$ can be computed in $O(1)$ time.
% Essentially, we consider all possibilities of how each clique $C \in \mathcal{C}$ with $\chi(C) = 0$ is covered along with other cliques.
Let us verify that the invariant is maintained by the computation above.
If $c_t[f, \ell]$ is set to true, then there exist $f'$ and $\ell'$ satisfying the aforementioned condition, for which $c_{t'}[f', \ell']$ is also true.
Since $c_{t'}[f', \ell']$ is true, there exists a collection $(C_1, \dots, C_{\ell'})$ of cliques.
Also, $H_{f'}$ admits clique cover of size $\ell - \ell'$, which is also a collection of cliques in $G$.
Combining these cliques indeed satisfies the conditions.

\proofsubparagraph{Join node.}
Suppose that $t$ is a join node, i.e., $\sigma(t) = \sigma(t') = \sigma(t')$.
We have the recurrence:
\begin{align*}
    c_t[f, \ell] = \bigvee_{\ell' \in \{ 0, \dots, \ell \},\, f'\!,\, f''} (c_{t'}[f', \ell'] \wedge c_{t''}[f'', \ell - \ell']), 
\end{align*}
where $\bigvee$ ranges over functions $f', f''$ that map $P \in \sigma(t)$ to one of its configurations such that for every $P \in \sigma(t)$,
\begin{itemize}
    \item $P$ is partitioned in cliques in the same way, i.e., $f_{\mathcal{C}}(P) = f_{\mathcal{C}}'(P) = f_{\mathcal{C}}''(P)$, and 
    \item for every $C \in f_{\mathcal{C}}(P)$, $f_{\mathcal{\chi}}(P)(C) = 1$ if and only if $C$ is covered in one of the children, i.e., $f_{\mathcal{\chi}}'(P)(C) = 1$ or $f_{\mathcal{\chi}}''(P)(C) = 1$.
\end{itemize}

To see why the invariant is maintained, note that if $c_t[f, \ell]$ is set to true, then there are $\ell'$ cliques certifying $c_{t'}[f', \ell']$ being true and $\ell - \ell'$ cliques certifying $c_{t''}[f'', \ell - \ell']$ being true.
Putting them together, we obtain a collection of $\ell$ cliques satisfying the conditions.

Observe that each entry can be computed in $2^{O(\sqrt{n})}$ time.
Since there are $2^{O(\sqrt{n})}$ entries, the running time is bounded by $2^{O(\sqrt n)}$.
Note that all arithmetic operations can be performed in polynomial time: we only require comparing distances between the given points and orientations between triples of given points; see the proof of Lemma~\ref{lemma:clique-bound}.
Theorem~\ref{thm:framework} is representation-agnostic, meaning that no additional arithmetic operations are required, except for constructing the graph from the given geometric representation.

This concludes the proof of Theorem~\ref{theorem:subexpalgo}.
\end{proof}

\section{Subexponential lower bound for $d \ge 2$}
In this section, we establish the impossibility of solving the \probcliqueparition problem on $d$-dimensional unit ball graphs in time better than $2^{O(n^{1 - 1/d})}$.
For this, we use the result of de Berg et al.~\cite{BergBKMZ20}, which states that, assuming \classETH, \probgridembedded cannot be solved in time $2^{o(n)}$ time, where $n$ is the number of variables of the given formula.

%A $3$-CNF formula $\phi = C_1 \wedge \ldots \wedge C_m$ is a boolean formula over $n$ variables $X = \{x_1, x_2, \ldots, x_n\}$, such that each clause $C_i$ is a disjunction of at most $3$ literals of the form $x_i$ or $\neg x_i$, for some $1 \le i \le n$. 
%Given a $3$-CNF formula $\phi$, its \emph {incidence} graph $G_{\phi}$ is the bipartite graph on its variables and clauses, where an edge connects a variable vertex and a clause vertex if the variable appears in the clause.
%A CNF formula $\phi$ is a $(3,3)$-CNF formula if all clauses in $\phi$ have a size at most three and each variable occurs at most three times.
%In a  $(3,3)$-SAT instance, we are given a $(3,3)$-CNF formula $\phi$, and the question is to decide whether $\phi$ is satisfiable. 
%We denote by $G^2({n_1,n_2})$ the two dimensional grid graph with vertex set $[n_1] \times [n_2]$.
%We say that a graph $H$ is \emph{embeddable} in $G^2({n_1,n_2})$ if it is a topological minor of $G^2({n_1,n_2})$, i.e, if $H$ has a subdivision that is a subgraph of $G^2({n_1,n_2})$.
\probgridembedded is defined as follows.
Let $G^2(n)$ denote the $n \times n$-grid graph, where there is a vertex $(i, j)$ for every $i, j \in [n]$ and an edge between $(i,j)$ and $(i', j')$ are adjacent if and only if $|i - i'| = |j - j'| = 1$.
We say that a graph $H$ is \emph{embedded} in $G^2(n)$ if a subdivision of $H$ is isomorphic to a subgraph of $G^2(n)$.
For a CNF formula $\phi$, the \emph{incidence graph} $G_{\phi}$ of $\phi$ is the bipartite graph, where there is a vertex for each variable and each clause, and there is an edge between a variable vertex and a clause vertex if and only if the variable appears in the clause.
A $(3, 3)$-CNF formula is a CNF formula where each variable appears at most 3 times and each clause has size at most 3.

% In , we are given a $(3,3)$-CNF formula whose incidence graph is embedded in an $n \times n$ grid, and the goal is to determine the satisfiability of the formula.
% More formally, the problem is defined as follows.

\defproblema{\probgridembedded}%
{A $(3,3)$-CNF formula $\phi$ together with an embedding of its incidence graph $G_{\phi}$ in $G^2({n})$.}%
{Is there a satisfying assignment for $\phi$?}
%To define the \probgridembedded problem, we need to define 
%Berge et al. showed the following result~\cite{BergBKMZ20}.
\begin{proposition}[\cite{BergBKMZ20}, Theorem 3.2]{\label{prop:gridembeddedeth}}
    \probgridembedded can not be solved in time $2^{o(n)}$ unless \classETH fails.
 \end{proposition}

To show \classETH-hardness for $\mathbb{R}^d$, $d \ge 3$, we use the \emph{cube wiring theorem} due to de Berg et al.~\cite{BergBKMZ20}.
Let $B^{d}(n)$ denote $[n]^d$ and $G^d(n)$ denote the $d$-dimensional hypercube over $B^d(n)$.
Also, for $p \in B^{d-1}(n)$ and $h \in [n]$, let $\xi^{h}(p) = (p_1, \dots, p_{d-1}, h) \in B^{d}(n)$.
For $s \in \mathbb{N}$, a set $P \subseteq \mathbb{Z}^{d-1}$ is said to be $s$-spaced if there is an integer $0 \le r < s$ such that for every $p = (p_1, \dots, p_{d-1}) \in P$ and $i \in [d-1]$, $p_i \equiv r \bmod 2$.

\begin{theorem}[Cube wiring theorem \cite{BergBKMZ20}]\label{thm:cube}
    For $d \ge 3$, let $P$ and $Q$ be two 2-spaced subsets of $B^{d-1}(n)$ and let $M$ be a perfect matching in the bipartite graph $(P \cup Q, P \times Q)$.
    Then, for $n' \in O(n)$, $G^d(n')$ contains vertex-disjoint paths that connect $\xi^{1}(p)$ and $\xi^{n'}(q)$ for every $pq \in M$.
\end{theorem}

Now we prove our theorem.

