            ||\pi(c_1) - \pi(c_2)|| &\ge 2 + \xi,\label{eq:pi6}
        \end{align}
        and for any other two vertices $v, u$ of $G'$, the distance $||\pi(v) - \pi(u)||$ is at most $2 - \xi$.
        \label{claim:pi}
    \end{claim}
    \begin{proof}
        Let $\xi = \epsilon'/2$. Equation~\eqref{eq:pi1} holds immediately by construction, since each $v \in T \cup B$ is situated exactly $R_1$ away from the origin, each $w \in W$ exactly $R_2$ away from the origin, $T \cup B$ is contained in the 3-dimensional subspace $Ox_1x_2x_3$ which is orthogonal to the plane $Ox_4x_5$ where $W$ is contained, and $R_1^2 + R_2^2 = 4$ by definition of $R_2$.

        For Equation~\eqref{eq:pi2}, observe that $||\pi(t_e^1) - \pi(t_e^2)|| = 2 + 2\epsilon'$ for each $e \in E(G)$ since these two points are situated diametrically opposite to each other on a circle of radius $1 + \epsilon'$. Therefore, $||\pi(t_e^1) - \pi(t_e^2)|| \ge 2 + \xi$ since $\epsilon' = 2\xi \ge \xi/2$. On the other hand, consider the points $t_e^1$ and $t_{e'}^2$ for $e \ne e'$. Since $t_{e'}^2$ lies on the same circle at the angle of at least $\delta/m$ away from $t_e^2$, the distance between $t_e^1$ and $t_{e'}^2$ is at most $2 (1 + \epsilon') \cos (\delta/2m)$. Therefore, if it holds that $(1 + \epsilon') \cos(\delta/2m) \le 1 + \xi/2 = 1 + \epsilon'/4$, then all distances between the points of $T$ are as desired. Moreover, exactly the same arguments hold for Equation~\eqref{eq:pi3} and the distances between the points of $B$. We now show this bound given that $\epsilon'$ is sufficiently small:
        \begin{multline*}
            \epsilon' \le \frac{\delta^2}{20m^2} \implies 
            \frac{1 + \epsilon'}{\epsilon'} \ge \frac{20m^2}{\delta^2} \implies
            \frac{\delta^2}{16 m^2} \ge \frac{5}{4} \cdot \frac{\epsilon'}{1 + \epsilon'}\\
            \implies 1 - \frac{\delta^2}{16 m^2} \le 1 - \frac{5}{4} \cdot \frac{\epsilon'}{1 + \epsilon'} = \frac{1 - \epsilon'/4}{1 + \epsilon'}\\
            \implies
            (1 + \epsilon') \cdot \cos\frac{\delta}{2m} \le (1 + \epsilon') \cdot (1 - \frac{\delta^2}{16 m^2}) \le 1 - \epsilon'/4.
        \end{multline*}
        Here, we also use that $\delta$ is a sufficiently small constant.

        Consider now Equation~\eqref{eq:pi4}, the distance between $\pi(c_1)$ and $\pi(t_e^h)$ is equal to $\sqrt{3 + r^2}$ for each $e \in E(G)$ and $h \in [2]$. It is therefore sufficient to have $\sqrt{3 + (1 + \epsilon')^2} \ge 2 + \xi$, which holds since $\epsilon' = 2\xi$, and the same argument holds for Equation~\eqref{eq:pi5} because of the symmetry.
        Note that the distance between $\pi(c_2)$ and $\pi(t_e^h)$ for any $e \in E(G)$, $h \in [2]$ is equal to 
        $$\sqrt{(\sqrt{3} - \sqrt{2} + 2\epsilon)^2 + r^2} = \sqrt{(\sqrt{3} - \sqrt{2})^2 + 1 + O(\epsilon + \epsilon')} < 1.5 \le 2 - \xi,$$
        for sufficiently small $\epsilon$, $\epsilon'$ and $\xi$. The same holds for $\pi(c_1)$ and $\pi(b_e^h)$ for any $e \in E(G)$, $h \in [2]$.

        For Equation~\eqref{eq:pi6}, $$||\pi(c_1) - \pi(c_2)|| = 2\sqrt{3} - \sqrt{2} + 2\epsilon\ge 2.049 \ge 2 + \xi$$
        when $\xi$ is sufficiently small.

        It remains to verify that pairwise distances not discussed above are bounded by $2 - \xi$. Consider first $w \in W$ and $c_h$ for $h \in [2]$,  the respective squared distance is
        \begin{multline*}
        ||\pi(w) - \pi(c_h)||^2 = R_2^2 + (\sqrt{3} - \sqrt{2}/2 + \epsilon)^2 = 4 - R_1^2 + (\sqrt{3} - \sqrt{2}/2)^2 + O(\epsilon)\\
        \le 5.025 - R_1^2 + O(\epsilon) = 5.025 - (\sqrt{2}/2 - \epsilon)^2 - (1 + \epsilon')^2 + O(\epsilon) \\
        = 5.025 - 1/2 - 1 + O(\epsilon + \epsilon') = 3.525 + O(\epsilon + \epsilon') \le 3.8
        \end{multline*}
        for sufficiently small $\epsilon$ and $\epsilon'$. Therefore, $||\pi(w) - \pi(c_h)|| \le 2 - \xi$ when $\xi$ is sufficiently small.

        Note also that when $\delta$ is a sufficiently small constant, distances between all pairs of vertices in $W$ under $\pi$ are at most $1$, since the images occupy an arc which is a small fraction of a constant-radius circle, and the same holds for pairs in $T_1$, $T_2$, $B_1$, $B_2$.

        Finally, it remains to consider pairs of the form $t \in T$, $b \in B$. Observe that when projecting $T$ and $B$ orthogonally on the plane $Ox_2x_3$, these sets lie on the same circle of radius $r = 1 + \epsilon'$, and the radial distance between a point in $T$ and a point in $B$ is always at most $\pi / 2 + \delta$, since $T_1$, $B_1$, $T_2$, $B_2$ are each rotated $\pi/2$ further away from the previous set, and each of the four sets occupies an arc of radial length at most $\delta$. Therefore, 
        \begin{multline*}
            (2 - \xi)^2 - ||\pi(t) - \pi(b)||^2 \ge (2 - \xi)^2 - (\sqrt{2} - 2\epsilon)^2 - 2 (1 + \epsilon')^2 (1 + \sin \delta) \\
            \ge 4(\sqrt{2} - 1) \epsilon - 4\xi - 6 \epsilon' - 8 \delta,
        \end{multline*}
        by using $\epsilon', \epsilon \le 1$ and $\sin \delta \le \delta$.
        The above value is greater than zero if $\epsilon \ge 8(\epsilon' + \xi + \delta)$.

        To conclude the proof of the claim,  we note that the parameters $\xi$, $\epsilon'$, $\delta$, $\epsilon$ clearly admit values that satisfy all the restrictions above. Indeed, it is only required that each of them does not exceed a certain constant independent of the other parameters, and additionally that $2\xi = \epsilon' \le \frac{\delta^2}{20m^2}$, and $\epsilon \ge 8(\epsilon' + \xi + \delta)$.

    \end{proof}

    Finally, we construct the embedding $\pi'$ that gives the desired representation of $G'$. For that, we modify $\pi$ in the following way: we only change the images of vertices in $T\cup B$. Namely, $\pi'(v) = \pi(v)$ for $v \in V(G') \setminus (T \cup B)$, and for each $e = uv \in E(G)$,
    \begin{align*}
        \pi'(t_e^1) = \pi(t_e^1) + \theta \cdot \overrightarrow{\pi(u)O},\\
        \pi'(b_e^1) = \pi(b_e^1) + \theta \cdot \overrightarrow{\pi(u)O},\\
        \pi'(t_e^2) = \pi(t_e^2) + \theta \cdot \overrightarrow{\pi(v)O},\\
        \pi'(b_e^2) = \pi(b_e^2) + \theta \cdot \overrightarrow{\pi(v)O},
    \end{align*}
 where $\theta > 0$ is a small value to be defined later.
    We show that the embedding $\pi'$ is indeed a unit ball representation of the complement of $G'$. 

    \begin{claim}
        For every $u, v \in V(G')$, $uv \in E(G')$ if and only if $||\pi'(u) - \pi'(v)|| > D$, for some $D > 2$.
        \label{claim:piprime}
    \end{claim}
    \begin{proof}
        First, we consider distances between the pairs $\pi'(w)$, $\pi'(v)$, where $w \in W$, $v \in T \cup B$.
        Let $v \in T \cup B$ and let $w$ be the unique vertex in $W$ such that $\pi'(v) = \pi(v) + \theta \cdot \overrightarrow{\pi(w)O}$. The respective squared distance is then $||\pi'(v) - \pi'(w)||^2 = R_1^2 + (R_2 + \theta)^2$.
        On the other hand, consider a vertex $w' \in W$ with $w' \ne w$.
        For $v$ and $w'$, the squared distance is $||\pi'(v) - \pi'(w')||^2 \le R_1^2 + R_2^2 + \theta^2 + 2 R_2\theta \cos(\delta/n)$, since the distance is independent in $Ox_1x_2x_3$ and $Ox_4x_5$, and in the latter plane the vertex $w'$ is at least at angle of $\delta / n$ away from the line $\overrightarrow{O\pi(w)}$, which by the law of cosines gives the upper bound above. 

        By setting $D = \sqrt{R_1^2 + R_2^2 + \theta^2 + 2 R_2\theta \cos(\delta/n)}$ we therefore achieve that $||w' - v|| \le D$ for each $w' \ne w$, while $||w - v|| > D$ since 
        $$(R_1^2 + (R_2 + \theta)^2) - (R_1^2 + R_2^2 + \theta^2 + 2 R_2\theta \cos(\delta/n)) = 2 R_2 \theta \cdot (1 - \cos(\delta / n)) > 0.$$

        Observe that $2 < D$ since $R_1^2 + R_2^2 = 4$, and that $D < 2 + \xi/2$ for a sufficiently small value of $\theta$; fix $\theta$ so that the latter holds.
        We now verify the distance condition for the remaining pairs.
        First, the distance between vertices of $W$ and $c_1$/$c_2$ is the same under $\pi$ and $\pi'$, so it is at most $2 < D$.
        It remains to consider distances between pairs of vertices in $X$, where $X = T \cup B \cup C$. For each $v, u \in X$, 
        $$||\pi'(u) - \pi'(v)||^2 - ||\pi(u) - \pi(v)||^2 \le 2 \theta^2 R_2^2$$
        since the change from $\pi$  to $\pi'$ shifts each vertex by at most the vector of $\theta \cdot \overrightarrow{\pi(w)O}$ for some $w \in W$; the length of this vector is $\theta R_2$, and $\pi$ acts only into the subspace $Ox_1x_2x_3$ on $X$. Clearly, for sufficiently small $\theta$ we get that
$$-\xi/2 < ||\pi'(u) - \pi'(v)|| - ||\pi(u) - \pi(v)|| < \xi/2.$$
        Therefore, all distances that were at most $2 - \xi$ (at least $2 + \xi$, respectively) under $\pi$ from Claim~\ref{claim:pi} remain at most $2 - \xi / 2$ (at least $2 + \xi / 2$, respectively) under $\pi'$. Since $2 - \xi/2 < 2 < D < 2 + \xi/2$, the proof of the claim is concluded.
    \end{proof}

    By Claim~\ref{claim:piprime}, we get the correctness of the presented reduction.
    It remains to observe that the reduction can be done in polynomial time: Only precision polynomial in input size is required for the parameters used for the computation of the coordinates.
    Since in the resulting instance of \probcliqueparition there are $O(n + m)$ vertices, and \textsc{$3$-Coloring} does not admit a $2^{o(n + m)}$-time algorithm under the \classETH, the statement of the theorem follows.
\end{proof}


