\subsection{Convergence Analysis of {\tt 2CEOAFL} Algorithm}
\label{conv2ceoaflSubSection}
\noindent
We make the following standard assumptions \cite{jiang2022model,liu2022Joint, stich2018sparsified,reisizadeh2020FedPAQ,pervej2024online,pervej2024hierarchical}.

\noindent
\textbf{Assumption $\mathbf{1}$}(Smoothness).
    The local loss functions are $\beta$-Lipschitz smooth, i.e., for some $\beta > 0$, we have $\Vert \nabla f_u \left(\mathbf{w} | \mathcal{D}_u^t \right) - \nabla f_u \left(\mathbf{w}'| \mathcal{D}_u^t\right) \Vert \leq \beta \Vert \mathbf{w} - \mathbf{w}' \Vert$.

\noindent
\textbf{Assumption $\mathbf{2}$} (Unbiased gradient with bounded variance). 
    The stochastic mini-batch gradient at each \ac{acv} is unbiased, i.e., $\mathbb{E}_{\xi \sim \mathcal{D}_u^t} [g_u \left(\mathbf{w}_u | \mathcal{D}_u^t\right)] = \nabla f_u \left( \mathbf{w}_u | \mathcal{D}_u^t\right)$, for all $u$ and $\mathbf{w}_u$.
    Besides, the variance of the stochastic gradients are bounded, i.e., $\left\Vert g_u \left( \mathbf{w}_u | \mathcal{D}_u^t \right) - \nabla f_u \left( \mathbf{w}_u | \mathcal{D}_u^t \right) \right\Vert^2 \leq \sigma^2$ for some $\sigma \geq 0$, for all $u$. 

\noindent
\textbf{Assumption $\mathbf{3}$} (Bounded gradient dissimilarity).
There exist some finite constants $\rho_1 \geq 1$ and $\rho_2 \geq 0$ such that the local and global gradients have the following relationship 
\begin{align}
    \left\Vert \nabla f_u \left(\mathbf{w} |\mathcal{D}_u^t \right) \right \Vert^2 \leq  \rho_1 \left \Vert \nabla f \left(\mathbf{w} | \mathcal{D}^t \right) \right\Vert^2 + \rho_2 \epsilon_u^t,
\end{align}
where $\epsilon_u^t$ is the difference between the statistical data distributions of $\mathcal{D}^t$ and $\mathcal{D}_u^t$. 
We assume that $\rho_1=1$ and $\rho_2=0$ when all clients have identical data distributions.


\noindent
\textbf{Assumption $\mathbf{4}$}.
The stochastic quantization operation is unbiased, i.e., $\mathbb{E}_Q \left[Q (\mathbf{d}) \right] = \mathbf{d}$. 
Besides, its variance grows as 
\begin{align}
    \mathbb{E}_Q \left[ \left\Vert Q (\mathbf{d}) - \mathbf{d} \right\Vert^2 \right] \leq q \Vert \mathbf{d} \Vert^2 ,
\end{align}
where $q$ is a positive real constant.

\noindent
\textbf{Assumption $\mathbf{5}$} (Pruning ratio \cite{stich2018sparsified}).
The pruning ratio $\delta_u^t \in [0,\delta_{\mathrm{th}}]$, where $0 < \delta_{\mathrm{th}} \leq 1$, is bounded as follows:
\begin{equation}
\label{pruneRatio}
    \delta_u^t \geq \left\Vert \mathbf{w}_u^{t} - \Bar{\mathbf{w}}_u^{t,0} \right\Vert^2 / \left\Vert \mathbf{w}_u^{t} \right\Vert^2. 
\end{equation}
Moreover, $\mathbf{w}_u^{t, \tau} = \Bar{\mathbf{w}}_u^{t, \tau}$ only when $\delta_u^t = 0$.  

\begin{Definition}[Local data distribution shift \cite{pervej2024online}]
Suppose that the $u^{\mathrm{th}}$ \ac{acv} has datasets $\mathcal{D}_u^{t-1}$ and $\mathcal{D}_u^t$ during the global round $(t-1)$ and $t$, respectively. 
Then, there exist a $\Phi_u^t \geq 0$ that measures the shifts in the distributions of the \ac{acv}'s datasets between two consecutive global round as 
\begin{align}
\label{localDataShift_Def}
    \left \Vert \nabla f_u \left(\mathbf{w} | \mathcal{D}_u^{t-1}  \right) - \nabla f_u \left(\mathbf{w} | \mathcal{D}_u^t  \right) \right\Vert^2 \leq \Phi_u^t, \qquad \forall u \in \mathcal{U}, 
\end{align}
with $\Phi_u^{t=0}=0$.
\end{Definition}


Since the loss functions are typically not convex, we seek a sub-optimal convergence bound. 
We define $\frac{1}{T} \sum_{t=0}^{T-1} \mathbb{E} \left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2 \coloneqq \pmb{\theta}$, where $\bar{\nabla} f (\cdot)  \coloneqq \sum_{u=0}^{U-1} \alpha_u \nabla f_u (\cdot) \odot \mathbf{m}_u^t$, and derive a $\pmb{\theta}$-sub-optimal convergence bound in what follows.
\begin{Theorem}
\label{conv_Theorem}
Suppose the above assumptions hold. 
When the learning rates $\eta^t \leq \frac{1}{\beta\kappa(2+q)}$ and $\Tilde{\eta}^t < \text{min} \left\{\frac{1}{2\sqrt{2}\beta\kappa}, \frac{1}{2\sqrt{2\rho_1}\beta\kappa} \right\}$, the global gradient is upper-bounded as
\begin{align}
    & \mathbb{E} \!\left[\left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2 \right] \rs  
    \leq \rs \frac{2 \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t \kappa} \nonumber\\
    &\quad + \beta \underbrace{\sigma^2}_{\mathrm{error:~SG}} \Big( \underbrace{\kappa \eta^t \sum\nolimits_{u=0}^{U-1} \alpha_u^2 \mathrm{C}_u\left(q,\mathfrak{q}_u^t \right) }_{\mathrm{error:~quantization}} + 2 \beta \kappa (\Tilde{\eta}^t)^2 \Big) + \nonumber\\
    &\quad \underbrace{16 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \sum\nolimits_{u=0}^{U-1} \alpha_u \Phi_u^t}_{\mathrm{error: ~local~data~ dist.~shift}} + \underbrace{8 \rho_2 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \sum\nolimits_{u=0}^{U-1} \alpha_u \epsilon_u^t}_{\mathrm{error:~gradient ~ dissimilarity}} + \nonumber\\
    &\quad \underbrace{2 \beta^2 \sum\nolimits_{u=0}^{U-1} \alpha_u \delta_u^t \mathbb{E} \left[\left \Vert \mathbf{w}_u^t \right\Vert^2 \right]}_{\mathrm{error:~model~ pruning}},  \label{convgBound_Gradient_Evolution}
\end{align}
where $\mathrm{C}_u \left(q,\mathfrak{q}_u^t \right) \coloneqq 2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t $. 
Moreover, averaging over time, we get the convergence bound as
\begin{align}
    &\pmb{\theta}  
    \leq \frac{2}{\kappa T} \sum\nolimits_{t=0}^{T-1} \left[ \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right) / \eta^t \right] + \nonumber\\
    & \left(\beta  \sigma^2 / T \right) \rs \left( \sum\nolimits_{u=0}^{U-1} \rs \alpha_u^2 \sum\nolimits_{t=0}^{T-1} \rs \eta^t  \mathrm{C}_u\left(q, \mathfrak{q}_u^t\right) + 2 \beta \kappa \sum\nolimits_{t=0}^{T-1} (\Tilde{\eta}^t)^2 \!\right) \! + \nonumber\\
    & \frac{16 \beta^2 \kappa^2}{T} \sum_{t=0}^{T-1} \rs \left(\Tilde{\eta}^t\right)^2 \sum_{u=0}^{U-1} \alpha_u \Phi_u^t + \frac{8 \rho_2 \beta^2 \kappa^2 }{T} \sum_{t=0}^{T-1} \left(\Tilde{\eta}^t\right)^2 \sum_{u=0}^{U-1} \alpha_u \epsilon_u^t + \nonumber\\
    & \left(2 \beta^2 / T \right) \sum\nolimits_{t=0}^{T-1} \sum\nolimits_{u=0}^{U-1} \alpha_u \delta_u^t \mathbb{E} \left[\left \Vert \mathbf{w}_u^t \right\Vert^2 \right]. \label{convBoundAvgOverTime}
\end{align}
\end{Theorem}
\begin{proof}
The proof is left in Appendix \ref{appendix_Conv_Theorem}.
\end{proof}



The first term in (\ref{convgBound_Gradient_Evolution}) captures the change in the global loss function between two consecutive rounds, while the second term is the consequence of the mini-batch \ac{sgd} and the gradients quantization.
Besides, the third term is due to continual local data distribution shifts, while the fourth term reflects the effect of bounded gradient dissimilarities between the \acp{acv} due to statistical data heterogeneity. 
Finally, the last term is the effect of model pruning. 


\begin{Remark}
While diminishing learning rates $\eta^t \rightarrow 0$ and $\Tilde{\eta}^t \rightarrow 0$ as $t \rightarrow \infty$, may make the noise from the stochastic gradients, i.e., $\sigma^2$, quantization $q$, local data distribution shift $\Phi_u^t$ and bounded gradient dissimilarity, i.e., $\epsilon_u^t$, terms close to $0$, small learning rates may slow down the learning performance.
Besides, since these error terms get scaled by $\kappa$, one may choose a local rate that satisfies $\eta^t \propto \frac{1}{\kappa}$ to control these error terms. 
However, regardless of the choice of the learning rate, the error from model pruning in the last term does not vanish unless $\bar{\mathbf{w}}_u^{t,0}=\mathbf{w}_u^{t,0}$.
Therefore, the global gradient may only converge to a neighborhood of a stationary point. 
\end{Remark}




