\setcounter{Theorem}{0} 
\section{Proof of Theorem \ref{conv_Theorem_Supp}}
\label{appendix_Conv_Theorem}
\noindent
\begin{Theorem}
\label{conv_Theorem_Supp}
Suppose that the above assumptions hold. 
When the learning rates $\eta^t \leq \frac{1}{\beta\kappa(2+q)}$ and $\Tilde{\eta}^t < \text{min} \left\{\frac{1}{2\sqrt{2}\beta\kappa}, \frac{1}{2\sqrt{2\rho_1}\beta\kappa} \right\}$, the global gradient is upper-bounded as
\begin{align}
    \mathbb{E} \left[\left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2 \right] 
    &\leq \Bigg[ \frac{2 \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t\kappa} + \beta \sigma^2 \left( \kappa \eta^t \sum_{u=0}^{U-1} \alpha_u^2 \mathrm{C}_u\left(q,\mathfrak{q}_u^t \right) + 2 \beta \kappa (\Tilde{\eta}^t)^2 \right) + \nonumber\\
    &~ 2 \beta^2 \sum_{u=0}^{U-1} \alpha_u \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 16 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \sum_{u=0}^{U-1} \alpha_u \Phi_u^t + 8 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \rho_2 \sum_{u=0}^{U-1} \alpha_u \epsilon_u^t \Bigg], 
\label{convgBound_Gradient_Evolution_Supp}
\end{align}
where $\mathrm{C}_u \left(q,\mathfrak{q}_u^t \right) \coloneqq 2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t $. 
Moreover, averaging over time gives the following $\pmb{\theta}$-suboptimal convergence bound.
\begin{align}
    &\frac{1}{T}\sum_{t=0}^{T-1}  \mathbb{E} \left[\left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2 \right]  
    \leq \frac{2}{\kappa T} \sum_{t=0}^{T-1} \frac{\left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t} + \frac{\beta \sigma^2}{T} \left( \sum_{u=0}^{U-1} \alpha_u^2 \sum_{t=0}^{T-1} \eta^t  \mathrm{C}_u\left(q, \mathfrak{q}_u^t\right) + 2 \beta \kappa \sum_{t=0}^{T-1} (\Tilde{\eta}^t)^2 \right) + \nonumber\\
    &\Mquad \frac{16 \beta^2 \kappa^2}{T} \sum_{t=0}^{T-1} \left(\Tilde{\eta}^t\right)^2 \sum_{u=0}^{U-1} \alpha_u \Phi_u^t + \frac{8 \beta^2 \kappa^2 \rho_2}{T} \sum_{t=0}^{T-1} \left(\Tilde{\eta}^t\right)^2 \sum_{u=0}^{U-1} \alpha_u \epsilon_u^t + \frac{2 \beta^2}{T} \sum_{t=0}^{T-1} \sum_{u=0}^{U-1} \alpha_u \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right]. \label{convBoundAvgOverTime_Supp}
\end{align}
\end{Theorem}

\begin{proof}
Following our aggregation rule in (\ref{aggRule}), we can write
\begin{align}
\label{conv_eqn0}
    f\left(\mathbf{w}^{t+1} | \mathcal{D}^{t+1}\right) 
    &= f \left(\mathbf{w}^t - \eta^t\sum_{u=0}^{U-1} \alpha_u \Pi_u^t \right) \nonumber\\ 
    &\overset{(a)}{\leq} f \left( \mathbf{w}^t|\mathcal{D}^t \right) + \eta^t\bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), -\sum_{u=0}^{U-1} \alpha_u \Pi_u^t \bigg> + \frac{\beta (\eta^t)^2} {2} \left \Vert \sum_{u=0}^{U-1} \alpha_u \Pi_u^t \right \Vert^2,
\end{align}
where $(a)$ stems from $\beta$-Lipschitz smoothness, i.e., $f(y) \leq f(x) + \left< \nabla f(x), y-x \right> + \frac{\beta}{2} \Vert y - x \Vert^2$.


Now, taking expectations on both sides of (\ref{conv_eqn0}), we get the following
\begin{align}
    \mathbb{E} \left[f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] 
    &\leq \mathbb{E} \big[f \left( \mathbf{w}^t|\mathcal{D}^t \right)\big] + \underbrace{\eta^t\mathbb{E} \bigg[\bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), -\sum_{u=0}^{U-1} \alpha_u \Pi_u^t \bigg>\bigg]}_{\mathrm{T}_1} + \underbrace{\frac{\beta (\eta^t)^2} {2} \mathbb{E} \Bigg[ \left \Vert \sum_{u=0}^{U-1} \alpha_u \Pi_u^t \right \Vert^2 \Bigg]}_{\mathrm{T}_2},
    \label{conv_eqn0_1}
\end{align}
where the expectation depends on the randomness of the mini-batch sampling, random quantization events and stochastic quantizer $Q$.


Then, considering all randomness, we simplify the $\mathrm{T}_1$ term of (\ref{conv_eqn0_1}) as
\begin{align}
    &\mathrm{T}_1 = \eta^t\mathbb{E}_{\pmb{\zeta}^t, Q, \mathbf{\mathfrak{q}}^t} \bigg[\bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), - \sum_{u=0}^{U-1} \alpha_u \Pi_u^t \bigg> \bigg] \nonumber\\
    &=-\eta^t\mathbb{E}_{\pmb{\zeta}^t, Q} \bigg[ \mathbb{E}_{\mathbf{\mathfrak{q}}^t |\pmb{\zeta}^t, Q} \bigg[ \bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \Pi_u^t \bigg>\bigg] \bigg] \nonumber\\
    &=-\eta^t\mathbb{E}_{\pmb{\zeta}^t, Q} \bigg[ \bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t, Q} \big[ \Pi_u^t \big] \bigg> \bigg] \nonumber\\
    &\overset{(a)}{=} -\eta^t\mathbb{E}_{\pmb{\zeta}^t, Q} \left[ \bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t + \sum_{u=0}^{U-1} \alpha_u (1-\mathfrak{q}_u^t) \cdot Q \left( \mathbf{d}_u^t \right) \bigg> \right]\nonumber\\
    &=-\eta^t\mathbb{E}_{\pmb{\zeta}^t} \left[ \mathbb{E}_{Q|\pmb{\zeta}^t} \left[ \bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t + \sum_{u=0}^{U-1} \alpha_u (1-\mathfrak{q}_u^t) \cdot Q \left( \mathbf{d}_u^t \right) \bigg> \right] \right]\nonumber\\
    &=-\eta^t\mathbb{E}_{\pmb{\zeta}^t} \left[ \bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t + \sum_{u=0}^{U-1} \alpha_u (1-\mathfrak{q}_u^t) \cdot \mathbb{E}_{Q|\pmb{\zeta}^t} \left[ Q \left( \mathbf{d}_u^t \right) \right] \bigg> \right]\nonumber\\
    &\overset{(b)}{=}-\eta^t\mathbb{E}_{\pmb{\zeta}^t} \left[ \bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t + \sum_{u=0}^{U-1} \alpha_u (1-\mathfrak{q}_u^t) \cdot \mathbf{d}_u^t \bigg> \right]\nonumber\\
    &= -\eta^t\mathbb{E}_{\pmb{\zeta}^t} \left[ \bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \mathbf{d}_u^t \bigg> \right]\nonumber\\
    &\overset{(c)}{=} -\eta^t\mathbb{E}_{\pmb{\zeta}^t} \left[ \bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} g_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \odot \mathbf{m}_u^t \bigg> \right] \nonumber\\
    &= -\eta^t\bigg< \nabla f \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \mathbb{E}_{\pmb{\zeta}^t} \left[ g_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \odot \mathbf{m}_u^t \right] \bigg>  \nonumber\\
    &\overset{(d)}{=} -\eta^t\left< \sum_{u=0}^{U-1} \alpha_u \nabla f_u \left(\mathbf{w}^t | \mathcal{D}_u^t \right), \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \nabla f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \odot \mathbf{m}_u^t \right> \nonumber\\
    &= -\eta^t\sum_{u=0}^{U-1} \alpha_u \left< \nabla f_u \left(\mathbf{w}^t | \mathcal{D}_u^t \right) \odot \mathbf{m}_u^t, \sum_{\tau=0}^{\kappa-1} \nabla f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \odot \mathbf{m}_u^t \right> \nonumber\\
    &= -\eta^t\sum_{u=0}^{U-1} \alpha_u \left< \bar{\nabla} f_u \left( \mathbf{w}^t | \mathcal{D}^t \right), \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right> \nonumber\\
    &=-\eta^t\sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left< \bar{\nabla} f_u \left( \mathbf{w}^t | \mathcal{D}^t \right), \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right> \nonumber\\
    &\overset{(e)}{=} -\frac{\eta^t}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left[ \left\Vert \bar{\nabla} f_u \left( \mathbf{w}^t | \mathcal{D}_u^t \right) \right\Vert^2 + \left\Vert \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right\Vert^2 - \left\Vert \bar{\nabla} f_u \left( \mathbf{w}^t | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right\Vert^2 \right] \nonumber\\
    &= \frac{\eta^t}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left( \mathbf{w}^t | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right\Vert^2 - \frac{\eta^t}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left( \mathbf{w}^t | \mathcal{D}_u^t \right) \right\Vert^2 - \frac{\eta^t}{2} \sum_{\tau=0}^{\kappa-1} \sum_{u=0}^{U-1} \alpha_u \left\Vert \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right\Vert^2 \nonumber\\
    &\overset{(f)}{\leq} \frac{\eta^t \beta^2}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \mathbf{w}^t - \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 - \frac{\eta^t\kappa}{2} \left\Vert \sum_{u=0}^{U-1} \alpha_u \bar{\nabla} f_u \left( \mathbf{w}^t | \mathcal{D}_u^t \right) \right\Vert^2 - \frac{\eta^t}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right\Vert^2 \nonumber\\
    &\overset{(g)}{\leq} \frac{\eta^t \beta^2}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \mathbf{w}^t - \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 - \frac{\eta^t\kappa}{2} \left\Vert \bar{\nabla} f \left( \mathbf{w}^t|\mathcal{D}^t \right) \right\Vert^2 - \frac{\eta^t}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right\Vert^2, \label{second_term_sim}
\end{align}
where $(a)$ stems from the two cases for the \ac{acv}'s model difference upload, which is defined in (\ref{modeDifUpload}).
Besides, $(b)$ comes from the unbiased quantizer assumption, while $(c)$ is obtained using the definition of $\mathbf{d}_u^t$. 
$(d)$ stems from the unbiased stochastic gradient assumption.
Furthermore, $(e)$ arises from the fact that $2\left< \mathbf{x}, \mathbf{y} \right> = \Vert \mathbf{x} \Vert^2 + \Vert \mathbf{y} \Vert^2 - \Vert \mathbf{x} - \mathbf{y} \Vert^2 $ for a real vector space.
Moreover, $(f)$ stems due to the convexity of vector norm and Jensen inequality, i.e., $\Vert \sum_{i=1}^I \alpha_i \mathbf{x}_i\Vert^2 \leq \sum_{i=1}^I \alpha_i \Vert \mathbf{x}_i \Vert^2$ and $\beta$-Lipschitz smoothness property. 
In $(g)$, we use the fact $\bar{\nabla} f \left( \mathbf{w}^t|\mathcal{D}^t \right) \coloneqq \sum_{u=0}^{U-1} \alpha_u \bar{\nabla} f_u \left( \mathbf{w}^t | \mathcal{D}^t \right)$ since $f (\mathbf{w}) \coloneqq \sum_{u=0}^{U-1} f_u (\mathbf{w})$.


Now, we approximate the $\mathrm{T}_2$ term in (\ref{conv_eqn0_1}) considering all randomness as
\begin{align}
    &\mathrm{T}_2 = \frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q,\mathbf{\mathfrak{q}}^t} \left[ \left \Vert \sum_{u=0}^{U-1} \alpha_u \Pi_u^t \right \Vert^2 \right]  \nonumber\\
    &=\frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q} \left[ \mathbb{E}_{\mathbf{\mathfrak{q}}^t|\pmb{\zeta}^t,Q} \left[ \left \Vert \sum_{u=0}^{U-1} \alpha_u \Pi_u^t \right \Vert^2 \right] \right]  \nonumber\\
    &\overset{(a)}{=}\frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q} \left[ \mathbb{E}_{\mathbf{\mathfrak{q}}^t|\pmb{\zeta}^t,Q} \left[ \left \Vert \sum_{u=0}^{U-1} \alpha_u \Pi_u^t - \mathbb{E}_{\mathbf{\mathfrak{q}}^t|\pmb{\zeta}^t,Q} \left[ \sum_{u=0}^{U-1} \alpha_u \Pi_u^t \right] \right \Vert^2 \right] + \left(\mathbb{E}_{\mathbf{\mathfrak{q}}^t|\pmb{\zeta}^t,Q} \left[ \sum_{u=0}^{U-1} \alpha_u \Pi_u^t \right] \right)^2 \right]  \nonumber\\
    &=\frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q} \left[ \mathbb{E}_{\mathbf{\mathfrak{q}}^t|\pmb{\zeta}^t,Q} \left[ \left \Vert \sum_{u=0}^{U-1} \alpha_u \left(\Pi_u^t -  \mathbb{E}_{\mathbf{\mathfrak{q}}^t|\pmb{\zeta}^t,Q} \left[\Pi_u^t \right] \right) \right \Vert^2 \right] + \left\Vert \sum_{u=0}^{U-1} \alpha_u \mathbb{E}_{\mathbf{\mathfrak{q}}^t|\pmb{\zeta}^t,Q} \left[\Pi_u^t \right] \right\Vert^2 \right]  \nonumber\\
    &=\frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q} \Bigg[ \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[\sum_{u=0}^{U-1} \alpha_u^2  \left \Vert \Pi_u^t -  \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[\Pi_u^t \right] \right \Vert^2 + \sum_{u=0}^{U-1} \alpha_u \left(\Pi_u^t -  \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[\Pi_u^t \right] \right) \times \sum_{u'=0, u'\neq u}^{U-1} \alpha_{u'} \left(\Pi_{u'}^t -  \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[\Pi_{u'}^t \right] \right) \right] + \nonumber\\
    &\Squad \left\Vert \sum_{u=0}^{U-1} \alpha_u \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[\Pi_u^t \right] \right\Vert^2 \Bigg]  \nonumber\\
    &\overset{(b)}{=}\frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q} \left[ \sum_{u=0}^{U-1} \alpha_u^2 \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[ \left \Vert \Pi_u^t -  \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[\Pi_u^t \right] \right \Vert^2  \right] + \left\Vert \sum_{u=0}^{U-1} \alpha_u \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[\Pi_u^t \right] \right\Vert^2 \right]  \nonumber\\
    &= \frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q} \left[ \sum_{u=0}^{U-1} \alpha_u^2 \mathbb{E}_{\mathbf{\mathfrak{q}}^t | \pmb{\zeta}^t,Q} \left[ \left \Vert \Pi_u^t -  \left[\mathfrak{q}_u^t \mathbf{d}_u^t + (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right] \right \Vert^2  \right] + \left\Vert \sum_{u=0}^{U-1} \alpha_u  \left[\mathfrak{q}_u^t \mathbf{d}_u^t + (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right] \right\Vert^2 \right]  \nonumber\\
    &= \frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q} \Bigg[ \sum_{u=0}^{U-1} \alpha_u^2 \bigg\{ \mathfrak{q}_u^t \left \Vert \mathbf{d}_u^t -  \left[\mathfrak{q}_u^t \mathbf{d}_u^t + (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right] \right \Vert^2 + (1-\mathfrak{q}_u^t) \left \Vert Q\left(\mathbf{q}_u^t\right) -  \left[\mathfrak{q}_u^t \mathbf{d}_u^t + (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right \Vert^2  \right] \bigg\} + \nonumber\\
    &\Squad \left\Vert \sum_{u=0}^{U-1} \alpha_u  \mathfrak{q}_u^t \mathbf{d}_u^t + \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right)  \right\Vert^2 \Bigg] \nonumber\\
    &\overset{(c)}{\leq} \frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t,Q} \Bigg[ \sum_{u=0}^{U-1} \alpha_u^2 \bigg\{ \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \left \Vert \mathbf{d}_u^t -  Q \left( \mathbf{d}_u^t \right) \right \Vert^2  \bigg\} + 2\left\Vert \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t \right\Vert^2 + 2 \left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right\Vert^2 \Bigg] \nonumber\\
    &=\frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t} \left[ \mathbb{E}_{Q|\pmb{\zeta}^t} \left[ \sum_{u=0}^{U-1} \alpha_u^2 \bigg\{ \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \left \Vert \mathbf{d}_u^t -  Q \left( \mathbf{d}_u^t \right) \right \Vert^2  \bigg\} + 2\left\Vert \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t \right\Vert^2 + 2 \left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right\Vert^2 \right] \right] \nonumber\\
    &=\frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t} \left[  \sum_{u=0}^{U-1} \alpha_u^2 \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \mathbb{E}_{Q|\pmb{\zeta}^t} \left[\left \Vert \mathbf{d}_u^t -  Q \left( \mathbf{d}_u^t \right) \right \Vert^2  \right] + 2\left\Vert \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t \right\Vert^2 + 2 \mathbb{E}_{Q|\pmb{\zeta}^t} \left[ \left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right\Vert^2 \right] \right] \nonumber\\
    &\overset{(d)}{\leq} \frac{\beta (\eta^t)^2} {2} \mathbb{E}_{\pmb{\zeta}^t} \left[  \sum_{u=0}^{U-1} \alpha_u^2 \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) q \left \Vert \mathbf{d}_u^t \right \Vert^2 + 2\left\Vert \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t \right\Vert^2 + 2 \mathbb{E}_{Q|\pmb{\zeta}^t} \left[ \left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right\Vert^2 \right] \right] \nonumber\\
    &= \frac{\beta (\eta^t)^2} {2} \Bigg[ q \sum_{u=0}^{U-1} \alpha_u^2 \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \left( \mathbb{E}_{\pmb{\zeta}^t} \left[ \left \Vert \mathbf{d}_u^t - \mathbb{E}_{\pmb{\zeta^t}} \left[\mathbf{d}_u^t\right] \right \Vert^2 \right] + \left(\mathbb{E}_{\pmb{\zeta}^t} \left[\mathbf{d}_u^t\right] \right)^2 \right) + \nonumber\\
    &\Squad 2 \mathbb{E}_{\pmb{\zeta}^t} \left[ \left\Vert \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t - \mathbb{E}_{\pmb{\zeta}^t} \left[ \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t \right] \right\Vert^2 \right] + 2 \left(\mathbb{E}_{\pmb{\zeta}^t} \left[ \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \mathbf{d}_u^t \right]\right)^2 + \nonumber\\
    &\Squad \mathbb{E}_{\pmb{\zeta}^t} \left\{ 2\mathbb{E}_{Q|\pmb{\zeta}^t} \left[ \left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) - \mathbb{E}_{Q|\pmb{\zeta}^t} \left[\sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right] \right\Vert^2 \right] + 2\left(\mathbb{E}_{Q|\pmb{\zeta}^t}\left[ \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) Q\left( \mathbf{d}_u^t \right) \right] \right)^2 \right\} \Bigg] \nonumber\\
    &\overset{(e)}{=}\frac{\beta (\eta^t)^2} {2} \Bigg[ q \sum_{u=0}^{U-1} \alpha_u^2 \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \left( \mathbb{E}_{\pmb{\zeta}^t} \left[\left \Vert \sum_{\tau=0}^{\kappa-1} \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) - \mathbb{E}_{\pmb{\zeta^t}} \left[\sum_{\tau=0}^{\kappa-1} \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right)\right] \right \Vert^2 \right] + \left(\mathbb{E}_{\pmb{\zeta}^t} \left[\sum_{\tau=0}^{\kappa-1} \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right] \right)^2 \right) + \nonumber\\
    &\Squad 2 \mathbb{E}_{\pmb{\zeta}^t} \left[\left\Vert \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \left[ \sum_{\tau=0}^{\kappa-1} \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) - \mathbb{E}_{\pmb{\zeta}^t} \left[  \sum_{\tau=0}^{\kappa-1} \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right] \right] \right\Vert^2 \right] + 2 \left(\mathbb{E}_{\pmb{\zeta}^t} \left[ \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \sum_{\tau=0}^{\kappa-1} \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right]\right)^2 + \nonumber\\
    &\Squad \mathbb{E}_{\pmb{\zeta}^t} \left[ 2 \sum_{u=0}^{U-1} \alpha_u^2 (1 - \mathfrak{q}_u^t)^2 \mathbb{E}_{Q|\pmb{\zeta}^t} \left[ \left\Vert  Q \left( \mathbf{d}_u^t \right) -  \mathbf{d}_u^t \right\Vert^2 \right] + 2\left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) \mathbf{d}_u^t \right\Vert^2 \right] \Bigg] \nonumber\\
    &\leq \frac{\beta (\eta^t)^2} {2} \Bigg\{ q \sum_{u=0}^{U-1} \alpha_u^2 \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \left( \sum_{\tau=0}^{\kappa-1} \mathbb{E}_{\pmb{\zeta}^t} \left[\left \Vert \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right \Vert^2 \right] + \left\Vert \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \right) + \nonumber\\
    &\Squad 2 \sum_{u=0}^{U-1} \alpha_u^2 \left(\mathfrak{q}_u^t\right)^2 \sum_{\tau=0}^{\kappa-1} \mathbb{E}_{\pmb{\zeta}^t} \left[ \left\Vert \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \right] + 2 \left\Vert  \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 + \nonumber\\
    &\Squad 2 \sum_{u=0}^{U-1} \alpha_u^2 (1 - \mathfrak{q}_u^t)^2 q ~ \mathbb{E}_{\pmb{\zeta}^t} \left[\left\Vert \mathbf{d}_u^t \right\Vert^2 \right] + 2 \mathbb{E}_{\pmb{\zeta}^t} \left[\left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) \mathbf{d}_u^t \right\Vert^2 \right] \Bigg\} \nonumber\\
    &\overset{(f)}{\leq} \frac{\beta (\eta^t)^2} {2} \Bigg\{ q \sum_{u=0}^{U-1} \alpha_u^2 \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \left[ \sum_{\tau=0}^{\kappa-1} \sigma^2 + \left\Vert \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \right] +  2 \sum_{u=0}^{U-1} \alpha_u^2 \left(\mathfrak{q}_u^t\right)^2 \sum_{\tau=0}^{\kappa-1} \sigma^2 + 2 \left\Vert  \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 + \nonumber\\
    &\Squad 2 q \sum_{u=0}^{U-1} \alpha_u^2 (1 - \mathfrak{q}_u^t)^2 \left( \sum_{\tau=0}^{\kappa-1} \mathbb{E}_{\pmb{\zeta}^t} \left[\left\Vert \left[\bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right)\right] \right\Vert^2\right] + \left\Vert \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert \right) + \nonumber\\
    &\Squad 2\sum_{u=0}^{U-1} \alpha_u^2 (1 - \mathfrak{q}_u^t)^2 \sum_{\tau=0}^{\kappa-1} \mathbb{E}_{\pmb{\zeta}^t} \left[ \left\Vert \bar{g}_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \right] + 2\left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \Bigg\} \nonumber\\
    &\leq \frac{\beta (\eta^t)^2} {2} \Bigg\{ q \sum_{u=0}^{U-1} \alpha_u^2 \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \left[ \kappa \sigma^2 + \left\Vert \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \right] + 2 \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left(\mathfrak{q}_u^t\right)^2 + 2 \left\Vert  \sum_{u=0}^{U-1} \alpha_u \mathfrak{q}_u^t \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 + \nonumber\\
    &\Squad 2 q \sum_{u=0}^{U-1} \alpha_u^2 (1 - \mathfrak{q}_u^t)^2 \left[\kappa \sigma^2 + \left\Vert \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert \right] + 2 \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 (1 - \mathfrak{q}_u^t)^2 + 2\left\Vert \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t) \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \Bigg\} \nonumber\\
    &\leq \frac{\beta (\eta^t)^2} {2} \Bigg\{  \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left[2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right] + q \kappa \sum_{u=0}^{U-1} \alpha_u^2 \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2  + \nonumber\\
    &\Squad 2 \sum_{u=0}^{U-1} \alpha_u \left\Vert \mathfrak{q}_u^t \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 + 2 q \kappa \sum_{u=0}^{U-1} \alpha_u^2 (1 - \mathfrak{q}_u^t)^2 \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert +  2 \sum_{u=0}^{U-1} \alpha_u \left\Vert (1 - \mathfrak{q}_u^t) \sum_{\tau=0}^{\kappa-1} \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \Bigg\} \nonumber\\
    &\leq \frac{\beta (\eta^t)^2} {2} \Bigg\{  \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left[2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right] + q \kappa \sum_{u=0}^{U-1} \alpha_u^2 \left[ \mathfrak{q}_u^t (1-\mathfrak{q}_u^t) + (1 - \mathfrak{q}_u^t)^2 \right] \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2  + \nonumber\\
    &\Squad 2 \kappa \sum_{u=0}^{U-1} \alpha_u \left(\mathfrak{q}_u^t\right)^2 \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 + 2 \kappa \sum_{u=0}^{U-1} \alpha_u (1 - \mathfrak{q}_u^t)^2 \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \Bigg\} \nonumber\\
    &=\frac{\beta (\eta^t)^2} {2} \Bigg\{  \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left[2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right] + q \kappa \sum_{u=0}^{U-1} \alpha_u^2 (1-\mathfrak{q}_u^t)  \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2  + \nonumber\\
    &\Squad 2 \kappa \sum_{u=0}^{U-1} \alpha_u \left[ 1 - 2\mathfrak{q}_u^t (1 - \mathfrak{q}_u^t)\right] \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \Bigg\} \nonumber\\
    &\overset{(g)}{\leq} \frac{\beta (\eta^t)^2} {2} \Bigg\{  \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left[2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right] + q \kappa \sum_{u=0}^{U-1} \alpha_u^2  \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2  + 2 \kappa \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \Bigg\} \nonumber\\
    &\overset{(h)}{\leq} \frac{\beta (\eta^t)^2} {2} \Bigg\{  \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left[2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right] + q \kappa \sum_{u=0}^{U-1} \alpha_u  \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2  + 2 \kappa \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2 \Bigg\} \nonumber\\
    &=\frac{\beta (\eta^t)^2} {2} \left[  \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left(2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right) + \left(2+q\right) \kappa \sum_{u=0}^{U-1} \alpha_u  \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2\right],
    \label{third_term_sim}
\end{align}
where $(a)$ comes from the definition of variance. 
In $(b)$, we use the fact that the cross product terms becomes zero when the expectation (w.r.t $\mathbf{\mathfrak{q}}^t$) is taken.
Besides, $(c)$ is true since $\Vert \sum_{i=0}^{I-1} \mathbf{a}_i \Vert^2=\Vert \sum_{i=0}^{I-1} 1 \cdot \mathbf{a}_i \Vert^2 \leq I \sum_{i=0}^{I-1} \Vert \mathbf{a}_i \Vert^2$ from Cauchy-Schwarz inequality, while $(d)$ appears from the bounded variance assumption of the stochastic quantizer in Assumption $4$.
In $(e)$, we use the definition of $\mathbf{d}_u^t$, while $(f)$ is true from the bounded variance assumption of the stochastic gradients. 
Furthermore, in $(g)$, we use the fact that $0 \leq \mathfrak{q}_u^t \leq 1$ implies $(1-\mathfrak{q}_u^t) \leq 1$ and thus, $\frac{1}{2} \leq \left(1 - 2\mathfrak{q}_u^t (1-\mathfrak{q}_u^t)\right) \leq 1$.
Finally, $(h)$ is true due to the fact that $\Vert \mathbf{a} \Vert \geq 0$ for any vector $\mathbf{a}$, $0\leq \alpha_u \leq 1$, and $\sum_{u=0}^{U-1}\alpha_u=1$, which implies $\sum_{u=0}^{U-1} \alpha_u^2 \Vert \mathbf{a} \Vert^2 \leq \sum_{u=0}^{U-1} \alpha_u \Vert \mathbf{a} \Vert^2$. 



To that end, plugging (\ref{second_term_sim}) and (\ref{third_term_sim}) into 
(\ref{conv_eqn0_1}), we get
\begin{align}
    &\mathbb{E} \left[f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] 
    \leq \mathbb{E} \big[f \left( \mathbf{w}^t|\mathcal{D}^t \right)\big] + \frac{\eta^t \beta^2}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \mathbf{w}^t - \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 - \frac{\eta^t\kappa}{2} \left\Vert \bar{\nabla} f \left( \mathbf{w}^t|\mathcal{D}^t \right) \right\Vert^2 - \frac{\eta^t}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right\Vert^2 + \nonumber\\
    & \Squad \frac{\beta (\eta^t)^2} {2} \left[  \kappa \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left(2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right) + \left(2+q\right) \kappa \sum_{u=0}^{U-1} \alpha_u  \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left(\bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) \right\Vert^2\right] \nonumber\\
    &= \mathbb{E} \big[f \left( \mathbf{w}^t|\mathcal{D}^t \right)\big] + \frac{\beta \kappa (\eta^t)^2 \sigma^2} {2} \sum_{u=0}^{U-1} \alpha_u^2 \left(2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right) + \frac{\eta^t \beta^2}{2} \sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \mathbf{w}^t - \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 - \frac{\eta^t\kappa}{2} \left\Vert \bar{\nabla} f \left( \mathbf{w}^t|\mathcal{D}^t \right) \right\Vert^2 \nonumber \\
    &\Squad - \frac{\eta^t}{2} \left(1 - \beta \kappa \eta^t(2+q) \right)\sum_{u=0}^{U-1} \alpha_u \sum_{\tau=0}^{\kappa-1} \left\Vert \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^t \right) \right\Vert^2.
    \label{conv_eqn1_0}
\end{align}
When $\eta^t\leq \frac{1}{\beta \kappa(2+q)}$, we have $0 \leq (1 - \beta \eta^t \kappa (2+q)) \leq 1$.
As such, we drop the last term in (\ref{conv_eqn1_0}).
Then, after rearranging the terms in (\ref{conv_eqn1_0}), dividing both sides by $\frac{\eta^t\kappa}{2}$ and taking expectations on both sides, we get the following
\begin{align}
    \mathbb{E} \left[ \left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2  \right]
    &\leq \frac{2 \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t\kappa} + \beta \kappa \eta^t \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left(2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right) + \nonumber \\
    & \frac{\beta^2}{\kappa} \sum_{u=0}^{U-1} \alpha_u\sum_{\tau=0}^{\kappa-1} \underbrace{\mathbb{E} \left[\left \Vert \mathbf{w}^{t} - \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 \right]}_{\mathrm{T}_3}. \label{conv_eqn1_2}
\end{align}


Now, we simplify the $\mathrm{T}_3$ term as follows
\begin{align}
\label{t3termSimplified}
    \mathrm{T}_3 &= \mathbb{E} \left[\left \Vert \mathbf{w}^t -  \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 \right] \nonumber\\
    &=\mathbb{E} \left[\left \Vert \mathbf{w}^t -\mathbf{w}_u^t + \mathbf{w}_u^t -  \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 \right] \nonumber\\
    &\overset{(a)}{=} \mathbb{E} \left[\left \Vert \mathbf{w}_u^t -  \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 \right] \nonumber\\
    &= \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} + \Tilde{\eta}^t\sum_{\tau'=0}^{\tau-1} \bar{g}_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) \right\Vert^2 \right] \nonumber\\
    &\overset{(b)}{\leq} 2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \mathbb{E} \left[\left \Vert \Tilde{\eta}^t\sum_{\tau'=0}^{\tau-1} \bar{g}_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right)\right\Vert^2 \right] \nonumber\\
    &\overset{(c)}{=} 2 \mathbb{E} \left[\left \Vert \mathbf{w}^t_u - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \left(\Tilde{\eta}^t\right)^2 \mathbb{E} \left[\left \Vert \sum_{\tau'=0}^{\tau-1} \left\{ \bar{g}_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) - \mathbb{E}\left[ \bar{g}_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) \right] \right\} \right\Vert^2 \right] + 2(\Tilde{\eta}^t)^2 \left( \mathbb{E} \left[ \sum_{\tau'=0}^{\tau-1} \bar{g}_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) \right] \right)^2 \nonumber\\
    &\overset{(d)}{=} 2 \mathbb{E} \left[\left \Vert \mathbf{w}^t_u - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \left(\Tilde{\eta}^t\right)^2 \sum_{\tau'=0}^{\tau-1} \mathbb{E} \left[\left \Vert \bar{g}_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) \right\Vert^2 \right] + 2(\Tilde{\eta}^t)^2 \left\Vert \sum_{\tau'=0}^{\tau-1} \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) \right\Vert^2 \nonumber\\
    &\overset{(e)}{\leq} 2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \kappa \left(\Tilde{\eta}^t\right)^2 \sigma^2 + 2(\Tilde{\eta}^t)^2 \left\Vert \sum_{\tau'=0}^{\tau-1} \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) \right\Vert^2 \nonumber\\
    &=2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \kappa \left(\Tilde{\eta}^t\right)^2 \sigma^2 + 2(\Tilde{\eta}^t)^2 \Bigg\Vert \sum_{\tau'=0}^{\tau-1} \bigg[ \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^{t-1} \right) + \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^{t-1} \right) - \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t-1} \right) + \nonumber\\
    &\Bquad \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t-1} \right) - \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t} \right) + \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t} \right) \bigg] \Bigg\Vert^2 \nonumber\\
    &\overset{(f)}{\leq} 2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \kappa \left(\Tilde{\eta}^t\right)^2 \sigma^2 + 8(\Tilde{\eta}^t)^2 \left\Vert \sum_{\tau'=0}^{\tau-1} \left[ \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^{t-1} \right) \right] \right\Vert^2 + \nonumber\\
    &\Bquad 8(\Tilde{\eta}^t)^2 \left\Vert \sum_{\tau'=0}^{\tau-1} \left[\bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau'} | \mathcal{D}_u^{t-1} \right) - \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t-1} \right) \right]\right\Vert^2 + \nonumber\\
    &\Bquad 8(\Tilde{\eta}^t)^2 \left\Vert \sum_{\tau'=0}^{\tau-1} \left[ \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t-1} \right) - \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t} \right) \right]\right\Vert^2 + 8(\Tilde{\eta}^t)^2 \left\Vert \sum_{\tau'=0}^{\tau-1} \left[\bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t} \right) \right] \right\Vert^2 \nonumber\\
    &\overset{(g)}{\leq} 2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \kappa \left(\Tilde{\eta}^t\right)^2 \sigma^2 + 8 \kappa^2 (\Tilde{\eta}^t)^2 \left\Vert  \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^t \right) - \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t, \tau} | \mathcal{D}_u^{t-1} \right) \right\Vert^2 + \nonumber\\
    &\Bquad 8 \kappa^2 (\Tilde{\eta}^t)^2 \left\Vert \bar{\nabla} f_u \left( \Bar{\mathbf{w}}_u^{t,\tau} | \mathcal{D}_u^{t-1} \right) - \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t-1} \right) \right\Vert^2 + \nonumber\\
    &\Bquad 8\kappa^2 (\Tilde{\eta}^t)^2 \left\Vert \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t-1} \right) - \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t} \right) \right\Vert^2 + 8\kappa^2 (\Tilde{\eta}^t)^2 \left\Vert \bar{\nabla} f_u \left( \mathbf{w}^{t} | \mathcal{D}_u^{t} \right) \right\Vert^2 \nonumber\\
    &\overset{(h)}{\leq} 2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \kappa \left(\Tilde{\eta}^t\right)^2 \sigma^2 + 8 \Phi_u^t \kappa^2 (\Tilde{\eta}^t)^2 +  8 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \left\Vert  \Bar{\mathbf{w}}_u^{t,\tau} - \mathbf{w}^{t} \right\Vert^2 + 8 \Phi_u^t \kappa^2 (\Tilde{\eta}^t)^2 + \nonumber\\
    & \Bquad 8 \kappa^2 (\Tilde{\eta}^t)^2 \left[\rho_1 \left\Vert \bar{\nabla} f (\mathbf{w}^t | \mathcal{D}^t \right\Vert^2 + \rho_2 \epsilon_u^t \right],
\end{align}
where $(a)$ stems from the fact that $\mathbf{w}_u^t \gets \mathbf{w}^t$ during the synchronization phase at the starting of each \ac{fl} round, 
$(c)$ from the definition of variance

Taking expectation on both sides of (\ref{t3termSimplified}), and rearranging the terms we get
\begin{align}
    \mathbb{E} \left[\left \Vert \mathbf{w}^t - \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 \right] 
    \leq \frac{2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \kappa \left(\Tilde{\eta}^t\right)^2 \sigma^2 + 8 \Phi_u^t \kappa^2 (\Tilde{\eta}^t)^2 + 8 \Phi_u^t \kappa^2 (\Tilde{\eta}^t)^2 + 8 \kappa^2 (\Tilde{\eta}^t)^2 \left[\rho_1 \left\Vert \bar{\nabla} f (\mathbf{w}^t | \mathcal{D}^t \right\Vert^2 + \rho_2 \epsilon_u^t \right] }{1 - 8 \beta^2 (\Tilde{\eta}^t)^2\kappa^2},
\end{align}
When $\Tilde{\eta}^t < \frac{1}{2\sqrt{2}\beta\kappa}$, we have $0 < (1 - 8\beta^2(\Tilde{\eta}^t)^2\kappa^2) < 1$. 
As such, we write 
\begin{align}
    \mathrm{T}_3 = \mathbb{E} \left[\left \Vert \mathbf{w}^t - \Bar{\mathbf{w}}_u^{t, \tau} \right\Vert^2 \right] 
    \leq 2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \kappa \left(\Tilde{\eta}^t\right)^2 \sigma^2 + 16 \Phi_u^t \kappa^2 (\Tilde{\eta}^t)^2 + 8 \kappa^2 (\Tilde{\eta}^t)^2 \rho_1 \mathbb{E} \left[\left\Vert \bar{\nabla} f (\mathbf{w}^t | \mathcal{D}^t \right\Vert^2\right] + 8 \kappa^2 (\Tilde{\eta}^t)^2 \rho_2 \epsilon_u^t.
\end{align}

Finally, plugging $\mathrm{T}_3$ into (\ref{conv_eqn1_2}), we get
\begin{align}
    &\mathbb{E} \left[ \left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2  \right]
    \leq \frac{2 \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t\kappa} + \beta \kappa \eta^t \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left(2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right) + \nonumber\\
    &\Squad \frac{\beta^2}{\kappa} \sum_{u=0}^{U-1} \alpha_u\sum_{\tau=0}^{\kappa-1} \bigg\{ 2 \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 2 \kappa \left(\Tilde{\eta}^t\right)^2 \sigma^2 + 16 \Phi_u^t \kappa^2 (\Tilde{\eta}^t)^2 + 8 \kappa^2 (\Tilde{\eta}^t)^2 \rho_1 \mathbb{E} \left[\left\Vert \bar{\nabla} f (\mathbf{w}^t | \mathcal{D}^t \right\Vert^2\right] + 8 \kappa^2 (\Tilde{\eta}^t)^2 \rho_2 \epsilon_u^t \bigg\} \nonumber\\
    &= \frac{2 \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t\kappa} + \beta \kappa \eta^t \sigma^2 \sum_{u=0}^{U-1} \alpha_u^2 \left(2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right) + 2 \kappa \beta^2 \left(\Tilde{\eta}^t\right)^2 \sigma^2 + \nonumber\\
    &\Squad 2 \beta^2 \sum_{u=0}^{U-1} \alpha_u \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 16 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \sum_{u=0}^{U-1} \alpha_u \Phi_u^t + 8 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \rho_1 \mathbb{E} \left[\left\Vert \bar{\nabla} f (\mathbf{w}^t | \mathcal{D}^t \right\Vert^2\right] + 8 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \rho_2 \sum_{u=0}^{U-1} \alpha_u \epsilon_u^t \nonumber\\
    &= \frac{2 \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t\kappa} + \beta \sigma^2 \left( \kappa \eta^t \sum_{u=0}^{U-1} \alpha_u^2 \left(2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right) + 2 \beta \kappa (\Tilde{\eta}^t)^2 \right) + \nonumber\\
    &\Squad 2 \beta^2 \sum_{u=0}^{U-1} \alpha_u \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 16 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \sum_{u=0}^{U-1} \alpha_u \Phi_u^t + 8 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \rho_2 \sum_{u=0}^{U-1} \alpha_u \epsilon_u^t + 8 \rho_1 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2  \mathbb{E} \left[\left\Vert \bar{\nabla} f (\mathbf{w}^t | \mathcal{D}^t \right\Vert^2\right].
\end{align}

Rearranging the terms, we write
\begin{align}
    & \mathbb{E} \left[\left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2 \right] 
    \leq \Bigg[ \frac{2 \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t\kappa} + \beta \sigma^2 \left( \kappa \eta^t \sum_{u=0}^{U-1} \alpha_u^2 \mathrm{C}_u\left(q,\mathfrak{q}_u^t \right) + 2 \beta \kappa (\Tilde{\eta}^t)^2 \right) + \nonumber\\
    &\Squad 2 \beta^2 \sum_{u=0}^{U-1} \alpha_u \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 16 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \sum_{u=0}^{U-1} \alpha_u \Phi_u^t + 8 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \rho_2 \sum_{u=0}^{U-1} \alpha_u \epsilon_u^t \Bigg] \Big/ \big[1 - 8 \rho_1 \beta^2 (\Tilde{\eta}^t)^2\kappa^2\big]. \label{convBoundAvgOverTime_Eq2}
\end{align}
where $\mathrm{C}_u \left(q,\mathfrak{q}_u^t \right) \coloneqq \left(2 + 2q +(4+q)\left(\mathfrak{q}_u^t\right)^2 - (3q+4)\mathfrak{q}_u^t \right)$.


Similar to our previous assumption, if $\Tilde{\eta}^t< \frac{1}{2\sqrt{2\rho_1}\beta\kappa}$, we have $0 < \left( 1 - 8\rho_1\beta^2(\Tilde{\eta}^t)^2\kappa^2 \right) < 1$.
Therefore, we simplify (\ref{convBoundAvgOverTime_Eq2}) as
\begin{align}
    \mathbb{E} \left[\left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2 \right] 
    &\leq \Bigg[ \frac{2 \left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t\kappa} + \beta \sigma^2 \left( \kappa \eta^t \sum_{u=0}^{U-1} \alpha_u^2 \mathrm{C}_u\left(q,\mathfrak{q}_u^t \right) + 2 \beta \kappa (\Tilde{\eta}^t)^2 \right) + \nonumber\\
    &~ 2 \beta^2 \sum_{u=0}^{U-1} \alpha_u \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right] + 16 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \sum_{u=0}^{U-1} \alpha_u \Phi_u^t + 8 \beta^2 \kappa^2 (\Tilde{\eta}^t)^2 \rho_2 \sum_{u=0}^{U-1} \alpha_u \epsilon_u^t \Bigg]. 
\end{align}


Finally, averaging over time results in the following
\begin{align}
    &\frac{1}{T}\sum_{t=0}^{T-1}  \mathbb{E} \left[\left\Vert \bar{\nabla} f \left( \mathbf{w}^{t} | \mathcal{D}^t \right) \right\Vert^2 \right]  
    \leq \frac{2}{\kappa T} \sum_{t=0}^{T-1} \frac{\left( \mathbb{E} \left[ f \left(\mathbf{w}^{t} | \mathcal{D}^t \right) \right] - \mathbb{E} \left[ f \left( \mathbf{w}^{t+1} | \mathcal{D}^{t+1} \right) \right] \right)} {\eta^t} + \frac{\beta  \sigma^2}{T} \left( \sum_{u=0}^{U-1} \alpha_u^2 \sum_{t=0}^{T-1} \eta^t  \mathrm{C}_u\left(q, \mathfrak{q}_u^t\right) + 2 \beta \kappa \sum_{t=0}^{T-1} (\Tilde{\eta}^t)^2 \right) + \nonumber\\
    &\Mquad \frac{16 \beta^2 \kappa^2}{T} \sum_{t=0}^{T-1} \left(\Tilde{\eta}^t\right)^2 \sum_{u=0}^{U-1} \alpha_u \Phi_u^t + \frac{8 \beta^2 \kappa^2 \rho_2}{T} \sum_{t=0}^{T-1} \left(\Tilde{\eta}^t\right)^2 \sum_{u=0}^{U-1} \alpha_u \epsilon_u^t + \frac{2 \beta^2}{T} \sum_{t=0}^{T-1} \sum_{u=0}^{U-1} \alpha_u \mathbb{E} \left[\left \Vert \mathbf{w}_u^t - \Bar{\mathbf{w}}_u^{t, 0} \right\Vert^2 \right], 
\end{align}
which concludes the proof.
\end{proof}

