\section{The PT Game: Preservation and Vanishing of Equilibria}
We have the PT utilities,
\begin{align}
    \widetilde J_i(x_i,\x_{-i},\p)=\sum_{j=1}^Mq_j[v_i\circ J_i(x_i,\x_{-i},\p,\xi_j)].
\end{align}
As in the EUT case, we consider the game  for a fixed $\p$. Under Assumption \ref{as:v-assumption}, we see that $\widetilde J_i$ is concave in $x_i$. Thus, the first derivative being zero is necessary and sufficient for equilibrium. Equating $\frac{\partial \widetilde J_i}{\partial x_i}$ to zero is equivalent to the fixed point equation given component-wise by
\begin{align}\label{eq:fixed-point-PT}
    x_i=\sum_{j=1}^Ny_j-\sum_{j\ne i}x_j-\frac{N^2}{2a_i}(p_i-\mathbb{E}[\tilde\xi^{\x,\p}(i)]),
\end{align}
where $\tilde\xi^{\x,\p}(i)$ is a random variable with support $\{\xi_1,...,\xi_M\}$ and distribution
\begin{align}\label{eq:transf-prob-dist}
    \mathbb{P}[\tilde\xi^{\x,\p}(i)=\xi_k]=\frac{q_kv_i^{\prime}(J_i(x_i,\x_{-i},\p,\xi_k))}{\sum_{j=1}^Mq_jv_i^{\prime}(J_i(x_i,\x_{-i},\p,\xi_j))}.
\end{align}
Note that in the case of the EUT game, \eqref{eq:fixed-point-PT} will have $\tilde\xi^{\x,\p}(i)$  replaced by $\xi$. The impact of the prospect theoretic modification is to shift the mean of the randomness.  However, the dependence of this shift on each strategy $\x$,  price $\p$ and player $i$ makes it much harder to obtain an explicit form for the equilibrium, unlike what we had in the EUT setting. The following criterion is equivalent to  \eqref{eq:fixed-point-PT}.
\begin{lem}\label{lem:charac-eq-PT}
    A joint strategy $\x$ is a Nash equilibrium for the PT game at price $\p$ if and only if there exists $\kappa_{\p,\x}$ that satisfies,
    \begin{align}\label{eqn:constr-coupl-PT}
        \sum_{j=1}^Nx_j-\sum_{j=1}^Ny_j=-\frac{N^2}{2}\kappa_{\p,\x},
    \end{align}
    and 
    \begin{align}\label{eq:defn-kappa-p-x}
      \kappa_{\p,\x}=\frac{p_i-\mathbb{E}[\tilde\xi^{\x,\p}(i)]}{a_i}= \frac{p_1-\mathbb{E}[\tilde\xi^{\x,\p}(1)]}{a_1},~i=1,...,N.
    \end{align}
\end{lem}

\subsection{Existence and Uniqueness} Restricting strategies to compact sets, we can obtain existence results for the fixed point map in a projected form.
\begin{lem}
    Let $\mathcal X_i$ be convex and compact. The equation for $\x$ given componentwise by
    \begin{align*}
        x_i=\mathrm{proj}_{\mathcal X_i}\left[\sum_{j=1}^Ny_j-\sum_{j\ne i}x_i-\frac{N^2}{2a_i}(p_i-\mathbb{E}[\tilde\xi^{\x,\p}(i)])\right],
    \end{align*}
    has a fixed point.
\end{lem}
\begin{proof}
    Follows from Brouwer's fixed point theorem~\cite{rudinBaby}.
\end{proof}
It is difficult to show uniqueness of equilibria for a general form of the PT game. One naturally expects it to display multiple equilibria. The following theorem shows that for a specific instance, where the users are symmetric are the functions $v_i$ are identical and exponential, and the vector $\p$ is restricted to be identical across users, we obtain unique equilibria at each $\p$. We also obtain a structural result on the equilibria.
\begin{thm}\label{thm:uniq-PT-sym}
    Let the users be symmetric, i.e., $a_i=a$ for all $i$, and let $\mathcal P=\{p\textbf{1}:p\in\mathbb{R}\}$.
    Let the PT transformations $v_i$ be identically equal to $v(z)=1-\exp(-\lambda z)$, for some positive $\lambda$. Then the set $\widetilde X^*(\p)$ has exactly one element, for each $\p\in\mathcal P$, and satisfies $x^*_i-y_i=x^*_1-y_1$ for all users $i$.
\end{thm}

The proof is presented in Appendix \ref{sec:proof-uniq-PT-sym}. Here the PT transform reduces the uncountable set of EUT equilibria to a singleton, at each $\p$. This form of $v$ is an example of a uniformly risk-averse user. While in general PT transforms are not uniformly risk averse, the theorem suggests that PT transforms that are partially of the above form, may exhibit unique equilibria for some parameters.


\subsection{Convergence to Equilibria} As in the EUT case, we use algorithm \ref{alg:con-alg-grad} in the PT case as well. The only difference is that $\Delta_i$ is replaced by
\begin{align}\label{eq:delta-tilde}
    \tilde\Delta_i:=\frac{\partial}{\partial x_i}\widetilde J_i(x_i,\x_{-i},\p).
\end{align}
While the PT game does not retain the potential structure of the EUT game, it is still a concave game, owing to Assumption \ref{as:v-assumption}. In the absence of potential or monotone structure, it is not easy to establish global convergence of gradient dynamics.
However, there are conditions for local convergence to Nash equilibria, such as in~\cite{tan2023necessary}. Not all PT transformations satisfy these conditions. In Section \ref{sec:numerical-study}, we present an example as Case 1, which satisfies these conditions for local convergence. Global convergence of the algorithm for more general forms of the PT game  will be taken up in a subsequent work.
 \subsection{Preservation and Vanishing of EUT Equilibria}
 The EUT to PT transformation behaves differently with different Nash equilibria of the EUT setting. We will call an equilibrium $\x^*$ in $X^*(\p)~$\emph{symmetric} for a user $i$ if the PT transformation affects all the outcomes of that equilibrium symmetrically, i.e.,
 $$v_i(\overline J_i(x^*_i,x^*_{-i},\p,\xi_j))=v_i(\overline J_i(x^*_i,x^*_{-i},,\p,\xi_k))~\forall~ j,k.$$
 Thus, the equilibrium $\y$ is symmetric for all users at price $\overline\xi\textbf{1}$. Similarly, for $\p\ne \overline\xi\textbf{1}$, any $\x^*\in X^*(\p)$ for which $x_j^*=y_j^*$ is symmetric for user $j$. Any equilibrium which is not symmetric for user $i$, will be called \emph{asymmetric} for user $i$. We present two results, showing how a symmetric equilibrium is preserved, while asymmetric equilibria are not.
\begin{prop}\label{prop:equilibrium-PT}
    We have $\y\in\widetilde X^*(\overline\xi\textbf{1})$.
 \end{prop}
The proof is presented in Appendix \ref{sec:proof-equilibrium-PT}. Thus, when $\p=\overline\xi\textbf{1}$, we see that $\y$, which is a symmetric Nash equilibrium of $\mathcal G_{\text{EUT}}$ is also a Nash equilibrium of $\mathcal G_{\text{PT}}$.

\begin{prop}\label{prop:equilibrium-destr}
    If some $v_k$ is strictly concave, then any element of  $X^*(\p)$ which is asymmetric for user $k$, will not belong to $\widetilde X^*(\p)$. 
 \end{prop}
 The proof is presented in Appendix  \ref{sec:proof-equilibrium-destr}. It follows that when all  users have strictly concave PT transformations $v_i$, none of the equilibria which are asymmetric for any user, are preserved.
\begin{cor}
    If the $v_i$ are differentiable, non decreasing and strictly concave for all $i$, we have, for $\p\in\mathcal P_1$,
    \begin{align}
        \widetilde X^*(\p)\cap X^*(\p)=\begin{cases}
            \{\y\}, &\p=\overline\xi\textbf{1},\\
            \phi, &\p\ne\overline\xi\textbf{1}.
        \end{cases}
    \end{align}
\end{cor}
 %\begin{remar}
 %    While the proof of Proposition \ref{prop:equilibrium-destr} relied on the strict concavity of the $v_i$, this is not necessary for the vanishing of equilibria. It is sufficient that at the equilibrium, there exists some $\xi_j$ such that $v_i$ is strictly concave at $J_i(x_i^*,\x_{-i}^*,\p,\xi_j)$.
 %\end{remar}
