\section{Proof of Lemma \ref{lem:Nash-eq-set-EUT}}\label{sec:proof-Nash-eq-set-EUT}
  For a fixed $\p$, the Nash equilibrium~\eqref{def:Nash-eqbm-EUT} is given by any point $\x^*=(x_i^*)_{i=1}^N$ that satisfies
	\begin{align}\label{eqn:Nash-condtn-loc}
		x_i^{*}\in\arg_{x_i}\max \overline J_i(x_i,\x_{-i}^*,\p),~i=1,...,N.
	\end{align}
    Since $\frac{\partial^2}{\partial x_i^2}\overline J_i(x_i,\x_{-i},\p)<0$, it follows that any $\x^*$ that satisfies
$
     \frac{\partial}{\partial x_i}\overline J_i(x_i^*,\x_{-i}^*,\p) =0
$ for $i=1,..,N,$
 is a Nash equilibrium. This is equivalent to the family of equations,
 \begin{align}\label{eqn:condtn-1}
    \frac{N^2}{2a_i}(p_i-\overline\xi)= (\sum_{j}y_j-\sum_jx_j),~i=1,...,N.
 \end{align}
If $\p\notin\mathcal P_1$, the system of equations \eqref{eqn:condtn-1} is inconsistent and there is no solution. If $\p\in\mathcal P_1$, we can see that the system \eqref{eqn:condtn-1} is equivalent to the single equation
\begin{align}\label{eqn:simplified-x-y-p}
         \sum_jx_j-\sum_jy_j=-\frac{N^2}{2}\kappa_{\p}.
     \end{align}
\section{Proof of Theorem \ref{thm:uniq-PT-sym}}\label{sec:proof-uniq-PT-sym}
    Let $\p:=p\textbf{1}$. 
    Define
    $$
        F(\Delta):=\frac{\sum_{k=1}^Mq_k\xi_k\exp(\lambda\Delta\xi_k)}{\sum_{k=1}^Mq_k\exp(\lambda\Delta\xi_k)}.
    $$
    It is easy to check that $$\frac{\partial F(\Delta)}{\partial\Delta}>0,$$ and hence, it is strictly increasing in $\Delta$. Since $\mathbb{E}[\tilde\xi^{\x,\p}(i)]=F(y_i-x_i)$, and since \ref{eq:defn-kappa-p-x} implies that
$$
        \mathbb{E}[\tilde\xi^{\x,\p}(1)]=\mathbb{E}[\tilde\xi^{\x,\p}(i)]~\forall ~i,
    $$
    it follows that at equilibrium, $$
        y_i-x_i=y_j-x_j~\forall~i,j.$$
    Using this, \eqref{eqn:constr-coupl-PT} and \eqref{eq:defn-kappa-p-x} now reduce to finding $\Delta$ such that
    $$
        p-\frac{2a\Delta}{N}=F(\Delta).
    $$
    Since $p-\frac{2a\Delta}{N}$ is strictly decreasing and $F$ is strictly increasing in $\Delta$, there is exactly one solution.

\section{Proof of Proposition \ref{prop:equilibrium-PT}}\label{sec:proof-equilibrium-PT}
      Let $v_i^{\prime}$  denote the first derivative of $v_i$. 
     Using  \ref{eqn:simplified-x-y-p} with $\p=\overline\xi\textbf{1}$ and $\x=\y$, this evaluates to
     \begin{align*}
        \frac{\partial}{\partial x_i}\widetilde J_i(y_i,\y_{-i},\overline\xi\textbf{1}) &= v_i^{\prime}(b_i-{\overline\xi}y_i)\sum_{j=1}^M q_j[-{\overline\xi}+\xi_j]=0.
     \end{align*}
     Since $v_i$ is non decreasing and concave and $J_i$ is concave, it follows~\cite{boyd2004convex} that $\tilde u(\cdot)=\sum_jq_j[v_i\circ J_i(\cdot,\xi_j)]$ is concave. Then the first derivative being zero implies \eqref{def:Nash-eqbm-PT}.
\section{Proof of Proposition \ref{prop:equilibrium-destr}}\label{sec:proof-equilibrium-destr}
 Let $\p\in\mathcal P_1$. Let $\x^*\in \hat X^*(\p)$ be asymmetric for user $k$. Clearly, then $x^*_k\ne y_k$. Define $\Delta_k=y_k- x_k^*$. We present the proof for the case $\Delta_k>0$ (For $\Delta_k<0$, the proof is the similar with appropriate sign changes).  For $\p\in\mathcal P_1$, and at $\x^*$, we have
 \begin{align*}
     \frac{\partial}{\partial x_k}\widetilde J_k(x_k^*,\x_{-k}^*,\p)=\sum_{j=1}^M q_j(\xi_j-\overline\xi)v_k^{\prime}(\tilde b_k-(\xi_j-\overline\xi)\Delta_k),
 \end{align*}
where 
$$\tilde b_k=b_k-y_k\overline\xi+x_k(\overline\xi-p_k)-\frac{N^2}{4a_i}(p_i-\overline\xi)^2.$$ 
Since $v_k(z)$ is strictly concave, $v_k^{\prime}(z)$ is strictly decreasing in $z$. Thus,
\begin{align}
    v^{\prime}_k(\tilde b_k-(z-\overline\xi)\Delta_k)=v^{\prime}_k(\tilde b_k)+\epsilon(z),
\end{align}
where $\epsilon(z)$ satisfies,
\begin{align}\label{eq:epsilon-zed}
    \epsilon(z) \begin{cases}
        <0, &z<\overline\xi,\\
        >0, &z>\overline\xi.
    \end{cases}
\end{align}
Thus we have
\begin{align*}
    \frac{\partial}{\partial x_k}\widetilde J_k(x_k^*,\x_{-k}^*,\p) &=\sum_{j=1}^M q_j(\xi_j-\overline\xi)[v_k^{\prime}(\tilde b_k)+\epsilon(\xi_j)]>0,
\end{align*}
where the inequality follows by noting that $\overline\xi$ is the mean of $\xi$, and \eqref{eq:epsilon-zed}.
Thus $\x^*$ is not a Nash equilibrium.
\section{Proof of Example \ref{exmp:linear-deriv}}\label{sec:proof-exmp-linear-deriv}
    Say $\x^*\in\widetilde X^*(\overline\xi\textbf{1})$, but $\x^*\notin X^*(\overline\xi\textbf{1})$. Then, from \eqref{eqn:equilibrium-criterion},
