\section{Complete Gradient Analysis for SE-RBFNet}
\label{section:gradients}

SE-RBFNet optimises surface representation problems using the following loss function:
\begin{equation}
\begin{aligned}
\mathcal{L}(\boldsymbol{\widetilde{\Theta}})=\alpha \cdot \sum_{i \in id_{all} }\left(\Psi\left(\boldsymbol{v}_i, \boldsymbol{\widetilde{\Theta}}\right)-t_i\right)^2+\beta \cdot\|\boldsymbol{W}\|_1 \text{,}
\end{aligned}
\end{equation}
where 
\begin{equation*}
\begin{aligned}
\Psi(\boldsymbol{v}_i, \boldsymbol{\widetilde{\Theta}}) &= \sum_{j=1}^M w_j \cdot |w_j| \hat{\Phi}(\boldsymbol{v}_i, \Theta_j) \\
&= \sum_{j=1}^M w_j \cdot |w_j| e^{-\left\|\boldsymbol{D}_j \boldsymbol{R}_j\left(\boldsymbol{v}_i-\boldsymbol{c}_j\right)\right\|_2^2} .
\end{aligned}
\end{equation*}
$\Psi(\boldsymbol{v}_i, \boldsymbol{\widetilde{\Theta}})$ is the SE-RBFNet output for the input $\boldsymbol{v}_i$, $t_i$ is the corresponding ground-truth SDF value, and $\boldsymbol{\widetilde{\Theta}}$ denotes the set of all SE-RBFNet parameters. Only the points corresponding to the indices in $id_{all}$ are used for loss calculation. 

The relevant parameters are defined as follows:
\begin{itemize}
    \item $V$: the total training points, which consists of $N$ points, i.e.,
    $V=\displaystyle\bigcup_{i=1}^{N}\boldsymbol{v}_i$, where $\boldsymbol{v}_i$ denotes the $i$-th training point.
    \item $\boldsymbol{F}$, denoted as the feature matrix, has dimensions $N\times M$, and each element represents the response value of the $i$-th point coordinate $\boldsymbol{v}_i$ under the influence of the $j$-th ERBF $\hat{\Phi}(\boldsymbol{v}_i, \Theta_j)$.
    \item $\boldsymbol{D}_j = \text{diag}(d_{j1}, d_{j2}, d_{j3})$: the lengths of the $j$-th ERBF along its principal axes. 
    \item $\boldsymbol{c}_j = (c_{j1}, c_{j2}, c_{j3})$: the center of the $j$-th ERBF.
    \item $w_j$: the weight of the $j$-th ERBF from the hidden layer to the output layer. 
    \item $\boldsymbol{a}_j = (\theta_{x_j}, \theta_{y_j}, \theta_{z_j})$: the rotation angles of the $j$-th ERBF.
    \item $\boldsymbol{R}\left(\theta_{x_j}, \theta_{y_j}, \theta_{z_j}\right)$: the rotation matrix of the $j$-th ERBF.
    \begin{equation*}
    \begin{aligned}
     \boldsymbol{R}\left(\theta_{x_j}, \theta_{y_j}, \theta_{z_j}\right) 
    = {\left[\begin{array}{ccc}
    r^{j}_{1} & r^{j}_{2} & r^{j}_{3} \\
    r^{j}_{4} & r^{j}_{5} & r^{j}_{6} \\
    r^{j}_{7} & r^{j}_{8} & r^{j}_{9}
    \end{array}\right], }
    \end{aligned}
    \end{equation*}
    where  \par
    $r^{j}_{1} = \cos \theta_{x_j} \cos \theta_{y_j}$;  \par 
    $r^{j}_{2} = -\cos \theta_{z_j} \sin \theta_{x_j}-\sin \theta_{y_j} \sin \theta_{z_j} \cos \theta_{x_j}$;  \par 
    $r^{j}_{3} = \sin \theta_{x_j} \sin \theta_{z_j}-\cos \theta_{x_j} \cos \theta_{z_j} \sin \theta_{y_j}$;  \par 
    $r^{j}_{4} = \cos \theta_{y_j} \sin \theta_{x_j}$;  \par
    $r^{j}_{5} = \cos \theta_{x_j} \cos \theta_{z_j}-\sin \theta_{x_j} \sin \theta_{y_j} \sin \theta_{z_j}$;  \par
    $r^{j}_{6} = -\sin \theta_{z_j} \cos \theta_{x_j}-\cos \theta_{z_j} \sin \theta_{x_j} \sin \theta_{y_j}$;  \par
    $r^{j}_{7} = \sin \theta_{y_j}$;  \par 
    $r^{j}_{8} = \cos \theta_{y_j} \sin \theta_{z_j} $;  \par
    $r^{j}_{9} = \cos \theta_{y_j} \cos \theta_{z_j}$;  \par

    \item $E_i = \Psi(\boldsymbol{v}_i, \boldsymbol{\widetilde{\Theta}}) - t_i$: the residual of the $i$-th training point $\boldsymbol{v}_i$.
\end{itemize}

In what follows, we derive the analytical gradients of the loss with respect to each parameter group: weights, axis lengths, centers, and rotation angles.
The gradient of each parameter is denoted as:
\begin{equation}
\label{equ:grad}
\begin{aligned}
\nabla{\mathcal{L}(\boldsymbol{\widetilde{\Theta}})}=\left\{\alpha \cdot \frac{\partial \mathcal{L}_2}{\partial \boldsymbol{C}}, \alpha \cdot \frac{\partial \mathcal{L}_2}{\partial \bar{\boldsymbol{D}}}, \alpha \cdot \frac{\partial \mathcal{L}_2}{\partial \boldsymbol{A}}, \alpha \cdot \frac{\partial \mathcal{L}_2}{\partial \boldsymbol{W}} + \beta \cdot \frac{\partial \mathcal{L}_1}{\partial \boldsymbol{W}}\right\} \text{.}
\end{aligned}
\end{equation}

\subsection{Weight Gradient}
The loss consists of a squared error term and an $\mathcal{L}_1$ regularization on the weights:
\begin{equation}
\begin{aligned}
\label{eq:grad_w_l1}
\frac{\partial \mathcal{L}_2}{\partial w_j} &= \sum_{i=1}^N 4 \cdot w_j \cdot \text{sign}(w_j) \cdot \boldsymbol{F}_{ij} \cdot E_i \text{,} \\
\frac{\partial \mathcal{L}_1}{\partial w_j} &=  \text{sign}(w_j)\text{,}
\end{aligned}
\end{equation}
where $\boldsymbol{F}_{ij}$ is the activation of the $j$-th ellipsoid on the $i$-th input.


\subsection{Axis Length Gradient}

Let $\boldsymbol{\Delta}_{\boldsymbol{x}_{i}} = \boldsymbol{x}_i - \boldsymbol{c}_j$ and $\widetilde{D}_{\boldsymbol{x}_{i}} = \boldsymbol{R}\left(\theta_{x_j}, \theta_{y_j}, \theta_{z_j}\right) \cdot \boldsymbol{\Delta}_{\boldsymbol{x}_{i}}$ denote the rotated input offset. Then, for each axis length $d_{jk}$:
\begin{equation}
\begin{aligned}
    \frac{\partial \mathcal{L}_2}{\partial d_{jk}} &= \sum_{i=1}^N -4 \cdot\text{sign}(w_j) \cdot w_j^2 \cdot d_{jk} \cdot \boldsymbol{F}_{ij} \cdot \widetilde{D}_{x_{ik}}^2 \cdot E_i, \\
    \quad k&=1,2,3. 
    \label{eq:grad_d}
\end{aligned}
\end{equation}



\subsection{Center Gradient}

Define the intermediate vector:
\begin{equation}
\begin{aligned}
    \widetilde{\boldsymbol{E}}_i &= 
    \begin{pmatrix}
        d_{j1}^2 \cdot w_j^2 \cdot \widetilde{D}_{x_{i1}} \cdot \boldsymbol{F}_{ij} \\
        d_{j2}^2 \cdot w_j^2 \cdot \widetilde{D}_{x_{i2}} \cdot \boldsymbol{F}_{ij} \\
        d_{j3}^2 \cdot w_j^2 \cdot \widetilde{D}_{x_{i3}} \cdot \boldsymbol{F}_{ij}
    \end{pmatrix},
    \\
    \widetilde{\boldsymbol{F}}_i &= \boldsymbol{R}\left(\theta_{x_j}, \theta_{y_j}, \theta_{z_j}\right)^\mathrm{T} \cdot \widetilde{\boldsymbol{E}}_i.
\end{aligned}
\end{equation}
Then, the gradient with respect to the center coordinate $c_{jk}$ is:
\begin{equation}
    \frac{\partial \mathcal{L}_2}{\partial c_{jk}} = \sum_{i=1}^N 4 \cdot \text{sign}(w_j) \cdot \widetilde{F}_{ik} \cdot E_i, \quad k=1,2,3. \label{eq:grad_c}
\end{equation}



\subsection{Rotation Angle Gradient}

The gradients with respect to each angle are as follows:

\subsubsection{\texorpdfstring{Gradient w.r.t. $\theta_{x_j}$}{Gradient w.r.t. theta\_xj}}
\begin{equation}
    \frac{\partial \mathcal{L}_2}{\partial \theta_{x_j}} = \sum_{i=1}^N -4 \cdot \text{sign}(w_j) \cdot E_i \cdot \left( \widetilde{E}_{i1} \cdot (-\widetilde{D}_{x_{i2}}) + \widetilde{E}_{i2} \cdot (-\widetilde{D}_{x_{i1}}) \right). \label{eq:grad_theta_x}
\end{equation}

\subsubsection{\texorpdfstring{Gradient w.r.t. $\theta_{y_j}$}{Gradient w.r.t. theta\_yj}}
Define:
\begin{align*}
    \widetilde{D}_X &= -\cos\theta_{x_j} \sin\theta_{y_j} \Delta_{x_{i1}} - r^j_1 \sin\theta_{z_j} \Delta_{x_{i2}} - r^j_1 \cos\theta_{z_j} \Delta_{x_{i3}}, \\
    \widetilde{D}_Y &= -\sin\theta_{x_j} \sin\theta_{y_j} \Delta_{x_{i1}} - r^j_4 \sin\theta_{z_j} \Delta_{x_{i2}} - r^j_4 \cos\theta_{z_j} \Delta_{x_{i3}}, \\
    \widetilde{D}_Z &= \cos\theta_{y_j} \Delta_{x_{i1}} - \sin\theta_{y_j} \sin\theta_{z_j} \Delta_{x_{i2}} - \sin\theta_{y_j} \cos\theta_{z_j} \Delta_{x_{i3}},
\end{align*}
and the gradient is:
\begin{equation}
    \frac{\partial \mathcal{L}_2}{\partial \theta_{y_j}} = \sum_{i=1}^N -4 \cdot \text{sign}(w_j) \cdot E_i \cdot \left( \widetilde{E}_{i1} \cdot \widetilde{D}_X + \widetilde{E}_{i2} \cdot \widetilde{D}_Y + \widetilde{E}_{i3} \cdot \widetilde{D}_Z \right). \label{eq:grad_theta_y}
\end{equation}

\subsubsection{\texorpdfstring{Gradient w.r.t. $\theta_{z_j}$}{Gradient w.r.t. theta\_zj}}
Using the partial derivative of $\boldsymbol{R}$ with respect to $\theta_{z_j}$:
\begin{align*}
    \hat{D}_X &= r^j_3 \Delta_{x_{i2}} - r^j_2 \Delta_{x_{i3}}, \\
    \hat{D}_Y &= r^j_6 \Delta_{x_{i2}} - r^j_5 \Delta_{x_{i3}}, \\
    \hat{D}_Z &= r^j_9 \Delta_{x_{i2}} - r^j_8 \Delta_{x_{i3}},
\end{align*}
the gradient becomes:
\begin{equation}
    \frac{\partial \mathcal{L}_2}{\partial \theta_{z_j}} = \sum_{i=1}^N -4 \cdot \text{sign}(w_j) \cdot E_i \cdot \left( \widetilde{E}_{i1} \cdot \hat{D}_X + \widetilde{E}_{i2} \cdot \hat{}{D}_Y + \hat{E}_{i3} \cdot \hat{D}_Z \right). \label{eq:grad_theta_z}
\end{equation}



