\subsection{Algorithm Description}
Our stochastic diagonal estimation method lies on the following proposition. 
\begin{lemma}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{equation}\label{eq:E}
\frac{1}{2}\cdot\EE\left[\ub^\top \Ab \ub\cdot \bm{u}_p^2 - \ub^\top \Ab \ub\right]
=  \Ab_{p,p}.
\end{equation}
\end{lemma}
\begin{proof}
First, we have
\begin{align*}
\EE\left[\ub^\top \Ab \ub\cdot \bm{u}_p^2\right]
=&
\EE\left[ \sum_{i, j=1}^{d} \Ab_{i,j}\ub_i \ub_j \cdot \ub_p^2   \right]
=
\EE\left[ \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \cdot \ub_p^2 \right]\\
=& \EE\left[ \sum_{i=1, i\neq p}^{d} \Ab_{i,i} \ub_i^2 \cdot \ub_p^2 + \Ab_{p,p} \ub_p^4 \right] \\
\stackrel{\eqref{eq:Eu}}{=}&
\sum_{i=1,i\neq p}^{d} \Ab_{i,i} + 3 \Ab_{p,p}
= \tr(\Ab) + 2\Ab_{p,p}.
\end{align*}

Furthermore, 
\begin{align*}
\EE\left[ \ub^\top \Ab \ub\right]
=
\EE\left[\tr(\ub^\top \Ab \ub)\right]
=
\EE\left[ \tr(\Ab \ub\ub^\top) \right]
= \tr(\Ab).
\end{align*}

Thus, it holds that
\begin{align*}
\EE\left[\ub^\top \Ab \ub\cdot \bm{u}_p^2 - \ub^\top \Ab \ub\right] = 2 \Ab_{p,p}.
\end{align*}
\end{proof}

Eq.~\eqref{eq:E} provide an unbiased estimation of diagonal entries of $\Ab$. 
Then, we can take $N$ samples to reduce the variance of stochastic estimation to obtain a high precision estimation.
Letting random variables $\ub^{(j)} \sim\cN(\bm{0}, \I_d)$ with $j = 1,\dots, N$, then we construct the following diagonal estimation 
\begin{equation}\label{eq:g}
\bm{g} = \frac{1}{2N} \sum_{j=1}^{N} \left[\ub^{(j)}\right]^\top \Ab \ub^{(j)}\cdot \Big([\ub^{(j)}]^2 - \bm{1}_d\Big). 
\end{equation}
It is easy to check that $\bm{g}$ in Eq.~\eqref{eq:g} is also an unbiased estimation of diagonal entries of $\Ab$ but with a variance depending on $1/N$.  
The detailed algorithm description is listed in Algorithm~\ref{alg:SA}.

\begin{algorithm}[t]
\caption{Stochastic Diagonal Entries Estimation  Based on Quadratic Form Oracles}
\label{alg:SA}
\begin{small}
\begin{algorithmic}[1]
\STATE {\bf Input:} A query $Q_{\Ab}(\cdot)$ which returns $Q_{\Ab}(\ub) = \ub^\top \Ab \ub$, sample size $N$
\STATE Generate $N$ random Gaussian vectors $\ub^{(j)} \sim \cN(0, \I_d)$
\STATE Obtain $[\ub^{(j)}]^\top \Ab \ub^{(j)}$ by accessing $Q_{\Ab}(\ub^{(j)})$
\STATE {\bf Output:} $\frac{1}{2N} \sum_{j=1}^{N} \left[\ub^{(j)}\right]^\top \Ab \ub^{(j)}\cdot \Big([\ub^{(j)}]^2 - \bm{1}_d\Big)  $
\end{algorithmic}
\end{small}
\end{algorithm}

\subsection{Sample Complexity}

First, we give a sample complexity of Algorithm~\ref{alg:SA} to achieve an element-wise error bound.
\begin{theorem}\label{thm:main}
Let $\bm{g}$ defined in Eq.~\eqref{eq:g} be the output of Algorithm~\ref{alg:SA}. 
Given parameters $0<\delta<1$ and $0<\varepsilon$, then with a probability at least $1-\delta$, it holds that
\begin{equation}\label{eq:eps}
\Ab_{p,p} - \varepsilon \leq \bm{g}_p \leq \Ab_{p,p} + \varepsilon,
\end{equation}
if $N$ satisfies that
\begin{equation}\label{eq:N}
N \geq \frac{V}{4\delta \varepsilon^2}, 
\quad\mbox{ with }\quad V = 2 \Big(\tr(\Ab) + 4 \Ab_{p,p}\Big)^2 
+ \norm{\Ab + \Ab^\top}^2 
+ 8\norm{\Ab_{p,:}^\top + \Ab_{:,p}}^2
- 12 \Ab_{p,p}^2.
\end{equation}
\end{theorem}

Theorem~\ref{thm:main} shows that the sample complexity of Algorithm~\ref{alg:SA} depends on $\varepsilon^{-2}$ which is the same as the ones of stochastic diagonal entries estimation with queries to matrix-vector product \citep{baston2022stochastic,hallman2023monte,cortinovis2022randomized}.
Furthermore, the sample complexity of Algorithm~\ref{alg:SA} to estimating $\Ab_{p,p}$ depends on $\Ab_{p,p}$, $\norm{\Ab + \Ab^\top}^2$, $\tr(\Ab)$ and $\norm{\Ab_{p,:}^\top + \Ab_{:,p}}^2$.
Especially, the $\norm{\Ab + \Ab^\top}^2$ term dominates the sample complexity.
In contrast, to achieve the same precision described in Eq.~\eqref{eq:eps}, \citet{baston2022stochastic} shows that stochastic diagonal entries estimation based on matrix-vector product only needs
\begin{equation}\label{eq:N_p}
N' = \frac{2(\norm{\Ab_p}^2 - \Ab_{p,p}^2)\log\frac{2}{\delta}}{\varepsilon^2}
\end{equation}
matrix-vector product oracles.
Comparing Eq.~\eqref{eq:N} and Eq.~\eqref{eq:N_p}, we can observe that our stochastic diagonal entries estimation requires a larger query number than the one based on matrix-vector product. 
This is because Algorithm~\ref{alg:SA} can only query to the quadratic forms $\ub^\top \Ab \ub$ which contains much less information than the one of matrix product $\Ab \ub$. 

This information difference between  the quadratic forms $\ub^\top \Ab \ub$ and matrix-vector $\Ab\ub$ can be demonstrated in the following example.
Letting $\Ab$ be a Hessian matrix of $f(\xb)$, then Proposition~\ref{prop:uAu} shows that $\ub^\top \Ab \ub$ can be approximated by only three queries of the function value. 
Instead, the Hessian-vector product requires to compute the gradient $\nabla f(\xb)$ shown as follows:
\begin{equation}
	\nabla^2 f(\xb) \ub \approx \frac{\nabla f(\xb + \alpha \ub) - \nabla f(\xb - \alpha \ub) }{2\alpha}.
\end{equation}
Noting that, it may require $\cO(d)$ function queries to compute the gradient $\nabla f(\cdot)$. 
Thus, our stochastic diagonal entries estimation requires a larger query number than the one based on matrix-vector product.



Next, we will give a sample complexity of Algorithm~\ref{alg:SA} to achieve a norm-wise error bound.
\begin{theorem}\label{thm:main1}
Let $\bm{g}$ defined in Eq.~\eqref{eq:g} be the output of Algorithm~\ref{alg:SA}. 
Given parameters $0<\delta<1$ and $0<\varepsilon$, then with a probability at least $1-\delta$, it holds that
\begin{equation}\label{eq:eps3}
\norm{\bm{g} - \diag(\Ab)}^2 \leq \varepsilon\sum_{i=1}^{d} \Ab_{i,i}^2,
\end{equation}
if $N$ satisfies that
\begin{equation}\label{eq:N1}
N = \frac{1}{4\varepsilon\delta} \cdot \frac{(4d + 16) \Big(\tr(\Ab)\Big)^2
+ (d+8)\norm{\Ab + \Ab^\top}^2 
%+ 8\sum_{p=1}^{d}\norm{\Ab_{p,:}^\top + \Ab_{:,p}}^2
+ 20\sum_{i=1}^{d} \Ab_{i,i}^2}{\sum_{i=1}^{d} \Ab_{i,i}^2}. 
\end{equation}
\end{theorem}

Note that $\norm{\Ab + \Ab^\top}^2 = \norm{\Ab + \Ab^\top}^2 - 4 \sum_{i=1}^{d}\Ab_{i,i}^2  + 4 \sum_{i=1}^{d}\Ab_{i,i}^2 $ and $4 \sum_{i=1}^{d}\Ab_{i,i}^2 = \norm{\diag(\Ab + \Ab^\top)}^2$. 
Thus, the term $ \norm{\Ab + \Ab^\top}^2 - 4 \sum_{i=1}^{d}\Ab_{i,i}^2 $ is the square of ``Frobenius'' norm of off-diagonal entries of $\Ab + \Ab^\top$.
Accordingly, we can represent Eq.~\eqref{eq:N1} as 
\begin{align*}
	N = \frac{1}{4\varepsilon\delta} \cdot \left( \frac{(4d + 16) \Big(\tr(\Ab)\Big)^2}{\sum_{i=1}^{d} \Ab_{i,i}^2} + \frac{(d+8) \left(\norm{\Ab + \Ab^\top}^2 - 4 \sum_{i=1}^{d}\Ab_{i,i}^2\right) }{\sum_{i=1}^{d} \Ab_{i,i}^2} + \Big(4d + 52\Big) \right)
\end{align*} 
Thus, if $|\tr(\Ab)|$ is small and the off-diagonal entries of $\Ab + \Ab^\top$ are of small absolute value, then sample size $N$ required to achieve the same accuracy can also be small.
In this case, then the sample complexity is dominated by the dimension $d$.

To achieve the accuracy in Eq.~\eqref{eq:eps3}, Corollary 2 of \citet{baston2022stochastic} shows that stochastic diagonal estimation with matrix-vector product needs a sample complexity
\begin{equation}
N' = \frac{\norm{\Ab}^2 - \sum_{i=1}^{d} \Ab_{i,i}^2}{\varepsilon \cdot \sum_{i=1}^{d} \Ab_{i,i}^2} \cdot \log\frac{1}{\delta}.
\end{equation}
Comparing above equation with Eq.~\eqref{eq:N1}, we can obtain that $N = \cO(d) \cdot N'$. 
This is also because the matrix-vector product can provide more information than the matrix quadratic form.
