\subsection{High Probability Version}

The sample size $N$ in Eq.~\eqref{eq:N} depends the $\frac{1}{\delta}$. 
Thus, it requires a large sample size to guarantee Eq.~\eqref{eq:eps} to hold with a high probability.
Next, we will make a simple variant of Algorithm~\ref{alg:SA} to make the sample size $N$ depend on $\log\frac{1}{\delta}$ instead of $\delta$.

The new algorithm relies on Algorithm~\ref{alg:SA} which runs   Algorithm~\ref{alg:SA}   $8\log\frac{1}{\delta}$ times   with parameter $N = \frac{V}{\varepsilon^2}$ and coordinately take the median of  these $8\log\frac{1}{\delta}$ outputs of Algorithm~\ref{alg:SA} as the final result.  
The detailed algorithm description is listed in Algorithm~\ref{alg:SA1}.
The idea behind of Algorithm~\ref{alg:SA1} is based on the following fact.
Theorem~\ref{thm:main} shows that if we take sample size $N = \frac{V}{\varepsilon^2}$, then each output of Algorithm~\ref{alg:SA} satisfies Eq.~\eqref{eq:eps} with a probability $\frac{1}{4}$. 
Then, the median of $8\log\frac{1}{\delta}$ outputs of  Algorithm~\ref{alg:SA} will satisfies Eq.~\eqref{eq:eps} with a probability $1-\delta$.


\begin{theorem}\label{thm:main2}
Let $\bm{g}$ be the output of Algorithm~\ref{alg:SA1}. 
Given parameters $0<\delta<1$ and $0<\varepsilon$, then with a probability at least $1-\delta$, 
it holds that
\begin{equation}\label{eq:eps2}
\Ab_{p,p} - \varepsilon \leq \bm{g}_p \leq \Ab_{p,p} + \varepsilon,
\end{equation}
if parameters $N'$ and $T$ of Algorithm~\ref{alg:SA1} satisfies
\begin{equation*}
N' = \frac{2 \Big(\tr(\Ab) + 4 \Ab_{p,p}\Big)^2 
+ \norm{\Ab + \Ab^\top}^2 
+ 8\norm{\Ab_{p,:} + \Ab_{:,p}}^2
- 12 \Ab_{p,p}^2}{ \varepsilon^2},
\quad\mbox{ and }\quad
T = 8\log\frac{1}{\delta}.
\end{equation*}
\end{theorem}


Theorem~\ref{thm:main2} shows that the total sample complexity to achieve Eq.~\eqref{eq:eps2} is 
\begin{align*}
N = N' T 
= 
8\log\frac{1}{\delta}  \cdot \frac{2 \Big(\tr(\Ab) + 4 \Ab_{p,p}\Big)^2 
	+ \norm{\Ab + \Ab^\top}^2 
	+ 8\norm{\Ab_{p,:} + \Ab_{:,p}}^2
	- 12 \Ab_{p,p}^2}{ \varepsilon^2}.
\end{align*}
The sample complexity in above equation depends on $\log\frac{1}{\delta}$ instead of $\frac{1}{\delta}$ in Eq.~\eqref{eq:N}. 

\begin{algorithm}[t]
\caption{Stochastic Diagonal Entries Estimation with High Probability}
\label{alg:SA1}
\begin{small}
\begin{algorithmic}[1]
\STATE {\bf Input:} A query $Q_{\Ab}(\cdot)$ which returns $Q_{\Ab}(\ub) = \ub^\top \Ab \ub$, sample size $N'$ and iteration number $T$
\FOR{$t = 1,\dots, T$}
\STATE Obtain $\bm{g}^{(t)}$ by Algorithm~\ref{alg:SA} with $Q_{\Ab}(\cdot)$ and $N'$ as input.
\ENDFOR
%\FOR{$p=1\dots, d$}
%\STATE Sort $\bm{g}_p^{(1)},\dots, \bm{g}_p^{(T)}$ 
%\ENDFOR
\STATE {\bf Output:} the median of $\bm{g}^{(t)}  $ coordinately.
\end{algorithmic}
\end{small}
\end{algorithm}

\section{Sample Complexity Analysis}

In the previous section, we provide the sample complexities of Algorithm~\ref{alg:SA} and Algorithm~\ref{alg:SA1}. 
In this section, we will provide the detailed analysis to obtain these sample complexities.
The key to the analysis is the variance of the unbiased estimation in Eq.~\eqref{eq:E}.

\subsection{Variance of Estimation}

First, the variance of our unbiased estimation has the following decomposition.
\begin{lemma}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, the it holds that
\begin{equation}\label{eq:var}
\begin{aligned}
&\EE\left[ \left( \ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub - 2\Ab_{p,p} \right)^2 \right]\\
=&	
\EE\left[ \left( \ub^\top \Ab \ub \cdot \ub_p^2  \right)^2 \right] 
+ \EE\left[ \left( \ub^\top \Ab \ub \right)^2 \right]
- 2 \EE\left[ \left(\ub^\top \Ab \ub \cdot \ub_p \right)^2  \right]
- 4\Ab_{p,p}^2.
\end{aligned}
\end{equation}
\end{lemma}
\begin{proof}
By Eq.~\eqref{eq:E} and Lemma~\ref{lem:var}, we can obtain that
\begin{align*}
\EE\left[ \left( \ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub - 2\Ab_{p,p} \right)^2 \right]
=
\EE\left[ \left(\ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub\right)^2 \right] 
- 4\Ab_{p,p}^2.
\end{align*}
Furthermore, 
\begin{align*}
\EE\left[ \left(\ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub\right)^2 \right]
=
\EE\left[ \left( \ub^\top \Ab \ub \cdot \ub_p^2  \right)^2 \right] 
+ \EE\left[ \left( \ub^\top \Ab \ub \right)^2 \right]
- 2 \EE\left[ \left(\ub^\top \Ab \ub \cdot \ub_p \right)^2  \right].
\end{align*}
Combining above equation, we can obtain the result.
\end{proof}

Eq.~\eqref{eq:var} shows that the variance mainly depends on the terms $\EE\left[\left(\ub^\top \Ab \ub\cdot \bm{u}_p^n  \right)^2  \right]$ with $n = 0,1,2$.
Next, we will compute the exact value of $\EE\left[\left(\ub^\top \Ab \ub\cdot \bm{u}_p^n  \right)^2  \right]$.

\begin{lemma}\label{lem:3a}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{equation}\label{eq:a}
\EE\left[ \left(\ub^\top \Ab \ub   \right)^2 \right]
=
\Big(\tr(\Ab)\Big)^2 + 2 \sum_{i=1}^{d} \Ab_{i,i}^2 
+ \sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2,
\end{equation}
\begin{equation}\label{eq:a1}
\begin{aligned}
&\EE\left[\left( \ub^\top \Ab \ub \cdot \ub_p \right)^2\right]
= 
\Big(\tr(\Ab)\Big)^2 
+ 4 \Ab_{p,p} \tr(\Ab) 
+ 2 \sum_{i=1}^{d} \Ab_{i,i}^2 
+ 8 \Ab_{p,p}^2 \\
&
+ \sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
+ 2 \sum_{i>j,  j= p}^{d}\Big(\Ab_{i,p} + \Ab_{p,i} \Big)^2
+ 2 \sum_{i>j,  i= p}^{d}\Big( \Ab_{p,j} + \Ab_{j,p} \Big)^2,
\end{aligned}
\end{equation}
and
\begin{equation}\label{eq:a2}
\begin{aligned}
&\EE\left[ \left(\ub^\top \Ab \ub\cdot \bm{u}_p^2  \right)^2 \right] 
=
3 \Big(\tr(\Ab)\Big)^2 + 6 \sum_{i= 1}^{d} \Ab_{i,i}^2 + 24 \Ab_{p,p} \cdot \tr(\Ab) + 72 \Ab_{p,p}^2  \\
&+ 3 \sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
+ 12 \sum_{i>j,  j= p}^{d} \Big(\Ab_{i,p} + \Ab_{p,i}\Big)^2
+ 12 \sum_{i>j, i=p}^{d} \Big(\Ab_{p,j} + \Ab_{j, p}\Big)^2.
\end{aligned}
\end{equation}
\end{lemma}

Given above two lemmas, we can obtain the explicit formula of the variance.

\begin{lemma}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{equation}\label{eq:main}
\begin{aligned}
&\EE\left[ \left( \ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub - 2\Ab_{p,p} \right)^2 \right]\\
=&
2 \Big(\tr(\Ab) + 4 \Ab_{p,p}\Big)^2 
+ \norm{\Ab + \Ab^\top}^2 
+ 8\norm{\Ab_{p,:} + \Ab_{:,p}}^2
- 12 \Ab_{p,p}^2.
\end{aligned}	
\end{equation}
and
\begin{equation}\label{eq:main1}
\begin{aligned}
&\EE\left[ \sum_{p=1}^{d}\left(\ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub - 2\Ab_{p,p}\right)^2 \right]\\
=&
(4d + 16) \Big(\tr(\Ab)\Big)^2
+ d\norm{\Ab + \Ab^\top}^2 
+ 8\sum_{p=1}^{d}\norm{\Ab_{p,:} + \Ab_{:,p}}^2
+ 20\sum_{i=1}^{d} \Ab_{i,i}^2.
\end{aligned}
\end{equation}
\end{lemma}
\begin{proof}
First, we have
\begin{align*}
&\EE\left[ \left(\ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub - 2\Ab_{p,p}\right)^2 \right]\\
\stackrel{\eqref{eq:var}}{=}& 
\EE\left[ \left( \ub^\top \Ab \ub \cdot \ub_p^2  \right)^2 \right] 
+ \EE\left[ \left( \ub^\top \Ab \ub \right)^2 \right]
- 2 \EE\left[ \left(\ub^\top \Ab \ub \right)^2 \cdot \ub_p^2 \right] - 4\Ab_{p,p}^2\\
\stackrel{\eqref{eq:a}\eqref{eq:a1}\eqref{eq:a2}}{=}& 
3 \Big(\tr(\Ab)\Big)^2 + 6 \sum_{i= 1}^{d} \Ab_{i,i}^2 + 24 \Ab_{p,p} \cdot \tr(\Ab) + 68 \Ab_{p,p}^2  \\
&+ 3 \sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
+ 12 \sum_{i>j,  j= p}^{d} \Big(\Ab_{i,p} + \Ab_{p,i}\Big)^2
+ 12 \sum_{i>j, i=p}^{d} \Big(\Ab_{p,j} + \Ab_{j, p}\Big)^2\\
&
+ \Big(\tr(\Ab)\Big)^2 + 2 \sum_{i=1}^{d} \Ab_{i,i}^2 
+ \sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2\\
&
- 2 \left(\Big(\tr(\Ab)\Big)^2 
+ 4 \Ab_{p,p} \tr(\Ab) 
+ 2 \sum_{i=1}^{d} \Ab_{i,i}^2 
+ 8 \Ab_{p,p}^2\right)\\
&
-2\left(\sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
+ 2 \sum_{i>j,  j= p}^{d}\Big(\Ab_{i,p} + \Ab_{p,i} \Big)^2
+ 2 \sum_{i>j,  i= p}^{d}\Big( \Ab_{p,j} + \Ab_{j,p} \Big)^2\right)\\
=&
2\Big(\tr(\Ab)\Big)^2
+ 4\sum_{i= 1}^{d} \Ab_{i,i}^2
+ 16\Ab_{p,p} \cdot \tr(\Ab)
+ 52 \Ab_{p,p}^2\\
&
+ 2\sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
+ 8 \sum_{i>j,  j= p}^{d} \Big(\Ab_{i,p} + \Ab_{p,i}\Big)^2
+ 8\sum_{i>j, i=p}^{d} \Big(\Ab_{p,j} + \Ab_{j, p}\Big)^2.
\end{align*}

Furthermore, it holds that
\begin{align*}
4\sum_{i= 1}^{d} \Ab_{i,i}^2 + 2\sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2 = \norm{\Ab + \Ab^\top}^2.
\end{align*}
We also have
\begin{align*}
8 \sum_{i>j,  j= p}^{d} \Big(\Ab_{i,p} + \Ab_{p,i}\Big)^2
+ 8\sum_{i>j, i=p}^{d} \Big(\Ab_{p,j} + \Ab_{j, p}\Big)^2 
+ 32 \Ab_{p,p}^2 
= 8\norm{\Ab_{p,:} + \Ab_{:,p}}^2
\end{align*}

Thus,
\begin{align*}
&\EE\left[ \left(\ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub - 2\Ab_{p,p} \right)^2 \right]\\
=&
2\Big(\tr(\Ab)\Big)^2 
+ 16\Ab_{p,p} \cdot \tr(\Ab)
+ \norm{\Ab + \Ab^\top}^2 
+ 8\norm{\Ab_{p,:} + \Ab_{:,p}}^2
+ 20\Ab_{p,p}^2\\
=&
2 \Big(\tr(\Ab) + 4 \Ab_{p,p}\Big)^2 
+ \norm{\Ab + \Ab^\top}^2 
+ 8\norm{\Ab_{p,:} + \Ab_{:,p}}^2
- 12 \Ab_{p,p}^2.
\end{align*}

Furthermore, we can obtain that
\begin{align*}
&\EE\left[ \sum_{p=1}^{d}\left(\ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub - 2\Ab_{p,p}\right)^2 \right]\\
=&
2 \sum_{p=1}^{d}\Big(\tr(\Ab) + 4 \Ab_{p,p}\Big)^2 
+ d\norm{\Ab + \Ab^\top}^2 
+ 8\sum_{p=1}^{d}\norm{\Ab_{p,:} + \Ab_{:,p}}^2
- 12 \sum_{p=1}^{d}\Ab_{p,p}^2\\
=& 
4d \Big(\tr(\Ab)\Big)^2 
+ 16 \tr(\Ab) \sum_{p=1}^{d} \Ab_{p,p} 
+ 32 \sum_{p=1}^{d}\Ab_{p,p}^2
+ d\norm{\Ab + \Ab^\top}^2 
+ 8\sum_{p=1}^{d}\norm{\Ab_{p,:} + \Ab_{:,p}}^2
- 12 \sum_{p=1}^{d}\Ab_{p,p}^2\\
=& 
(4d + 16) \Big(\tr(\Ab)\Big)^2
+ d\norm{\Ab + \Ab^\top}^2 
+ 8\sum_{p=1}^{d}\norm{\Ab_{p,:} + \Ab_{:,p}}^2
+ 20\sum_{i=1}^{d} \Ab_{i,i}^2.
\end{align*}

