\subsection{Sample Complexity Analysis}

Given the variance of unbiased estimation in Eq.~\eqref{eq:E}, combining with the Chebyshev's inequality, we can prove the results in Theorem~\ref{thm:main} as follows.
\begin{proof}[Proof of Theorem~\ref{thm:main}]
By Chebyshev's inequality, we can obtain that
\begin{align*}
&\PP\left\{ \left| \frac{1}{2N}\sum_{j=1}^{N} \left[\ub^{(j)}\right]^\top \Ab \ub^{(j)}\cdot \Big([\ub_p^{(j)}]^2 - 1\Big) - \Ab_{p,p} \right| > \varepsilon \right\}\\
\leq& 
\frac{1}{4N} \cdot  \frac{\EE\left[\left(\ub^\top \Ab \ub\cdot \bm{u}_p^2 -\tr(\Ab) - 2\Ab_{p,p} \right)^2\right]}{\varepsilon^2}\\
\stackrel{\eqref{eq:main}}{=}&
\frac{2 \Big(\tr(\Ab) + 4 \Ab_{p,p}\Big)^2 
+ \norm{\Ab + \Ab^\top}^2 
+ 8\norm{\Ab_{p,:} + \Ab_{:,p}}^2
- 12 \Ab_{p,p}^2}{4N \varepsilon^2},
\end{align*}
where the first inequality is because of the  Chebyshev's inequality and the independence of $\ub^{(j)}$'s in Algorithm~\ref{alg:SA}.

By setting the right hand of above equation to $\delta$, we should choose $N$ to be 
\begin{equation*}
N = \frac{2 \Big(\tr(\Ab) + 4 \Ab_{p,p}\Big)^2 
+ \norm{\Ab + \Ab^\top}^2 
+ 8\norm{\Ab_{p,:} + \Ab_{:,p}}^2
- 12 \Ab_{p,p}^2}{4\delta \varepsilon^2}.
\end{equation*}
\end{proof}
Next, we will prove the results in Theorem~\ref{thm:main1} similar to the one of Theorem~\ref{thm:main}.
\begin{proof}[Proof of Theorem~\ref{thm:main1}]
By the Markov's inequality, we can obtain that
\begin{align*}
&\PP\left\{ 	\norm{\bm{g} - \diag(\Ab)}^2 > \varepsilon\sum_{i=1}^{d} \Ab_{i,i}^2 \right\}
\leq 
\frac{\EE\left[\norm{\bm{g} - \diag(\Ab)}^2  \right]}{\varepsilon\sum_{i=1}^{d} \Ab_{i,i}^2}\\
=&
\frac{1}{4N} \frac{\EE\left[ \sum_{p=1}^{d}\left( \ub^\top \Ab \ub \cdot \ub_p^2 - \ub^\top \Ab \ub - 2\Ab_{p,p} \right)^2 \right]}{\varepsilon\sum_{i=1}^{d} \Ab_{i,i}^2}\\
\stackrel{\eqref{eq:main1}}{=}&
\frac{1}{4N} \cdot \frac{(4d + 16) \Big(\tr(\Ab)\Big)^2
+ d\norm{\Ab + \Ab^\top}^2 
+ 8\sum_{p=1}^{d}\norm{\Ab_{p,:} + \Ab_{:,p}}^2
+ 20\sum_{i=1}^{d} \Ab_{i,i}^2}{\varepsilon\sum_{i=1}^{d} \Ab_{i,i}^2}.
\end{align*}
Furthermore, it holds that
\begin{align*}
\sum_{p=1}^{d}\norm{\Ab_{p,:} + \Ab_{:,p}}^2 
= 
\norm{ \Ab + \Ab^\top }^2.
\end{align*}
Thus,
\begin{align*}
\PP\left\{ 	\norm{\bm{g} - \diag(\Ab)}^2 > \varepsilon\sum_{i=1}^{d} \Ab_{i,i}^2 \right\}
\leq
\frac{1}{4N} \cdot \frac{(4d + 16) \Big(\tr(\Ab)\Big)^2
	+ (d+8)\norm{\Ab + \Ab^\top}^2 
	%+ 8\sum_{p=1}^{d}\norm{\Ab_{p,:} + \Ab_{:,p}}^2
	+ 20\sum_{i=1}^{d} \Ab_{i,i}^2}{\varepsilon\sum_{i=1}^{d} \Ab_{i,i}^2}.
\end{align*}


By setting the right hand of above equation to $\delta$, we should choose $N$ to be 
\begin{align*}
N = \frac{1}{4\varepsilon\delta} \cdot \frac{(4d + 16) \Big(\tr(\Ab)\Big)^2
+ (d+8)\norm{\Ab + \Ab^\top}^2 
%+ 8\sum_{p=1}^{d}\norm{\Ab_{p,:} + \Ab_{:,p}}^2
+ 20\sum_{i=1}^{d} \Ab_{i,i}^2}{\sum_{i=1}^{d} \Ab_{i,i}^2}. 
\end{align*}	
\end{proof}



Next, we will prove the results in Theorem~\ref{thm:main2}.

\begin{proof}[Proof of Theorem~\ref{thm:main2}]
By the setting of $N'$ and Theorem~\ref{thm:main}, we can obtain that for any integer $1\leq p\leq d$, with a probability at least $1-\frac{1}{4}$, $\bm{g}_p^{(j)}$ in Algorithm~\ref{alg:SA1} satisfies that
\begin{equation}\label{eq:eps1}
\Ab_{p,p} - \varepsilon \leq \bm{g}_p^{(j)} \leq \Ab_{p,p} +\varepsilon.
\end{equation}

Define a random variable $Y^{(j)}$
\begin{equation}
Y^{(j)} 
=
\begin{cases}
1, \qquad\mbox{if $\bm{g}_p^{(j)}$ satisfies Eq.~\eqref{eq:eps1}}\\
0, \qquad\mbox{otherwise}
\end{cases}.
\end{equation} 

Assume that $\bm{g}_p$, the output of Algorithm~\ref{alg:SA1}, is a bad estimation, that is $\bm{g}_p > \Ab_{p,p} +\varepsilon$ or $\bm{g}_p < \Ab_{p,p} - \varepsilon$. 
Because $\bm{g}_p$ is the median of $\bm{g}_p^{(j)}$, if $\bm{g}_p > \Ab_{p,p} +\varepsilon$, then at most half of $\bm{g}_p^{(j)}$ will no larger than $\Ab_{p,p} +\varepsilon$ which implies that at most half of $\bm{g}_p^{(j)}$ satisfy Eq.~\eqref{eq:eps1}.
For the same reason, if $\bm{g}_p < \Ab_{p,p} -\varepsilon$, then at most half of $\bm{g}_p^{(j)}$ will no less than $\Ab_{p,p} -\varepsilon$ which implies that at most half of $\bm{g}_p^{(j)}$ satisfy Eq.~\eqref{eq:eps1}.
Therefore,  $|\bm{g}_p - \Ab_{p,p}|>\varepsilon$ implies that    at most half of $\bm{g}_p^{(j)}$ satisfy Eq.~\eqref{eq:eps1} which will lead to $\sum_{j} Y^{(j)} \leq \frac{T}{2}$.
Accordingly, we can obtain that
\begin{align*}
\PP\left( |\bm{g}_p - \Ab_{p,p}|>\varepsilon \right) 
\leq& 
\PP\left( \sum_{j} Y^{(j)} \leq \frac{T}{2}  \right)
=
\PP\left( \sum_{j} Y^{(j)} - \EE\left[ \sum_{j} Y^{(j)} \right] \leq \frac{T}{2} - \EE\left[ \sum_{j} Y^{(j)} \right] \right)\\
\leq& 
\PP\left( \sum_{j} Y^{(j)} - \EE\left[ \sum_{j} Y^{(j)} \right] \leq - \frac{T}{4} \right)
\leq
\exp\left( \frac{-2 T^2/16}{T} \right),
\end{align*}
where the second inequality is because $\EE\left[\sum_{j}Y^{(j)}\right] = \sum_{j}\EE\left[ Y^{(j)} \right] \geq \frac{3T}{4}$ and the last inequality is because of Lemma~\ref{lem:hoeffding}.

By setting $\exp\left( \frac{-2 T^2/16}{T} \right) = \delta$, we can obtain that $T = 8\log\frac{1}{\delta}$ which concludes the proof.
\end{proof}


