\section{Some Useful Lemmas}

\begin{lemma}\label{lem:var}
Letting $a$ be a random variable, then it holds that $\EE\left[\Big(a - \EE[a]\Big)^2\right] = \EE\left[a^2\right] - \Big(\EE\left[a\right]\Big)^2$.
\end{lemma}

\begin{lemma}
Letting  $u \sim \cN(0,1)$, that is $u$ is a random variable of standard Gaussian distribution, then it holds that 
\begin{equation}\label{eq:Eu}
\EE\left[u^2\right] = 1,\; \EE\left[u^4\right] = 3,\; \EE\left[u^6\right] = 15,\;\mbox{and}\;\; \EE\left[u^8\right] = 105,
\end{equation} 
and 
\begin{equation}\label{eq:zero}
\EE\left[u^n\right] = 0, \forall n\mbox{ is an odd integer.}
\end{equation}
\end{lemma}


\begin{lemma}[\cite{hoeffding1994probability}]\label{lem:hoeffding}
Let $X_1,\dots , X_n$ be independent bounded random variables such
that $X_i$ falls in the interval $[a_i, b_i]$ with probability one. Letting $S_n = \sum_{i=1}^{n} X_i$,  then for any $t > 0$
we have
\begin{equation}
\PP\left( S_n - \EE[S_n] \leq -t \right) \leq \exp\left(\frac{-2t^2}{\sum_{i=1}^{n}(b_i - a_i)^2}\right)
\end{equation}
\end{lemma}

\section{Proof of Proposition~\ref{prop:uAu}}

\begin{proof}[Proof of Proposition~\ref{prop:uAu}]
	First, by the definition of $\Delta(\xb, \alpha\ub)$, we can obtain the following equations:
	\begin{align*}
		f(\xb + \alpha \ub) =& f(\xb) + \alpha \nabla^\top f(\xb) \ub + \frac{\alpha^2}{2} \ub^\top \nabla^2 f(\xb) \ub + \Delta(\xb, \alpha\ub)\\
		f(\xb - \alpha \ub) =& f(\xb) - \alpha \nabla^\top f(\xb) \ub + \frac{\alpha^2}{2} \ub^\top \nabla^2 f(\xb) \ub + \Delta(\xb, -\alpha\ub).
	\end{align*}
Thus, we can obtain that 
	\begin{align*}
		\frac{f(\xb + \alpha \ub) + f(\xb - \alpha \ub) - 2f(\xb)}{\alpha^2}
		=
		\ub^\top \nabla^2 f(\xb) \ub + \frac{\Delta(\xb, \alpha\ub) + \Delta(\xb, -\alpha\ub)}{\alpha^2}
	\end{align*}

	By the $\gamma$-Lipschitz continuous of the Hessian, Lemma~1 of \citet{nesterov2006cubic} shows that
	\begin{align*}
		\left|f(\yb) - f(\xb) - \nabla^\top f(\xb) (\yb - \xb) - \frac{1}{2} (\yb - \xb)^\top \nabla^2 f(\xb) (\yb - \xb) \right| \leq \frac{\gamma \norm{\yb - \xb}^3}{6}.
	\end{align*}
	Then, we can obtain that
	\begin{align*}
		\Big|\Delta(\xb, \alpha\ub)\Big| \leq \frac{\alpha^3 \norm{\ub}^3}{6} \qquad\mbox{ and }\qquad \Big|\Delta(\xb, -\alpha\ub)\Big| \leq \frac{\alpha^3 \norm{\ub}^3}{6}.
	\end{align*}
	Thus, 
	\begin{align*}
		\left| \frac{\Delta(\xb, \alpha\ub) + \Delta(\xb, -\alpha\ub)}{\alpha^2} \right|
		\leq 
		\frac{\alpha \norm{\ub}^3}{3}.
	\end{align*}

	Furthermore, by Lemma~4 of \citet{ye2025hessian}, with a probability $1-\delta$,  it holds that $\norm{\ub} \leq 2d + 3 \log\frac{1}{\delta}$.
	Thus, we can obtain that 
	\begin{equation*}
		\left| \frac{\Delta(\xb, \alpha\ub) + \Delta(\xb, -\alpha\ub)}{\alpha^2} \right| \leq \frac{\alpha \left( 2d + 3 \log\frac{1}{\delta} \right)^3}{3}.
	\end{equation*}
\end{proof}

\section{Proof of Lemma~\ref{lem:3a}}

First, we decompose $\EE\left[ \left(\ub^\top \Ab \ub\cdot \bm{u}_p^n  \right)^2 \right]$ into  two terms.
\begin{lemma}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{equation}\label{eq:uAu}
\begin{aligned}
\EE\left[ \left(\ub^\top \Ab \ub\cdot \bm{u}_p^n  \right)^2 \right]
=
\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p^n\right)^2 \right] + \EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right].
\end{aligned}
\end{equation}
\end{lemma}
\begin{proof}
We have
\begin{align*}
&\EE\left[ \left(\ub^\top \Ab \ub\cdot \ub_p^n  \right)^2 \right]
=
\EE\left[ \left(\sum_{i, j=1} \Ab_{i,j} \ub_i\ub_j \ub_p^n\right)^2  \right] \\
=&
\EE\left[ \left(\sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p^n +  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n\right)^2 \right]\\
=&
\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p^n\right)^2 \right] + \EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right]\\
&+ 2\EE\left[ \left( \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p^n \right) \cdot \left( \sum_{i \neq  j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right) \right].
\end{align*}
Furthermore, 
\begin{align*}
\EE\left[ \left( \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p^n \right) \cdot \left( \sum_{i \neq  j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right) \right]
=
\EE\left[ \sum_{i=1}^{d} \sum_{k\neq \ell}^{d}\Ab_{i,i} \Ab_{k,\ell} \ub_i^2 \ub_k\ub_\ell \ub_p^{2n} \right]
= 0,
\end{align*}
where the last equality is because of Eq.~\eqref{eq:zero}.
Thus, we can obtain the final result.
\end{proof}

Next, we will bound two terms in the right hand of Eq.~\eqref{eq:uAu} in the next two subsections.

\subsection{Bound of First Term}

We will bound the first term in Eq.~\eqref{eq:uAu} and we have the following result.
\begin{lemma}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{align}
\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \right)^2 \right]
=&
\Big(\tr(\Ab)\Big)^2 + 2 \sum_{i=1}^{d} \Ab_{i,i}^2, \label{eq:Auu0}\\
\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p\right)^2 \right] \label{eq:Auu1}
=&
\Big(\tr(\Ab)\Big)^2 
+ 4 \Ab_{p,p} \tr(\Ab) 
+ 2 \sum_{i=1}^{d} \Ab_{i,i}^2 
+ 8 \Ab_{p,p}^2,\\
\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p^2\right)^2 \right] 
=& 
3 \Big(\tr(\Ab)\Big)^2 
+ 6 \sum_{i=1}^{d} \Ab_{i,i}^2 
+ 24 \Ab_{p,p} \cdot \tr(\Ab) + 72 \Ab_{p,p}^2. \label{eq:Auu_p}
\end{align}
\end{lemma}
\begin{proof}
First, we have
\begin{align*}
&\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p^n\right)^2 \right]
=
\EE\left[ \sum_{i=1}^{d}\sum_{j=1}^{d} \Ab_{i,i} \Ab_{j,j} \ub_i^2 \ub_j^2 \ub_p^{2n} \right]\\
=&
\EE\left[ \sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n} \right] + \EE\left[ \sum_{i\neq j, i = p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n}  \right] \\
&+ \EE\left[ \sum_{i\neq j, j = p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n}  \right] 
+ \EE\left[ \sum_{i= j, j \neq p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n}  \right] 
+ \EE\left[ \sum_{i= j = p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n} \right].
\end{align*}
Next, we will bound above terms and we have
\begin{align*}
\EE\left[ \sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n} \right] 
= \sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j} \EE\left[ \ub_i^2  \right] \EE\left[ \ub_j^2 \right] \EE\left[ \ub_p^{2n} \right]
=
\begin{cases}
\sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j}, \qquad n = 0\\
\sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j}, \qquad n = 1\\
3\sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j} \qquad n = 2
\end{cases},
\end{align*}
where the first equality is because $\ub_i$, $\ub_j$ and $\ub_p$ are independent when $i\neq j\neq p$ and the last equality is because of Eq.~\eqref{eq:Eu}. 
Similarly, we have
\begin{align*}
&\EE\left[ \sum_{i\neq j, i = p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n}  \right]
= \EE\left[ \sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j}   \ub_j^2 \ub_p^{2n + 2}  \right]
\\
=& 
\sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j} \EE\left[ \ub_j^2 \right] \EE\left[ \ub_p^{2n + 2} \right]
\stackrel{\eqref{eq:Eu}}{=}
\begin{cases}
\sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j} \qquad &n = 0 \\
3 \sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j} \qquad &n = 1\\
15 \sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j} \qquad &n = 2
\end{cases} ,
\end{align*}
and
\begin{align*}
&\EE\left[ \sum_{i\neq j, j = p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n}  \right] 
=
\EE\left[ \sum_{i\neq p}^{d} \Ab_{i,i} \Ab_{p,p} \ub_i^2 \ub_p^{2n+2} \right]\\
=& \sum_{i\neq p}^{d} \Ab_{i,i} \Ab_{p,p} \EE\left[ \ub_i^2 \right] \EE\left[ \ub_p^{2n+2} \right]
\stackrel{\eqref{eq:Eu}}{=} 
\begin{cases}
\sum_{i\neq  p} \Ab_{p,p} \Ab_{i,i} \qquad &n = 0\\
3 \sum_{i\neq  p} \Ab_{p,p} \Ab_{i,i} \qquad &n = 1\\
15 \sum_{i\neq  p} \Ab_{p,p} \Ab_{i,i} \qquad &n = 2
\end{cases}.
\end{align*}
Furthermore, we have
\begin{align*}
&\EE\left[ \sum_{i= j, j \neq p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n}  \right] 
= \EE\left[ \sum_{i \neq p}^{d} \Ab_{i,i}^2 \ub_i^4\ub_p^{2n} \right]\\
=& \sum_{i \neq p}^{d} \Ab_{i,i}^2 \EE\left[ \ub_i^4 \right] \EE\left[\ub_p^{2n}\right]
\stackrel{\eqref{eq:Eu}}{=} 
\begin{cases}
3 \sum_{i\neq p}^{d} \Ab_{i,i}^2\qquad &n = 0\\
3 \sum_{i\neq p}^{d} \Ab_{i,i}^2\qquad &n = 1\\
9 \sum_{i\neq p}^{d} \Ab_{i,i}^2\qquad &n = 2
\end{cases},
\end{align*}
and
\begin{align*}
\EE\left[ \sum_{i= j = p} \Ab_{i,i} \Ab_{j,j}  \ub_i^2 \ub_j^2 \ub_p^{2n} \right]
= \EE\left[ \Ab_{p,p}^2 \ub_p^{2n+4} \right] 
\stackrel{\eqref{eq:Eu}}{=} 
\begin{cases}
3 \Ab_{p,p}^2\qquad &n = 0\\
15 \Ab_{p,p}^2\qquad &n = 1\\
105 \Ab_{p,p}^2\qquad &n = 2
\end{cases}.
\end{align*}

Thus, when $n = 0$, we can obtain that
\begin{align*}
\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \right)^2 \right]
=& 
\sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j}
+ \sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j}
+ \sum_{i\neq  p} \Ab_{p,p} \Ab_{i,i}
+ 3 \sum_{i\neq p}^{d} \Ab_{i,i}^2
+ 3 \Ab_{p,p}^2\\
=&
\sum_{i=1, j=1}^d \Ab_{i,i} \Ab_{j,j} + 2\sum_{i\neq p}^{d} \Ab_{i,i}^2 + 2\Ab_{p,p}^2\\
=&
\Big(\tr(\Ab)\Big)^2 + 2 \sum_{i=1}^{d} \Ab_{i,i}^2.
\end{align*}

When $n = 1$, we can obtain that
\begin{align*}
\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p\right)^2 \right]
=& 
\sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j} 
+ 3 \sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j}
+ 3 \sum_{i\neq  p} \Ab_{p,p} \Ab_{i,i}
+ 3 \sum_{i\neq p}^{d} \Ab_{i,i}^2
+ 15 \Ab_{p,p}^2\\
=&
\sum_{i=1, j=1}^d \Ab_{i,i} \Ab_{j,j}
+ 2 \sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j}
+ 2 \sum_{i\neq  p} \Ab_{p,p} \Ab_{i,i}
+ 2 \sum_{i\neq p}^{d} \Ab_{i,i}^2
+ 14 \Ab_{p,p}^2\\
=&
\Big(\tr(\Ab)\Big)^2 + 4 \Ab_{p,p} \tr(\Ab) + 2 \sum_{i=1}^{d} \Ab_{i,i}^2 + 8 \Ab_{p,p}^2.
\end{align*}

When $n = 2$, we obtain that
\begin{align*}
\EE\left[ \left(  \sum_{i=1}^{d} \Ab_{i,i} \ub_i^2 \ub_p^2\right)^2 \right]
=& 3 \sum_{i\neq j\neq p} \Ab_{i,i} \Ab_{j,j}  
+  15 \sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j} + 15 \sum_{i\neq  p} \Ab_{p,p} \Ab_{i,i} 
+ 9 \sum_{i\neq p}^{d} \Ab_{i,i}^2 + 105 \Ab_{p,p}^2\\
=& 3 \sum_{i=1, j=1}^d \Ab_{i,i} \Ab_{j,j}  + 6 \sum_{i\neq p}^{d} \Ab_{i,i}^2 + 12  \sum_{j\neq  p} \Ab_{p,p} \Ab_{j,j} + 12 \sum_{i\neq  p} \Ab_{p,p} \Ab_{i,i} + 102 \Ab_{p,p}^2\\
=& 3 \Big(\tr(\Ab)\Big)^2 + 6 \sum_{i=1}^{d} \Ab_{i,i}^2 + 24 \Ab_{p,p} \cdot \tr(\Ab) + 72 \Ab_{p,p}^2.
\end{align*}
\end{proof}

\subsection{Bound of Second Term}

We will decompose the second term of the right hand of Eq.~\eqref{eq:uAu} in Lemma~\ref{lem:decom}. 
First, we provide the following lemma.
\begin{lemma}
\label{lem:sqr}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{align*}
\EE\left[ \left(  \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right] 
=&
\EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]\\
\EE\left[ \left(  \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right] 
=&
\EE\left[  \sum_{i<j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right].
\end{align*}
\end{lemma}
\begin{proof}
We have
\begin{align*}
&\EE\left[ \left(  \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right] 
=\EE\left[\sum_{i>j}^{d} \sum_{k>\ell}^{d} \Ab_{i,j} \Ab_{k,\ell}  \ub_i\ub_j \ub_k\ub_\ell \ub_p^{2n} \right] \\
=&  \EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right] 
+\EE\left[ \sum_{i> j,\; k=i,\; \ell \neq j,\; k>\ell} \Ab_{i,j} \Ab_{k,\ell} \ub_i\ub_j \ub_k\ub_\ell \ub_p^{2n} \right] \\
&+\EE\left[ \sum_{i> j,\; k\neq i,\; \ell = j,\;k>\ell} \Ab_{i,j} \Ab_{k,\ell} \ub_i\ub_j \ub_k\ub_\ell \ub_p^{2n} \right] 
+\EE\left[ \sum_{i> j,\; k\neq i,\; \ell \neq j,\; k>\ell} \Ab_{i,j} \Ab_{k,\ell} \ub_i\ub_j \ub_k\ub_\ell \ub_p^{2n} \right]\\
&
+ \EE\left[ \sum_{i>j,\; k> \ell,\; i = \ell} \Ab_{i,j} \Ab_{k,\ell} \ub_i \ub_j\ub_k \ub_\ell \ub_p^{2n} \right]
+ \EE\left[ \sum_{i>j,\; k >\ell,\; j = k} \Ab_{i,j}\Ab_{k,\ell} \ub_i \ub_j^2 \ub_\ell \ub_p^{2n} \right].
\end{align*}
We also have 
\begin{align*}
\EE\left[ \sum_{i> j,\; k=i,\; \ell \neq j,\;k>\ell} \Ab_{i,j} \Ab_{k,\ell} \ub_i\ub_j \ub_k\ub_\ell \ub_p^{2n} \right]
=
\sum_{i> j,\; k=i\; \ell \neq j,\;k>\ell} \Ab_{i,j} \Ab_{i,\ell} \EE\left[  \ub_i^2 \ub_j \ub_\ell \ub_p^{2n} \right] 
=
0,
\end{align*}
where the last equality is because of $\ell \neq j$ and Eq.~\eqref{eq:zero}.

Similarly, we can obtain 
\begin{align*}
\EE\left[ \sum_{i> j,\; k\neq i\; \ell = j,\;k>\ell} \Ab_{i,j} \Ab_{k,\ell} \ub_i\ub_j \ub_k\ub_\ell \ub_p^{2n} \right]
=&
\sum_{i> j,\; k\neq i\; \ell = j,\;k>\ell} \Ab_{i,j} \Ab_{k,\ell} \EE\left[  \ub_i\ub_j^2 \ub_k \ub_p^{2n} \right]
= 0,\\
\EE\left[ \sum_{i>j,\; k> \ell,\; i = \ell} \Ab_{i,j} \Ab_{k,\ell} \ub_i \ub_j\ub_k \ub_\ell \ub_p^{2n} \right] 
=&
\sum_{i>j,\; k> \ell,\; i = \ell}\EE\left[  \Ab_{i,j} \Ab_{k,\ell} \ub_i^2 \ub_j\ub_k \ub_p^{2n} \right]
=0, \\
\EE\left[ \sum_{i>j,\; k >\ell,\; j = k} \Ab_{i,j}\Ab_{k,\ell} \ub_i \ub_j\ub_k \ub_\ell \ub_p^{2n} \right]
=& 
\sum_{i>j,\; k >\ell,\; j = k}\EE\left[  \Ab_{i,j}\Ab_{k,\ell} \ub_i \ub_j^2 \ub_\ell \ub_p^{2n} \right]
= 0.
\end{align*}
We also have
\begin{align*}
\EE\left[ \sum_{i> j,\; k\neq i,\; \ell \neq j,\; k>\ell} \Ab_{i,j} \Ab_{k,\ell} \ub_i\ub_j \ub_k\ub_\ell \ub_p^{2n} \right]
=
\sum_{i> j,\; k\neq i,\; \ell \neq j,\; k>\ell}
\EE\left[ \Ab_{i,j} \Ab_{k,\ell} \ub_i\ub_j \ub_k\ub_\ell \ub_p^{2n} \right]
= 
0.
\end{align*}

Thus, we can obtain that
\begin{equation*}
\EE\left[ \left(  \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right] 
=
\EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]. 
\end{equation*}

Similarly, we can obtain that
\begin{equation*}
\EE\left[ \left(  \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right] 
=
\EE\left[  \sum_{i<j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right].
\end{equation*}
\end{proof}

\begin{lemma}\label{lem:decom}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{equation}\label{eq:Auup}
\begin{aligned}
\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right]
=&
\EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]
+ \EE\left[  \sum_{i<j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]\\
& 
+ 2\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \cdot \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n  \right].	
\end{aligned}
\end{equation}
\end{lemma}
\begin{proof}
We have
\begin{align*}
&\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right] 
= 
\EE\left[ \left( \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n  + \sum_{i < j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right]\\
=& 
\EE\left[  \left(  \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2  \right] 
+ \EE\left[  \left(  \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2  \right]\\
&+ 2\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \cdot \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n  \right]\\
=& \EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right] 
+ \EE\left[  \sum_{i<j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]
+ 2\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \cdot \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n  \right], 
\end{align*}
where the last equality is because of Lemma~\ref{lem:sqr}.
\end{proof}

Next, we will bound three terms in the right hand of Eq.~\eqref{eq:Auup}.
\begin{lemma}
\label{lem:A_ij}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{align}
\EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]
=& 
\begin{cases}
\sum_{i>j}^{d} \Ab_{i,j}^2  \qquad &n=0 \\
\sum_{i>j}^{d} \Ab_{i,j}^2
+ 2 \sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ 2 \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2 \qquad & n = 1\\
3 \sum_{i>j}^{d} \Ab_{i,j}^2 
+ 12 \sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ 12 \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2 \qquad &n=2
\end{cases}
\label{eq:A_ij}\\
\EE\left[  \sum_{i<j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right] 
=& 
\begin{cases}
\sum_{i<j}^{d} \Ab_{i,j}^2  \qquad &n=0 \\
\sum_{i<j}^{d} \Ab_{i,j}^2
+ 2 \sum_{i<j,  j= p}^{d} \Ab_{i,p}^2 
+ 2 \sum_{i<j,  i= p}^{d} \Ab_{p,j}^2 \qquad & n = 1\\
3 \sum_{i<j}^{d} \Ab_{i,j}^2 
+ 12 \sum_{i<j,  j= p}^{d} \Ab_{i,p}^2 
+ 12 \sum_{i<j,  i= p}^{d} \Ab_{p,j}^2 \qquad & n=2
\end{cases}.
\end{align}
\end{lemma}
\begin{proof}
First, we have
\begin{equation}\label{eq:EE}
\begin{aligned}
&\EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right] \\
=& 
\EE\left[  \sum_{i>j, i\neq p, j\neq p}^{d} \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]
+
\EE\left[  \sum_{i>j,  j= p}^{d} \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right] 
+ \EE\left[  \sum_{i>j,  i= p}^{d} \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]\\
=&
\sum_{i>j, i\neq p, j\neq p}^{d} \Ab_{i,j}^2 \EE\left[\ub_i^2\right] \EE\left[\ub_j^2\right] \EE\left[\ub_p^{2n}\right]
+ \sum_{i>p,  j= p}^{d} \Ab_{i,p}^2 \EE\left[   \ub_i^2  \right] \EE\left[\ub_p^{2n+2}\right] 
+ \sum_{p>j,  i= p}^{d} \Ab_{p,j}^2 \EE\left[   \ub_j^2  \right] \EE\left[\ub_p^{2n+2}\right].
\end{aligned}	
\end{equation}
When $n = 0$, by Eq.~\eqref{eq:Eu}, Eq.~\eqref{eq:EE} reduces to
\begin{align*}
\sum_{i>j, i\neq p, j\neq p}^{d} \Ab_{i,j}^2
+\sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2
=
\sum_{i>j}^{d} \Ab_{i,j}^2.
\end{align*}

When $n = 1$, by Eq.~\eqref{eq:Eu}, Eq.~\eqref{eq:EE} reduces to
\begin{align*}
\sum_{i>j, i\neq p, j\neq p}^{d} \Ab_{i,j}^2
+3\sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ 3\sum_{i>j,  i= p}^{d} \Ab_{p,j}^2
=
\sum_{i>j}^{d} \Ab_{i,j}^2
+ 2 \sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ 2 \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2.
\end{align*}

When $n = 2$, by Eq.~\eqref{eq:Eu}, Eq.~\eqref{eq:EE} reduces to 
\begin{align*}
&3 \sum_{i>j, i\neq p, j\neq p}^{d} \Ab_{i,j}^2  
+ 15 \sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ 15 \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2 \\
=& 
3 \sum_{i>j}^{d} \Ab_{i,j}^2 
+ 12 \sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ 12 \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2.
\end{align*}

Combining above results, we can obtain
\begin{equation*}
\EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right]
= 
\begin{cases}
\sum_{i>j}^{d} \Ab_{i,j}^2  \qquad &n=0 \\
\sum_{i>j}^{d} \Ab_{i,j}^2
+ 2 \sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ 2 \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2 \qquad & n = 1\\
3 \sum_{i>j}^{d} \Ab_{i,j}^2 
+ 12 \sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
+ 12 \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2 \qquad &n=2
\end{cases}.
\end{equation*}

Similarly, we can obtain that
\begin{align*}
\EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^{2n} \right] 
= 
\begin{cases}
\sum_{i<j}^{d} \Ab_{i,j}^2  \qquad &n=0 \\
\sum_{i<j}^{d} \Ab_{i,j}^2
+ 2 \sum_{i<j,  j= p}^{d} \Ab_{i,p}^2 
+ 2 \sum_{i<j,  i= p}^{d} \Ab_{p,j}^2 \qquad & n = 1\\
3 \sum_{i<j}^{d} \Ab_{i,j}^2 
+ 12 \sum_{i<j,  j= p}^{d} \Ab_{i,p}^2 
+ 12 \sum_{i<j,  i= p}^{d} \Ab_{p,j}^2 \qquad & n=2
\end{cases}.
\end{align*}
\end{proof}

\begin{lemma}
\label{lem:cross}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
\begin{align*}
&\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \cdot \sum_{k< \ell}^{d} \Ab_{k,\ell} \ub_k\ub_\ell \ub_p^n  \right] \\
=&
\begin{cases}
\sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} \qquad &n=0\\
\sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} 
+ 2 \sum_{i>j,  j= p}^{d} \Ab_{i,p} \Ab_{p,i} 
+ 2 \sum_{i>j,  i= p}^{d} \Ab_{p,j} \Ab{j,p}  \qquad & n=1 \\
3 \sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} 
+ 12 \sum_{i>j,  j= p}^{d} \Ab_{i,p} \Ab_{p,i} 
+ 12 \sum_{i>j,  i= p}^{d} \Ab_{p,j} \Ab{j,p} \qquad &n=2
\end{cases}.
\end{align*}
\end{lemma}
\begin{proof}
First, we have
\begin{align*}
&\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^2 \cdot \sum_{k< \ell}^{d} \Ab_{k,\ell} \ub_k\ub_\ell \ub_p^2  \right]\\
=&
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k =j,\; \ell = i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n}\right]
+ 
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k \neq j,\; \ell = i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right]\\
&
+\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k = j,\; \ell \neq i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right] 
+
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k \neq j,\; \ell \neq i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right]\\
&
+\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; j = \ell}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right]
+
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k = i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right].
\end{align*}
Then, we have
\begin{align*}
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k \neq j,\; \ell = i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right]
= \sum_{i>j}^{d} \sum_{k< \ell,\; k \neq j,\; \ell = i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \EE\left[ \ub_i^2 \ub_j    \ub_k \ub_p^{2n} \right]
= 0,
\end{align*}
where the last equality is because of Eq.~\eqref{eq:zero}.

Similarly, we can obtain that
\begin{align*}
&\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k = j,\; \ell \neq i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right]
=
\sum_{i>j}^{d} \sum_{k< \ell,\; k = j,\; \ell \neq i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \EE\left[\ub_i\ub_j^2 \ub_\ell \ub_p^{2n}\right] =0,\\
&
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k \neq j,\; \ell \neq i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right]
= \sum_{i>j}^{d} \sum_{k< \ell,\; k \neq j,\; \ell \neq i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \EE\left[ \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right] = 0,\\
&
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; j = \ell}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right]
=\sum_{i>j}^{d} \sum_{k< \ell,\; j = \ell}^{d} \Ab_{i,j}  \Ab_{k,\ell}
\EE\left[\ub_i \ub_j^2 \ub_k \ub_p^{2n}\right] =0,\\
&
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k = i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n} \right]
=\sum_{i>j}^{d} \sum_{k< \ell,\; k = i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \EE\left[ \ub_i^2 \ub_j \ub_\ell \ub_p^{2n} \right] =0.
\end{align*}

Thus, we can obtain that
\begin{align*}
&\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \cdot \sum_{k< \ell}^{d} \Ab_{k,\ell} \ub_k\ub_\ell \ub_p^n  \right]\\
=&
\EE\left[ \sum_{i>j}^{d} \sum_{k< \ell,\; k =j,\; \ell = i}^{d} \Ab_{i,j}  \Ab_{k,\ell} \ub_i  \ub_j    \ub_k\ub_\ell \ub_p^{2n}\right]\\
=& \EE\left[\sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} \ub_i^2\ub_j^2 \ub_p^{2n}\right].
\end{align*}

Define a matrix $\Bb\in\RR^{d\times d}$ with $\Bb_{i,j} = \Ab_{i,j} \Ab_{j,i}$.
Then, by Eq.~\eqref{eq:A_ij}, we can obtain that
\begin{align*}
\EE\left[  \sum_{i>j}^{d}  \Bb_{i,j} \ub_i^2\ub_j^2  \right]
=& 
\sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i},\\
\EE\left[  \sum_{i>j}^{d}  \Bb_{i,j} \ub_i^2\ub_j^2 \ub_p^2 \right]
=&
\sum_{i>j}^{d} \Bb_{i,j} 
+ 2 \sum_{i>j,  j= p}^{d} \Bb_{i,p} 
+ 2 \sum_{i>j,  i= p}^{d} \Bb_{p,j}\\
=&
\sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} 
+ 2 \sum_{i>j,  j= p}^{d} \Ab_{i,p} \Ab_{p,i} 
+ 2 \sum_{i>j,  i= p}^{d} \Ab_{p,j} \Ab{j,p}.
\end{align*}
and,
\begin{align*}
\EE\left[  \sum_{i>j}^{d}  \Bb_{i,j} \ub_i^2\ub_j^2 \ub_p^4 \right]
=& 
3 \sum_{i>j}^{d} \Bb_{i,j} 
+ 12 \sum_{i>j,  j= p}^{d} \Bb_{i,p} 
+ 12 \sum_{i>j,  i= p}^{d} \Bb_{p,j}\\
=& 
3 \sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} 
+ 12 \sum_{i>j,  j= p}^{d} \Ab_{i,p} \Ab_{p,i} 
+ 12 \sum_{i>j,  i= p}^{d} \Ab_{p,j} \Ab{j,p}.
\end{align*}
\end{proof}

Based on above lemmas, we will provide the explicit bounds of $\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^n \right)^2 \right]$ with $n = 0,1,2$ in the next lemmas.

\begin{lemma}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
	\begin{equation}\label{eq:Auu2}
		\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j  \right)^2 \right]
		= 
		\sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2.
	\end{equation}
\end{lemma}
\begin{proof}
	By Eq.~\eqref{eq:Auup} with $n = 0$, we can obtain that
	\begin{align*}
		\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j  \right)^2 \right]
		=
		\EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2  \right]
		+ \EE\left[  \sum_{i<j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2  \right]
		+ 2\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j  \cdot \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j   \right].	
	\end{align*}
	Combining with Lemma~\ref{lem:A_ij} and Lemma~\ref{lem:cross} wit $n=0$,
	we can obtain that
	\begin{align*}
		\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j  \right)^2 \right]
		= 
		\sum_{i>j}^{d}\Ab_{i,j}^2
		+ \sum_{i<j}^{d}\Ab_{i,j}^2 
		+ 2 \sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i}
		=
		\sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2.
	\end{align*}
\end{proof}

\begin{lemma}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
	\begin{equation}\label{eq:Auu3}
		\begin{aligned}
			\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p \right)^2 \right]
			=& 
			\sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
			+ 2 \sum_{i>j,  j= p}^{d}\Big(\Ab_{i,p} + \Ab_{p,i} \Big)^2\\
			&
			+ 2 \sum_{i>j,  i= p}^{d}\Big( \Ab_{p,j} + \Ab_{j,p} \Big)^2.
		\end{aligned}	
	\end{equation}
\end{lemma}
\begin{proof}
	By Eq.~\eqref{eq:Auup} with $n = 1$, we can obtain that
	\begin{align*}
		\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p \right)^2 \right]  
		\stackrel{\eqref{eq:Auup}}{=}& \EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^2 \right] 
		+ \EE\left[  \sum_{i<j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^2 \right]\\
		&
		+ 2\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p \cdot \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p  \right]. 
	\end{align*}
	Combining with Lemma~\ref{lem:A_ij} and Lemma~\ref{lem:cross} wit $n=1$,
	we can obtain that
	\begin{align*}
		&\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p \right)^2 \right]\\  
		=&	
		\sum_{i>j}^{d} \Ab_{i,j}^2
		+ 2 \sum_{i>j,  j= p}^{d} \Ab_{i,p}^2 
		+ 2 \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2\\
		&
		+ \sum_{i<j}^{d} \Ab_{i,j}^2
		+ 2 \sum_{i<j,  j= p}^{d} \Ab_{i,p}^2 
		+ 2 \sum_{i<j,  i= p}^{d} \Ab_{p,j}^2\\
		&
		+2\sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} 
		+ 4 \sum_{i>j,  j= p}^{d} \Ab_{i,p} \Ab_{p,i} 
		+ 4 \sum_{i>j,  i= p}^{d} \Ab_{p,j} \Ab{j,p}\\
		=&
		\sum_{i>j}^{d} \Big(\Ab_{i,j}^2 + \Ab_{j,i}^2 + 2\Ab_{i,j}\Ab_{j,i}\Big)
		+ 2 \sum_{i>j,  j= p}^{d} \Big( \Ab_{i,p}^2 + \Ab_{p,i}^2 + 2\Ab_{i,p} \Ab_{p,i}  \Big)\\
		&
		+ 2 \sum_{i>j,  i= p}^{d} \Big( \Ab_{p,j}^2 + \Ab_{j,p}^2 + 2\Ab_{j,p} \Ab_{p,j}  \Big)\\
		=&
		\sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
		+ 2 \sum_{i>j,  j= p}^{d}\Big(\Ab_{i,p} + \Ab_{p,i} \Big)^2
		+ 2 \sum_{i>j,  i= p}^{d}\Big( \Ab_{p,j} + \Ab_{j,p} \Big)^2.
	\end{align*}
\end{proof}

\begin{lemma}
Given a matrix $\Ab\in\RR^{d\times d}$ and a random Gaussian vector $\ub\sim \cN(\bm{0}, \I_d)$, and an integer $1\leq p\leq d$, then it holds that
	\begin{equation}\label{eq:Auu}
		\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^2 \right)^2 \right] 
		= 3 \sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
		+ 12 \sum_{i>j,  j= p}^{d} \Big(\Ab_{i,p} + \Ab_{p,i}\Big)^2
		+ 12 \sum_{i>j, i=p}^{d} \Big(\Ab_{p,j} + \Ab_{j, p}\Big)^2.
	\end{equation}
\end{lemma}
\begin{proof}
	First, by Eq.~\eqref{eq:Auup} with $n = 2$, we have
	\begin{align*}
		\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^2 \right)^2 \right]  
		\stackrel{\eqref{eq:Auup}}{=}& \EE\left[  \sum_{i>j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^4 \right] 
		+ \EE\left[  \sum_{i<j}^{d}  \Ab_{i,j}^2 \ub_i^2\ub_j^2 \ub_p^4 \right]\\
		&
		+ 2\EE\left[ \sum_{i> j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^2 \cdot \sum_{i< j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^2  \right]. 
	\end{align*}
	Then, combining with Lemma~\ref{lem:A_ij} and Lemma~\ref{lem:cross} wit $n=2$, we can obtain that
	\begin{align*}
		\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^2 \right)^2 \right]
		=& 3 \left( \sum_{i>j}^{d} \Ab_{i,j}^2 + \sum_{i<j}^{d} \Ab_{i,j}^2 +  2\sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} \right)\\
		&+ 12 \left(\sum_{i>j,  j= p}^{d} \Ab_{i,p}^2  +  \sum_{i<j,  i= p}^{d} \Ab_{p,j}^2 + 2 \sum_{i>j,  j= p}^{d} \Ab_{i,p} \Ab_{p,i} \right)\\
		&+12 \left( \sum_{i>j,  i= p}^{d} \Ab_{p,j}^2 + \sum_{i<j,  j= p}^{d} \Ab_{i,p}^2 +  2\sum_{i>j,  i= p}^{d}\Ab_{p,j} \Ab{j,p} \right).
	\end{align*}

	Furthermore, it holds that
	\begin{align*}
		\sum_{i>j}^{d} \Ab_{i,j}^2 + \sum_{i<j}^{d} \Ab_{i,j}^2 +  2\sum_{i>j}^{d} \Ab_{i,j} \Ab_{j,i} 
		= \sum_{i>j}^{d} \left( \Ab_{i,j}^2 +  \Ab_{j,i}^2 + 2 \Ab_{i,j} \Ab_{j,i}  \right)
		= \sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2.
	\end{align*}
	Similarly, we have
	\begin{align*}
		&\sum_{i>j,  j= p}^{d} \Ab_{i,p}^2  +  \sum_{i<j,  i= p}^{d} \Ab_{p,j}^2 + 2 \sum_{i>j,  j= p}^{d} \Ab_{i,p} \Ab_{p,i}\\
		=& 
		\sum_{i>j,  j= p}^{d} \left(\Ab_{i,p}^2 + \Ab_{p,i}^2 + 2\Ab_{i,p} \Ab_{p,i}\right)
		= \sum_{i>j,  j= p}^{d} \Big(\Ab_{i,p} + \Ab_{p,i}\Big)^2,
	\end{align*}
	and
	\begin{align*}
		&\sum_{i>j,  i= p}^{d} \Ab_{p,j}^2 + \sum_{i<j,  j= p}^{d} \Ab_{i,p}^2 +  2\sum_{i>j,  i= p}^{d}\Ab_{p,j} \Ab{j,p}\\
		=& 
		\sum_{i>j, i=p}^{d} \left(\Ab_{p,j}^2 + \Ab_{j, p}^2 + 2\Ab_{p,j} \Ab{j,p}\right)
		= 
		\sum_{i>j, i=p}^{d} \Big(\Ab_{p,j} + \Ab_{j, p}\Big)^2.
	\end{align*}

	Thus, we can obtain that
	\begin{align*}
		\EE\left[ \left(  \sum_{i\neq j}^{d} \Ab_{i,j} \ub_i\ub_j \ub_p^2 \right)^2 \right] 
		= 3 \sum_{i>j}^{d} \Big(\Ab_{i,j} + \Ab_{j,i}\Big)^2
		+ 12 \sum_{i>j,  j= p}^{d} \Big(\Ab_{i,p} + \Ab_{p,i}\Big)^2
		+ 12 \sum_{i>j, i=p}^{d} \Big(\Ab_{p,j} + \Ab_{j, p}\Big)^2.
	\end{align*}

\end{proof}

