The relevance of separating and enclosing vectors arises from the following observation. Each $v \in \mathbb{R}^{n}$ and $x \in \mathbb{R}^{n}_{>0}$ induce a univariate signomial 
\begin{align}
\label{Eq_InducedSignomial} 
\mathbb{R}_{>0} \to \mathbb{R}, \quad t \mapsto f(t^v \ast x) = \sum_{\mu \in \sigma(f)} c_\mu x^\mu t^{v \cdot \mu}.
\end{align}
If $v$ is a separating (resp. enclosing) vector, then $f(t^v \ast x)$, viewed as a signomial in $t$, has  at most one (resp. two) sign changes in its coefficient sequence.

Recall that a coefficient of a univariate signomial $g$ is called the \emph{leading coefficient} $\LC(g)$ (resp. \emph{trailing coefficient} $\SC(g)$) if the corresponding exponent is the largest (resp. smallest). 


\begin{ex}
Let $f$ be the signomial in \eqref{Eq_Example2} and let $A,B \subseteq \sigma(f)$ as given in Example \ref{Ex::ExRunning}. For fixed $x \in \mathbb{R}^{n}_{>0}$, the induced univariate signomials as in \eqref{Eq_InducedSignomial} equal
\begin{align*}
 f(t^1 x, t^0 y) &= (-101x^3 y^2)t^3 + (51x^2 -x^2y + 50x^2y^3 )t^2+xy^3 t^1 + y^4 - 9.5y^3+30.5y^2 - 37y +12,\\
f_{|A}(t^1 x, t^0 y) &= (-101x^3 y^2)t^3 + (51x^2 -x^2y + 50x^2y^3 )t^2+xy^3 t^1 + y^4 +30.5y^2  +12,\\
f_{|B}(t^{-1} x, t^0 y) &=     y^4 - 9.5y^3+30.5y^2 - 37y +12   +xy^3 t^{-1} +   (51x^2+ 50x^2y^3 )t^{-2}.
 \end{align*}

The leading coefficient of $f_{|A}(t^1 x, t^0 y)$ is $-101x^3 y^2$, which is negative for all $(x,y) \in \mathbb{R}_{>0}^2$. This phenomenon always happens. If $v$ is a strict separating vector of $\sigma(f)$, then the leading coefficient of the induced signomial in \eqref{Eq_InducedSignomial} is negative. On the contrary, this might not be true for non-strict separating vectors. For example, we have
 \begin{align*}
 & \LC(f_{|B}(t^{-1} x, t^0 y)) =  y^4 - 9.5y^3+30.5y^2 - 37y +12 < 0,  & &\text{ if }  y^4 - 9.5y^3+30.5y^2 - 37y +12 < 0, \\
 & \LC(f_{|B}(t^{-1} x, t^0 y))  = xy^3 > 0,  & &\text{ if }  y^4 - 9.5y^3+30.5y^2 - 37y +12 = 0, \\
  & \LC(f_{|B}(t^{-1} x, t^0 y)) =  y^4 - 9.5y^3+30.5y^2 - 37y +12 > 0, & &\text{ if }  y^4 - 9.5y^3+30.5y^2 - 37y +12 > 0.
 \end{align*}
\end{ex}

If $\LC(g) < 0$ (resp. $\SC(g) <0$), then $g$ attains negative values for large (resp. small) enough $t \in \mathbb{R}_{>0}$. This simple observation and the univariate Descartes' rule of signs give the following statement.

\begin{lemma}
\label{Lemma_UniSignchanges}
Let $g\colon \mathbb{R}_{>0} \to \mathbb{R}, \, g(t) = \sum_{i = 1}^{d} a_i t^{\nu_i}$ be a univariate signomial such that $g(1) < 0$.
\begin{itemize}
\item[(i)] If $\LC(g) < 0$ and $g$ has at most one sign change in its coefficient sign sequence, then $g(t) <0$ for all $t\geq 1$.
\item[(ii)] If $\SC(g) < 0$ and $g$ has at most one sign change in its coefficient sign sequence, then $g(t) <0$ for all $t\leq 1$.
\item[(iii)] If $g$ has at most two sign changes in its coefficient sign sequence and $\LC(g) < 0$ or $\SC(g) < 0,$ then $g(t) <0$ for all $t\leq 1$ or $g(t) <0$ for all $t\geq 1$.
\end{itemize}
\end{lemma}

Lemma \ref{Lemma_UniSignchanges} played a crucial role in the proof of the following theorems in \cite{DescartesHypPlane}.


\begin{thm}
\label{Thm::FirstDescartes}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$  be a signomial. 
\begin{itemize}
\item[(i)] If there exists a strict separating hyperplane of $\sigma(f)$, then $f^{-1}( \mathbb{R}_{<0})$ is non-empty and contractible  \cite[Theorem 3.6]{DescartesHypPlane}.
\item[(ii)] If there exists a pair of strict enclosing hyperplanes of $\sigma_+(f)$, then $b_0(f^{-1}( \mathbb{R}_{<0})) \leq 2$ \cite[Theorem 3.8]{DescartesHypPlane}.
\item[(iii)] If $f$ has at most one negative coefficient, then $f^{-1}(\mathbb{R}_{<0})$ is either empty or logarithmically convex \cite[Theorem 3.4]{DescartesHypPlane}.
\end{itemize}
\end{thm}

In addition to Theorem \ref{Thm::FirstDescartes}, another condition on the signed support of the signomial $f$ implying that $f$ has at most one negative connected component, is that the negative and positive exponent vectors of $f$ are separated by a simplex and its negative vertex cones \cite[Theorem 4.6]{DescartesHypPlane}. We postpone recalling this result to Section \ref{Section::OneNegCC} and continue with investigating separating and enclosing hyperplanes.

\subsection{Non-strict separating and non-strict enclosing hyperplanes}
\label{Section::NonStrict}
In the following propositions, we investigate what happens when $\sigma(f)$ (resp. $\sigma_+(f)$) has a separating (resp. enclosing) hyperplane that is not necessarily strict. In these cases, a bound on $b_0(f^{-1}( \mathbb{R}_{<0}))$ is given by the number of negative connected components of restrictions of $f$ to certain subsets of $\sigma(f)$. These technical statements serve as the core part of the proofs in Section \ref{Section::OneNegCC} and Section \ref{Section::NegAndParaFaces}.

The first such statement considers subsets of the support containing all negative exponent vectors and those positive exponent vectors which lie on the separating hyperplane.

  \begin{prop}
\label{Prop_NonStrictSepHyp}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$  be a signomial whose support has a separating hyperplane $\mathcal{H}_{v,a}$. For any subset $R \subseteq \sigma(f)$ such that $\sigma_-(f) \subseteq R$ and $\mathcal{H}_{v,a}  \cap \sigma_+(f) \subseteq R$, we have:
\begin{itemize}
\item[(i)] For all $U \in \mathcal{B}_0^-(f_{|R})$, there exists a unique $V \in  \mathcal{B}_0^-(f)$ such that $U \cap f^{-1}(\mathbb{R}_{<0}) \subseteq V$.
\item[(ii)] The map
\begin{align*}
\phi \colon  \mathcal{B}_0^-(f_{|R})  \to  \mathcal{B}_0^-(f), \quad U \mapsto 
      \begin{array}{l@{}}
        \text{connected component of $f^{-1}(\mathbb{R}_{<0})$} \\
        \text{that contains } U \cap f^{-1}(\mathbb{R}_{<0}) 
      \end{array}
\end{align*}
is well defined and bijective. In particular, it holds
\begin{align*}
 b_0 ( f_{|R}^{-1}(\mathbb{R}_{<0}) ) = b_0 ( f^{-1}(\mathbb{R}_{<0}) ).
\end{align*}
\end{itemize}
\end{prop}

Before giving the proof of Proposition \ref{Prop_NonStrictSepHyp}, we illustrate the idea behind it by the following example.

\begin{ex}
\label{Ex::Proof24}
The hyperplane $\mathcal{H}_{v,1}$ with $v=(1,0)$ is a separating hyperplane of the support~of
\[ f = 1+ x_1 + x_2 - 4x_1 x_2+ x_1  x_2^2.\]
The set $R = \{(1,1), (1,0),(0,1),(1,2)\}$ satisfies the assumptions in Proposition  \ref{Prop_NonStrictSepHyp}. If $x,y \in f^{-1}(\mathbb{R}_{<0})$ lie in the same connected component of $f_{|R}^{-1}(\mathbb{R}_{<0})$, then there exists a continuous path $\gamma\colon [0,1] \to \mathbb{R}^n_{>0}$ with $\gamma(0) = x, \, \gamma(1) = y$ and the paths 
\[\gamma_{v,x} \colon [0,1] \to \mathbb{R}^n_{>0}, \, t \mapsto t^v \ast x, \qquad \gamma_{v,y} \colon [0,1] \to \mathbb{R}^n_{>0}, \, t \mapsto t^v \ast y\]
are contained in $f^{-1}(\mathbb{R}_{<0})$. Using $v$, we push the path $\gamma$ such that its image becomes a subset of $ f^{-1}(\mathbb{R}_{<0})$. More precisely, we consider the path 
\[\tilde{\gamma}\colon [0,1] \to \mathbb{R}^n_{>0}, \quad s \mapsto t_0^v\ast \gamma(s)\]
for a fixed large enough $t_0 > 0$, see Figure \ref{FIG2_new}(b). Concatenating the paths $\tilde{\gamma}, \, \gamma_{v,x} \, \gamma_{v,y}$, we obtain a path between $x$ and $y$ in $f^{-1}(\mathbb{R}_{<0})$. Thus, $x$ and $y$ are contained in the same connected component of $f^{-1}(\mathbb{R}_{<0})$. We will use this observation to prove part (i) of Proposition \ref{Prop_NonStrictSepHyp}.

For $x_1,x_2 \in f^{-1}_{|R}(\mathbb{R}_{<0})$, if $t_0^{v} \ast x_1$ and $t_0^{v} \ast x_2$ are in the same connected component of $f^{-1}(\mathbb{R}_{<0})$ for some $t_0 >0$, then $x_1, x_2$ lie in the same connected component of  $f^{-1}_{|R}(\mathbb{R}_{<0})$, see Figure \ref{FIG2_new}(c). This fact will be used in the proof of Proposition \ref{Prop_NonStrictSepHyp} to show injectivity of the map~$\phi$.
\end{ex}


