\begin{proof}[Proof of Proposition \ref{Prop_NonStrictSepHyp}]
First observe that
\begin{align}
\label{Eq_fFcontf}
f^{-1}(\mathbb{R}_{<0} ) \subseteq f_{|R}^{-1}(\mathbb{R}_{<0} ),
\end{align}
because $f_{|R}(x) \leq f(x)$ for all $x \in \mathbb{R}^{n}_{>0}$.

If $\sigma_+(f)  \subseteq R$, then $R = \sigma(f)$ and we are done. So we assume that there exists $\alpha_0 \in \sigma_+(f)$ such that $\alpha_0 \notin \mathcal{H}_{v,a}$. Since $\mathcal{H}_{v,a}$ is a separating hyperplane of $\sigma(f)$, we have
\begin{align}
\label{Eq::ProofProp_NonStrictSepHyp}
  v \cdot \beta  \geq  a \geq v \cdot \alpha \qquad \text{for all }  \beta \in \sigma_-(f), \,\alpha \in \sigma_+(f) \qquad \text{and} \quad a > v \cdot \alpha_0.
 \end{align}

For $x \in \mathbb{R}^{n}_{>0}$ , consider the path
\[ \gamma_{v,x}\colon [1,\infty) \to \mathbb{R}^n_{>0}, \quad t \mapsto t^v \ast x \]
and the univariate signomial  $f(t^v \ast x)$ as in $\eqref{Eq_InducedSignomial}$. Note that $f(\gamma_{v,x}(t)) =  f(t^v \ast x)$ for all $t \geq 1$.

If $v$ is a strict separating vector of $\sigma(f)$, then $f(t^v \ast x)$ has a negative leading coefficient. If $v$ is not strict, then 
\[ \LC( f(t^v\ast x)) = f_{|\mathcal{H}_{v,a}}(x) \quad \text{and} \quad f_{|R}(x) =  f_{|\mathcal{H}_{v,a}}(x) + \sum_{\alpha \in \sigma_+(f) \cap R \cap \mathcal{H}^{-,\circ}_{v,a}} c_\alpha x^\alpha. \]
Thus, if $f_{|R}(x) <0$, then  $ \LC( f(t^v\ast x)) < 0$.

By \eqref{Eq::ProofProp_NonStrictSepHyp},  $f(t^v\ast x)$ and $f_{|R}(t^v\ast x)$ have at most one sign change in their coefficient sign sequence. By Lemma \ref{Lemma_UniSignchanges}(i), we have:
\begin{align}
\label{Eq_ProofNegFace}
&\im \gamma_{v,x} \subseteq f^{-1}(\mathbb{R}_{<0}), & &\text{for all } x \in f^{-1}(\mathbb{R}_{<0}), \\
\label{Eq_ProofNegFace_ftilde}
 &\im \gamma_{v,x} \subseteq f_{|R}^{-1}(\mathbb{R}_{<0}) \quad \text{and} \quad  \gamma_{v,x}(t) \in f^{-1}(\mathbb{R}_{<0}), &  &\text{for all }  x \in f_{|R}^{-1}(\mathbb{R}_{<0}) < 0, \, t\gg 1.
\end{align}
This gives that each connected component of $f_{|R}^{-1}(\mathbb{R}_{<0})$ has a non-empty intersection with $f^{-1}(\mathbb{R}_{<0})$. For an illustration of the path $\gamma_{v,x}$ we refer to Figure \ref{FIG2_new}(b)(c).

To prove (i), let $U \in \mathcal{B}_0^-(f_{|R})$, $x,y \in U \cap f^{-1}(\mathbb{R}_{<0})$ and consider a continuous path 
\[ \gamma\colon [0,1] \to \mathbb{R}^{n}_{>0}\]
such that $\gamma(0) = x, \, \gamma(1) = y$ and $\gamma(s) \subseteq f_{|R}^{-1}(\mathbb{R}_{<0} )$ for all $s \in [0,1]$.

We construct now a path between $x$ and $y$ that is contained in $f^{-1}(\mathbb{R}_{<0})$. For a fixed $s \in [0,1]$, since $f_{|R}(\gamma(s)) <0$, and the signomial $f(t^v\ast \gamma(s))$ has exactly one sign change in its coefficient sign sequence, Descartes' rule of signs implies that $f(t^v\ast \gamma(s))$ has exactly one positive real root $\tau(s)$, which is simple. Now, the Implicit Function Theorem \cite{EDWARDS197356} implies that the function
\[\tau\colon [0,1] \to \mathbb{R}_{>0}, \quad s \mapsto \tau(s)\] 
is continuous. So $T := \max_{s \in [0,1]}\tau(s)$ exists and we have:
\[f(t_0^v\ast \gamma(s)) < 0 \qquad \text{for some } t_0 > \max\{1,T\} \text{ and all } s \in [0,1].\]
Thus, the path
\[  [0,1] \to \mathbb{R}^n_{>0}, \quad s \to t_0^v \ast \gamma(s) \]
connects $t_0^v \ast x$ and $t_0^v \ast y$, and is contained in  $f^{-1}(\mathbb{R}_{<0})$ (cf. Figure \ref{FIG2_new}(b)). By \eqref{Eq_ProofNegFace}, the paths $\gamma_{v,x}, \gamma_{v,y}$ are contained in $f^{-1}(\mathbb{R}_{<0})$ and join $x$ and $t_0 \ast x$, resp. $y$ and $t_0 \ast y$. Thus, if $x,y$ are in the same connected component of $f_{|R}^{-1}(\mathbb{R}_{<0})$, then they are also in the same connected component of $f^{-1}(\mathbb{R}_{<0})$, which gives (i).

By (i), the map $\phi$ is well defined. Now we show that $\phi$ is bijective. From \eqref{Eq_fFcontf}, it follows that every $W \in \mathcal{B}_0^{-}(f)$ lies in a connected component of  $f_{|R}^{-1}(\mathbb{R}_{<0} )$, which is a preimage of $W$ under $\phi$. Thus, $\phi$ is surjective.

To show injectivity of $\phi$, consider $U_1, U_2 \in \mathcal{B}_{0}^{-}(f_{|R})$ such that $\phi(U_1) = \phi(U_2)$ and let $x_1 \in U_1, x_2 \in U_2$. By \eqref{Eq_ProofNegFace_ftilde}
\begin{align*}
 \im \gamma_{v,x_1}  \subseteq f_{|R}^{-1}(\mathbb{R}_{<0}),  \quad  \im \gamma_{v,x_2} \subseteq f_{|R}^{-1}(\mathbb{R}_{<0}) \quad \text{and} \\
 \gamma_{v,x_1}(t_0) \in f^{-1}(\mathbb{R}_{<0}), \quad  \gamma_{v,x_2}(t_0) \in f^{-1}(\mathbb{R}_{<0}) \text{ for some } t_0\gg 1.
\end{align*}
Since $U_1 \cap f^{-1}(\mathbb{R}_{<0})$ and $U_2 \cap f^{-1}(\mathbb{R}_{<0})$ are in the same connected component of $f^{-1}(\mathbb{R}_{<0})$, there exists a continuous path $\gamma_3$ between $ \gamma_{v,x_1}(t_0)$ and $ \gamma_{v,x_2}(t_0)$ such that $\im \gamma_3 \subseteq f^{-1}(\mathbb{R}_{<0})$ (cf. Figure \ref{FIG2_new}(c)). By \eqref{Eq_fFcontf}, we have $\im \gamma_3  \subseteq f_{|R}^{-1}(\mathbb{R}_{<0})$. Thus,  $\gamma_{v,x_1}, \gamma_3$ and  $\gamma_{v,x_2}$ give a continuous path between $x_1$ and $x_2$ contained in $f_{|R}^{-1}(\mathbb{R}_{<0})$. Thus, $x,y$ lie in the same connected component of $f_{|R}^{-1}(\mathbb{R}_{<0})$, which implies that $U_1 = U_2$.
\end{proof}


In the following, we generalize the proof of Theorem \ref{Thm::FirstDescartes}(ii) to the case where the enclosing hyperplanes are not necessarily strict. To ease the reading of the proofs, we discuss first the notation we are going to use. Given a pair of enclosing hyperplanes $(\mathcal{H}_{v,a}, \mathcal{H}_{v,b})$ of $\sigma_+(f)$, we define
\begin{align}
\label{Eq::DefAB}
A = (\mathcal{H}^{+}_{v,a} \cap \sigma_-(f)) \cup \sigma_+(f), \qquad B = (\mathcal{H}^{-}_{v,b} \cap \sigma_-(f)) \cup \sigma_+(f). 
\end{align}
That is, both $A$ and $B$ contain all the positive exponent vectors of $f$. The set $A$ (resp. $B$) contains the negative exponent vectors from one (resp. the other) side of the area enclosed by the hyperplanes $\mathcal{H}_{v,a}, \mathcal{H}_{v,b}$. Note that by definition, $\mathcal{H}_{v,a}$ (resp $\mathcal{H}_{-v,-b}$) is a separating hyperplane of the support of the restricted signomials $f_{|A}$ (resp $f_{|B})$. If $(\mathcal{H}_{v,a}, \mathcal{H}_{v,b})$ is a pair of strict enclosing hyperplanes, then  $\mathcal{H}_{v,a}$ and $\mathcal{H}_{-v,-b}$ are  strict separating hyperplanes of $\sigma(f_{|A})$ and $\sigma(f_{|B})$ respectively. In this case, by Theorem \ref{Thm::FirstDescartes}(i) we have:
\begin{align}
\label{Eq:StrictEnclAB}
b_0\big( f_{|A}^{-1}(\mathbb{R}_{<0})\big) = 1, \qquad b_0\big( f_{|B}^{-1}(\mathbb{R}_{<0})\big) = 1.
\end{align}


\begin{ex}
\label{Ex:NewEx2}
For the signomial 
\[ f = 2 - 2 x_1^2 - 2 \, x_2^{2}  + 5 \, x_1 x_2  + x_1^{2} x_2^{2} -2 \, x_1^{3} x_2,\]
the pair of hyperplanes $(\mathcal{H}_{v,2},\mathcal{H}_{v,0})$ with $v=(1,0)$ is a pair of enclosing hyperplanes of $\sigma(f)$, see Figure~\ref{FIG3_new}(a). The sets $A,B$ from \eqref{Eq::DefAB} are given by
\begin{align*}
A &= (\mathcal{H}^{+}_{v,2} \cap \sigma_-(f)) \cup \sigma_+(f) =  \{ (2,0),(3,1),(2,2),(1,1),(0,0) \} \\ 
B &= (\mathcal{H}^{-}_{v,0} \cap \sigma_-(f)) \cup \sigma_+(f) =  \{ (0,2),(2,2),(1,1),(0,0) \}.
\end{align*}
 For fixed $x \in \mathbb{R}^{2}_{>0}$, the induced univariate signomials as in \eqref{Eq_InducedSignomial} equal
\begin{equation}
\label{Eq:NewExInduced}
\begin{aligned}
 f(t^1 x, t^0 y) &= -2 x_1^3x_2 t^3 + (x_1^2x_2^2-2x_1^2)t^2+5x_1x_2 t +(2-2x_2^2)\\
f_{|A}(t^1 x, t^0 y) &=  -2 x_1^3x_2 t^3 + (x_1^2x_2^2-2x_1^2)t^2+5x_1x_2 t +2\\
f_{|B}(t^{-1} x, t^0 y) &=    (2-2x_2^2) +5x_1x_2 t^{-1} +  x_1^2x_2^2 t^{-2} .
 \end{aligned}
 \end{equation}
 By construction, the signomials $f_{|A}(t^1 x, t^0 y),\, f_{|B}(t^{-1} x, t^0 y)$ have at most one sign change in their coefficient sequence. Using this, we will show in the proof of  Proposition \ref{Prop_StripBound0} that for any $x \in f^{-1}(\mathbb{R}_{<0})$ one of the paths
 \begin{align}
 \label{Eq::NewExPath}
  \gamma_v \colon[1,\infty) \to \mathbb{R}^n_{>0} , \quad t \mapsto t^v \ast x, \qquad \gamma_{-v} \colon[1,\infty) \to \mathbb{R}^n_{>0} , \quad t \mapsto t^{-v} \ast x
 \end{align}
 connects x to a point in $f^{-1}_{|A}(\mathbb{R}_{<0}) \cup f^{-1}_{|B}(\mathbb{R}_{<0})$, see Figure~\ref{FIG3_new}(b). One technical difficulty we must address in the proof of Proposition  \ref{Prop_StripBound0} is that the leading and trailing coefficients of induced signomials in \eqref{Eq:NewExInduced} depend on $x$. For example,
 \begin{align*}
  &   \SC(f(t^{1} x, t^0 y)) = \LC(f_{|B}(t^{-1} x, t^0 y))  = (2-2x_2^2) < 0,   &\SC(f_{|A}(t^{1} x, t^0 y)) = 2  \quad  &\text{ if } 2-2x_2^2 <  0, \\
 &   \SC(f(t^{1} x, t^0 y)) = \LC(f_{|B}(t^{-1} x, t^0 y))  = 5 x_1 x_2 > 0,   &\SC(f_{|A}(t^{1} x, t^0 y)) = 2  \quad &\text{ if } 2-2x_2^2 = 0. \\
 \end{align*}
\end{ex}



