 In the next proposition, we consider subsets $R \subseteq A$, $S \subseteq B$ such that $f_{|A}$  and $R$ (resp. $f_{|B}$ and $S$) satisfy the hypothesis of Proposition \ref{Prop_NonStrictSepHyp}.

\begin{prop}
\label{Prop_StripBound0}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$  be a signomial and $(\mathcal{H}_{v,a}, \mathcal{H}_{v,b})$ be a pair of enclosing hyperplanes of $\sigma_+(f)$. Let $A,B \subseteq \sigma(f)$ be as in \eqref{Eq::DefAB} and let $R \subseteq A, \, S \subseteq B$ such that 
\begin{itemize}
\item $R \cap \sigma_-(f) = A \cap \sigma_-(f), \qquad  \mathcal{H}_{v,a} \cap \sigma_+(f) \subseteq R$,
\item  $S \cap \sigma_-(f) = B \cap \sigma_-(f), \qquad  \mathcal{H}_{v,b} \cap \sigma_+(f) \subseteq S$.
\end{itemize}
 Then the map
\begin{align*}
\varphi \colon &\mathcal{B}_0^-(f_{|R}) \sqcup \mathcal{B}_0^-(f_{|S}) \to \mathcal{B}_0^-(f), \\
 U &\mapsto \begin{cases} 
 \text{ connected component of $f^{-1}( \mathbb{R}_{<0})$ that contains } U \cap f_{|A}^{-1}(\mathbb{R}_{<0}),  & \textrm{if } U \in \mathcal{B}_0^-(f_{|R}) , \\
\text{ connected component of $f^{-1}( \mathbb{R}_{<0})$ that contains }U \cap f_{|B}^{-1}(\mathbb{R}_{<0}), & \textrm{if } U \in \mathcal{B}_0^-(f_{|S }). \end{cases}
\end{align*}
is well defined and surjective. In particular, we have
\[ b_0\big( f^{-1}(\mathbb{R}_{<0} )\big) \leq  b_0\big( f_{|R }^{-1}(\mathbb{R}_{<0}) \big) +b_0\big( f_{|S }^{-1}(\mathbb{R}_{<0}) \big),\]
\end{prop}

\begin{proof}
The idea of the proof follows closely the arguments in \cite[Theorem 3.8]{DescartesHypPlane}. Since $f_{|A}$ and $f_{|B}$ are obtained by removing some of the monomials with negative coefficient from $f$, $f(x) \leq f_{|A}(x)$ and $f(x) \leq f_{|B}(x)$ for all $x \in \mathbb{R}^{n}_{>0}$. This implies:
\begin{align*}
f_{|A}^{-1}(\mathbb{R}_{<0}) \subseteq f^{-1}(\mathbb{R}_{<0}), \qquad \text{and} \qquad f_{|B}^{-1}(\mathbb{R}_{<0}) \subseteq f^{-1}(\mathbb{R}_{<0}).
\end{align*}
Thus, every connected component of $f_{|A}^{-1}(\mathbb{R}_{<0})$ and $f_{|B}^{-1}(\mathbb{R}_{<0})$ is contained in a unique connected component of $f^{-1}(\mathbb{R}_{<0}) $. By this observation, the map
\[ \psi\colon \mathcal{B}_0^-(f_{|A}) \sqcup \mathcal{B}_0^-(f_{|B}) \to \mathcal{B}_0^-(f), \quad V \mapsto \text{connected component of $f^{-1}(\mathbb{R}_{<0})$ that contains } V\]
is well defined.

From Proposition \ref{Prop_NonStrictSepHyp} applied to $f_{|A}$ and $R$ or $f_{|B}$ and $S$, it follows that the map
\begin{align*}
\phi \colon &\mathcal{B}_0^-(f_{|R}) \sqcup \mathcal{B}_0^-(f_{|S}) \to \mathcal{B}_0^-(f_{|A}) \sqcup \mathcal{B}_0^-(f_{|B}) , \\
 U &\mapsto \begin{cases} 
 \text{ connected component of $f_{|A}^{-1}( \mathbb{R}_{<0})$ that contains } U \cap f_{|A}^{-1}(\mathbb{R}_{<0}),  & \textrm{if } U \in \mathcal{B}_0^-(f_{|R}) , \\
\text{ connected component of $f_{|B}^{-1}( \mathbb{R}_{<0})$ that contains }U \cap f_{|B}^{-1}(\mathbb{R}_{<0}), & \textrm{if } U \in \mathcal{B}_0^-(f_{|S }). \end{cases}
\end{align*}
is well defined and bijective. Since $\varphi$ is the composition of $\phi$ and $\psi$, it is enough to show that $\psi$ is surjective.  

To prove that $\psi$ is surjective, for $W \in \mathcal{B}^-_0(f)$ and any $x \in W$, we show that one of the two paths
\begin{align*}
\gamma_v \colon [1,\infty) \to \mathbb{R}^n_{>0}, \quad t \mapsto t^v \ast x, \qquad \gamma_{-v} \colon [1,\infty) \to \mathbb{R}^n_{>0}, \quad t \mapsto t^{-v} \ast x
\end{align*}
\begin{itemize}
\item[(a)] connects $x$ to a point $y \in f_{|A}^{-1}(\mathbb{R}_{<0}) \cup f_{|B}^{-1}(\mathbb{R}_{<0})$, and
\item[(b)] the image of the path is contained in $ f^{-1}(\mathbb{R}_{<0})$.
\end{itemize}
For an example of these paths, we refer to Figure \ref{FIG3_new}. If (a) and (b) are satisfied, then any connected component $V \in \mathcal{B}_0^-(f_{|A}) \sqcup \mathcal{B}_0^-(f_{|B}) $ that contains $y$ will be a preimage of $W$ under $\psi$. To see this, we define
 \begin{align*}
 S_{x,a}(t) := \sum_{\mu\in \sigma(f), \, a \leq v \cdot \mu} c_\mu x^\mu t^{v\cdot \mu}, \qquad  S_{x,b}(t) :=   \begin{cases}
 \sum\limits_{\mu\in \sigma(f), \,  v \cdot \mu \leq b} c_\mu x^\mu t^{v \cdot \mu}, \text{ if } a \neq b\\
 \sum\limits_{\mu\in \sigma(f), \,  v \cdot \mu < b} c_\mu x^\mu t^{v \cdot \mu}, \text{ if } a = b
\end{cases}.
\end{align*}
 and  consider the signomials
\begin{align*}
&\tilde{f}_A(t) := f_{|A}(t^{v} \ast x) = S_{x,a}(t) +  \sum_{\mu\in \sigma_+(f),  v \cdot \mu < a} c_\mu x^\mu t^{v\cdot \mu},  \\
&\tilde{f}_B(t) := f_{|B}(t^{v} \ast x) = \sum_{\mu\in \sigma_+(f),  b < v \cdot \mu } c_\mu x^\mu t^{v \cdot \mu} + S_{x,b}(t).
\end{align*}
A simple argument shows that
\begin{equation}
\label{Eq_ProofA}
\begin{aligned}
 \text{If } \LC(\tilde{f}_A) < 0, &\text{ then } \tilde{f}_A(t_A) < 0 \text{ for some } t_A > 1  \text{ and } \gamma_v \text{ connects } x \text{ to } f_{|A}^{-1}(\mathbb{R}_{<0}). \\
  \text{If } \SC(\tilde{f}_B) < 0, &\text{ then }\tilde{f}_B(t_B) < 0 \text{ for some } t_B < 1 \text{ and } \gamma_{-v} \text{ connects } x \text{ to } f_{|B}^{-1}(\mathbb{R}_{<0}).
\end{aligned}
\end{equation}

Since $(\mathcal{H}_{v,a},\mathcal{H}_{v,b})$ is a pair of enclosing hyperplanes of $\sigma_+(f)$, the univariate signomial
\begin{align*}
&\tilde{f}(t) := f(t^{v} \ast x) = S_{x,a}(t) +  \sum_{\substack{\mu \in \sigma_+(f), \\ b < v \cdot \mu < a}} c_\mu x^\mu t^{v \cdot \mu} + S_{x,b}(t) 
\end{align*}
has at most two sign changes in its coefficient sign sequence. We denote the number of sign changes by $\signvar(\tilde{f})$. By Lemma \ref{Lemma_UniSignchanges}, we have:
\begin{align} \nonumber
&\im(\gamma_{v}) \subseteq f^{-1}(\mathbb{R}_{<0})\, \text{or} \, \im(\gamma_{-v}) \subseteq f^{-1}(\mathbb{R}_{<0}), & &\text{ if } \LC(\tilde{f}) < 0 \text{ and }  \SC(\tilde{f}) < 0,\\ 
\label{Eq::Proof_Prop_StripBound0}
&\im(\gamma_{v}) \subseteq f^{-1}(\mathbb{R}_{<0}), & &\text{ if } \LC(\tilde{f}) < 0 \text{ and } \signvar(\tilde{f}) \leq 1, \\
&\im(\gamma_{-v}) \subseteq f^{-1}(\mathbb{R}_{<0}), & &\text{ if } \SC(\tilde{f}) < 0 \text{ and } \signvar(\tilde{f}) \leq 1.  \nonumber
\end{align}

In view of \eqref{Eq_ProofA} and \eqref{Eq::Proof_Prop_StripBound0}, to obtain (a) and (b) all we need is to show that one of the following holds:
\begin{itemize}
\item[(I)]  $\LC(\tilde{f})=\LC(\tilde{f}_A)  < 0 \text{ and }  \SC(\tilde{f})=\SC(\tilde{f}_B)  < 0$,
\item[(II)] $\LC(\tilde{f})=\LC(\tilde{f}_A) < 0 \text{ and } \signvar(\tilde{f}) \leq 1$,
\item[(III)] $\SC(\tilde{f})=\SC(\tilde{f}_B) < 0 \text{ and } \signvar(\tilde{f}) \leq 1$. 
\end{itemize}

The leading and trailing coefficients $\LC(\tilde{f}),\LC(\tilde{f}_A),\SC(\tilde{f})$ and  $\SC(\tilde{f}_B)$ depend on the signs of $S_{x,a}(t), \, S_{x,b}(t)$. If $S_{x,a}(t)$ (resp. $S_{x,b}(t)$) is not the zero polynomial, then $\LC(\tilde{f}) = \LC(\tilde{f}_A) = \LC( S_{x,a})$ (resp. $\SC(\tilde{f}) = \SC(\tilde{f}_B) = \SC(S_{x,b})$). As $\tilde{f}(1) <0$, we have that at least one of $S_{x,a}(t)$ and $S_{x,b}(t)$  is not the zero polynomial, furthermore $\LC(S_{x,a}) < 0$ or $\SC(S_{x,b})< 0$. We have the following cases:

\begin{itemize}
\item If $\LC(S_{x,a}) < 0$ and $\SC(S_{x,b}) < 0$, then $S_{x,a} \not\equiv 0$, $S_{x,b} \not\equiv 0$  and (I) is satisfied. 
\item If $\LC(S_{x,a}) < 0$ and $\SC(S_{x,b}) > 0$ or $S_{x,b} \equiv 0$, then (II) holds.
\item  If $\SC(S_{x,b}) < 0$ and $\LC(S_{x,a}) > 0$ or $S_{x,a} \equiv 0$, then (III) holds.
\end{itemize}
\end{proof}


If $(\mathcal{H}_{v,a}, \mathcal{H}_{v,b})$ is a pair of enclosing hyperplanes of $\sigma_+(f)$, then by Proposition \ref{Prop_NonStrictSepHyp}(iii), the number of negative connected components of $f_{|R}$ and $f_{|S}$ does not depend on the choice of $R$ and $S$, as long as they satisfy the assumptions of Proposition \ref{Prop_StripBound0}. So to reduce the computational cost of finding $b_0(f_{|R}^{-1}(\mathbb{R}_{<0}))$ and $b_0(f_{|S}^{-1}(\mathbb{R}_{<0}))$ one might choose the sets $R, S$ as small as possible, that is $R = \mathcal{H}_{v,a}^+ \cap \sigma(f)$ and $S = \mathcal{H}_{v,b}^- \cap \sigma(f)$. However, if $R$ and $S$ are as large as possible, that is $R = A$ and $S = B$, then one can refine the bound from Proposition \ref{Prop_StripBound0} by identifying negative connected components of $f_{|A}$ and $f_{|B}$ that intersect. To make this precise, consider the bipartite graph with vertex set and edges defined as
\begin{equation} \label{Eq::GraphABVertex}
\begin{aligned}
\mathcal{B}_{A,B} &:= \mathcal{B}_0^-(f_{|A}) \sqcup \mathcal{B}_0^-(f_{|B}), \\ 
\mathcal{E}_{A,B} &:= \{ (U,V) \mid U \in \mathcal{B}_0^-(f_{|A} ), V \in \mathcal{B}_0^-(f_{|B}) \colon U \cap V \neq \emptyset \}.
\end{aligned}
\end{equation}

\begin{prop}
\label{Lema_StripBound}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$  be a signomial, $(\mathcal{H}_{v,a}, \mathcal{H}_{v,b})$ a pair of enclosing hyperplanes  of $\sigma_+(f)$, and let $A,B \subseteq \sigma(f)$ be as in \eqref{Eq::DefAB}. Then 
\[ b_0\big( f^{-1}(\mathbb{R}_{<0} )\big) \leq C \leq b_0\big( f_{|A }^{-1}(\mathbb{R}_{<0}) \big) +b_0\big( f_{|B }^{-1}(\mathbb{R}_{<0}) \big),\]
where $C$ denotes the number of connected components of the graph $(\mathcal{B}_{A,B}, \mathcal{E}_{A,B})$ from \eqref{Eq::GraphABVertex}.
\end{prop}

\begin{proof}
The inequality $C \leq b_0\big( f_{|A }^{-1}(\mathbb{R}_{<0}) \big) +b_0\big( f_{|B }^{-1}(\mathbb{R}_{<0})\big)$ follows from the fact that a graph cannot have more connected components than the number of its vertices.

Let $\varphi$ be the surjective map from Proposition \ref{Prop_StripBound0} with $R = A, S = B$. If the intersection of two connected sets is non-empty, then their union is connected. This gives that if $U,V \in \mathcal{B}_{A,B}$ lie in the same connected component of the graph $(\mathcal{B}_{A,B},\mathcal{E}_{A,B})$, then $U$ and $V$ are contained in the same connected component of $f^{-1}(\mathbb{R}_{<0})$. This yields a well defined map
\[\tilde{\varphi}\colon \mathcal{B}_{A,B}\big/{\sim} \to \mathcal{B}_0^-(f), \quad [U] \mapsto \varphi(U) = \text{ connected component of $f^{-1}(\mathbb{R}_{<0})$ that contains $U$}.\]
where $\sim$ denotes the equivalence relation that identifies two elements of $\mathcal{B}_{A,B}$ if they lie in the same connected component of the graph ($\mathcal{B}_{A,B},\mathcal{E}_{A,B})$, and $[U]$ denotes the equivalence class of $U$ under this relation. Since $\varphi$ is surjective, so is $\tilde{\varphi}$, which gives $b_0\big( f^{-1}(\mathbb{R}_{<0} )\big) \leq C$.
\end{proof}


\begin{remark}
\label{Remark::StrictEnclosing}
If $(\mathcal{H}_{v,a}, \mathcal{H}_{v,b})$ is a pair of strict enclosing hyperplanes of $\sigma_+(f)$, then from \eqref{Eq:StrictEnclAB} and Proposition \ref{Lema_StripBound} follows that 
\[ b_0\big( f^{-1}(\mathbb{R}_{<0} )\big) \leq 2,\]
which recovers the bound from Theorem \ref{Thm::FirstDescartes}(ii).
\end{remark}

\begin{ex}
\label{Ex_ParaFaces}
We revisit the signomial $f$ in \eqref{Eq_Example2} from Example \ref{Ex::ExRunning}, whose support and a pair of enclosing hyperplanes  $(\mathcal{H}_{v,2}, \mathcal{H}_{v,0})$, $v=(1,0)$ of $\sigma_+(f)$ are depicted in Figure \ref{FIG1}(a). The signomials $f_{|A}, \, f_{|B}$ are shown in \eqref{Eq_Example1} and \eqref{Eq_Example3}.

Using the \texttt{Maple} \cite{maple} function \texttt{IsEmpty()}, one can check that $f_{|A}^{-1}(\mathbb{R}_{<0}) \cap  f_{|B}^{-1}(\mathbb{R}_{<0}) = \emptyset$. Thus, the graph $( \mathcal{B}_{A,B}, \mathcal{E}_{A,B})$ does not have any edges and the bound $C$ on $b_0\big( f^{-1}(\mathbb{R}_{<0} )\big)$ provided by Proposition \ref{Lema_StripBound} equals
\[ C = b_0\big( f_{|A}^{-1}(\mathbb{R}_{<0} )\big) + b_0\big( f_{|B}^{-1}(\mathbb{R}_{<0} )\big). \]

Since $\sigma(f_{|A})$ has a strict separating hyperplane, $b_0\big( f_{|A}^{-1}(\mathbb{R}_{<0} )\big) = 1$ by Theorem \ref{Thm::FirstDescartes}(i). In Example \ref{Ex_NegFace}, we show that $b_0\big( f_{|B}^{-1}(\mathbb{R}_{<0} )\big) = 2$. Thus, Proposition \ref{Lema_StripBound} gives the bound $C = 3$. In this case, $C$ equals the number of negative connected components of $f$. In Example \ref{Ex_Running}, we will consider a signomial where the bound $C$ is not sharp.

Using the function \texttt{implicit\_plot()} from  \texttt{SageMath} \cite{sagemath}, we depicted the sets $f^{-1}(\mathbb{R}_{<0})$, $f_{|A}^{-1}(\mathbb{R}_{<0})$ and   $f_{|B}^{-1}(\mathbb{R}_{<0})$ in Figure \ref{FIG2}(a),(b).
\end{ex}

