One might wonder if, for other choices of $R$ and $S$, the bound from Proposition \ref{Prop_StripBound0} could be refined using a similar idea as in the proof of Proposition \ref{Lema_StripBound}. We will show that such a refinement is possible in the special case where all the exponent vectors are contained in the enclosing hyperplanes, or in other words the exponent vectors lie on parallel faces of the Newton polytope (Proposition \ref{Thm_ParallelFaces}). Example \ref{Ex::RSCounterExample} shows that Proposition \ref{Lema_StripBound} might fail for other choices of $R$ and $S$.

\begin{ex}
\label{Ex::RSCounterExample}
Consider again the signomial $f$ in \eqref{Eq_Example2} from Example \ref{Ex::ExRunning} and choose
\[ R =  \{ (3,2),(2,1),(2,3),(1,3),(2,0) \}, \quad S =   \{ (0,3),(0,1),(1,3),(0,4),(0,2),(0,0)\}.\]
Similarly to \eqref{Eq::GraphABVertex}, we investigate the graph whose vertices are
\begin{align*}
\mathcal{B}_{R,S} &:= \mathcal{B}_0^-(f_{|R}) \sqcup \mathcal{B}_0^-(f_{|S})  \text{ and edges} \\ 
\mathcal{E}_{R,S} &:= \{ (U,V) \mid U \in \mathcal{B}_0^-(f_{|R} ), V \in \mathcal{B}_0^-(f_{|S}) \colon U \cap V \neq \emptyset \}.
\end{align*}
Since $\sigma(f_{|R})$ has a strict separating hyperplane, $f_{|R}$ has one negative connected component. From Theorem  \ref{Thm_NegFace}, it will follow that $f_{|S}$ has two negative connected components. Thus, the graph $(\mathcal{B}_{R,S},\mathcal{E}_{R,S})$ has three vertices. One can check that $(2,1) \in f_{|R}^{-1}(\mathbb{R}_{<0}) \cap  f_{|S}^{-1}(\mathbb{R}_{<0}) \neq \emptyset$. This implies that the graph has at most two connected components. Since $b_0( f^{-1}(\mathbb{R}_{<0} ) ) = 3$, the number of connected components of the graph $(\mathcal{B}_{R,S},\mathcal{E}_{R,S})$ cannot be an upper bound on $b_0( f^{-1}(\mathbb{R}_{<0} ))$. In Figure \ref{FIG2}(c), we depicted the sets $f_{|R}^{-1}(\mathbb{R}_{<0} ),f_{|S}^{-1}(\mathbb{R}_{<0} )$.
\end{ex}

To compute the bound $C$ in Proposition \ref{Lema_StripBound}, one should check whether the negative connected components of two signomials intersect. We finish this subsection with a criterion on the signed supports of two signomials guaranteeing that the intersection of their negative connected components is non-empty. 

\begin{prop}
\label{Prop_Box}
Let $f,g \colon \mathbb{R}^{n}_{>0} \to \mathbb{R}$  be signomials. If there exist negative exponent vectors $\beta_1 \in \sigma_-(f), \, \beta_2 \in \sigma_-(g)$ such that 
\[ \Conv\big( \{ \beta_1, \beta_2 \}\big) \cap \Conv\big( \sigma_+(f) \cup \sigma_+(g) \big) = \emptyset,\]
then  $f^{-1}(\mathbb{R}_{<0}) \cap g^{-1}(\mathbb{R}_{<0}) \neq \emptyset$.
\end{prop}

\begin{proof}
We start by observing
\begin{align}
\label{Eq_ProofBox1_Prop}
 f(x)  \leq f_{|\sigma_+(f) \cup \{ \beta_1 \} }(x), \quad \text{and} \quad g(x)  \leq g_{|\sigma_+(g) \cup \{ \beta_2 \}}(x) \quad \text{ for all } x \in \mathbb{R}^{n}_{>0},
\end{align}
since $f, f_{|\sigma_+(f) \cup \{ \beta_1 \} }$ (resp. $g,  g_{|\sigma_+(g) \cup \{ \beta_2 \}}$) differ only in monomials with negative coefficients. 

As non-intersecting closed convex sets can be separated by an affine hyperplane see e.g. \cite[Section 2.2, Theorem 1]{grunbaum2003convex}, from $\Conv( \{ \beta_1, \beta_2 \}) \cap \Conv( \sigma_+(f) \cup \sigma_+(g) ) = \emptyset$ it follows that there exists $w \in \mathbb{R}^{n}$ such that
\[ w \cdot \beta_1 > w \cdot \alpha, \quad w \cdot \beta_2 > w \cdot \alpha, \quad \text{for all } \alpha \in \sigma_+(f) \cup \sigma_+(g).\]
For a fixed $x \in \mathbb{R}^{n}_{>0}$, both univariate signomials
\[ f_{|\sigma_+(f) \cup \{ \beta_1 \}}(t^w\ast x), \qquad  g_{|\sigma_+(g) \cup \{ \beta_2 \}} (t^w\ast x)\]
have negative leading coefficients. Thus, there exists $t_0 \gg 0$ such that
\[ f_{|\sigma_+(f) \cup \{ \beta_1 \}}(t_0^w \ast x) < 0 \quad \text{ and } \quad  g_{|\sigma_+(g) \cup \{ \beta_2 \}}(t_0^w \ast x) < 0.\]
By \eqref{Eq_ProofBox1_Prop}, we have $t_0^w \ast x \in f_{|\sigma_+(f) \cup \{ \beta_1 \}}^{-1}(\mathbb{R}_{<0}) \cap g_{|\sigma_+(g) \cup \{ \beta_2 \}}^{-1}(\mathbb{R}_{<0}) \subseteq f^{-1}(\mathbb{R}_{<0}) \cap g^{-1}(\mathbb{R}_{<0})$, which completes the proof.
\end{proof}

\subsection{One negative connected component}
\label{Section::OneNegCC}
Building on the results of Section \ref{Section::NonStrict}, we describe conditions on the signs of the coefficients of $f$ and its support $\sigma(f)$ that guarantee that $f$ has one negative connected component. Similarly to Theorem \ref{Thm::FirstDescartes}(i), for polynomials satisfying these conditions the number of negative connected components does not depend on the values of the coefficients but only on their signs.

\begin{thm}
\label{Thm_Box}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$  be a signomial such that $\sigma_+(f)$ has a pair of strict enclosing hyperplanes $(\mathcal{H}_{v,a}, \mathcal{H}_{v,b})$. Assume that there exist negative exponent vectors $\beta_1, \beta_2 \in \sigma_-(f)$ such that 
\begin{itemize}
\item $\beta_1 \in \mathcal{H}^{+}_{v,a}$, $\beta_2 \in \mathcal{H}^{-}_{v,b}$ and 
\item $\Conv( \{ \beta_1, \beta_2 \}) \cap \Conv( \sigma_+(f) ) = \emptyset$.
\end{itemize}
Then $f^{-1}(\mathbb{R}_{<0})$ is non-empty and connected.
\end{thm}

\begin{proof}
Let  $A, B \subseteq \sigma(f)$ as in \eqref{Eq::DefAB}. Since $(\mathcal{H}_{v,a}, \mathcal{H}_{v,b})$ is a pair of strict enclosing hyperplanes of $\sigma_+(f)$, by  \eqref{Eq:StrictEnclAB} we have:
\[b_0\big( f_{|A}^{-1}(\mathbb{R}_{<0})\big) = 1, \qquad b_0\big( f_{|B}^{-1}(\mathbb{R}_{<0})\big) = 1.\]
The assumptions of the theorem are equivalent to $\beta_1 \in \sigma_-(f_{|A}), \, \beta_2 \in \sigma_-(f_{|B})$ and $\Conv( \{ \beta_1, \beta_2 \}) \cap \Conv( \sigma_+(f_{|A}) \cup \sigma_+(f_{|B})) = \emptyset$. Thus, by Proposition \ref{Prop_Box}, $f^{-1}_{|A}(\mathbb{R}_{<0}) \cap f^{-1}_{|B}(\mathbb{R}_{<0}) \neq \emptyset$. Now, from Proposition \ref{Lema_StripBound} it follows that $b_0( f^{-1}(\mathbb{R}_{<0})) = 1$.
\end{proof}


\begin{ex}
\label{Ex_Box}
Consider the signomial $f =-x^{4} y^{4} + 10 \, x^{3} y^{3} - 10 \, x^{4} - 10 \, y^{4} + 7 \, x y + 5 \, x - 1$. Figure \ref{FIG3}(a) displays the exponent vectors of $f$. The pair $(\mathcal{H}_{v,3.5}, \, \mathcal{H}_{v,0.5})$, $v=(1,0)$ is a pair of strict enclosing hyperplanes of $\sigma_+(f)$, furthermore
\begin{align}
\label{Eq::Ex_Box}
 \Conv( \{ (0,4),(4,4) \} ) \cap \Conv(\sigma_+(f) ) = \emptyset.
 \end{align}
Thus, $f^{-1}(\mathbb{R}_{<0})$ is connected by Theorem \ref{Thm_Box}. Figure \ref{FIG3}(b),(c) show $f^{-1}(\mathbb{R}_{<0})$, $f_{|A}^{-1}(\mathbb{R}_{<0})$ and $f_{|B}^{-1}(\mathbb{R}_{<0})$, where $f_{|A} =-x^{4} y^{4} + 10 \, x^{3} y^{3} - 10 \, x^{4}  + 7 \, x y + 5 \, x  $ and $f_{|B}=10 \, x^{3} y^{3}  - 10 \, y^{4} + 7 \, x y + 5 \, x - 1$.
\end{ex}


