By Theorem \ref{Thm::FirstDescartes}(iii), $f^{-1}(\mathbb{R}_{<0})$ is either empty or logarithmically convex, if the signomial $f$ has at most one negative coefficient. In particular, in that case $f$ has one negative connected component. A natural question to ask is what happens for signomials with at most one positive coefficient. For a univariate signomial $f$, it is easy to construct examples where $f$ has one positive coefficient and $f^{-1}(\mathbb{R}_{<0})$ is disconnected, take for example $f = -x^2 + 3x-1$. 

If $n \geq 2$ and the positive exponent vector lies in the interior of the Newton polytope, then $f^{-1}(\mathbb{R}_{<0})$ is homeomorphic to the complement of a bounded convex set  \cite[Corollary 3.5]{telek2023real} \cite[Theorem 3.4]{DescartesHypPlane}; therefore,  $f^{-1}(\mathbb{R}_{<0})$ is connected. This argument does not work if the positive exponent vector lies on the boundary of $\N(f)$, but the conclusion is still true. 

\begin{cor}
\label{Cor_OnePos}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \quad x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$  be a signomial. If $\dim \N(f) \geq 2$ and $\# \sigma_+(f) = 1$, then $f^{-1}(\mathbb{R}_{<0} )$ is non-empty and connected.
\end{cor}

\begin{proof}
Write $\{ \alpha \} = \sigma_+(f)$. Since $\dim \N(f) \geq 2$, there exist $\beta_1,\beta_2 \in \sigma_-(f)$ such that $\beta_1,\beta_2$ and $\alpha$ do not lie on a line. In that case, 
\[ \Conv( \{ \beta_1,\beta_2 \}) \cap \Conv( \{ \alpha \}) = \emptyset.\]

Pick a hyperplane $\mathcal{H}_{v,a}$ that contains $\alpha$ such that $\beta_1,\beta_2$ lie in different open half-spaces determined by $\mathcal{H}_{v,a}$. Thus, $(\mathcal{H}_{v,a},\mathcal{H}_{v,a})$ is a pair of strict enclosing hyperplanes of $\sigma_+(f)$.

Using Theorem \ref{Thm_Box}, we conclude that $f^{-1}(\mathbb{R}_{<0} )$ is non-empty and connected.
\end{proof}


Corollary \ref{Cor_OnePos} shows that one can flip the signs in Theorem \ref{Thm::FirstDescartes}(iii) if $\dim \N(f) \geq 2$, i.e. if $f$ has one negative coefficient, then both $f^{-1}(\mathbb{R}_{<0})$ and $(-f)^{-1}(\mathbb{R}_{<0})$ are (possibly empty) connected sets. As discussed at the end of Section \ref{Sec::Background}, a signomial has at most one negative connected component if its positive and negative exponent vectors are separated by a simplex and its negative vertex cones \cite[Theorem 4.6]{DescartesHypPlane}. We proceed by recalling this statement and show that it is possible to flip the signs also in that case under some mild assumptions. 

First we recall the definition of the \emph{negative vertex cone} of a simplex. For an $n$-simplex $P \subseteq \mathbb{R}^{n}$ with vertices $\mu_0, \dots , \mu_n$, the negative vertex cone of $P$ at the vertex $\mu_k$ is defined as
\[ P^{-,k} := \mu_k + \Cone( \mu_k - \mu_0, \dots , \mu_k - \mu_n) .\]
Thus, $P^{-,k}$ is the cone with apex at $\mu_k$ which is generated by the edges pointing into $\mu_k$. For the union of the negative vertex cones $P^{-,0}, \dots ,P^{-,n}$, we write $P^-$.

\begin{thm} \cite[Theorem 4.6]{DescartesHypPlane}
\label{Thm::VertCones46}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$  be a signomial. If there exists an $n$-simplex $P \subseteq \mathbb{R}^{n}$ such that 
\[ \sigma_{-}(f) \subseteq P, \quad \text{ and } \quad \sigma_{+}(f) \subseteq P^{-},\]
then $f^{-1}(\mathbb{R}_{<0} )$  is either empty or contractible.
\end{thm}  

As another consequence of Theorem \ref{Thm_Box}, we have the following result.

\begin{cor}
\label{Lemma_SimplexVertCones}
Let $n \geq 2$ and let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$ be a signomial. Assume that there exists an $n$-simplex $P \subseteq \mathbb{R}^{n}$ such that 
\[ \sigma_{+}(f) \subseteq P \quad \text{ and } \quad \sigma_{-}(f) \subseteq P^{-}. \]
If $\sigma_-(f) \cap \inte(P^-) \neq \emptyset$, then $f^{-1}(\mathbb{R}_{<0} )$ is non-empty and connected.
\end{cor}

\begin{proof}
Denote $\mu_0, \dots , \mu_n$ the vertices of $P$ and write $P$ as
\begin{align}
\label{Eq_Psimplex}
P = \bigcap_{j=0}^{n}\mathcal{H}^{-}_{v_{j},a_j}
\end{align}
for a choice of normal vectors $v_0, \dots , v_n \in \mathbb{R}^{n}$ and scalars $a_0, \dots, a_n \in \mathbb{R}$ such that $\mu_k$ equals the intersection point of the hyperplanes $\mathcal{H}_{v_j,a_j}, j \in \{0,\dots, n\} \setminus \{k \}$. By \cite[Proposition 4.3]{DescartesHypPlane}, each negative vertex cone has the form: 
\[P^{-,k} = \bigcap_{j=0,j\neq k}^n\mathcal{H}^{+}_{v_{j},a_j}  \qquad k=0,\dots,n.\]
Note that if $\beta \in P^{-,k}$, then $\beta$ is contained in $\mathcal{H}^{-,\circ}_{v_{k},a_k}$. Since $\sigma_+(f) \subseteq P$  and $\sigma_-(f) \subseteq P^-$, we have
\begin{align}
\label{Eq-AlphainP}
v_k \cdot \beta \geq a_k \geq v_k \cdot \alpha  \geq v \cdot \mu_k \geq v_k  \cdot\beta', \quad \text{ and } v_k \cdot \alpha > v_k \cdot \beta'
\end{align}
for all $\beta \in  \sigma_-(f) \setminus P^{-,k}, \, \alpha \in \sigma_+(f), \, \beta' \in  \sigma_-(f) \cap P^{-,k}$,  $k=0,\dots,n$.

Let $\beta_0 \in \sigma_-(f) \cap \inte(P^-)$ and assume without loss of generality that $\beta_0 \in \inte(P^{-,0})$, so
\begin{align}
\label{Eq_Beta0inP0}
a_0 > v_0 \cdot \beta_0 \qquad \text{and} \qquad v_j \cdot \beta_0 > a_j, \quad \text{for } j = 1, \dots , n.
\end{align}

If $ \sigma_-(f) \cap P^{-,1} = \emptyset$, then $\sigma_-(f) \subseteq  \mathcal{H}_{v_1,a_1}^+$. Since $ \beta_0 \in \mathcal{H}_{v_1,a_1}^{+,\circ}$ , $\mathcal{H}_{v_1,a_1}$ is a strict separating hyperplane of $\sigma(f)$, which implies that $f^{-1}(\mathbb{R}_{<0} )$ is non-empty and connected by Theorem \ref{Thm::FirstDescartes}(i).

Assume now that $ \sigma_-(f) \cap P^{-,1} \neq \emptyset$, let $\beta_1 \in\sigma_-(f) \cap P^{-,1}$ and $b_1 \in \mathbb{R}$ such that
\[ v_1 \cdot \alpha > b_1 > v_1 \cdot \beta_1 \qquad \text{for all } \alpha \in \sigma_+(f).\]
From \eqref{Eq-AlphainP}, it follows that $(\mathcal{H}_{v_1,a_1}, \mathcal{H}_{v_1,b_1})$ is a pair of enclosing hyperplanes of $\sigma_+(f)$. By \eqref{Eq_Beta0inP0}, we have $\beta_0 \in \mathcal{H}^{+,\circ}_{v_1,a_1}$. Thus, $(\mathcal{H}_{v_1,a_1}, \mathcal{H}_{v_1,b_1})$ is a pair of strict enclosing hyperplanes.

Every element $\mu \in \Conv(\beta_0 , \beta_1) \setminus \{ \beta_1 \}$ has the form $\mu = t \beta_0 + (1-t) \beta_1$ for some $t \in (0,1]$. By \eqref{Eq-AlphainP} and \eqref{Eq_Beta0inP0}, we have
\[ v_2 \cdot \mu = t (v_2 \cdot \beta_0) + (1- t) (v_2 \cdot \beta_1) > a_2.\] 
Thus, $\Conv(\beta_0 , \beta_1) \setminus \{ \beta_1 \} \subseteq \mathcal{H}_{v_2,a_2}^{+,\circ}$, which implies that 
\[ \Conv(\{ \beta_0,\beta_1 \} ) \cap \Conv(\sigma_+(f)) = \emptyset. \]
From Theorem \ref{Thm_Box}, it follows that $f^{-1}(\mathbb{R}_{<0} )$ is non-empty and connected.
\end{proof}

\begin{ex} 
\label{Ex_Simplex} 
\textbf{(a)} Consider the signomial
\[ f =-x^{5} y^{\frac{7}{3}} - x^{5} y^{2} + x^{2} y^{2} - x y^{3} - y^{4} + 2 \, x^{2} y^{\frac{4}{3}} + 2 \, x y^{2} - x y.\]
The simplex $P=\operatorname{Conv}((1,1),(4,2),(1,3))$ contains $\sigma_+(f)$ and the negative exponent vectors are contained in the union of the negative vertex cones $P^-$. By Theorem \ref{Thm::VertCones46}, we have that $(-f)^{-1}(\mathbb{R}_{<0})$ is connected. From Corollary \ref{Lemma_SimplexVertCones}, it follows that $f^{-1}(\mathbb{R}_{<0})$ is connected as well. The exponent vectors of $f$, the simplex $P$ and its negative vertex cones are depicted in Figure~\ref{FIG4}(a),(b).

To write $P$ as an intersection of half-spaces as in \eqref{Eq_Psimplex} in the proof of Corollary \ref{Lemma_SimplexVertCones}, one can choose $v_0 = (-1,0), \, v_1 = (0.5,1.5), \, v_2 = (0.5,-1.5)$. With this choice we have:
\[ P = \mathcal{H}_{v_0,-1}^- \cap \mathcal{H}_{v_1,5}^- \cap \mathcal{H}_{v_2,-1}^-. \]

\medskip

\textbf{(b)} The following example shows that the assumption $\sigma_-(f) \cap \inte(P^-) \neq \emptyset$ in Corollary \ref{Lemma_SimplexVertCones} is necessary. If we remove the exponent vectors $(0,4),(5,2) \in  \relint(P^-)$ from the support of $f$, the signomial
