The next proposition refines the bound from Proposition \ref{Prop_StripBound0} in the special case where the pair of enclosing hyperplanes $(\mathcal{H}_{v,a},\mathcal{H}_{v,b})$ of $\sigma_+(f)$ is non-strict and all the exponent vectors of $f$ lie on the union of the two hyperplanes. In this case, the hyperplanes $\mathcal{H}_{v,a},\mathcal{H}_{v,b}$ cut out two parallel faces of the Newton polytope of $f$, i.e.:
\[ \N(f)_v = \N(f) \cap \mathcal{H}_{v,a}, \quad \N(f)_{-v} = \N(f) \cap \mathcal{H}_{v,b}.\]

Similarly to \eqref{Eq::GraphABVertex}, we define a bipartite graph whose set of vertices and edges are
\begin{equation}
\label{Eq::GraphvVertex}
\begin{aligned}
\mathcal{B}_v &:= \mathcal{B}_0^-(f_{|\N(f)_v } ) \sqcup \mathcal{B}_0^-(f_{|\N(f)_{-v}}), \\
\mathcal{E}_v &:= \{(U,V) \mid U \in \mathcal{B}_0^-(f_{|\N(f)_v } ), V \in \mathcal{B}_0^-(f_{|\N(f)_{-v}}) \colon U \cap V \neq \emptyset \}.
\end{aligned}
\end{equation}


\begin{prop}
\label{Thm_ParallelFaces}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$ be a signomial. Assume that there exists  $v \in \mathbb{R}^{n}$ such that $\sigma(f) \subseteq \N(f)_v \cup \N(f)_{-v}$. Then
\[ b_0\big( f^{-1} (\mathbb{R}_{<0}) \big) = D \leq b_0\big( f_{|N(f)_v}^{-1} (\mathbb{R}_{<0}) \big) + b_0\big( f_{|N(f)_{-v}}^{-1} (\mathbb{R}_{<0}) \big),\]
where $D$ denotes the number of the connected components of the graph $(\mathcal{B}_v,\mathcal{E}_v)$ from \eqref{Eq::GraphvVertex}.
\end{prop}

\begin{proof}

After an affine change of coordinates (see e.g. \cite[Lemma 2.3]{DescartesHypPlane}), we assume that $v = (0, \dots , 0 ,1) \in \mathbb{R}^n$, $\N(f)_v = \N(f) \cap \mathcal{H}_{v,1}$ and $\N(f)_{-v} = \N(f) \cap \mathcal{H}_{v,0}$. There exist signomials $f_1,f_2 \colon \mathbb{R}^{n-1}_{>0} \to \mathbb{R}$ such that  $f(x) = f_1(x_1, \dots , x_{n-1}) + x_n f_2(x_1, \dots , x_{n-1})$ for all $x \in \mathbb{R}^n_{>0}$. Note that $f_1^{-1}(\mathbb{R}_{<0})$ (resp. $f_2^{-1}(\mathbb{R}_{<0})$) has the same number of connected components as $f_{|N(f)_{-v}}^{-1}(\mathbb{R}_{<0})$ (resp. $f_{|N(f)_{v}}^{-1}(\mathbb{R}_{<0})$). Moreover, the number of connected components of $f_1^{-1}(\mathbb{R}_{<0})\cup f_2^{-1}(\mathbb{R}_{<0})$ is $D$. We decompose this set into three pairwise disjoint sets
\begin{align*}
 W_0 &=  \{ \tilde{x} \in \mathbb{R}^{n-1}_{>0} \mid f_1(\tilde{x}) < 0,\, f_2(\tilde{x}) \leq 0\} \cup  \{  \tilde{x} \in \mathbb{R}^{n-1}_{>0} \mid  f_1(\tilde{x}) \leq 0,\, f_2(\tilde{x}) < 0\}\\
 W_1 &=  \{\tilde{x} \in \mathbb{R}^{n-1}_{>0} \mid   f_1(\tilde{x}) < 0,\, f_2(\tilde{x}) > 0\}, \quad W_2 =  \{\tilde{x} \in \mathbb{R}^{n-1}_{>0} \mid   f_1(\tilde{x}) > 0,\, f_2(\tilde{x}) < 0\}.
 \end{align*}
Consider the map 
\[ F \colon \mathbb{R}^{n-1}_{>0} \to \mathbb{R},  \quad \tilde{x} \mapsto -\tfrac{f_1(\tilde{x})}{f_2(\tilde{x})} \]
which is continous on $W_1 \cup W_2$ and has some poles and zeros in $W_0$. It holds that
\begin{equation}
\label{Eq::Elevator}
\begin{aligned}
&\text{ if }  \tilde{x} \in W_0, \text{ then} &(\tilde{x},x_n) \in f^{-1}(\mathbb{R}_{<0}) \quad  &\text{ for all  } x_n > 0, \\
&\text{ if }  \tilde{x} \in W_1, \text{ then}  &(\tilde{x},x_n) \in f^{-1}(\mathbb{R}_{<0}) \quad  &\text{ if and only if  }  x_n < F(\tilde{x}),  \\
& \text{ if }  \tilde{x} \in W_2, \text{ then}  &(\tilde{x},x_n) \in f^{-1}(\mathbb{R}_{<0}) \quad  &\text{ if and only if  }  x_n > F(\tilde{x}). 
\end{aligned}
\end{equation}

It follows that  the projection map
  \[\pi\colon f^{-1}(\mathbb{R}_{<0}) \to  f_1^{-1}(\mathbb{R}_{<0})\cup f_2^{-1}(\mathbb{R}_{<0}), \quad  \, x \mapsto \pi(x) = (x_1, \dots , x_{n-1}) \]
is well defined, continuous and surjective. This gives that the number of connected components of $f^{-1}(\mathbb{R}_{<0}) $ is at most $D$.

To show equality, we show that for every connected component $U$ of $f_1^{-1}(\mathbb{R}_{<0})\cup f_2^{-1}(\mathbb{R}_{<0})$, the set $\pi^{-1}(U)$ is connected. For $i=0,1,2$, let $U_{i,1},\dots ,U_{i,k_i}$ be the connected components of $U \cap W_i$. By \eqref{Eq::Elevator}, the sets $\pi^{-1}(U_{i,j})$ are connected. Therefore it is enough to show that $\pi^{-1}(U_{i,j} \cup U_{i',j'})$ is connected if $U_{i,j} \cup U_{i',j'}$ is connected for $i,i' \in \{0,1,2\}$, $j \in \{1,\dots,k_i\},\, j' \in \{1,\dots,k_{i'}\}$ . Note that  $U_{1,j} \cup U_{2,j'}$ cannot be connected through a path that is contained in $f_1^{-1}(\mathbb{R}_{<0})\cup f_2^{-1}(\mathbb{R}_{<0})$. Using \eqref{Eq::Elevator}, it follows that $\pi^{-1}(U_{0,j} \cup U_{i',j'})$, $i' =1,2$ is connected. This concludes the proof. For an illustration, we refer to Figure \ref{FIG4_new} and Example \ref{Ex:NewParaFaces}.
\end{proof}

