From Proposition \ref{Thm_ParallelFaces}, we derive a criterion to ensure that a polynomial has at most one negative connected component. This criterion can be interpreted as a version of Theorem \ref{Thm_Box} where we replace strict separating hyperplanes by non-strict ones. 

\begin{thm}
\label{Thm_ParallelFacesEdge}
Let $f\colon \mathbb{R}^{n}_{>0} \to \mathbb{R}, \, x \mapsto \sum_{\mu \in \sigma(f)} c_{\mu}x^{\mu}$ be a signomial. Assume that there exists $v \in \mathbb{R}^{n}$ such that $\sigma(f) \subseteq \N(f)_v \cup \N(f)_{-v}$ and 
\[b_0 \big( f_{|\N(f)_{v}}^{-1}(\mathbb{R}_{<0}) \big) = b_0 \big( f_{|\N(f)_{-v}}^{-1}(\mathbb{R}_{<0}) \big)   = 1.\]
If there exist negative exponent vectors $\beta_1 \in \N(f)_v$ and  $\beta_2 \in \N(f)_{-v}$ such that $\Conv(\beta_1, \beta_2)$ is an edge of $\N(f)$, then $b_0 \big( f^{-1}(\mathbb{R}_{<0}) \big) = 1$.
\end{thm}

\begin{proof}
Throughout the proof we assume that $\N(f)_v \neq \N(f)_{-v}$, otherwise the statement is obvious. First, we show that $\Conv(\beta_1, \beta_2) \cap \sigma(f) = \{ \beta_1, \beta_2 \} .$ For $\alpha \in \Conv(\beta_1, \beta_2) \cap \sigma(f)$, if $\alpha \notin  \{ \beta_1, \beta_2 \}$, then there exists $t \in (0,1)$ such that $\alpha = t \beta_1 + (1-t) \beta_2$. Let $\mathcal{H}_{v,a}$ and $\mathcal{H}_{v,b}$ be the supporting hyperplanes of $\N(f)_v$ and $\N(f)_{-v}$ respectively. As $\N(f)_v \neq \N(f)_{-v}$, $a > b$. Thus, we have 
\[ v \cdot \alpha = t (v \cdot \beta_1) + (1-t) (v \cdot \beta_2) = ta + (1-t)b \neq a,b  \qquad \text{ if } t \in (0,1).\]
which contradicts $\alpha \in \mathcal{H}_{v,a} \cup \mathcal{H}_{v,b}$.

Proposition \ref{Prop_Box} implies that $f^{-1}_{|\N(f)_{v}} (\mathbb{R}_{<0}) \cap f^{-1}_{|\N(f)_{-v}} (\mathbb{R}_{<0}) \neq \emptyset$. Thus, by Proposition \ref{Thm_ParallelFaces} we have $b_0\big( f^{-1}(\mathbb{R}_{<0}) \big) = 1$.
\end{proof}

\begin{remark}
In the last step of the proof of Theorem \ref{Thm_ParallelFacesEdge},  instead of Proposition \ref{Thm_ParallelFaces} one could use Theorem \ref{Thm_NegFace} and Proposition \ref{Lema_StripBound} as well to conclude that  $b_0\big( f^{-1}(\mathbb{R}_{<0}) \big) = 1$.
\end{remark}

\begin{ex}
\label{Ex_cube}
For each $c_1, \dots , c_8 \in \mathbb{R}_{>0}$, the Newton polytope of 
\[f(x,y,z) = c_1 x+c_2 xy- c_3y-c_4+c_5 yz- c_6z- c_7 xz- c_8 xyz\]
 is the cube depicted in Figure \ref{FIG8}. The top and the bottom faces of the cube are parallel to each other and contain all the exponent vectors of $f$. Choosing $v = (0,0,1)$, we have that $\sigma(f) \subseteq \N(f)_v \cup \N(f)_{-v}$. Since both $\sigma(f_{|\N(f)_v})$ and $\sigma(f_{|\N(f)_{-v}})$ have a strict separating hyperplane, $b_0 \big( f_{|\N(f)_{v}}^{-1}(\mathbb{R}_{<0}) \big) = b_0 \big( f_{|\N(f)_{-v}}^{-1}(\mathbb{R}_{<0}) \big)   = 1$ by Theorem \ref{Thm::FirstDescartes}(i).

The vertices of the edge $\Conv\big( (0,0,0),(0,0,1) \big)$  correspond to negative exponent vectors, thus $f^{-1}(\mathbb{R}_{<0})$ is connected by Theorem \ref{Thm_ParallelFacesEdge}.
\end{ex}

