\subsection{The Core Idea: Higher Inclusion Probability
}\label{sec:warmup}


%\seri{Double check that independent set is $\mathcal{I}$ and not $I$.}\seri{double check that intervals are $I$ and not $B$}\seri{Check that neighbors in bucket $i$ are $N_i(v)$ and not $B$}
In this section we show that there exists a two-round algorithm that includes each node with probability higher than $1/\Delta$ in $\Delta$-regular triangle-free graphs. 

\begin{lem}\label{thm:log-star-lower}
In $\Delta$-regular triangle-free graphs, there is a two-round algorithm that finds an independent set $\mathcal{I}$  such that the probability that a node $v$ is included in $\mathcal{I}$ is at least $\frac{\log^* \Delta}{10^4\Delta}$.
\end{lem}



    Before providing the algorithm, we set up some notation. We denote the input graph by $G$, the set of nodes by $V(G)$, and the set of edges by $E(G)$. We assume without loss of generality that $\Delta > 1000$.\footnote{Otherwise, Luby's one-round algorithm includes each node with probability $1/(\Delta+1) > \log^* \Delta / (1000\Delta)$ for $\Delta \leq 1000$.} Let $k = \lfloor (\log^* \Delta)/10 \rfloor$, $a_1 = 5$, and $a_{i+1} = e^{a_i - 3}$ for every integer $i \in [2, \cdots, k]$. Furthermore, let $b_i = a_i/\Delta$, and define the intervals $I_i = (b_i, b_{i+1}]$ and $J_i = (b_i, 1]$ for each integer $i \in [k]$. Observe that \( a_i < \Delta^{1/10} \), and that all intervals \( I_i \) and \( J_i \) are contained within the interval \( [0, 1] \), since \( \frac{5}{\Delta} \leq b_i \leq \frac{1}{100} \) by the definition of \( k \). Finally, we use the standard notation \( u \sim v \) to refer to a neighbor \( u \) of \( v \).




%For any $i\in [k]$, let $\mathcal{S}_i \subseteq \mathcal{S}$ denote the family of multisets of $\Delta-1$ elements all taken from $J_i$. $a_{i+1} \le \frac{1}{e^{-2(2a_i/\Delta)(\Delta-2)}} \le e^{4a_i}$. Thus, by definition of $k$, $b_i\le 1/100$ for all $i\in [k+1]$. Furthermore, $a_{i+1}\ge e^{2a_i(\Delta-2)/\Delta} \ge 10 a_i$ and $b_{i+1}\ge 10 b_i$ for all $i\in [k]$ since $a_1 \ge 5$.\seri{do we need the 2-factor in $b_i$?}


The algorithm for proving Lemma~\ref{thm:log-star-lower} is provided in Algorithm~\ref{alg:2-round}. Each node $v$ picks a uniformly random rank $r_v \in [0,1]$. If $r_v\in I_i$ for some $i\in [k]$ and $r_u\in J_i$ for all $u\sim v$, then $v$ joins a set of candidates $C$.\footnote{Intuitively speaking, $v$ is a candidate if its rank falls into some interval $I_i$ and none of the neighbors' ranks falls into a smaller interval $I_j$ for $j<i$.} If $v$ is a candidate and none of its neighbors is a candidate, then $v$ is added to the independent set $\mathcal{I}$. The algorithm can be implemented in two rounds: in the first round, each node picks a random rank and sends it to its neighbors. In the second round, each node informs its neighbors whether it is a candidate and decides whether to join the independent set accordingly.%\seri{a reminder for myself to not repeat things again after technical overview..}


\begin{algorithm}
\caption{Two-round algorithm for proving Lemma~\ref{thm:log-star-lower}}\label{alg:2-round}
\begin{algorithmic}[1]
\State Initialize the independent set $I \gets \emptyset$ and the candidate set $C \gets \emptyset$
\For{each node $v \in V(G)$}
    \State Sample a uniformly random rank $r_v \in [0,1]$ independently
    \If{$r_v \in I_i$ for some $i \in [k]$}
        \State Let $i(v)$ be the unique value for which $r_v \in I_{i(v)}$
        \If{$r_u \in J_{i(v)}$ for all $u \sim v$}
            \State Add $v$ to the set of candidates $C$
        \EndIf
    \EndIf
\EndFor
\For{each node $v \in C$}
    \If{$u \notin C$ for all $u \sim v$}
        \State Add $v$ to the independent set $\mathcal{I}$
    \EndIf
\EndFor
\end{algorithmic}
\end{algorithm}



\begin{proof}[Proof of Lemma~\ref{thm:log-star-lower}]
Clearly, Algorithm~\ref{alg:2-round} produces an independent set $\mathcal{I}$ as no candidate joins $\mathcal{I}$ if it has a neighboring candidate. Hence, we focus on the probability that $u$ is added to the independent set (i.e., the inclusion probability). %\seri{just fix the ``ands below"}

~\\\noindent\textbf{Inclusion probability}: We fix the node $v$ for the rest of the proof. Let $C_i$ be the set of candidates in $C$ with ranks in $I_i$, i.e., $C_i = \{u \in C \mid r_u \in I_i\}$. First, we show that the probability that $v \in C_i$ is $\approx 1/\Delta$ for any $i \in [k]$. Then, we show that the probability that $v \in \mathcal{I}$ given that $v \in C_i$ is at least a constant. Hence, since the $I_i$'s are disjoint, summing over all $i$'s gives an inclusion probability of $\approx \log^* \Delta / \Delta$.


~\\\noindent\textbf{Lower bounding $\Pr[v\in C_i]$:} Observe that:

\begin{align}
    \Pr[v\in C_i]  &= \Pr [ r_v\in I_i \text{ and } (r_u\in J_i \text{ } \forall u\sim v)]\\ &= (b_{i+1} - b_i)\cdot (1-b_i)^\Delta\\
    &\geq \frac{a_{i+1} - a_i}{\Delta}\cdot \exp\left(-\Delta( b_i + 2b_i^2)\right)\\
    &\geq \frac{a_{i+1}}{2\Delta}\cdot \exp\left(-a_i - 2a_i^2/\Delta\right)\\
    &\geq \frac{a_{i+1}}{2\Delta}\cdot \exp\left(-a_i - 1/2\right)\\
    &\geq \frac{a_{i+1}}{2\Delta}\cdot \frac{1}{e^4\cdot a_{i+1}}\\
    &=\frac{1}{2\cdot e^4\cdot \Delta}
\end{align}

where (2) follows by independence, (3) follows by a standard argument for approximating exponents (see also Proposition~\ref{prop:exp-approx}), (5) follows since $a_i< \Delta^{1/10}$ and $\Delta>1000$, which implies that $2a_i^2/\Delta < 1/2$, and (6) follows sins $a_{i+1}\cdot e^4 = e^{a_i-3}\cdot e^4 > e^{a_i}\cdot \sqrt{e} = \exp(a_i+1/2)$.

~\\\noindent\textbf{Lower bounding $\Pr[v\in \mathcal{I}\mid v\in C_i]$:} The main idea is to notice that if $v \in C_i$, then whether it is included in the independent set $\mathcal{I}$ depends solely on its neighbors $u$ with ranks $r_u \in I_i$. This is because if $v \in C_i$, then all of its neighbors $u$ have ranks $r_u \in J_i$. Furthermore, those with ranks $r_u \in I_j$ for $j > i$ cannot be candidates (due to Line 6 in Algorithm~\ref{alg:2-round}) because they have a neighbor, $v$ itself, with rank $r_v \notin J_j$. Hence, to bound the probability that a node $v \in C_i$ is added to the independent set, it suffices to bound the probability that none of the neighbors $u$ with $r_u \in I_i$ are in $C$ (the other neighbors are not in $C$ with probability 1).


For this, we first upper bound the number of neighbors of $v\in C_i$ with ranks in  $I_i$, then we upper bound the probability that a given such neighbor is a candidate, and finally we use a standard union bound argument to show that none of these neighbors is a candidate with constant probability. 

Let $N_i(v)$ be the set of neighbors $u$ of $v$ with $r_u\in I_i$, and let $s_i = |N_i(v)|$. Observe that for a neighbor $u$ of $v$, $\Pr[u\in N_i(v)\mid v\in C_i] = (b_{i+1}-b_i)/(1-b_i)$ (since $v\in C_i$, we know that $u$ is not in the interval $[0,b_i]$). Hence, we get that $\mathbb{E}[s_i\mid v\in C_i] \leq  \Delta\cdot b_{i+1}/(99/100)\leq 2\Delta\cdot b_{i+1} = 2a_{i+1}$. Therefore, by Markov's inequality, $\Pr[s_i < 4a_{i+1}\mid v\in C_i]\geq 1/2$. 

Furthermore, for a neighbor $u\in N_i(v)$ it holds that $\Pr[u\in C\mid v\in C_i] =(1-b_i)^{(\Delta-1)}$. This is because for such a neighbor $u$, since $r_u\in I_i$, the probability that it is in $C$ is exactly the probability that it does not have a neighbor $w\neq v$ with $r_w\notin J_i$. Since the graph is triangle-free, $v$ and $u$ have no common neighbors. Therefore, the event that $u$ has no neighbor $w\neq v$ with $r_w\in J_i$ is independent of the event that $v\in C_i$. Hence, for a neighbor $u$ of $v$, $\Pr[r_w\in J_i \text{ } \forall w\sim u \mid v\in C_i] =(1-b_i)^{(\Delta-1)}\leq e^{-a_i(\Delta-1)/\Delta} = e^{-a_i + a_i/\Delta}\leq e^{-a_i + 1/2}$. By a union bound, if $s_i<4a_{i+1}$, we get that $\Pr[u\notin C \text{ } \forall u\in N_i(v) \mid v\in C_i]\geq 1-4a_{i+1}\cdot e^{-a_i + 1/2} \geq 1- 4/e^2$. %\aaron{minor issue: $s_i$ is a random variable. Acknowledge that we need to fix all randomness on $v$ and all neighbors of $v$ in order to make it deterministic. I.e. the conditioning should not be over $v\in C_i$, but on some specific fixing for the 1-neighborhood of $v$.}\seri{let me know if it makes sense now}

Now we are ready to give a lower bound on $\Pr[v\in \mathcal{I}\mid v\in C_i]$. Observe that:
\setcounter{equation}{0}

\begin{align}
    \Pr[v\in \mathcal{I}\mid v\in C_i] &= \Pr[u\notin C \text{ } \forall u\sim v \mid v\in C_i]\\ &= \Pr[u\notin C \text{ } \forall u\in N_i(v) \mid v\in C_i]\\
    &\geq \Pr[u\notin C \text{ } \forall u\in N_i(v)\mid v\in C_i, s_i < 4a_{i+1})]\cdot \Pr[s_i < 4a_{i+1}\mid v\in C_i]\\
    &\geq \left(1-4a_{i+1}\cdot \frac{1}{e^2\cdot a_{i+1}}\right)\cdot (1/2)\\
    &\geq \left(1-4e^{-2}\right)\cdot (1/2)\\
    & \geq \frac{1}{5}
\end{align}

where (2) and (4) follow from the discussion above. Given the lower bounds on $\Pr[v\in C_i]$ and $\Pr[v\in \mathcal{I}\mid v\in C_i]$, we are ready to give a lower bound on the probability that a node $v$ is included in $\mathcal{I}$. 

~\\\noindent\textbf{Lower bounding $\Pr[v\in \mathcal{I}]$:} Since the $I_i$'s are disjoint, we have that:

\begin{align*}
\Pr[v\in \mathcal{I}] &= \sum_{i=1}^k \Pr[v\in C_i \cap \mathcal{I}]\\
&=\sum_{i=1}^k \Pr[v\in \mathcal{I}\mid v\in C_i]\cdot \Pr[v\in C_i]\\
&\geq \sum_{i=1}^k \frac{1}{5}\cdot \frac{1}{2\cdot e^4\Delta}\\
&\geq \frac{\log^*\Delta}{10^4\Delta}
\end{align*}

as desired.
