\begin{defn}\label{def:golden}\textbf{(Golden Iterations)}\\
    For a node $v\in V(G^{(t)})$, let $L^{(t)}_v$ be the set of neighbors $u\in V(G^{(t)})$ of $v$ for which $d^{(t)}_u\leq \ell$. We say that an iteration $t'$ of the for loop in Line 3 in Algorithm~\ref{alg:preshattering} is a golden iteration for a node $v$ if $d^{(t')}_v\geq 1/\ell$ and $\sum_{u\in L^{(t')}_v} p^{(t')}_u\geq d^{(t')}_v/(100\ell^2)$. We denote by $g^{(t)}_v$ be the number of golden iterations $t'\in [t]$ for $v$.
\end{defn}

%\If{$p_v^{(t)} = p_v^{(t-1)} = \tau$}
         %   \State $h_v^{(t)} \gets h_v^{(t-1)} + 1$
        %\Else
         %   \State $h_v^{(t)} \gets h_v^{(t-1)}$
        %\EndIf

\begin{defn}\label{def:deg}\textbf{(Degree Reduction Iterations)}\\
    We say that an iteration $t'$ is a degree reduction iteration for a node $v$ if $p^{(t')}_v = p^{(t'-1)}_v = \tau$. We denote by $h^{(t)}_v$ the number of degree reduction iterations $t'\in [t]$ for $v$.
\end{defn}

\begin{lem}\label{lem:golden-rounds}
Deterministically, for every vertex $v\in V(G^{(T)})$, $T \le h_v^{(T)} + 3g_v^{(T)} + 6\log_\ell \Delta$.
\end{lem}

\begin{proof}
%\aaron{Check $d_v^{(t)}$ superscripts carefully; make sure that they shouldn't be $t+1$ or $t-1$}. 
Let $N^{(t)}_v\subseteq V(G^{(t)})$ be the set of surviving neighbor of $v$ in the $t$'th iteration, and recall that $L^{(t)}_v$ is the set of neighbors $u\in N^{(t)}_v$ of $v$ for which $d^{(t)}_u\leq \ell$. First, we show that for every $t$ that is not a golden iteration  (i.e., $g_v^{(t)} = g_v^{(t-1)}$) and $d_v^{(t)} > 1/\ell$, $d_v^{(t+1)} \le 2d_v^{(t)}/\ell$. This is because, for such an iteration $t$, we have that:

\begin{align*}
d_v^{(t+1)} &= \sum_{u\in N^{(t+1)}_v} p_u^{(t+1)}\\
&\leq \sum_{u\in N^{(t)}_v} p_u^{(t+1)}\\
&= \sum_{u\in L_v^{(t)}} p_u^{(t+1)} + \sum_{u\in N^{(t)}_v\setminus L_v^{(t)}} p_u^{(t+1)}\\
&\le \sum_{u\in L^{(t)}_v} \ell p_u^{(t)} + \sum_{u\in N^{(t)}_v\setminus L_v^{(t)}} \frac{p_u^{(t)}}{\ell}\\
&< \ell\frac{d_v^{(t)}}{100\ell^2} + \frac{d_v^{(t)}}{\ell}\\
&\le \frac{2d_v^{(t)}}{\ell}
\end{align*}

For any $t$, the update rule for $p^{(t)}_v$ ensures that $d_v^{(t+1)} \le \ell d_v^{(t)}$. Hence, we can upper bound the number of $t\in [T]$ for which $d_v^{(t)} > \ell$, as follows. For any $t\in [T]$, let $e_v^{(t)}$ denote the number of $s\le t$ for which $d_v^{(s)} > \ell$. Consider two $a \le b\in \{2,3,\hdots,T\}$ with the property that $d_v^{(s)} > \ell$ for all $s$ with $a\le s\le b-1$, but with $d_v^{(a-1)} \le \ell$ as well. Observe that $d_v^{(a-1)} > 1/\ell$, so for all $s$ with $a-1 \le s \le b-1$ we have that:

$$d_v^{(s+1)} \le (2/\ell)^{1 - (g_v^{(s)} - g_v^{(s-1)})} \ell^{g_v^{(s)} - g_v^{(s-1)}} d_v^{(s)}$$ 

Thus,

$$\ell < d_v^{(b)} \le (2/\ell)^{b+1-a-(g_v^{(b-1)}-g_v^{(a-2)})}\ell^{g_v^{(b-1)}-g_v^{(a-2)}}d_v^{(a-1)} \le \ell^{(3/2)(g_v^{(b-1)}-g_v^{(a-2)}) - (b+1-a)/2}\ell$$

which implies that $b+1-a \le 3(g_v^{(b-1)}-g_v^{(a-2)})$. Furthermore, the number of iterations it takes to get out of the first interval $[0,\cdots, a]$ in which $d^{a'}_v> \ell$ for all $a'\in [a]$ is at most $\log_{\ell}(d^{0}_v)\leq \log_{\ell}(\Delta\cdot \tau)\leq 6\log_{\ell}\Delta$. Hence, summing over all possible intervals $[a,\cdots,b]$ for which $d^{a'}_v> \ell$ for every $a'\in [a]$ yields that $e_v^{(T)} \le 3g_v^{(T)} + 6\log_\ell \Delta$.

Next, we use the bound on $e_v^{(T)}$ to bound $T$. Each iteration counted by $e_v^{(T)}$ decreases $p_v^{(t)}$ by a factor of exactly $\ell$, while each iteration besides the ones counted by $h_v^{(T)}$ increases $p_v^{(t)}$ by a factor of exactly $\ell$. All other iterations do not change $p_v^{(t)}$. Thus,

$$\tau \ge p_v^{(T)} = \ell^{T - h_v^{(T)} - e_v^{(T)}}p_v^{(0)} = \ell^{T - h_v^{(T)} - e_v^{(T)}}\tau$$

Thus, $T - h_v^{(T)} - e_v^{(T)} \le 0$, which means that $T \le h_v^{(T)} + 3g_v^{(T)} + 6\log_\ell \Delta$ as desired.
\end{proof}

