The following lemma is analogous to Lemma 4.1 in~\cite{Ghaffari16} and Lemma 3.2 in~\cite{BarenboimEPS16}. For completeness, we give a detailed proof in Appendix~\ref{app:diff}.

\begin{lem}\label{lem:ruling-survival}
Let $X$ be a set of vertices in $G$ for which the distance between any pair of vertices in $X$ within $G$ is at least 10. Then,

$$\Pr[\forall v\in X : v\in V(G^{(T)}) \text{ and } g_v^{(T)} \ge T/50] \le \gamma^{|X|T/50}$$

where $\gamma := 2e^{-(\log^*\Delta)^{24/25}/10^{10}}$.
\end{lem}

The following lemma is analogous to Lemma 4.2 in~\cite{Ghaffari16} and the discussion after it, and Lemma 3.3 and the discussion in Section 3.2 in~\cite{BarenboimEPS16}. For completeness, we give a full proof in Appendix~\ref{app:diff}.

\begin{lem}\label{lem:shattering-small-components}
    Let $Y: = \{ v \in V(G^{(T)}) : g_v^{(T)} \ge T / 50 \}$, and let $H$ be the graph induced by the nodes in $Y$. There is a $\poly(\log\log n)$-round algorithm that finds an MIS in $H$ with high probability.
\end{lem}


\begin{lem}\label{lem:deg-bound} Let $Y: = \{ v \in V(G^{(T)}) : g_v^{(T)} \ge T / 50 \}$. Deterministically the graph induced by 
$V(G^{(T)})\setminus Y$ has maximum degree $10\ell/\tau$.
\end{lem}

\begin{proof}
Suppose, for the sake of contradiction, that there exists $v\in V(G^{(T)})\setminus Y$ that has at least $z = 10^8\ell/\tau$ neighbors $u_1,u_2,\hdots,u_z$ for which $u_i \in V(G^{(T)})\setminus Y$ for all $i\in [z]$. By Lemma \ref{lem:golden-rounds}, $h_v^{(T)} \ge 9T/10$ and $h_{u_i}^{(T)} \ge 9T/10$ for all $i\in [z]$. We now will obtain contradictory bounds for the quantity

$$S = \sum_{t\in [T]:h_v^{(t)}\ne h_v^{(t-1)}} d_v^{(t-1)}$$

First, we obtain an upper bound. Recall that $h_v^{(t)} \ne h_v^{(t-1)}$ implies that $d_v^{(t-1)} \le \ell$ and $p_v^{(t)} = p_v^{(t-1)} = \tau$. By the first implication,

$$S \le \sum_{t\in [T]:h_v^{(t)}\ne h_v^{(t-1)}} \ell = h_v^{(T)}\ell \le T\ell$$

Next, we obtain a lower bound. For each $u_i$, there are at least $T - T/10 - T/10 = 4T/5$ values of $t$ for which both $h_v^{(t)}\ne h_v^{(t-1)}$ and $h_{u_i}^{(t)}\ne h_{u_i}^{(t-1)}$. Thus,

$$S \ge \sum_{i=1}^z \sum_{t\in [T]:h_v^{(t)}\ne h_v^{(t-1)} \text{ and } h_{u_i}^{(t)}\ne h_{u_i}^{(t-1)}} p_{u_i}^{(t-1)} \ge z (4T/5)\tau > T\ell$$

a contradiction, as desired.
\end{proof}


\begin{proof}[Proof of Theorem \ref{thm:main-girth}]
%The call to $\text{Mohsen}(H')$ at the end ensures that the returned independent set is a maximal independent set, so it suffices to bound the runtime and error probability. 

We run the pre-shattering algorithm (Algorithm~\ref{alg:preshattering}) for $T=O(\log_{\ell}\Delta)$ rounds. By Lemma~\ref{lem:golden-rounds}, each node either experiences $O(T)$ golden iterations or $O(T)$ degree reduction iterations. By Lemma~\ref{lem:shattering-small-components}, there is a $\poly(\log\log n)$-round algorithm that finds an MIS in the graph induced by the nodes who experience $O(T)$ golden iterations. By Lemma~\ref{lem:deg-bound} we can then use the deterministic $O(\Delta'+\log^*n)$ algorithm by~\cite{Kuhn09,BarenboimE09,BarenboimEK14}, where $\Delta'=O(\ell/\tau)\ll \poly(\log\log n)$, in the remaining graph induced by the nodes who experience $O(\log_{\ell}\Delta)$ degree reduction iterations, which takes $\ll \poly(\log\log n)$ rounds. 
\end{proof}

Before proving Theorem~\ref{thm:trees}, let us recall the following theorem from~\cite{BarenboimEPS16}.

\begin{thm}[Theorem 7.2 in~\cite{BarenboimEPS16}]\label{thm:deg-arb}
Let \( G \) be a graph of arboricity \( \lambda \) and maximum degree \( \Delta \), and let \( t \geq \max \{(5\lambda)^8, (4(c+1) \ln n)^7\} \) be a parameter. In \( O(\log_t \Delta) \) rounds, we can find an independent set \(\mathcal{I}\) such that, with probability at least \( 1 - n^{-c} \), the maximum degree in the graph induced by \( V(G) \setminus \mathcal{I} \) is at most \( t\lambda \).

\end{thm}

Now we are ready to prove Theorem~\ref{thm:trees}. Let us restate it for convenience.

\thmtrees*
\begin{proof}[Proof of Theorem~\ref{thm:trees}]
    We first use Theorem~\ref{thm:deg-arb} with $t=2^{\sqrt{\log n\cdot \log(\log^* n)}}$. Since the arboricity $\lambda=1$ in trees, this implies that the maximum degree of the tree becomes $\Delta'\leq 2^{\sqrt{\log n\cdot \log(\log^* n)}}$ in $O(\sqrt{\log n/\log(\log^* n)})$ rounds. Thus, by using Theorem~\ref{thm:main-girth}, we can find an MIS in the remaining tree in $O(\log(\Delta')/\log(\log^*\Delta') + \poly(\log\log n)) = O(\sqrt{\log n/\log(\log^* n)})$ rounds, as desired.
\end{proof}


