\section{Standard Exponent Approximation}

\begin{prop}\label{prop:exp-approx}
For any $\delta > 0$ and $x\in (0,1-\delta)$,

$$e^{-x-x^2/\delta} \le 1 - x \le e^{-x}$$
\end{prop}

\begin{proof}
Apply $\ln$ to both sides. Recall that, for any $x\in (0,1)$,

$$\ln(1 - x) = -\sum_{i=1}^{\infty} \frac{x^i}{i}$$

Since $x > 0$, $\ln(1 - x) \le -x$, completing the upper bound. For the lower bound, use a geometric series upper bound. Specifically,

\begin{align*}
\ln(1 - x) &= -x - \frac{x^2}{2} - \sum_{i=3}^{\infty} \frac{x^i}{i}\\
&\ge -x - \frac{x^2}{2} - x^2 \sum_{i=3}^{\infty} (1 - \delta)^{i-2}\\
&= -x - \frac{x^2}{2} - x^2 (1 - \delta)/\delta\\
&\ge -x - \frac{x^2}{\delta}\\
\end{align*}

as desired.
\end{proof}


\section{Differed Proofs from Section~\ref{sec:full}}\label{app:diff}

%Our algorithm is inspired by, but differs in crucial ways from Ghaffari's Algorithm \aaron{Cite}. Thus, we wanted to make our result entirely self-contained. In this section, we prove our post-shattering-step in Lemmas \ref{lem:ruling-survival} and \ref{lem:shattering-small-components}, which were originally proven in \aaron{Cite}. In particular, we prove Lemma \ref{lem:ruling-survival} in more detail than was present in \aaron{Cite}, clarifying details around the usage of adversarial coinflips.

%Whenever a vertex experiences a golden round, its survival probability decreases by a factor of $\gamma$, making it possible to prove Lemma \ref{lem:ruling-survival}. To extract the full benefit of these decreases, we need to exploit both the independence of decisions made by vertices within $X$ in a round and the independence of randomness across rounds. One can try to obtain this by unrolling the effect randomness from all $T$ rounds for one vertex at a time \aaron{mention that Ghaffari does this}. Intuitively, one would try to exploit the fact that $v$'s survival should not depend on randomness unrolled for future vertices in $X$. However, this is tricky to formalize. To formalize this, we need to define an event $E_v$ related to the survival of a vertex $v\in X$ after $T$ rounds. Here are two attempts at a definition, both of which are flawed:

%\begin{enumerate}
 %   \item Let $E_v$ be the set of randomness realizations for all vertices in $G$ from all rounds that lead to $v$ surviving. $E_v$ depends on randomness from all vertices, making exploitation of the high distance between vertices in $X$ impossible.
  %  \item Let $E_v$ be the set of randomness realizations for all vertices within $G$-distance 10 of $v$ for which there exists a realization of randomness for all other vertices that makes $v$ survive. This definition allows us to exploit independence across $X$. However, the fact that $v$ deterministically experiences at least $T/50$ golden rounds is not enough to establish that $\Pr[E_v] \le \gamma^{T/50}$. One would need to be able to do a union bound to remove the existence quantifier to establish this.
%\end{enumerate}

%Instead, we handle all of the vertices in $X$ simultaneously by conditioning on all possible transcripts of golden round occurrences for vertices in $X$. We describe each transcript as a tuple of subsets $(Z^{(t)})_{t=1}^T$ of $X$. For each tuple, we can unroll the survival probability of $X$ by writing the probability as a product of two terms: one capturing effects of round $T$ and the other capturing effects of all prior rounds. The round $T$ term can be upper bounded by exploiting independence across $X$. The other term can be bounded inductively by applying the same idea to round $T-1,T-2,\hdots,1$. For each transcript, the survival probability is as low as desired thanks to the deterministic guarantee on golden rounds, so the desired result holds by the exclusivity of the transcript options.

We now give the proof of Lemma \ref{lem:ruling-survival}. In the proof, we use the following notation:  For a tuple of sets $(S^{(a)})_{a\in I}$ for some integer $a$ and set of integers $I$, define $|S| := \sum_{a\in I} |S^{(a)}|$.

\begin{proof}[Proof of Lemma~\ref{lem:ruling-survival}]
For each $t\in [T]$, define a set-valued random variable $W^{(t)}\subseteq X$ to be the set of all $v\in X$ for which both $t$ is a golden iteration for $v$ (i.e., $g_v^{(t)} = g_v^{(t-1)} + 1$) and $g_v^{(t)} \le T/50$. Let $\mathcal{Z}$ denote the family of all $T$-tuples of sets $(Z^{(t)})_{t=1}^T$, where $Z^{(t)} \subseteq X$ for all $t\in [T]$ and each member of $X$ appears in exactly $T/50$ different sets $Z^{(t)}$. Since choices of $(Z^{(t)})_{t=1}^T$ for $(W^{(t)})_{t=1}^T$ are mutually exclusive,

\begin{align*}
    &\Pr[\forall v\in X : v\in V(G^{(T)}) \text{ and } g_v^{(T)} \ge T/50]\\
    &= \sum_{(Z^{(t)})_{t=1}^T \in \mathcal{Z}} \Pr[(\forall v\in X : v\in V(G^{(T)})) \text{ and } (\forall t\in [T] : W^{(t)} = Z^{(t)})]
\end{align*}

For each $t\in \{0,1,2,\hdots,T-1,T\}$, let $\mathcal{P}^{(t)}$ denote the family of all $t$-tuples of sets $P^{(s)} \subseteq X$ for which each member of $X$ appears in at most $T/50$ different sets $P^{(s)}$. $\mathcal{P}^{(0)}$ is defined to be the singleton family consisting just of the empty tuple. We now show for all $t\in \{0,1,\hdots,T\}$ that

\begin{align*}
    &\Pr[\forall v\in X : v\in V(G^{(T)}) \text{ and } g_v^{(T)} \ge T/50]\\
    &\le \sum_{(P^{(s)})_{s=1}^t \in \mathcal{P}^{(t)}} \gamma^{|X|T/50 - |P|}\Pr[(\forall v\in X : v\in V(G^{(t)})) \text{ and } (\forall s\in [t] : W^{(s)} = P^{(s)})]
\end{align*}

We prove this by induction in descending order of $t$. For $t = T$, the result holds trivially because $\mathcal{Z} \subseteq \mathcal{P}^{(T)}$. For the inductive step, consider some $t \in \{0,1,\hdots,T-1\}$ and assume that the result holds for $t+1$. In particular, we are given that

\begin{align*}
&\Pr[\forall v\in X : v\in V(G^{(T)}) \text{ and } g_v^{(T)} \ge T/50]\\
&\le \sum_{(P^{(s)})_{s=1}^{t+1} \in \mathcal{P}^{(t+1)}} \gamma^{|X|T/50 - |P|}\Pr[(\forall v\in X : v\in V(G^{(t+1)})) \text{ and } (\forall s\in [t+1] : W^{(s)} = P^{(s)})]\\
&= \sum_{(P^{(s)})_{s=1}^{t+1} \in \mathcal{P}^{(t+1)}} \gamma^{|X|T/50 - |P|}\Pr[(\forall v\in X : v\in V(G^{(t+1)})) \text{ and } W^{(t+1)} = P^{(t+1)} \text{ and } (\forall s\in [t] : W^{(s)} = P^{(s)})]\\
\end{align*}

$W^{(s)}$ for all $s\in [t+1]$ is a function of the randomness only from the first $t$ iterations of the for loop. $G^{(t)}$ is also only a function of the randomness from the first $t$ iterations. Given $G^{(t)}$, the event $\{\forall v\in X : v\in V(G^{(t+1)})\}$, i.e. survival of all $X$ in iteration $t+1$, is only a function of the randomness from the $t+1$th iteration of the for loop. Recall that $\text{Inclusion}$ is the only source of randomness in the algorithm and that survival within round $t+1$ only depends on randomness in the 3-neighborhood of a given vertex. Thus, being distance $\ge 10$ apart ensures that neighborhoods are disjoint and that the events $\{v\in V(G^{(t+1)})\}$ are conditionally independent given $G^{(t)}$. Therefore,

\begin{align*}
&\Pr[(\forall v\in X : v\in V(G^{(t+1)})) \mid W^{(t+1)} = P^{(t+1)} \text{ and } (\forall s\in [t] : W^{(s)} = P^{(s)})]\\
&= \E_{G^{(t)}}\left[\Pr\left[(\forall v\in X : v\in V(G^{(t+1)})) \mid G^{(t)}\right] \mid (\forall s\in [t+1] : W^{(s)} = P^{(s)})\right]\\
&= \E_{G^{(t)}}\left[\prod_{v\in X}\Pr\left[v\in V(G^{(t+1)}) \mid G^{(t)}\right] \mid (\forall s\in [t+1] : W^{(s)} = P^{(s)})\right]\\
&\le \E_{G^{(t)}}\left[\prod_{v\in P^{(t+1)}}\Pr\left[v\in V(G^{(t+1)}) \mid G^{(t)}\right] \mid (\forall s\in [t+1] : W^{(s)} = P^{(s)})\right]\\
&\le \E_{G^{(t)}}\left[\gamma^{|P^{(t+1)}|} \mid (\forall s\in [t+1] : W^{(s)} = P^{(s)})\right]\\
&= \gamma^{|P^{(t+1)}|}
\end{align*}

Since $W^{(t+1)}$ is defined if and only if $X\subseteq V(G^{(t)})$,

\begin{align*}
&\sum_{(P^{(s)})_{s=1}^{t+1} \in \mathcal{P}^{(t+1)}} \gamma^{|X|T/50 - |P|}\Pr[(\forall v\in X : v\in V(G^{(t+1)})) \text{ and } W^{(t+1)} = P^{(t+1)} \text{ and } (\forall s\in [t] : W^{(s)} = P^{(s)})]\\
&\le \sum_{(P^{(s)})_{s=1}^{t+1} \in \mathcal{P}^{(t+1)}} \gamma^{|X|T/50 - |P| + |P^{(t+1)}|}\Pr[W^{(t+1)} = P^{(t+1)} \text{ and } (\forall s\in [t] : W^{(s)} = P^{(s)})]\\
&= \sum_{(P^{(s)})_{s=1}^t \in \mathcal{P}^{(t)}} \gamma^{|X|T/50 - |P|}\Pr[(\forall v\in X : v\in V(G^{(t)})) \text{ and } (\forall s\in [t] : W^{(s)} = P^{(s)})]\\
\end{align*}

completing the induction step, where the last equality uses the exclusivity of choices for $P^{(t+1)}$. Thus, plugging in $t = 0$ shows that

$$\Pr[\forall v\in X : v\in V(G^{(T)}) \text{ and } g_v^{(T)} \ge T/50] \le \gamma^{|X|T/50}$$

as desired.
\end{proof}

Next, we prove Lemma \ref{lem:shattering-small-components}. %This is the same proof as the one given for Lemma \aaron{Cite Ghaffari}.

\begin{proof}[Proof of Lemma~\ref{lem:shattering-small-components}]
Given a decomposition of a graph into clusters $\{C_i\}_{i}$, the clustering graph is defined to be the graph where each cluster $C_i$ is a node, and each two nodes $C_i$ and $C_j$ are connected if there is an edge from some node $u\in C_i$ to some node $v\in C_j$ in the original graph. An $(r,c)$ network decomposition is a decomposition of the graph into clusters where the radius of each cluster is at most $r$ and clustering graph has chromatic number at most $c$. Given an $(r,c)$ network decomposition for $H$, one can find an MIS in $H$ in $O(r\cdot c)$ rounds by going over the color classes one at a time, and each time find an MIS for the clusters of the current color class (after deleting all the nodes found in previous independent sets together with their neighbors).

Hence, to prove the lemma, we show that $H$ admits an $\left(O(\log\log^2 n), O(\log\log n)\right)$ network decomposition that can be found efficiently. For this, we find a $(10, 100\log\log n)$-ruling set $R$ of $H$ by using the algorithm of~\cite{GfellerV07,SchneiderEW13}, which takes $O(\log\log n)$ rounds.\footnote{An $(\alpha,\beta)$-ruling set is a set of nodes where any two nodes in the set are at distance at least $\alpha$ from each other, and any other node is at distance at most $\beta$ from some node in the ruling set.} Then, we make a cluster $C_v$ around each node $v\in R$, where each node $u \in V(H)$ joins the cluster of the closest $v\in R$, with ties broken arbitrarily. Let $H_R$ be the clustering graph corresponding to the clusters $\{C_v\}_{v\in R}$. To show that $H$ admits an $\left(O(\log\log^2 n), O(\log\log n)\right)$ network decomposition, it suffices to show that $H_R$ admits an $(O(\log\log n),O(\log\log n))$-network decomposition (and that it can be found efficiently together with the coloring of the clusters). Indeed, given such an $(O(\log\log n),O(\log\log n))$-network decomposition $\mathcal{C}_R$ for $H_R$ we can obtain a clustering $\mathcal{C}$ for $H$ as follows. Recall that each cluster in $\mathcal{C}_R$ is a union of riling-set clusters. For each $C'\in \mathcal{C}_R$, we define a cluster $C$ in $H$ that contains all the nodes in the union of all the ruling-set clusters in $C$. This implies an $O(\log\log n)^2$-radius, $O(\log\log n)$-color network decomposition $\mathcal{C}$ of $H$.

Thus, it remains to show that $H_R$ admits the desired $(O(\log\log n),O(\log\log n))$-network decomposition, and that it can be found efficiently. Recent algorithms show that in a graph with $n'$ nodes, an $(O(\log n'),O(\log n'))$-network decomposition can be found in $\tilde{O}(\log^2(n'))$ rounds deterministically.\footnote{Prior algorithms already imply $(O(\polylog n'),O(\polylog n'))$-network decomposition, which would suffice for our purposes. The very recent algorithm by~\cite{ecomposition} improves the polynomial in our $\poly(\log\log n)$ runtime for this lemma.} Hence, it suffices to show that each connected component of $H_R$ has at most $100\log_{\Delta} n$ vertices with high probability. Suppose, for the sake of contradiction, that there is a connected set $X\subseteq R$ with $|X| \ge 100\log_{\Delta} n$ in $H_R$. By construction of $H_R$, these vertices are also connected in $G^{(T)}$. We construct a set of nodes $Y\subseteq V(G^{(T)})$ as follows. First, we add all the nodes in $X$ to $Y$. Then, while there exists a vertex in $V(G^{(T)})$ with $G$-distance at least $10$ from some node in $Y$, we add this vertex to $Y$. The connectedness of $X$ in $G^{(T)}$ implies that any vertex in $Y$ is within $G$-distance 21 of some other vertex in $Y$. However, no such sets exist with high probability, because the number of such sets in $G$ is at most $n\Delta^{21|X|}$ and a union bound with Lemma \ref{lem:ruling-survival} implies that such a set exists with probability at most

$$\gamma^{|Y|T/50}n\Delta^{21|Y|} \le n\Delta^{-|Y|} \le n\Delta^{-|X|} \le n^{-50}$$

Thus, each connected component of $H_R$ has at most $O(\log_{\Delta} n)$ with high probability, as desired. 

\end{proof}

\section{Simple One-Round Lower Bound}\label{sec:lb}

In this section, we demonstrate the fundamental nature of the constant survival probability barrier when using previous approaches. As discussed in Section~\ref{sec:TO}, all randomized MIS algorithms in the literature, as well as ours, do not rely on vertex identifiers.


\begin{thm}\label{thm:lb}
    Let $G$ be a $\Delta$-regular graph without any constant-length cycles. Any randomized distributed one-round algorithm with no vertex IDs that always returns an independent set $\mathcal{I}$ has the property that each node is in $\mathcal{I}$ or is adjacent to a node $\mathcal{I}$ with probability at most $p=1 - 1/(2e) + 1/\Delta$.
\end{thm}

This hardness result shows that all 1-round algorithms for independent set have constant vertex survival probability. This is in contrast with Lemma \ref{lem:weighted-logstar}, which shows that there is a 2-round algorithm for independent set with subconstant vertex survival probability.

To prove Theorem \ref{thm:lb}, we start viewing 1-round no-vertex-ID LOCAL algorithms for independent set in a simpler way. For any integer $k$, let $\mathcal{S}_k$ be the family of sets of numbers with size exactly $k$. A family of sets $\mathcal{V}\subseteq [0,1]\times \mathcal{S}_{\Delta}$ is called an \emph{independence family} if an only if for any set $S\in \mathcal{S}_{\Delta+1}$ and any distinct $u,v\in S$, either $(v,S\setminus \{v\})\notin \mathcal{V}$ or $(u,S\setminus \{u\})\notin \mathcal{V}$. For an independence family $\mathcal{V}$, let

$$P_{\mathcal{V}} := \Pr_{x\sim [0,1], \forall i\in [\Delta]: y_i\sim [0,1], S_i\sim \mathcal{S}_{\Delta-1}}[\forall i\in [\Delta] : (y_i,S_i\cup \{x\})\notin \mathcal{V} \text{ and } (x,\{y_1,y_2,\hdots,y_{\Delta}\})\notin \mathcal{V}]$$

In this probability, $x$ and all $y_i$s are sampled uniformly from $[0,1]$, and $S_i$ is sampled uniformly from $\mathcal{S}_{\Delta-1}$, all independently. This corresponds with sampling all randomness in a 2-neighborhood and assessing the probability that the vertex with rank $x$ survives. We now show the following:

\begin{prop}\label{prop:local-independence-equiv}
    All 1-round no-vertex-ID randomized LOCAL algorithms for independent set have vertex survival probability at least $P_{\mathcal{V}^*}$, where $\mathcal{V}^*$ is an independence family that minimizes $P_{\mathcal{V}^*}$.
\end{prop}

\begin{proof}
    For every 1-round no-vertex-ID LOCAL algorithm $A$, there is an associated independence family $\mathcal{V}_A$ of 1-neighborhood views that lead to inclusion in the independent set. This family is an independence family because of the fact that $A$ always outputs an independent set, and $(u,S\setminus \{u\})$ and $(v,S\setminus \{v\})$ can be adjacent to each other in a $\Delta$-regular graph that has no constant-length cycles. $P_{\mathcal{V}_A}$ is the survival probability of a vertex (with rank $x$) when the algorithm $A$ is applied, as randomness tapes for different vertices are all distinct with probability 1. Minimizing over all valid algorithms $A$ gives the desired result.
\end{proof}

Next, we upper bound the inclusion probability of a 1-round algorithm, where we fix one rank as done in Lemma \ref{lem:weighted-logstar}:

\begin{prop}\label{prop:hardness-inclusion}
    For any $x\in [0,1]$ and any independence family $\mathcal{V}$,

    $$\Pr_{y\sim [0,1], S\sim \mathcal{S}_{\Delta-1}}[(y,S\cup \{x\}) \in \mathcal{V}] \le \frac{1}{\Delta}$$
\end{prop}

\begin{proof}
    We can alternatively sample the pair $(y,S)$ by (a) sampling $T$ uniformly from $\mathcal{S}_{\Delta}$, (b) sampling $y$ uniformly from $T$, and (c) defining $S := T\setminus \{y\}$. Since $\mathcal{V}$ is an independence family, there exists at most one $z\in T$ for which $(z, T\cup \{x\}\setminus \{z\})\in \mathcal{V}$. Since $y$ is sampled uniformly,

    $$\Pr_{y\sim T_0}[(y,S\cup \{x\}) \in \mathcal{V} \mid T = T_0] \le \frac{1}{\Delta}$$

    for any $T_0\in \mathcal{S}_{\Delta}$. Taking the expectation over all possible $T_0$ shows that

    $$\Pr_{T,y}[(y,S\cup \{x\}) \in \mathcal{V}] \le \frac{1}{\Delta}$$

    as desired.
\end{proof}

We can now use independence to get the desired lower bound on survival probability:

\begin{proof}[Proof of Theorem \ref{thm:lb}]
Define $\mathcal{V}^*$ as in Proposition \ref{prop:local-independence-equiv}. For any $x\in [0,1]$,

$$\Pr_{\forall i\in [\Delta] : y_i\sim [0,1], S_i\sim \mathcal{S}_{\Delta-1}}[\forall i\in [\Delta] : (y_i, S_i)\notin \mathcal{V}^*] \ge (1 - 1/\Delta)^{\Delta} \ge 1/(2e)$$

by independence and Proposition \ref{prop:hardness-inclusion}. Taking the expectation over $x$ shows that

$$\Pr_{x\sim [0,1], \forall i\in [\Delta] : y_i\sim [0,1], S_i\sim \mathcal{S}_{\Delta-1}}[\forall i\in [\Delta] : (y_i, S_i)\notin \mathcal{V}^*] \ge 1/(2e)$$

Taking the expectation over $x$ in Proposition \ref{prop:hardness-inclusion} and replacing $y$ from the proposition with $x$ from this proof shows that

$$\Pr_{x\sim [0,1], \forall i\in [\Delta] : y_i\sim [0,1]}[(x, \{y_1,y_2,\hdots,y_{\Delta}\})\in \mathcal{V}^*] \le \frac{1}{\Delta}$$

Therefore, by a union bound, $P_{\mathcal{V^*}}\ge 1/(2e) - 1/\Delta$. Proposition \ref{prop:local-independence-equiv} yields the desired result.
\end{proof}

