%%                                  %%
%% UPPER BOUND ON THE FLIP DISTANCE %%
%%                                  %%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Upper Bound on the Flip Distance via \cref{thm:alpha}\eqref{item:alpha-upper-bound}}
\label{subsec_upper}

In this subsection, we assume that \cref{thm:alpha}\eqref{item:alpha-upper-bound} holds, and show how to derive \cref{thm:main-upper-bound} from it.
That is, we prove an upper bound of $\nicefrac 53\cdot(n-1)$ on the flip distance of two non-crossing trees $T$ and $T'$ on $n$ points by finding a large acyclic subset of the corresponding conflict graph $H$.
By \cref{thm:alpha}\eqref{item:alpha-upper-bound} we have $\dist(T,T') \leq \max\left\{\frac32,2-\frac{\las(H)}{|V(H)|}\right\} (n-1)$, so we seek to prove that $\las(H) \geq \nicefrac 13 \cdot |V(H)|$ whenever $H$ is non-empty.

Recall that a \enormal{} edge is incident to exactly one vertex at its corresponding gap.
We can think of a \enormal{} edge $e_i$ (or $e'_i$) to ``start'' at gap $i$ (either at $p_i$ or $p_{i+1}$) and then ``go'' either left or right.
Clearly, each \enormal{}-\enormal{} pair $(e,e')$ starts at the same gap.
Moreover, observe that $e$ and~$e'$ go in the same direction if and only if $e$ and~$e'$ are adjacent, i.e., have a common endpoint (which is then necessarily at the gap).


%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% ABOVE, BELOW, CROSSING %%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In order to prove a lower bound on $\las(H)$, and hence an upper bound on $\dist(T,T')$, let us inspect the gaps more closely.
We partition the set $I_N$ of all \enormal{}-\enormal{} gaps into three subsets, distinguishing for each gap with a corresponding \enormal{}-\enormal{} pair, whether these two edges are adjacent, and (in case they are) which edge is longer.
For each gap $g_i \in I_N$ with \enormal{}-\enormal{} pair $(e_i,e'_i) \in \pairs_N$, we say that
% 
\begin{itemize}
    \item $g_i$ is \emph{above} if $e_i$ and $e'_i$ are adjacent and $e_i$ is longer than $e'_i$,
    \item $g_i$ is \emph{below} if $e_i$ and $e'_i$ are adjacent and $e_i$ is shorter than $e'_i$, and
    \item $g_i$ is \emph{crossing} if $e_i$ and $e'_i$ are not adjacent.
\end{itemize}
% 
We denote the set of all above (respectively below, crossing) gaps in $I_N$ by $A$ (respectively $B$, $C$).
By definition, $A$, $B$, $C$ are pairwise disjoint, and hence $|A| + |B| + |C| = |I_N| \leq n-1$.

\begin{lemma}
    \label{lem:ABC-acyclic}
    Each of $A$, $B$, $C$ is an acyclic subset of $H$.
    In particular, $\las(H) \geq \nicefrac13 \cdot|V(H)|$.
\end{lemma}
%
\begin{proof}
    To prove that $Y \in \{A,B,C\}$ is acyclic, we show that there is some gap $g^* \in Y$ without incoming edges in $H[Y]$.
    By removing $g^*$ from $Y$ and repeating the argument, it follows that $Y$ is acyclic.
    We separately consider the three possible choices of $Y$.

    \begin{description}
	\item[Case $Y = A$:]
            Consider a gap $g_j \in A$ such that the length of $e_j$ is minimal.
            We claim that the gap $g_j$ has no incoming edge in $H[A]$. 
            Without loss of generality, we assume that $e_j$ and $e'_j$ share their left endpoint as illustrated in \cref{fig:ABC-acyclicA}; otherwise consider the mirror image.
            We show that $g_j$ has no incoming edge in $H[A]$ of any of the three types~1, 2, and~3.
            By the choice of $g_j$, $e_j$ does not cover any edge $e_i$ with $g_i \in A$; otherwise $e_i$ would be shorter than $e_j$.
            This excludes incoming edges of type~1 and~2.
            Further, for any $g_i \in A$ with $e_i$ covering $e_j$ and $e'_j$, then the gap $g_i$ cannot be covered by $e'_j$.
            This excludes incoming edges of type~3.

	\item[Case $Y = B$:]
	    This is symmetric to the previous case by exchanging the roles of $T$ and $T'$.
            In particular, any $g_j \in B$ such that the length of $e'_j$ is minimal has no incoming edges in $H[B]$.

	\item[Case $Y = C$:]
            Observe from \cref{fig:conflict-edge} that all directed edges in $H[C]$ are of type~1.
            Indeed, if $\overrightarrow{g_ig_j}$ is an edge of type~2, then $g_j \in B$, and if $\overrightarrow{g_ig_j}$ is an edge of type~3, then $g_i \in A$.

            It follows that $\overrightarrow{g_i g_j}$ is an edge in $H[C]$ if and only if $e_i$ crosses~$e'_j$.
            In order to find a $g_j \in C$ that has no incoming edge, we shall resort to basic geometry:             
            Consider the \representation of $T$ and $T'$ with horizontal spine, but restricted only to the edges corresponding to gaps in $C$.
            For each $g_i \in C$ with pair $(e_i,e'_i)$, let $Z_i \sse \mathbb{R}^2$ be the union of the two open semicircles for $e_i$ and $e'_i$ (each shortened a bit at both endpoints).
            Due to the shortening, the elements of $\{Z_i \mid g_i \in C\}$ are pairwise disjoint; see \cref{fig:ABC-acyclicC}.

            \begin{figure}[ht]
                \centering
                \begin{subfigure}{.3\textwidth}
                    \centering
                    \includegraphics[page=5]{Intro}
                    \caption{}
                    \label{fig:ABC-acyclicA}
	        \end{subfigure}\hfil
                \begin{subfigure}{.6\textwidth}
                    \centering
                    \includegraphics{C-is-acyclic-new}
                    \caption{}
                    \label{fig:ABC-acyclicC}
                \end{subfigure}
                \caption{
                    Illustration for the proof of \cref{lem:ABC-acyclic}.
                    (a) Case $Y=A$: Each of the red dashed edges is not there by the choice of $e_j$.
                    (b) Case $Y=C$: Gaps $g_2,g_4,g_6,g_7,g_9,g_{11}$ in $C$ and the corresponding $\{Z_i \mid g_i \in C\}$. Only $Z_9$ is not covered by any other $Z_i$.
                }
                \label{fig:C-is-acyclic}
            \end{figure}

            We say that a set $Y \sse \mathbb{R}^2$ is \emph{above} a set $X \sse \mathbb{R}^2$ if at least one $y \in Y$ lies vertically above at least one $x \in X$.
            Crucially, if $\overrightarrow{g_i g_j}$ is an edge in $H[C]$, then $Z_i$ is above $Z_j$.
            We claim that for some $Z_j$ no $Z_i$ is above $Z_j$, and hence $g_j \in C$ has no incoming edges in $H[C]$.
            To find $Z_j$, consider the rightmost point $r(Z_i)$ of each $Z_i$.
            (Using slight perturbations, we may assume that the $r(Z_i)$ have pairwise distinct $x$-coordinates.)
            There is at least one $r(Z_j)$ with no $Z_i$ above it; near $p_n$ at the latest.
            Among all rightmost points with no $Z_i$ above it, we pick the leftmost; say it is $r(Z_j)$ belonging to $g_j \in C$.
            Suppose (for the sake of a contradiction) some $Z_i$ is above $Z_j$.
            Then consider a rightmost point $q \in Z_j$ with some $Z_i$ above $q$.
            By the choice of $Z_j$, we have $q \neq r(Z_j)$.
            But then the rightmost point $r(Z_i)$ of $Z_i$ must be above $q$, and, by the choice of $q$, $r(Z_i)$ has no $Z_k$ above it --- a contradiction to the choice of $Z_j$, since $r(Z_i)$ lies further left than $r(Z_j)$.
            Hence, no $Z_i$ is above $Z_j$, and thus $g_j$ has no incoming edge $\overrightarrow{g_i g_j}$ in $H[C]$.
    \end{description}

    In each case $Y \in \{A,B,C\}$ we have found a gap $g^* \in Y$ with no incoming edges in $H[Y]$.
    Removing $g^*$ and repeating the argument shows that $H[Y]$ is acyclic.
\end{proof}

Together, \cref{lem:ABC-acyclic} and \cref{thm:alpha}\eqref{item:alpha-upper-bound} immediately imply an upper bound on~$\diam(\mathcal{F}_n)$, which, up to a small additive constant, is the same as~\cref{thm:main-upper-bound}. The full statement of~\cref{thm:main-upper-bound} follows from~\cref{thm:careful-main-upper-bound}.

\begin{corollary}
    \label{cor:5-over-3-upper-bound}
    Let $T,T'$ be any pair of two non-crossing trees on a convex set of $n$ points.
    Then the flip distance $\dist(T,T')$ is at most $\nicefrac53\cdot(n-1)$.
    In other words, $\diam(\mathcal{F}_n)\leq \nicefrac53\cdot(n-1)$.
\end{corollary}
% 
\begin{proof}
    If $H$ is empty, then \cref{thm:alpha}\eqref{item:alpha-upper-bound} guarantees a flip distance of at most $\nicefrac32\cdot(n-1)$.
    If $H$ is non-empty, then \cref{lem:ABC-acyclic} states that $\frac{\las(H)}{|V(H)|} \geq \nicefrac13$ and \cref{thm:alpha}\eqref{item:alpha-upper-bound} implies an upper bound of $\max\left\{\nicefrac32, 2-\nicefrac13\right\}\cdot(n-1) = \nicefrac53\cdot(n-1)$.
\end{proof}


