\section{Proof of \cref{thm:alpha}}
\label{sec_proof_alpha}

We now prove \cref{thm:alpha}, which relates the size of acyclic subsets of conflict graphs with upper and lower bounds for $\diam(\mathcal{F}_n)$, and is the key ingredient to \cref{thm:careful-main-upper-bound,thm:main-lower-bound,thm:main-upper-bound}.
We prove \cref{thm:alpha}\eqref{item:alpha-upper-bound} in \cref{subsec_upper_alpha} and \cref{thm:alpha}\eqref{item:alpha-lower-bound} in \cref{subsec_lower_alpha}.


%%%%%%%%%%%%%%%%%
%%             %%
%% UPPER BOUND %%
%%             %%
%%%%%%%%%%%%%%%%%
\subsection{Upper Bound}
\label{subsec_upper_alpha}

%%%%%%%%%%%%%%%%%%%%%%
%% GENERAL STRATEGY %%
%%%%%%%%%%%%%%%%%%%%%%
Recall that we want a flip sequence that transforms $T$ into $T'$.
With each flip we remove an edge and replace it by a new edge.
This way, we can trace each edge from its initial to its final position.
In particular, every flip sequence naturally pairs the edges of $T$ with those of~$T'$. 
Our approach for the upper bound is to let $\pairs$ be this pairing, i.e., to convert each edge $e$ of $T$ into the edge $e'$ of $T'$ with $(e,e') \in \pairs$.
For each pair $(e,e') \in \pairs$ we will do at most two flips.
More precisely, in our flip sequence, every gap $g_i$, $i \in [n-1]$ and the corresponding pair $(e_i,e'_i) \in \pairs$ shall have exactly one of the following properties.
% 
\begin{description}
    \item[$0$-flip:] 
        $e_i = e'_i$ and the edge $e_i$ is never replaced, keeping $e_i=e'_i$ in every intermediate tree.
    \item[$1$-flip:]
        $e_i \neq e'_i$ and the edge $e_i$ is replaced by $e'_i$ in a single, direct flip.
    \item[$2$-flip:] 
        $e_i \neq e'_i$, the edge $e_i$ is replaced by the boundary edge $p_ip_{i+1}$ in one flip, and $p_ip_{i+1}$ is replaced by $e'_i$ in a later flip.    
\end{description}
% 
Clearly, the total number of flips in our flip sequence is then the number of $1$-flips plus two times the number of $2$-flips.
Our goal is to have as few $2$-flips as possible.

%%%%%%%%%%%%%%%%%%%%
%% TYPES OF PAIRS %%
%%%%%%%%%%%%%%%%%%%%
Recall the partition of $\pairs$ into $\pairs_=,\pairs_N,\pairs_R$.
As mentioned before, we shall spend no flips on pairs in $\pairs_=$ and in total at most $\frac32|\pairs_R| + |\pairs_=|$ flips on pairs in $\pairs_R$.
For the pairs in $\pairs_N$, we shall do a $1$-flip for those corresponding to an acyclic subset of the conflict graph $H$, and spend a $2$-flip for the remaining pairs in $\pairs_N$.
But first, let us present sufficient conditions for the validity of these flip.

%%%%%%%%%%%%%%%%%%%%%%%%%%
%% FLIPPING TO BOUNDARY %%
%%%%%%%%%%%%%%%%%%%%%%%%%% 
Recall that every non-crossing edge-set $E$ on linearly ordered points $p_1,\ldots,p_n$ that covers all gaps has a corresponding map $\rho_E \colon \{g_1,\ldots,g_{n-1}\} \to E$, and that by \cref{lem_gap_edge_bij}, the set $E$ forms a tree if and only if $\rho_E$ is a bijection.

\begin{lemma}
    \label{lem:validFlip}
    Let $T$ be a non-crossing tree on linearly ordered points $p_1,\ldots,p_n$, and let $e_k = \rho_{T}(g_k)$ for $k = 1,\ldots,n-1$.

    Fix an edge $e_j \in T$ and consider an edge $e' = p_xp_y$ with $e' \notin T$, such that $e'$ covers $g_j$, and $e'$ does not cross any edge in $T - e_j$, and there is no $e_i\in T - e_j$ such that
    \begin{alphaenumerate}
        \item $e'$ covers $e_i$, and $e_i$ covers $g_j$, or \label{item:require-a}
        \item $e_i$ covers $e'$, and $e'$ covers $g_i$.\label{item:require-b}
    \end{alphaenumerate}
    Then, for $T' := (T - e_j) + e'$, each of the following holds.
    \begin{romanenumerate}
        \item $T'$ is a non-crossing tree, i.e., $\rho_{T'}$ is a bijection.\label{item:flip-non-crossing}

        \item Each edge $e \in T \cap T' = T - e_j$ corresponds to the same gap in $T$ and $T'$ ($\rho_{T}^{-1}(e) = \rho_{T'}^{-1}(e)$); the edge $e'$ corresponds to $g_j$ in $T'$ ($e' = \rho_{T'}(g_j)$).\label{item:flip-new-gaps}

        \item Each edge $e \in T \cap T' = T - e_j$ is \eshort{} (respectively \enormal{}, \eweird{}) in $T$ if and only if $e$ is \eshort{} (respectively \enormal{}, \eweird{}) in $T'$.\label{item:flip-same-types}
    \end{romanenumerate}
\end{lemma}
% 
\begin{proof}
    We first show \eqref{item:flip-non-crossing}.
    Note that $T'$ is non-crossing as $e'$ crosses no edge in $T - e_j$ by assumption.
    To show that $T'$ is a tree, by \cref{lem_gap_edge_bij}, it suffices to show that $\rho_{T'} \colon \{g_1,\ldots,g_{n-1}\} \to T'$ is a bijection.
    In fact, gap $g_j$ is covered by $e'$ and each $g_i \neq g_j$ is still covered by $e_i \in T-e_j$.
    As $|T'| = n-1$, it suffices to show that $\rho_{T'}$ is injective.
    By \eqref{item:require-a}, $\rho_{T'}(g_j) = e'$, and by \eqref{item:require-b}, $\rho_{T'}(g_i) = e_i$ for all $i\neq j$.
    Thus, $\rho_{T'}$ is a bijection and $T'$ a tree.

    In fact, we already know $\rho_{T'}$ explicitly, and can also conclude \eqref{item:flip-new-gaps}.
    Finally, \eqref{item:flip-same-types} follows from~\eqref{item:flip-new-gaps}, since the type of an edge $e$ depends only on $e$ and its associated gap.
\end{proof}

We use \cref{lem:validFlip} in particular for two special cases, namely, for $2$-flips when $e'$ is a boundary edge and for $1$-flips when the gap of $e'$ has no incoming edges in a subgraph $H[Y]$ of $H$.
For convenience, we show that the preconditions are fulfilled in these two cases.

\begin{lemma}\label{lem:flip-to-boundary}
    The preconditions of \cref{lem:validFlip} are fulfilled if we choose $e'$ as the boundary edge $p_jp_{j+1}$.
\end{lemma}
% 
\begin{proof}
    Clearly, a boundary edge does not cross any edge of $T$.
    Moreover, $e'$ is a \eshort{}edge that covers no edge of $T$ and covers only one gap, namely $g_j$, proving that no edge $e_i \in T - e_j$ has property \eqref{item:require-a} or \eqref{item:require-b}.
\end{proof}

\begin{lemma}\label{lem:validFlipAc}
    The preconditions of \cref{lem:validFlip} are fulfilled if $\pairs_R=\emptyset$, $g_j$ has no incoming edge in $H$ and $e'$ is chosen such that $(e_j,e')\in \pairs_N$, i.e., we flip $e_j$ for $e' = e'_j$.
\end{lemma}
% 
\begin{proof}
    Note that no \eshort{} edge of $T$ can violate a precondition of \cref{lem:validFlip}, since any such edge can cover neither $e'$ nor $g_j$.
    As $\pairs_R=\emptyset$ by assumption, the only edges of $T$ that remain to be checked are edges $e_i$ that belong to a pair $(e_i,e'_i)\in \pairs_N$.
    If $e'$ crosses such an edge $e_i$ of $T - e_j$, then there is the incoming edge $\overrightarrow{g_ig_j}$ of type~1 at $g_j$ in $H$.
    Secondly, if an edge $e_i$ of $T - e_j$ has property \eqref{item:require-a}, respectively \eqref{item:require-b}, then there is the incoming edge $\overrightarrow{g_ig_j}$ of type~2, respectively type~3, at $g_j$ in $H$.
\end{proof}

Recall that for a gap $g_i$ and non-crossing tree $T$, the edge $e_i = \rho_T(g_i)$ is \eweird{} if $e_i$ is neither incident to $p_i$ nor $p_{i+1}$.
We next bound the number $|\TW|$ of \eweird{} edges of $T$ in terms of the number $|\TS|$ of \eshort{} edges in $T$. 

\begin{lemma} 
   \label{lem_tiny_vs_weird}
    Let $T$ be a non-crossing tree on linearly ordered points $p_1,\ldots,p_n$. 
    Let $k\geq 1$ be the number of uncovered edges of $T$.
	Then $|\TS| \geq k$ and $|\TW| \leq |\TS|-k$.
\end{lemma}
%
\begin{proof} 
    Consider the cover relation of the edges of $T$ (with respect to the given linear order).
    Let us write $e \preceq f$ whenever $e$ is covered by $f$.
    Trivially, every edge $e \in T$ covers itself, i.e., $e \preceq e$.
    Since $e \preceq e'$ and $e' \preceq e''$ implies $e \preceq e''$, we have that $(T, \preceq)$ forms a partial order. 
    Moreover, since $T$ is non-crossing, it holds that for every $e\in T$, its upset $\{e' \in T \mid e \preceq e'\}$ is totally ordered, implying that the Hasse diagram of $(T,\preceq)$ is a rooted forest~$R$.
    The roots of~$R$ are the $k$ uncovered edges of $T$. 
    The nodes without children of~$R$ are the \eshort{} edges of $T$. 
    For an example, consider \cref{fig:rootedForest}.
    %
    \begin{figure}[htb]
	\centering
	\includegraphics[page=26]{Intro}
        \caption{
            Illustration for the proof of \cref{{lem_tiny_vs_weird}}.
            Example of a tree $T$ and the corresponding rooted forest $R$ consisting of three trees. 
            The root of the middle tree of $R$ is a \eweird{} edge of $T$.
        }
        \label{fig:rootedForest}
    \end{figure}
    %
    For convenience, we refer to any node without children as a leaf, even if it also the root of a tree.
    {Clearly, every rooted tree has at least one leaf}. 
    Consequently, $|\TS| \geq k$ follows from the fact that  $R$ consists of $k$ trees.

    To prove the second statement of the lemma, namely $|\TW| \leq |\TS|-k$, we show that any \eweird{} edge of~$T$ has at least two children in $R$. 
    By the well-known fact that the number of leaves in a rooted tree is at least one plus the number of nodes with at least two children, and our earlier observation that the {leaves} of~$R$ are the \eshort{} edges of $T$, $|\TW| \leq |\TS|-k$ follows.

    Let $e = p_ip_j$ be a \eweird{} edge with gap $g_k$ between $p_k$ and $p_{k+1}$. 
    Then $i<k$ and $k+1<j$.
    Let $e_i = \rho_T(g_i)$ be the edge with gap $g_i$, and let $e_{j-1} = \rho_T(g_{j-1})$ be the edge with gap $g_{j-1}$.
    The edges $e$, $e_i$, and $e_{j-1}$ are all different, since they have pairwise different gaps.
    Since $i<k$ and $k+1<j$, we have $e_i \preceq e$ and $e_{j-1} \preceq e$.
    Furthermore, any edge $f\neq e$ that covers both $e_i$ and $e_{j-1}$ also covers the points $p_k$ and $p_{k+1}$.
    However, since $g_k$ is the gap of $e$, it follows that $f$ also covers $e$.
    Hence, $e_i$ and $e_{j-1}$ are children of $e$ in $R$.
\end{proof}

Recall that we plan to flip some edges $e_i$ of $T$ to the boundary edge $p_ip_{i+1}$ corresponding to the gap $g_i$ of $e_i$.
In general, for a subset $I$ of gaps, let us denote by $T_I$ the graph obtained from $T$ by replacing, for each gap $g_i\in I$, the edge $e_i$ of $T$ by the corresponding boundary edge $p_ip_{i+1}$.
If $e_i$ is already \eshort{}, then $e_i = p_ip_{i+1}$; i.e., this replacement does not change anything and hence no flip os required.
Otherwise, $e_i \to p_ip_{i+1}$ always constitutes a valid flip by~\cref{lem:flip-to-boundary}.
In particular, \cref{lem:validFlip,lem:flip-to-boundary} assert that $T_I$ is a non-crossing tree and that there is a valid flip sequence $T \to \cdots \to T_I$.
The length of this flip sequence is the number of gaps in $I$ \emph{not} corresponding to \eshort{} edges of $T$. 

The following proposition states the number of flips that are required for handling the edges corresponding to pairs $\pairs_R \cup  \pairs_= \cup X$, where $X$ corresponds to the subset of edge pairs in $\pairs_N$ for which we make a $2$-flip in our final flip sequence.
Note that the proposition gives two partial flip sequences, since we will make all $1$-flips for pairs in  $\pairs_N$ between the first and the second flip of any $2$-flip of a pair in $\pairs$. 
This way, we will be able to use~\cref{lem:validFlipAc} for the pairs in $\pairs_N \setminus X$.
Recall that $I_=,I_R,I_N$ are the subsets of gaps corresponding to $\pairs_=,\pairs_R,\pairs_N$, respectively. 
We will especially consider the gaps in $I_R$ that correspond do a \eshort{}edge in $T$ or $T'$, since for those, we will require only 1 flip in our final flip sequence.

\begin{proposition}
    \label{prop:flip-to-boundary}
    Let $T,T'$ be two non-crossing trees on linearly ordered points $p_1,\ldots,p_n$, and $X \sse I_N$ be any (possibly empty) subset of the gaps corresponding to the \enormal{}-\enormal{} pairs.
    Then there are flip sequences $T \to \cdots \to T_{I_R \cup X}$ and $T'_{I_R \cup X} \to \cdots \to T'$ with in total at most $\frac32 |I_R| + |I_=| + 2|X| - 1$ flips.
\end{proposition}
% 
\begin{proof}
    Consider any $g_i \in I_R \cup X$ and the corresponding pair $(e_i,e'_i)$.
    If $g_i \in I_R$, at most one of $e_i,e'_i$ is \eshort{}.
    If $g_i \in X \subseteq I_N$, none of $e_i,e'_i$ is \eshort{}.
    Let $\IRS = \{g_i \in I_R \mid \text{$e_i$ is \eshort{}}\}$ and $\IRSp = \{g_i \in I_R \mid \text{$e'_i$ is \eshort{}}\}$.
    Then $\IRS \cap \IRSp = \emptyset$, since \eshort{}-\eshort{} pairs are in $I_=$ only.
    For the first flip sequence $T \to \cdots \to T_{I_R \cup X}$ we do (in any order) for every $g_i \in (I_R \cup X) - \IRS$ a flip that replaces $e_i$ by $p_ip_{i+1}$.
    This is a valid flip sequence by \cref{lem:flip-to-boundary}, and clearly transforms $T$ into $T_{I_R \cup X}$.
    It uses $|(I_R \cup X) - S| = |I_R - \IRS| + |X| = |I_R| - |\IRS| + |X|$ flips.
    Similarly, there is a valid flip sequence $T' \to \cdots \to T'_{I_R \cup X}$ that uses $|I_R| - |\IRSp| + |X|$ flips.
    Its reverse is the desired flip sequence $T'_{I_R \cup X} \to \cdots \to T'$.  

    In total, both flip sequences have $2|I_R| - (|\IRS| + |\IRSp|) + 2|X|$ flips.
    It remains to prove that $|\IRS| + |\IRSp| \geq \frac12|I_R| - |I_=| + 1$.
    To this end, note that every gap in $I_R - (\IRS \cup \IRSp)$ involves at least one \eweird{} edge.
    Recall that $\TW$ and $\TS$ denote the set of all \eweird{} and all \eshort{} edges in $T$, respectively.
    By \cref{lem_tiny_vs_weird}, we have $|\TW| \leq |\TS| - 1$ and $|\TWp| \leq |\TSp| - 1$.
    Moreover, $|\TS| + |\TSp| \leq |\IRS| + |\IRSp| + 2|I_=|$.
     Together we conclude 
    \[
        |I_R| \leq |\IRS| + |\IRSp| + |\TW| + |\TWp| \leq |\IRS| + |\IRSp| + |\TS| + |\TSp| - 2 \leq 2(|\IRS| + |\IRSp| + |I_=|) - 2,
    \]
    which gives the desired $|\IRS| + |\IRSp| \geq \frac12|I_R| - |I_=| + 1$.
\end{proof}

\cref{prop:flip-to-boundary} works for any subset $X \sse I_N$ of the \enormal{}-\enormal{} gaps.
We content ourselves with spending a $2$-flip on each gap in $X$ (reflected by the $2|X|$ term in the bound of \cref{prop:flip-to-boundary}), but aim to do a direct $1$-flip on each gap in $Y = I_N - X$.
For larger $|Y|$ we obtain an overall shorter flip sequence.
So we want a large set of \enormal{}-\enormal{} pairs that can all be done as $1$-flips.
These flips shall form a valid flip sequence $T_{I_R \cup X} \to \cdots \to T'_{I_R \cup X}$, connecting the two sequences obtained by \cref{prop:flip-to-boundary}.
As all the edges for gaps in $I_R \cup X$ are flipped to boundary edges in $T_{I_R \cup X}$ and $T'_{I_R \cup X}$, we can ``safely ignore'' all pairs corresponding to gaps in $I_= \cup I_R \cup X$ and focus on the \enormal{}-\enormal{} pairs corresponding to~$Y$.

\begin{proposition}
    \label{prop:flip-NN}
    Let $T,T'$ be two non-crossing trees on linearly ordered points $p_1,\ldots,p_n$, and $Y \sse I_N$ be an acyclic subset in $H = H(T,T')$, and $X=I_N-Y$.
    Then there is a flip sequence $T_{I_R \cup X}\to \dots \to T'_{I_R \cup X} $ with $|Y|$ flips.
\end{proposition}
% 
\begin{proof}
    Let $T_1:=T_{I_R \cup X}$ and $T_2:=T'_{I_R \cup X}$.
    \cref{lem:validFlip} guarantees that \enormal{}-\enormal{} pairs of $T,T'$ corresponding to gaps in $Y$ are still \enormal{}-\enormal{} pairs of $T_1,T_2$.
    Moreover, we have $\pairs_R=\emptyset$ for $T_1,T_2$.
    In particular, the conflict graph of $T_1,T_2$ is $H[Y]$.
    Because $H[Y]$ is acyclic, there exists a topological ordering $\prec$ of $H[Y]$.
    The first gap $g$ in $\prec$ has no incoming edges in $H[Y]$, and \cref{lem:validFlipAc,lem:validFlip} ensure that the direct flip of the corresponding pair $(e,e')$ of $g$ is valid and maintains all gap-assignments and types of edges.
    We repeat with direct flips for all pairs corresponding to $Y$ in the order given by $\prec$, until we reach $T_2$.
    As we spent one flip per pair, the resulting flip sequence has length $|Y|$.
\end{proof}


