%%                                     %%
%% CONFLICT GRAPHS AND ACYCLIC SUBSETS %%
%%                                     %%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Putting Things Together -- Proof of \cref{thm:alpha}\eqref{item:alpha-upper-bound}}

Now, we show how to obtain a short flip sequence from a large acyclic subset.

\begin{theorem*}[corresponding to \cref{thm:alpha}\eqref{item:alpha-upper-bound}]{\ \\}
    Let $T,T'$ be two non-crossing trees on linearly ordered points $p_1,\ldots,p_n$ with conflict graph $H = (V(H),E(H))$.
    Then the flip distance $\dist(T,T')$ is at most \mbox{$\max\left\{\frac32,2-\frac{\las(H)}{|V(H)|}\right\} (n-1)$} if $H$ is non-empty, and at most $\frac32(n-1)$ if $H$ is empty.
    \label{thm:large-acyclic-small-distance}
\end{theorem*}
% 
\begin{proof}
    First assume that $H$ is non-empty.
    Let $Y \sse I_N = V(H)$ be an acyclic subset of $H$ with $|Y| = \las(H)$.
    Let $\prec$ be a topological ordering of $H[Y]$.
    Denoting $X = I_N - Y$, our flip sequence $F$ from  $T $ to $T'$ is composed of three parts:
    % 
    \begin{description}
        \item[$F_1$:]
            $T \to \cdots \to T_{I_R \cup X}$ replaces (in any order) each non-\eshort{} edge $e_i \in T$ with $g_i \in I_R \cup X$ by the boundary edge $p_ip_{i+1}$.

        \item[$F_2$:]
            $T_{I_R \cup X} \to \cdots \to T'_{I_R \cup X}$ replaces in order according to $\prec$ each edge $e_i \in T$ with $g_i \in Y$ by the edge $e'_i \in T'$.

        \item[$F_3$:]
            $T'_{I_R \cup X} \to \cdots \to T'$ replaces (in any order) each boundary edge $p_ip_{i+1}$ with $g_i \in I_R \cup X$ and $p_ip_{i+1} \notin T'$ by the non-\eshort{} edge $e'_i \in T'$.
    \end{description}

    By \cref{prop:flip-to-boundary}, the sequences $F_1$ and $F_3$ are valid and have a total length of $|F_1|+|F_3|=\frac32 |I_R| + |I_=| + 2|X| - 1$.
    \cref{prop:flip-NN} ensures that $F_2$ is valid and has length $|Y|=|I_N| - |X|$.
    With $|Y| = \las(H)$ and $I_N=V(H)$ we conclude that
    % 
    \begin{align*}
        \dist(T,T') &\leq |F_1|+|F_2|+|F_3|\leq \frac32|I_R| + |I_=| + |I_N| + |X| = \frac32|I_R| + |I_=| + 2|I_N| - |Y| \\
        &\leq \frac32(|I_R|+|I_=|) + \left(2-\frac{|Y|}{|I_N|}\right)|I_N| = \frac32(|I_R|+|I_=|) + \left(2-\frac{\las(H)}{|V(H)|}\right)|I_N|\\
        &\leq \max\left\{\frac32,2-\frac{\las(H)}{|V(H)|}\right\} (|I_R|+|I_=|+|I_N|) \leq \max\left\{\frac32,2-\frac{\las(H)}{|V(H)|}\right\} (n-1).
    \end{align*}
    % 
    If $H$ is empty, then $\pairs_N = \emptyset$, and hence, $|I_N| = |X| = 0$.
    Then the above with only $F_1$ and $F_3$ gives $\dist(T,T') \leq \frac32|I_R| + |I_=| \leq \frac32(n-1)$.
\end{proof}


