    \caption{A pair of trees $(T,T')$ and their 2-blowups $(\blowup[2]{T},\blowup[2]{T'})$.}
    \label{fig:blowup}
\end{figure}

Here is the crucial connection between $k$-blowups and the conflict graph $H$ of $T,T'$.

\begin{observation}
    \label{obs:crossing-in-blowups}
    If $\overrightarrow{g_ig_j}$ is a directed edge in the conflict graph $H$ of $T,T'$, then in the $k$-blowups $\blowup{T},\blowup{T'}$ every edge in $\Lambda(e_i)$ crosses every edge in $\Lambda(e'_j)$.
\end{observation}
% 
\begin{proof}
    If $\overrightarrow{g_ig_j}$ is of type~1, then already $e_i$ and $e'_j$ cross and hence so do their fans.
    For $\overrightarrow{g_ig_j}$ of type~2 and type~3, it follows from the fact that the points $V(e_i)$ and $V(e'_j)$ lie in the gaps $g_i$ and $g_j$ of the original point set, respectively; see~\cref{fig:crossing-in-blowup} for illustrations.
\end{proof}

