	\includegraphics[page=2]{crossing-in-blowup}
        \caption{$\overrightarrow{g_i g_j}$ of type~3}
        \label{fig:crossing-in-blowup-type3}
    \end{subfigure}
    \caption{A directed edge $\overrightarrow{g_ig_j}$ of type~2 (a) or type~3 (b), makes $\Lambda(e_i)$ crossing $\Lambda(e'_j)$.}
    \label{fig:crossing-in-blowup}
\end{figure}

Now, we consider any flip sequence~$F$ from $\blowup{T}$ to $\blowup{T'}$ and denote the intermediate trees by $\blowup{T} = \blowupSeq[0], \blowupSeq[1], \dots, \blowupSeq[\ell] = \blowup{T'}$.
For each $(e,e')\in \pairs_N$, let $\gone(e)$ be the smallest index $a$ such that $\blowupSeq[a]$ contains no edge in $\Lambda(e)$.
Since \blowup{T'} contains no edge in $\Lambda(e)$, $\gone(e)$ is well-defined.
Evidently, in $F$ there is a flip $\blowupSeq[\gone(e)-1] \to \blowupSeq[\gone(e)]$ that replaces the last remaining edge in $\Lambda(e)$ by an edge not in $\Lambda(e)$.
We say that the pair $(e,e')$ is \emph{direct} if there is an $a\leq \gone(e)$ such that $\blowupSeq[a]$ contains an edge in $\Lambda(e')$, and \emph{indirect} otherwise.
These terms are motivated by the fact that in the former case, $F$ might contain a direct flip from an edge in $\Lambda(e)$ to an edge in in $\Lambda(e')$, while in the latter case this is impossible. 

\begin{lemma}
    \label{lem_direct_pairs}
    Let $(e_i,e'_i)\neq (e_j,e'_j)$ be direct pairs in $\pairs_N$.
    If the conflict graph $H$ of $T,T'$ contains the directed edge $\overrightarrow{g_ig_j}$, then $\gone(e_i) < \gone(e_j)$.
\end{lemma}
% 
\begin{proof} 
    We show that if $\gone(e_i)\geq \gone(e_j)$, then there is no edge from $g_i$ to $g_j$ in~$H$.

    Since $\gone(e_i)\geq \gone(e_j)$, $\blowupSeq[\gone(e_j)-1]$ contains an edge of $\Lambda(e_i)$.
    The edge that is flipped away from $\blowupSeq[\gone(e_j)-1]$ in the flip $\blowupSeq[\gone(e_j)-1] \to \blowupSeq[\gone(e_j)]$ is in $\Lambda(e_j)$, so since $\Lambda(e_j)\cap \Lambda(e_i)=\emptyset$ by construction, $\blowupSeq[\gone(e_j)]$ also contains an edge in $\Lambda(e_i)$.
    Thus, $\gone(e_i)> \gone(e_j)$.

    Now choose any $a\leq\gone(e_j)$ such that $\blowupSeq[a]$ contains an edge in $f' \in \Lambda(e'_j)$.
    Since $a \leq \gone(e_j) < \gone(e_i)$, $\blowupSeq[a]$ contains at least one edge of $f \in \Lambda(e_i)$.
    But $\blowupSeq[a]$ is non-crossing, so we have found edges $f\in \Lambda(e_i)$ and $f'\in \Lambda(e'_j)$ that do not cross.
    By \cref{obs:crossing-in-blowups} it follows that $\overrightarrow{g_ig_j}$ is not an edge in $H$.
\end{proof}

Let $\delta$ and $\bar \delta$ denote the number of direct and indirect pairs in $\pairs_N$ of the original pair $T,T'$ of trees induced by the flip sequence $F$ between the blowups $\blowup{T},\blowup{T'}$, respectively.
Clearly, $\delta+\bar \delta=|\pairs_N|$. 
\cref{{lem_direct_pairs}} implies the following crucial property.

\begin{corollary}
    \label{cor_direct_acyclic}
    The conflict graph $H$ has an acyclic subset of size $\delta$, i.e., $\las(H)\geq \delta$. 
\end{corollary}
% 
\begin{proof}
    Let $(e_{i_1},e'_{i_1}), \ldots, (e_{i_\delta},e'_{i_\delta})$ be the direct pairs, sorted so that $\gone(e_{i_1})\leq \dots \leq \gone(e_{i_\delta})$.
    By \cref{lem_direct_pairs}, every edge of $H$ between the gaps of two direct pairs points forward in that ordering.
    Hence, the subgraph of $H$ corresponding to (the gaps of) direct pairs is acyclic.
\end{proof}

Now, we aim to show a lower bound on the flip sequence in terms of the largest acyclic subset in $H$.
Intuitively speaking, we show that for each indirect pair $(e,e')$, the process of removing the $k$ edges in $\Lambda(e)$ and adding the $k$ edges in $\Lambda(e')$ in the flip sequence $F$ must involve introducing almost $k$ ``intermediate'' edges that are neither in $\blowup{T}$ nor in $\blowup{T'}$, which then increases the length of $F$.
\cref{lem_green_graph} below shows that a single indirect pair gives rise to many intermediate edges, i.e., costs additional flips.
\cref{lem_thickened_flip_length} further below shows that costs for different indirect pairs add up.
That is, we cannot ``reuse'' intermediate edges to reduce the cost in any effective way.

\begin{lemma}
    \label{lem_green_graph}
    Let $(e,e')\in \pairs_N$ be an indirect pair.
    Then there is a subgraph $G(e,e')$ of the tree $\blowupSeq[\gone(e)]$ that contains $V(e)$, does not contain any edges in $\blowup{T}$ or $\blowup{T'}$, and has at most $2n-1$ connected components.
\end{lemma}
% 
\begin{proof}
    Let $a=\gone(e)$.
    Because $(e,e')$ is indirect, $\blowupSeq[a] \cap \Lambda(e)$ and $\blowupSeq[a] \cap \Lambda(e')$ are empty.
    We first find a subgraph $E$ of $\blowupSeq[a]$ by doing the following for every edge $f \in \blowupSeq[a] \cap (\blowup{T} \cup \blowup{T'})$:
    % 
    \begin{itemize}
        \item Since $f \notin \Lambda(e)\cup \Lambda(e')$, all the points of $V(e)$ lie on the same side of $f$.
        \item Delete from $\blowupSeq[a]$ all the points (and their incident edges) that are on the other side (without $V(e)$) of $f$, keeping the endpoints of $f$.
    \end{itemize}
    % 
    Note that these deletions do not disconnect $\blowupSeq[a]$, so the remaining subgraph $E \sse \blowupSeq[a]$ is still connected.
    Further note that for every $f \in T \cup T'$ and its fan $\Lambda(f)$ in $\blowup{T}$ or $\blowup{T'}$, no two edges of $f \cup \Lambda(f)$ lie in $E$.
    Indeed, otherwise $V(e)$ lies on the same side of both these edges and one would be deleted when considering the other.
    Consequently, $E$ has at most $n-1$ edges of $\blowup{T}$ and at most $n-1$ edges of $\blowup{T'}$, i.e., $|E \cap (\blowup{T} \cup \blowup{T'})| \leq 2n-2$.
    Then $G(e,e') = E - (\blowup{T} \cup \blowup{T'})$ is the desired subgraph of $\blowupSeq[a]$.
\end{proof}

For the next lemma, recall that $F$ is an arbitrary but fixed flip sequence from $\blowup{T}$ to $\blowup{T'}$.

\begin{lemma}
    \label{lem_thickened_flip_length}
    The flip sequence $F$ from $\blowup{T}$ to $\blowup{T'}$ has length at least $(k-2n)(\bar \delta + |\pairs_N|)$.
\end{lemma}
% 
\begin{proof}
    For each indirect pair $(e,e') \in \pairs_N$, let $G(e,e')$ be the corresponding subgraph of $\blowupSeq[\gone(e)]$ guaranteed by \cref{lem_green_graph}.
    Let $U$ be the union of all $G(e,e')$ over all indirect pairs $(e,e') \in \pairs_N$.
    By \cref{lem_green_graph}, $U$ has at most $(2n-1)\bar \delta$ connected components and at least $k\bar \delta$ points, because it contains the points $V(e)$ for all indirect pairs $(e,e')$, and $|V(e)|=k$.
    Thus, $U$ has at least $k\bar \delta - (2n-1)\bar \delta \geq (k-2n)\bar \delta$ edges, none of which is in $\blowup{T}$ or $\blowup{T'}$.

    Consequently, the flip sequence $F$ has at least $|U| \geq (k-2n)\bar \delta$ flips that introduce an edge of $U$, as well as $|\blowup{T'} \setminus \blowup{T}|$ additional flips that introduce an edge of $\blowup{T'} \setminus \blowup{T}$.
    For each $(e,e')\in \pairs_N$, there are $k$ edges in $\Lambda(e')$ that do not appear in $\blowup{T}$.
    Thus, $|\blowup{T'}\setminus \blowup{T}|\geq k|\pairs_N|$.
    Adding all together, $F$ has length at least $(k-2n)\bar \delta + k|\pairs_N| \geq (k-2n)(\bar \delta + |\pairs_N|)$.
\end{proof}

\begin{lemma}
    \label{lem_rho}
    For any fixed pair $T,T'$ of trees, there is a constant $\constantC$ depending only on $T$ and $T'$, such that for all $k\geq 1$ it holds that 
    \[
        \dist(\blowup{T},\blowup{T'}) \geq \left(2-\frac{\las(H)}{|V(H)|}\right)n_k - c.
    \]
\end{lemma}
% 
\begin{proof}
    By \cref{lem_thickened_flip_length}, any flip sequence from $\blowup{T}$ to $\blowup{T'}$ with $\bar\delta$ indirect flips has length at least $(k-2n)(\bar \delta + |\pairs_N|)$.
    By construction, $\blowup{T}$ (and also $\blowup{T'}$) has $n_k = n+k|\pairs_N|$ points.
    Since $n$ is fixed and hence constant with respect to the total number $n_k$ of points, we get
    % 
    \begin{equation}
        \label{eq_vk}
        \dist(\blowup{T},\blowup{T'})\geq (k-2n)(\bar \delta + |\pairs_N|) \geq k(\bar \delta + |\pairs_N|) - c 
		\geq n_k \frac{\bar \delta + |\pairs_N|}{|\pairs_N|} - c. 
    \end{equation}
    % 
    The vertices of $H$ are in bijection with the pairs in $\pairs_N$, and by \cref{cor_direct_acyclic}, the number $\delta$ of direct pairs in $\pairs_N$ is at most $\las(H)$.
    Thus,
    \[
        \bar \delta = |\pairs_N| - \delta 
        \geq |\pairs_N|-\las(H) 
        = |V(H)|-\las(H).
    \]
    Plugging this with $|V(H)| = |\pairs_N|$ into \cref{eq_vk} completes the proof of the lemma:
    \[
        \dist(\blowup{T},\blowup{T'})\geq n_k \frac{2|V(H)|-\las(H)}{|V(H)|} - c 
		= n_k \left(2-\frac{\las(H)}{|V(H)|}\right) - c.\qedhere
    \]
\end{proof}

\cref{lem_rho} takes care of all $n$ of the form $n_k$ in \cref{thm_Delta}.
The following statement will help to deal with the intermediate values of $n$.

\begin{lemma}
    \label{lem_Fn_nondecreasing}
    The diameter of $\mathcal F_n$ is monotone in $n$, i.e., for any $n \ge 1$ it holds that $\diam(\mathcal{F}_n)\leq \diam(\mathcal{F}_{n+1})$.
\end{lemma}
% 
\begin{proof}
    Let $p_1,\dots, p_{n+1}$ be points in convex position listed in counterclockwise order.
    Let $T$ and $T'$ be non-crossing trees on the vertices $p_1,\dots, p_n$ with $\dist(T,T') = \diam(\mathcal{F}_n)$.
    Let $T_+$ and $T'_+$ be trees on the vertices $p_1,\dots, p_{n+1}$, with $E(T_+) = E(T)\cup \{p_{n+1}p_1\}$ and $E(T'_+) = E(T')\cup \{p_{n+1}p_1\}$.
    Note that $T_+$ and $T'_+$ are non-crossing spanning trees.
    To prove the lemma, it suffices to show that $\dist(T,T')\leq \dist(T_+,T'_+)$, since this implies $\diam(\mathcal{F}_n)\leq \diam(\mathcal{F}_{n+1})$.

    It is known that any common boundary edge stays fixed in any shortest flip sequence between the trees~\cite[Corollary~18]{aichholzer2022reconfiguration}. 
    In particular, this is true for the edge $p_{n+1}p_1$ and any flip sequence between $T_+$ and $T'_+$ of length $\dist(T_+, T'_+)$.
    Take such a sequence and collapse $p_{n+1}$ and $p_1$ to $p_1$, removing the edge $p_{n+1}p_1$ at every step of the sequence.
    This gives a valid flip sequence between $T$ and $T'$, because this collapse does not change connectivity or the existence of cycles or crossings in the graphs.
    Moreover, this sequence has length $\dist(T_+, T'_+)$, showing $\dist(T,T')\leq \dist(T_+,T'_+)$, as desired.
\end{proof}

\begin{proof}[Proof of \cref{thm_Delta}]
    By \cref{lem_rho}, we have a family of pairs of trees $(\blowup{T},\blowup{T'})_{k \geq 1}$ showing the desired lower bound on $\diam(\mathcal{F}_{\largeN})$ for each ${\largeN}$ of the form ${\largeN} = n_k \coloneqq n+k|V(H)|$ for some $k\geq 1$.
    Since $n_{k+1} - n_k$ is constant, it suffices to show that $\diam(\mathcal{F}_{\largeN}) \geq \diam(\mathcal{F}_{n_k})$ for $n_k\leq {\largeN}< n_{k+1}$, which follows from \cref{lem_Fn_nondecreasing}.
\end{proof}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%% beating the lower bound %%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subparagraph{Relation to the previous lower bound.}

One might wonder about a concrete instance where any flip sequence exceeds the previous lower bound.
The proof of \cref{thm:main-lower-bound} implies that for the trees $(T,T')$ depicted in~\cref{fig:exampleLBa} and $k$ large enough, $\dist(\blowup{T},\blowup{T'})$ is larger than the previous lower bound of $\lfloor \nicefrac{3}{2}\cdot n \rfloor -5$ from \cite[Theorem 3.5]{Hernando}, where $n=n_k$ is the number of vertices in $\blowup{T}$. 
But since the theorem involves a non-specified constant, it is not in itself enough to exhibit a concrete example of a pair of trees with a distance that is greater than the previous bound of $\lfloor \nicefrac{3}{2}\cdot n \rfloor -5$.
In the following, we show that for any $k>757$, $\dist(\blowup{T},\blowup{T'}) > \lfloor \nicefrac{3}{2}\cdot n_k \rfloor -5$.
That is, for any $k>757$, $(\blowup{T},\blowup{T'})$ is a pair of trees which beats the best previously known lower bound.

From \cref{lem_thickened_flip_length} and $\delta+\bar \delta = |\pairs_N|$ we know that for any pair $(T,T')$ of trees we have
$
    \dist(\blowup{T},\blowup{T'}) \geq (k-2n)(2|\pairs_N| - \delta).
$
%
Because $|V(H)| = |\pairs_N|$ and $\delta \le \las(H)$ by \cref{cor_direct_acyclic}, we have the following for $k-2n\ge 0$:
\[
    \dist(\blowup{T},\blowup{T'})\geq (k-2n)(2|V(H)| - \las(H)) %= k(2|V(H)| - \las(H))-2n(2|V(H)| - \las(H))
\]
Since $\blowup{T}$ has $n_k = n+k|\pairs_N|=n+k|V(H)|$ points, the previous lower bound for $\dist(\blowup{T},\blowup{T'})$ is 
$
    \lfloor \nicefrac{3}{2}\cdot n_k \rfloor -5 \le \nicefrac{3}{2}\cdot n_k-5 = \nicefrac{3}{2}\cdot n + \nicefrac{3}{2}\cdot k|V(H)|-5.
$
%
Consequently, $\dist(\blowup{T},\blowup{T'})$ exceeds the previous lower bound whenever
% 
\begin{equation}\label{eq:concrete_bound}
   (k-2n)(2|V(H)| - \las(H))> \nicefrac{3}{2}\cdot n + \nicefrac{3}{2}\cdot k|V(H)|-5.
\end{equation}
%
For our concrete trees $T,T'$ from~\cref{fig:exampleLBa}, we have $n=13$, $|V(H)|=9$, and $\las(H)=4$.
Plugging this into~\cref{eq:concrete_bound}, we get $(k-26)(18 - 4)> \nicefrac{3}{2}\cdot 13 + \nicefrac{3}{2}\cdot k\cdot 9-5$, which is equivalent to $k>757$.

We remark that we expect the true value for $k$ to be much smaller, since the the lower bound estimation from \cref{lem_thickened_flip_length,lem_rho} for the length of any flip sequence $F$ from $\blowup{T}$ to $\blowup{T'}$ is obviously far from tight; for $k < 2n$ that bound is is even negative. 
However, this non-optimal lower bound estimation only influences the constant additional term and not on the leading term of the new lower bound, which is one of the main results of this work. 


