\section{Main Results}
%--------------------------------------------------------------------------------------------------------------
The following result is a direct consequence of Proposition~\ref{prop: DAE standard} on the existence of a unique solution to linear DAEs with constant coefficients. Henceforth, it will be used to characterize exact turnpikes in \ref{prob: OCP}.
\begin{corollary}[Unique singular arcs in \ref{prob: OCP}] \label{cor: unique singular arc}
    Let Assumption \ref{ass: technical modeling} hold and let $\tau\in\bigcap_{i=1}^m \mc{T}_{i,=}(T)\neq\emptyset$.
    Then, \ref{prob: OCP} exhibits a unique singular arc in the sense of Definition \ref{def: singular arc} if and only if Assumption \ref{ass: regular pencil} holds. Moreover, on the singular arc, the solution is given by \eqref{eq: singArcSol}.\hfill $\square$
\end{corollary}

%--------------------------------------------------------------------------------------------------------------
\subsection{Time-varying exact turnpikes for DHNs}
%--------------------------------------------------------------------------------------------------------------
Next, we extend the \rev{dissipativity analysis  for stationary turnpikes in \ref{prob: OCP} from \cite{Faulwasser_Automatica17}} to the time-varying case. We provide sufficient conditions for \ref{prob: OCP} to exhibit a time-varying exact turnpike property and we show that a time-varying exact turnpike implies strict dissipativity.% in the sense of Definition~\ref{def: strict dissipativity}.

First, following \cite{tudo:faulwasser22a,Faulwasser_Automatica17}, we recall the definition of a time-varying measure turnpike property. 
Consider an arbitrary infinite-horizon input-state pair $\bar z$  satisfying \eqref{eq: LTI system} and the input constraints and the set %\hg{HG: Die Menge hängt noch vom optimal pair ab, aber das muss doch nicht eindeutig sein? Wie geht man damit um?}
    \begin{equation} \label{eq: defi Theta}
    \Theta_T(\varepsilon):=\{\tau\in[0,T]:\|z_T^\star(\tau, x_0)-\bar{z}(\tau)\|>\varepsilon\},
\end{equation}
    This set is Borel measurable and captures all time points when an optimal pair $z_T^\star$ is outside of an $\varepsilon$ neighborhood of $\bar z$.
\begin{defi}[\rev{Time-varying measure turnpike}] \label{def: turnpike}
     \ref{prob: OCP} exhibits a time-varying turnpike property with respect to ${\bar z}$ if there exists a function ${\nu:[0,\infty)\rightarrow[0,\infty)}$
     such that, for all ${x_0\in\mc{X}}$, all $T>0$, \rev{all optimal $u_T^\star\in L^1([0,T],\mathbb{R}^m)$}, and all $\varepsilon> 0$ we have
    \begin{equation} \label{eq: turnpike}
\mu(\Theta_T(\varepsilon))\leq\nu(\varepsilon)<\infty. 
    \end{equation}
    The optimal pairs $z_T^\star(\cdot, x_0)$ exhibit a time-varying \textit{exact turnpike property} if \eqref{eq: turnpike} holds for $\varepsilon=0$.\hfill $\square$
\end{defi}
The Lebesgue measure $\mu(\Theta_T(\varepsilon))$ quantifies the size $\Theta_T(\varepsilon)$, i.e., the time spent off the time-varying turnpike.
Put differently, Definition \ref{def: turnpike} requires that the time $\mu(\Theta_T(\varepsilon))$  the optimal solutions to \ref{prob: OCP} spend outside an $\varepsilon$-neighborhood of $\bar z$ is bounded by $\nu(\varepsilon)$, where $\nu(\varepsilon)$ is independent of the horizon $T$.
This essentially means that for any $x_0 \in \mc{X}_0$ and for sufficiently large $T>0$, the optimal trajectory $z_T^\star(\cdot, x_0)$ has to enter any arbitrarily small $\varepsilon$-neighborhood of $\bar z$. In the case of $\varepsilon=0$, i.e., the time-varying exact turnpike property, $z_T^\star(\cdot, x_0)$ must be temporarily equal to the turnpike.

Similarly to the results for time-invariant OCPs exhibiting stationary turnpikes, a time-varying turnpike of \ref{prob: OCP} can be shown if strict dissipativity is given.
Hence, we have the following assumption.
\begin{assumption} \label{ass: reachability and dissipativity}
(i) \ref{prob: OCP} is strictly dissipative with respect to ${\bar z\in Z^{1,1}(\rev{[0,\infty)},\mrm{int}(\mc{Z}))}$ in the sense of Definition~\ref{def: strict dissipativity}.
    (ii)  The trajectory ${\bar z\in Z^{1,1}([0,\infty),\mrm{int}(\mc{Z}))}$ is exponentially reachable, i.e., for all $x_0\in\mc{X}_0$, there exist
    an infinite-horizon admissible input ${u_\infty\in L^1([0,\infty),\mc{U})}$, and \rev{${c_1,~c_2\in\R_{>0}}$}, independent of $x_0$, such that, \rev{for all $\tau\geq 0$}, ${\|(x(\tau;u_\infty),u_\infty(\tau))-\bar z(\tau)\|\leq c_1 e^{-c_2\tau}}$ holds.
\end{assumption}

Next, we extend \cite[Thm. 2]{Faulwasser_Automatica17} to the time-varying case.

\begin{proposition}[Strict dissipativity $\Rightarrow$ turnpike] \label{prop: dissipativity to turnpike} 
Let Assumption \ref{ass: reachability and dissipativity} hold.
    Then, \ref{prob: OCP} exhibits a time-varying turnpike property with respect to ${\bar z\in Z^{1,1}([0,T],\mrm{int}(\mc{Z}))}$.\hfill $\square$
\end{proposition}

The proof follows the same steps as the one of \cite[Thm. 2]{Faulwasser_Automatica17} and is omitted due to space limitations.
The next result is an extension of \cite[Thm. 3]{Faulwasser_EJC17} to time-varying exact turnpikes.
\begin{theorem}[Turnpikes in \ref{prob: OCP} are exact]
    Let Assumptions \ref{ass: technical modeling}, \ref{ass: regular pencil} and \ref{ass: reachability and dissipativity} hold. 
    Then, for all $x_0\in\mc{X}_0$ and sufficiently large $T>0$, the turnpike of \ref{prob: OCP} 
    %has to be 
    is exact in the sense of Definition \ref{def: turnpike}.\hfill $\square$
\end{theorem}
\begin{proof}
    Let $\mc{B}_\varepsilon(\bar{z}(\tau))$ denote a closed ball centered at the turnpike at time $\tau$ with radius $\varepsilon>0$.
    From Proposition~\ref{prop: dissipativity to turnpike}, $\mu(\Theta_T(\varepsilon))\leq\nu(\varepsilon)$ follows.
    Thus, ${z_T^\star(\tau)\in\mc{B}_\varepsilon(\bar{z}(\tau))}$ \rev{for all}  ${\tau\in[0,T]\setminus\Theta_T(\varepsilon)}$ and \rev{all} $T>0$. % \todo{R1: "sufficiently large $T > 0$"; however, either it is not clear why this is mentioned, or the argument demands further clarifications.}.
    Let ${\mc{B}_\varrho(\bar{z}(\tau))}$ denote another closed ball centered at $\bar{z}$ at time $\tau$ with radius $\varrho>0$, such that ${\mc{B}_\varrho(\bar{z}(\tau))\subset\mrm{int}(\mc{Z})}$ for ${\tau\in[0,T]}$.
    We define %\todo{R1: The role of $\hat{\epsilon}$ is not clear.}
    \begin{equation} \label{eq: hat epsilon}
        \hat{\varepsilon}=\min_{\tau\in[0,T]}\{\|u_\mrm{min}-\bar{u}(\tau)\|,\|u_\mrm{max}-\bar{u}(\tau)\|,\varrho\}.
    \end{equation}
    \rev{Assumption \ref{ass: reachability and dissipativity} shows that close to the turnpike (in terms of $z^\star_T$) we have $\bar u(\tau)\in\mrm{int}(\mc{U})$} (almost surely) and hence ${\hat{\varepsilon}>0}$ holds. 
    %
    \rev{Consequently, Proposition~\ref{prop: dissipativity to turnpike} yields that} for some ${\varepsilon\in(0,\hat{\varepsilon})}$, sufficiently large ${T>0}$, and ${\tau\in[0,T]\setminus\Theta_T(\varepsilon)}$, we have ${z_T^\star(\tau)\in\mc{B}_\varepsilon(\bar{z}(\tau))}$. Thus, we henceforth analyze \ref{prob: OCP} locally around $\bar{z}$.
    %
    For $\varepsilon\in[0,\hat{\varepsilon})$, $\tau\in[0,T]\setminus\Theta_T(\varepsilon)$, we show  $z_T^\star(\tau)\in\mc{B}_\varepsilon(\bar{z}(\tau))$ implies $z_T^\star(\tau)=\bar{z}(\tau)$ (Steps 1 and 2).
    Step~3 shows $\mu(\Theta_T(0))\leq\nu(\hat{\varepsilon})<\infty$.

    Step 1: We show that for $\varepsilon\in[0,\hat{\varepsilon})$ and $\tau\in[0,T]\setminus\Theta_T(\varepsilon)$
      \begin{equation} \label{eq: step 1}
        z_T^\star(\tau)\in\mc{B}_\varepsilon(\bar z(\tau))\quad \Longrightarrow\quad  u_T^\star(\tau)=\bar u(\tau).
    \end{equation}

    Since $\mc{B}_\varepsilon(\bar z(\tau))\subset\mc{B}_\varepsilon(\bar x(\tau))\times\mc{B}_\varepsilon(\bar u(\tau))$ for $\varepsilon\in[0,\hat{\varepsilon})$, \rev{we have that $u_T^\star(\tau)\in \mc{B}_\varepsilon(\bar u(\tau))$ holds for all $\varepsilon\in[0,\hat{\varepsilon})$ and all $\tau\in[0,T]\setminus\Theta_T(\varepsilon)$. } 
    For $u_T^\star$ solving \ref{prob: OCP}, \rev{and for $\tau\in[0,T]\setminus \mathcal{T}_{i,=}(T)$ for some $i=1,\ldots,m$, we obtain from the PMP that $u_T^\star\in\{u_{\min,i},u_{\max,i}\}$ holds.
    Contrary to that, suppose that $\tau\in\bigcap_{i=1}^m\mathcal{T}_{i,=}(T)$, then the uniqueness of the singular arc (Corollary~\ref{cor: unique singular arc}) implies that  $u_T^\star(\tau)=\overline{u}(\tau)$ holds.
    Consequently, for all $\tau\in[0,T]$}, ${(u_T^\star(\tau))_i \in \{u_{\mrm{min},i}, u_{\mrm{max},i}, \bar u_i(\tau)\},~\text{for all } i=1,\ldots,m,}$ holds.
    That is, the optimal control is component-wise either at its max or min value or at the turnpike. 
    Hence, for all ${\varepsilon\in[0,\hat{\varepsilon})}$ and ${\tau\in[0,T]\setminus\Theta_T(\varepsilon)}$, \eqref{eq: hat epsilon} implies
    \begin{multline*}
        \mc{B}_\varepsilon(\bar u(\tau)) \cap \big( \{u_{\mrm{min},1}, u_{\mrm{max},1}, \bar u_1(\tau)\} \times \cdots \\
        \times \{u_{\mrm{min},m}, u_{\mrm{max},m}, \bar u_m(\tau)\}\big) = \bar u(\tau).
    \end{multline*}
    Put differently, strict dissipativity of the OCP combined with the uniqueness of the singular arc gives that sufficiently close to the turnpike the input can only be at its turnpike value \rev{$\bar u(\tau)$}. Therefore, \eqref{eq: step 1} holds.

    Step 2: From ${u_T^\star(\tau) = \bar u(\tau) \in \mrm{int}(\mc{U})}$ for ${\tau\in[0,T]\setminus\Theta_T(\varepsilon)}$, we conclude that \rev{$\mu\left(\bigcap_{i=1}^m \mc{T}_{i,=}(T)\right)>0$}. % \todo{R1: conclusion not clear}.
    Due to Assumption~\ref{ass: regular pencil}, \ref{prob: OCP} exhibits a unique singular arc for ${\tau\in[0,T]\setminus\Theta_T(\varepsilon)}$. Hence, it follows that
    \begin{equation} \label{eq: step 2}
        z_T^\star(\tau)\in\mc{B}_\varepsilon(\bar z(\tau))\Rightarrow x_T^\star(\tau) = \bar x(\tau).
    \end{equation}
    Combining \eqref{eq: step 1} and \eqref{eq: step 2} gives
    \begin{equation} \label{eq: z at turnpike}
        z_T^\star(\tau)\in\mc{B}_\varepsilon(\bar{z}(\tau)) \Rightarrow z_T^\star(\tau)=\bar{z}(\tau).
    \end{equation}
    Step 3: Proposition~\ref{prop: dissipativity to turnpike} implies $\mu(\Theta_T(\varepsilon))\leq\nu(\varepsilon)<\infty$ for all $\varepsilon>0$. 
    From \eqref{eq: z at turnpike}, we can deduce that, for all ${\varepsilon_1, \varepsilon_2 \in [0,\hat{\varepsilon})}$, it holds that \rev{$\mu(\Theta_T(\varepsilon_1))=\mu(\Theta_T(\varepsilon_2))<\nu(\hat{\varepsilon})$} 
    that is, $\mu(\Theta_T(0))\leq\nu(\hat{\varepsilon})<\infty$.
\end{proof}

\subsection{A converse turnpike result}
A crucial breakthrough in the dissipativity-based turnpike analysis have been converse results, i.e., results which explore the implications of assuming the existence of a turnpike in an OCP, see, e.g., \cite{Gruene16a,Faulwasser_Automatica17}.
The next result, which is a time-varying generalization of \cite[Thm. 7]{Faulwasser_Automatica17} shows that exact time-varying turnpikes imply strict dissipativity.
\begin{proposition}[Exact turnpike $\Rightarrow$ strict dissipativity] \label{prop: turnpike to dissipativity}
    \rev{L}et \ref{prob: OCP} exhibit a time-varying exact turnpike in the sense of Definition \ref{def: turnpike} at ${\bar z\in Z^{1,1}(\rev{[0,\infty)},\mrm{int}(\mc{Z}))}$. %Let Assumption~\ref{ass: exact turnpike} hold.

    \rev{If $\bar z$ is bounded, }
    then \ref{prob: OCP} is strictly dissipative with respect to ${\bar z}$ \rev{and all $\alpha\in\mathcal{K}$}.\hfill $\square$
\end{proposition}
\begin{proof}
    Choose any $\alpha\in\mc{K}$, $x_0\in\mathcal{X}_0$ and an optimal control $u_T^\star(x_0)\in L^1([0,T],\mc{U})$ for \ref{prob: OCP}. Let $\varepsilon=0$ and split the horizon $[0,T]$ into $\Theta_T(0)$ and $\Delta = [0,T]\setminus\Theta_T(0)$.
    We aim to derive an upper bound on the integral in the available storage $\mc{S}^\mrm{a}(x_0)$ that is given by \eqref{prob: Verify dissipativity}:
    \begin{align}
    &~~~~-\int_0^T\ell_{\bar z,\alpha}(\tau,z_T^\star(\tau))\mathrm{d}\tau \nonumber \\&
    =-\int_{\Theta_T(0)}\ell_{\bar z,\alpha}(\tau,z_T^\star(\tau))\mathrm{d}\tau -\int_\Delta \ell_{\bar z,\alpha}(\tau,z(\tau))\mathrm{d}\tau \nonumber \\&\leq\int_{\Theta_T(0)}|\ell_{\bar z,\alpha}(\tau,z_T^\star(\tau))|\mathrm{d}\tau + \int_\Delta |\ell_{\bar z,\alpha}(\tau,z(\tau))|\mathrm{d}\tau \nonumber \\
&    \rev{=} \int_{\Theta_T(0)}|\ell_{\bar z,\alpha}(\tau,z_T^\star(\tau))|\mathrm{d}\tau,\label{eq:first_estimate}
    \end{align}
    where in the last estimate the second integral vanishes as ${z_T^\star = \bar z}$  on ${\Delta = [0,T]\setminus\Theta_T(\varepsilon)}$.
    Using Lemma~\ref{lem: bounded states} we find that $x_T^\star$ admits an upper bound that does not depend on $T$.
    Hence, there exists $0<\hat \ell<\infty,$ such that\vspace*{-2mm}
    \begin{align}
    &~~      |\ell_{\bar z,\alpha}(\tau,z_T^\star(\tau))|\nonumber \\
&\hspace{-.15cm}=|\ell(\tau,z_T^\star(\tau))-\ell(\tau,\bar z(\tau))-\alpha(\|z_T^\star(\tau)-\bar z(\tau)\|)| \leq \hat\ell \label{eq:second_estimate}\vspace*{-1mm}
    \end{align}
is valid for all $\tau\in[0,T]$ and $\hat \ell$ is independent of both $T\geq 0$ and $u_T^\star$. Combining \eqref{eq:first_estimate}, \eqref{eq:second_estimate} and \eqref{eq: turnpike}, we obtain
\begin{align}
    \label{eq:almost}
-\int_0^T\ell_{\bar z,\alpha}(\tau,z_T^\star(\tau))\mathrm{d}\tau\leq \mu(\Theta_T(0))\hat\ell \leq \nu(0)\hat \ell
\end{align}
for all $T\geq 0$ and all solutions  $u_T^\star\in L^1([0,T],\mc{U})$ of \ref{prob: OCP}. Taking now the supremum in \eqref{eq:almost} over all optimal controls $u_T^\star\in L^1([0,T],\mc{U})$ and all $T\geq 0$ does, by construction, not affect the upper bound $\hat \ell$ and leads to ${\mc{S}^\mrm{a}(x_0)\leq \nu(0)\hat \ell<\infty}$ for all $x_0\in\mc{X}_0$.
Using Theorem~\ref{thm: Willems}, the assertion follows. 
\end{proof}
