\begin{lemma}\label{lem:AHurwitz}
    The matrix $A$ from \eqref{eq: LTI system} is Hurwitz.\hfill $\square$
\end{lemma}
\begin{proof}
    %By definition of the graph Laplacian in \cite{VANDERSCHAFT201721}, and 
    Since \rev{$m_v=1$ for all ${v\in\mc{V}}$ and }$\diag{[\kappa_v]_{v\in\mc{V}}}$ %\todo{R6: In the proof of Lemma 1, there is $m_v$ appearing, but $m_v=1$ for all v. This is also why $A$ can be chosen as the graph Laplacian without including weights corresponding to $m_v$. It would be consistent to argue here with the identity matrix I instead of $\diag{[m_v]_v}$.} 
    is diagonal positive definite, we have that $A$ is strictly diagonally dominant with negative diagonal entries.
    Thus, invoking Gershgorin's circle theorem \cite[Theorem 6.2.8]{HorJ12}, we conclude that $A$ is Hurwitz.
\end{proof}
Assumption~\ref{ass: technical modeling} (iii) implies the following, cf. \cite[p. 94]{khalil}:
\begin{lemma}[Bounded states] \label{lem: bounded states}
    For ${x_0\in\mc{X}_0}$ and ${u\in L^1([0,T],\mc{U})}$, and consider \eqref{eq: LTI system} with $A$ Hurwitz.
    Let $\omega(A)<0$ denote an upper bound for the real-parts of the eigenvalues of $A$.
    From Assumption \ref{ass: technical modeling} and the definition of $\mc{U}$ follows that ${\hat d=\sup_{t\in[0,T]} \|d(t)\|<\infty}$ and ${\hat{u}=\sup_{u\in\mc{U}}\|u\|<\infty}$. 
    Then, for some $k>0$ the state trajectory of \eqref{eq: LTI system} is bounded for all $T\geq0$, i.e., ${\| x(T) \|\leq ke^{-|\omega(A)|T}~\|x_0\| + \textstyle{\frac{k}{|\omega(A)|}} (\|B\| \hat u + \|E\| \hat d). \hspace*{.5cm} \square}$
\end{lemma}

