\subparagraph{Width.}

Given an angle $\theta$, let $u_\theta = (\cos \theta, \sin \theta)$ be the unit vector in direction $\theta$.
The \emph{(directional) width} of a closed curve $C$ in direction $\theta$ is the minimum distance between two parallel lines, orthogonal to $u_\theta$, that enclose $C$ (see \cref{fig:width}). Equivalently, it is the length of the projection of $C$ to a line parallel to $u_\theta$. Formally, we write:
\[ w(C, u_{\theta}) = \max_{p \in C} \langle u_{\theta}, p \rangle  - \min_{p \in C} \langle u_{\theta}, p \rangle. \]
The \emph{width} of a closed curve $C$ is the minimum width over all directions:
\[ w(C) = \min_{\theta \in [0, \pi)} w(C,u_{\theta}). \]

\begin{figure}[t]
	\begin{center}
		\includegraphics[width=.7\textwidth]{figs/width2.pdf}
	\end{center}
	\caption{A polygon $P$ and its width with respect to directions $\theta_1$ and $\theta_2$. Here $w(P, \theta_1) < w(P, \theta_2)$.}
	\label{fig:width}
\end{figure}

It is well known~\cite{cauchy} that the \emph{mean width} (computed by integration over all directions) of a closed convex curve is precisely its length divided by $\pi$. Since the width of a curve is clearly at most its mean width, we have:

\begin{lemma}\label{lem:cauchy}
	For any convex closed curve $C$ on $\mathbb{R}^2$, 
	$w(C) \le |C|/\pi$.
\end{lemma}


\section{Lower bounds: the circular point set}\label{sec:circle}

We start with an illustrative special case that will also provide our lower bound for the case $k = 2$. Let $P_n$ be a set of $n \ge 2$ points, arranged regularly-spaced along the unit circle. More precisely, define $P_n = \{ p_i \mid 1 \le i \le n \}$ with $p_i = ( \cos (2\pi \tfrac i n), \sin (2\pi \tfrac i n))$. See \cref{fig:evenPointsProof}~(a).

\begin{figure}
    \centering
    \includegraphics{figs/evenPoints.pdf}
    \caption{(a) Point set $P_{16}$. (b) Balanced partition of $P_{16}$.}
    % Simple $16$-gon with vertices P_16}
    \label{fig:evenPointsProof}
\end{figure}

Clearly, the shortest tour of $P_n$ goes around the circle, approaching a length of $2 \pi$ as $n$ goes to infinity. Thus, we have $\TSP(P_n) \rightarrow 2 \pi$. Now, consider the case $k = 2$. The intuitively best way of splitting the point set is shown in \cref{fig:evenPointsProof}~(b): Divide the circle with a straight cut into equal parts (assume for simplicity that $n$ is even). For both parts, take the half-circle plus the diagonal as a tour. As $n$ goes to infinity, the length of each of these tours will tend towards $\pi + 2$ (half the circumference plus twice the radius). Thus, the following holds:
\[ \lim_{n \rightarrow \infty} \gamma(P_n,2) \le \tfrac{\pi+2}{2 \pi} = \tfrac12 + \tfrac1\pi. \]

Later, in \cref{sec:ub}, we show that this upper bound holds for \emph{every} point set, using a similar technique of ``halving'' the optimal tour.

For our circular point set, it turns out that the bound is tight, since the above construction is optimal, as we show now. The main technical lemma is the following.

\begin{lemma}\label{lem:circle-subsets}
	Let $P_{2n} = \{ p_i \mid 1 \le i \le 2n \}$ with $p_i = ( \cos (2\pi \tfrac i {2n}), \sin (2\pi \tfrac i {2n}))$. Let $m \le 2n$, let $A_m = \{p_1, p_2, \dots, p_m\}$, and let $B \subseteq P_{2n}$ be an arbitary subset of size $m$. Then $\TSP(A_m) \le \TSP(B)$.
%	Let $m \le 2n$, let $A_m = \{p_1, p_2, \dots, p_m\}$, and let $B \subseteq P_{2n}$ be an arbitary subset of size $m$. Then $\TSP(A_m) \le \TSP(B)$.
\end{lemma}

%The proof of Lemma~\ref{lem:circle-subsets} appears in the ArXiv version of our paper. 
Before proving Lemma~\ref{lem:circle-subsets}, 
let us argue how it implies our claim. Take any partition of $P_{2n}$ into two sets $A$ and $B$. Without loss of generality, we have $|B| \ge n$. Thus, by Lemma~\ref{lem:circle-subsets}, we have $\TSP(B) \ge \TSP(A_n)$. Therefore, the partition $\{A_n, P_{2n} \setminus A_n\}$ is optimal, as desired. As argued above, we have $\lim_{n \rightarrow \infty} \TSP(A_n) / \TSP(P_{2n}) = \tfrac12 +\tfrac1\pi$. Hence, we have $\gamma(P_{2n},2) \rightarrow \tfrac12 + \tfrac1\pi$, and thus $\gamma(2) \ge \tfrac12 + \tfrac1\pi$. This proves the lower bound of Theorem~\ref{thm:bounds-2}.

To prove Lemma~\ref{lem:circle-subsets}, we need the following technical lemma.

\begin{lemma}\label{lem:sin-add}
		Let $t \in [0, 2\pi]$ and let $a,b \in [0, \tfrac t 2]$ with $a \ge b$. Then $\sin(a) + \sin(t-a) \ge \sin(b) + \sin(t-b)$.
\end{lemma}
\begin{proof}
	Let $f(x) = \sin(x) + \sin(t-x)$. It suffices to show that $f(x)$ is increasing on the interval $[0,\pi]$.

	Note that $f'(x) = \cos(x) - \cos(t-x)$. We want to show that $f'(x) \ge 0$ for $x \in [0,\pi]$, i.e.:
	\begin{align}
		\cos(x) \ge \cos(t-x).\label{eq:sin-add}
	\end{align}

	Indeed, if $t \le \pi$, then (\ref{eq:sin-add}) is equivalent to $x \le t-x$, which is equivalent to the assumption $x \le \tfrac t 2$. Otherwise, if $t \ge \pi$, then (\ref{eq:sin-add}) is equivalent to $x \le 2\pi - (t-x)$, which is true by assumption $t \le 2\pi$.
\end{proof}

We now prove Lemma~\ref{lem:circle-subsets}. First, recall that an optimal tour does not intersect itself (unless all points collinear). %~\cite{larson}. 
Thus, for every subset $B \subseteq P_{2n}$, the optimal tour on $B$ is a simple polygon whose vertices follow the order of the points on the circle.

Now take some subset $B \subseteq P_{2n}$ of size $m$. Without loss of generality, let $p_1 \in B$. We show that $B$ can be transformed into $A_m$ with a series of steps, each of which does not increase $\TSP(B)$.

\begin{lemma}\label{lem:circle-partition-helper}
	Suppose $p_i \in B$, $p_{i+1}, \dots, p_{j-1} \notin B$, and $p_j \in B$. If $B' = B \setminus \{p_j\} \cup \{p_{i+1}\}$, then $\TSP(B') \le \TSP(B)$.
\end{lemma}
\begin{proof}
	Let $\ell > j$ be minimal such that $p_\ell \in B$. (All index operations in this proof are taken $\bmod$ $2n$.)
	By our observation above, the optimal tour of $B$ and the optimal tour of $B'$ only differ in the edges $p_ip_j$, $p_jp_\ell$ (for $B$) and the edges $p_ip_{i+1}$, $p_{i+1} p_\ell$ (for $B'$). See \cref{fig:circle-tour-step} for an illustration.

	Observe that $|p_i p_j| = 2 \sin( \pi \tfrac{j-i}{2n})$. Lemma~\ref{lem:sin-add} implies that $ \sin( \pi \tfrac {j-i} {2n} ) + \sin( \pi \tfrac {\ell-j} {2n} ) \ge \sin( \pi \tfrac 1 {2n} ) + \sin( \pi \tfrac {\ell-i-1} {2n} )$, which concludes the proof.
\end{proof}

\begin{figure}
	\centering
	\includegraphics{figs/circle_tour_step}
	\caption{One step in the transformation of a tour $B$ into $A_m$.}\label{fig:circle-tour-step}
\end{figure}

Using Lemma~\ref{lem:circle-subsets}, it is not hard to extend the lower bound to larger $k$:
%Using Lemma~\ref{lem:circle-subsets}, it is not hard to extend the lower bound to larger $k$. The precise bound is stated above as Theorem~\ref{thm:lb-general} and proved in \cref{app:lb-general}.

\restateLBGeneral*
\begin{proof}
	Consider the point set $P_{kn}$. Lemma \ref{lem:circle-subsets} naturally extends to this point set, so we have that a balanced $k$-partition of $P_{kn}$ must consist of $k$ sets of $n$ consecutive points on the circle. Let $A$ denote one of these sets. We have
	\begin{align*}
		& \TSP(P_{kn}) = kn \cdot 2 \sin(\tfrac \pi {kn}), \text{ and}\\
		& \TSP(A) = (n-1) \cdot 2 \sin(\tfrac \pi {kn}) + 2 \sin(\tfrac{\pi(n-1)}{kn}). %, \text{ and thus}
	\end{align*}
	Thus,
	\begin{align*}
		& \gamma(P_{kn})  = \frac{\TSP(A)}{\TSP(P_{kn})} = \frac{n-1}{kn} + \frac{\sin(\tfrac{\pi(n-1)}{kn})}{kn \sin(\tfrac \pi {kn})} \xrightarrow{n \rightarrow \infty} \frac 1 k + \frac{\sin(\tfrac \pi k)}{\pi}.\tag*{\qedhere}
	\end{align*}
\end{proof}


\section{Upper bounds via short diagonals}\label{sec:ub}

We now prove several upper bounds for $\gamma(k)$. Recall that to show $\gamma(k) \le \alpha$, we need to argue that for \emph{every} point set $P$, there is a partition into $k$ subsets $Q_1, \dots, Q_k$ with $\TSP(Q_i) \le \alpha \cdot \TSP(P)$ for all $i \in [k]$.

%\subsection{The case \texorpdfstring{$k=2$}{k=2}}

Our  upper bound for $\gamma(2)$ adapts the idea for the circular point set from \cref{sec:circle}. Essentially, we take the optimal tour $C$ of $P$, split it in two at some point $p$ and its antipodal point $q$, and split the point set accordingly into $Q_1, Q_2$. Let $C_1 = C(p,q) \cup pq$ and $C_2 = C(q,p) \cup pq$. Observe that $C_1$, resp.\ $C_2$ are tours of $Q_1$, resp.\ $Q_2$, and $|C_1| = |C_2| = |C|/2 + |pq|$.
It turns out that we can always find an antipodal pair $p, q$ on $C$ such that the diagonal $|pq|$ is short.

\begin{lemma}\label{lem:short-halving-diag}
	Let $C$ be a closed polygonal curve. Then, there exists a diagonal $pq$ of $C$ such that $|C(p,q)| = |C|/2$ and $|pq| \le \tfrac 1 \pi |C|$.
\end{lemma}
\begin{proof}[Proof sketch.]
	Let $H$ be the convex hull of $C$. Then the width of $H$ is at most $\tfrac1\pi |H| \le \tfrac1\pi |C|$, by Lemma~\ref{lem:cauchy}. This means that there exists a direction $\theta$ such that the width of $H$ in direction $\theta$ is at most $\tfrac1\pi |C|$. Clearly, the same is true for $C$, so any diagonal of $C$ that is parallel to $u_\theta$ has length at most $\tfrac1\pi |C|$. Finally, for \emph{every} direction $\theta$, there exists an antipodal pair $p, q$ such that the diagonal $pq$ is parallel to $u_\theta$. (Essentially, we can rotate $p$ around the curve, obtaining every possible direction.)
	%See \cref{app:short-diags} for full proofs.
	For a full proof, see Lemma~\ref{lem:short-diag}.
\end{proof}

Using Lemma~\ref{lem:short-halving-diag}, the above discussion yields a partition of $P$ into two sets $Q_1$, $Q_2$ with $\TSP(Q_1), \TSP(Q_2) \le \tfrac12 |C| + \tfrac1\pi |C|$. Since $\TSP(P) = |C|$ by assumption, we have $\gamma(2) \le \tfrac12 + \tfrac1\pi$. This concludes the proof of Theorem~\ref{thm:bounds-2}.

Our second upper bound is a simple reduction for non-prime $k$.

\restateUBMultiply*
\begin{proof}
	Let $P$ be a point set.
	By definition, there is a partition of $P$ into sets $Q_1, Q_2, \dots, Q_a$ such that $\tsp(Q_i) \le \gamma(a) \cdot \tsp(P)$ for each $i \in [a]$. We can now further split each $Q_i$ into $b$ sets $Q_{i,1}, Q_{i,2}, \dots, Q_{i,b}$, for a total of $a \cdot b$ sets with $\tsp(Q_{i,j}) \le \gamma(b) \cdot \tsp(Q_i) \le \gamma(b) \cdot \gamma(a) \cdot \tsp(P)$. %This concludes the proof.
\end{proof}

Our third upper bound combines the short-diagonal technique with the recursive approach of Theorem~\ref{thm:ub-multiply}. The key is a generalization of Lemma~\ref{lem:short-halving-diag}. Essentially, we can always find a short diagonal to split the curve into not only two halves, but into two parts of \emph{any chosen length}. As a first step, we show that for every prescribed curve length and direction, we can find an appropriate diagonal.

\begin{lemma}\label{lem:curve-vec}
	Let $c \colon [0,1] \rightarrow \R^2$ be the parametrization of a closed curve, let $x \in \R$, $0 < x < 1$, and let $u$ be a vector. Then there exists some $t \in [0,1]$ such that the vector $c(t+x) - c(t)$ is orthogonal to $u$.
\end{lemma}
\begin{figure}
	\centering
	\includegraphics{figs/curve_vectors}
	\caption{Illustration of Lemma~\ref{lem:curve-vec}.}\label{fig:curve-vec}
\end{figure}
\begin{proof}
	Define $v(t) = c(t+x) - c(t)$ and $f(t) = v(t) \cdot u$. We need to show that there is some $t \in [0,1]$ such that $f(t) = 0$.

	Let $p_0 = c(t_0)$ be a point on $c$ minimizing $p_0 \cdot u$. See \cref{fig:curve-vec}. Observe that $p_0$ exists, since the image of $c$ is compact. We claim that $f(t_0) \ge 0$. Indeed, if $f(t_0) < 0$, then, by definition, we have
	\begin{align*}
		( c(t_0+x) - c(t_0) ) \cdot u < 0 \iff c(t_0+x) \cdot u < c(t_0) \cdot u,
	\end{align*}
	which contradicts the minimality of $c(t_0) \cdot u$. %If $f(t_0) = 0$, we are done; hence, we can assume $f(t_0) > 0$ for now.

	Similarly, let $p_1 = c(t_1)$ minimize $p_1 \cdot u$. By symmetry, we have $f(t_1) \le 0$.
	Finally, since $f$ is continuous, there must be some $t$ with $f(t) = 0$ by the intermediate value theorem. This concludes the proof.
\end{proof}

We now show how to split curves into parts of a prescribed length.

\begin{restatable}{lemma}{restateShortDiag}\label{lem:short-diag}
	Let $C$ be a closed polygonal curve. Then, for each given $x \in \R$, $0 < x < |C|$, there exists a diagonal $pq$ of $C$ such that $|C(p,q)| = x$ and the length of $pq$ is at most $\tfrac 1 \pi |C|$.
\end{restatable}
\begin{proof}
	Let $c$ be a canonical parametrization of $c$ and let $H$ be the convex hull of $C$. %Observe that $H$ is a closed polygonal curve, too, so it has a canonical parametrization $h \colon [0,|H|] \rightarrow \R^2$.
	Let $\theta$ be the angle that minimizes the directional width of $H$, i.e., we have $w(H,\theta) = w(H)$. By Lemma~\ref{lem:cauchy}, we have $w(H) \le \tfrac 1 \pi |H| \le \tfrac 1 \pi |C|$.

	Now let $u$ be a vector orthogonal to $u_\theta$. By Lemma~\ref{lem:curve-vec}, there exists a $t \in [0,|C|]$ such that $c(t+x) - c(t)$ is orthogonal to $u$, and thus parallel to $u_\theta$. Let $p = c(t)$ and $q = c(t+x)$. Then $|C(p,q)| = x$ by definition, and the length of $pq$ is bounded by $w(C, \theta) \le w(H,\theta) \le \tfrac 1 \pi |C|$. This concludes the proof.
\end{proof}

Using Lemma~\ref{lem:short-diag}, we obtain the following generic upper bound:

\begin{lemma}\label{lem:ub-diag-helper}
	Let $k, a, b \in \N$ with $k = a + b$, and let $x \in \R$, $0 < x < 1$. Then $\gamma(k) \le \max{\left\{ (x+ \tfrac 1 \pi) \cdot \gamma(a), (1-x + \tfrac 1 \pi) \cdot \gamma(b) \right\}}$.
\end{lemma}
\begin{proof}
	Let $P$ be a point set, and let $T$ be a tour of $P$. Without loss of generality, we have $|T| = 1$.

	We first use Lemma~\ref{lem:short-diag} to obtain a diagonal $pq$ of length at most $\tfrac 1 \pi$ such that $|C(p,q)| = x$. As in the proof of the upper bound of Theorem~\ref{thm:bounds-2}, we take the two tours $C_1 = C(p,q) \cup pq$ and $C_2 = C(q,p) \cup pq$, with $|C_1| \le x + \tfrac 1 \pi$ and $|C_2| \le 1 - x + \tfrac 1 \pi$.

	Now partition $P$ into $P_1, P_2$ such that $P_1 \subseteq C_1$ and $P_2 \subseteq C_2$. By definition, we have $\TSP(P_1) \le x + \tfrac 1 \pi$ and $\TSP(P_2) \le 1 - x + \tfrac 1 \pi$. Optimally partitioning $P_1$ into $a$ parts will yield tours of length at most $\gamma(a) \cdot \TSP(P_1)$, by definition, and similarly, optimally partitioning $P_2$ into $b$ parts will yield tours of length $\gamma(b) \cdot \TSP(P_2)$. Overall, we have $a+b = k$ tours of length at most $\max{\left\{ \gamma(a) \cdot \TSP(P_1), \gamma(b) \cdot \TSP(P_2)\right\}}$, as desired.
\end{proof}

Optimizing for $x$ in Lemma~\ref{lem:ub-diag-helper} yields
\[ x = \frac{\gamma(b)}{\gamma(a) + \gamma(b)} + \frac{\gamma(b) - \gamma(a)}{\pi \cdot (\gamma(a) + \gamma(b))}. \]
Finally, with a simple calculation, we have:
%The proof of Theorem~\ref{thm:ub-split} is finished by a simple calculation.

\restateSplitUB*

Note that the upper bound of Theorem~\ref{thm:bounds-2} follows as a special case when $a = b = 1$ (recall that $\gamma(1) = 1$).

