\subsection{Security definitions and useful lemmas}

\begin{lemma}(See e.g. \cite{walls1994quantum})
The displacement operation  $D$ satisfies the property
\be
\label{displacement}
    D(\beta) D(\gamma) = e^{i\, \Im(\beta \bar{\gamma})} D(\beta + \gamma).
\ee
\end{lemma}

We use the definition of a quantum authentication scheme given by Broadbent et al.\cite{broadbent2016efficient},
but with a small modification: we allow for a small probability that a decoding error occurs.\\

\begin{definition}[Quantum message authentication scheme]
\label{def:QAS}
A quantum authentication scheme (QAS) is a polynomial-time set of encryption and decryption channels $\{\mathcal{E}_k^{M \rightarrow C}, \mathcal{D}_k^{C \rightarrow MF}) \mid k \in \mathcal{K} \}$ where $\mathcal{K}$ is the set of possible keys, $M$ is the input system, $C$ is the encrypted system, and $F$ is a flag system indicating either acceptance $\ket{acc}$ or rejection $\ket{rej}$ such that
\be
    \forall_{\qr_M}\quad
    \Big\| (\mathcal{D}_k \circ \mathcal{E}_k)(\rho_M) - \rho_M \otimes \ket{\acc}\bra{\acc}_F\Big\|_{\rm tr} \leq \qe_{\rm dec},
%    (\mathcal{D}_k \circ \mathcal{E}_k)(\rho_M) = \rho_M \otimes \ket{\acc}\bra{\acc}_F.
\ee
where $\qe_{\rm dec}$ is a small decoding error probability.
\end{definition}
We allow the message register $M$ to be entangled with a reference system $R$ that belongs to the adversary.
The input to the scheme is expressed as a joint quantum state $\rho_{MR}$.

The adversary applies a joint unitary $U_{CR}$ on the encoded message and the reference system. 
For a fixed key $k$, the corresponding real-world quantum channel is defined as
\be
\mathcal{C}_k^{MR \to MRF} :\quad
\rho_{MR} \mapsto (\mathcal{D}_k \otimes \one_R) \left( U_{CR}\; (\mathcal{E}_k \otimes \one_R)(\rho_{MR})\; U_{CR}^\dagger \right).
\ee

The security definition relies on comparing this real-world channel with an idealized simulator which has access only to the ideal functionality. The ideal functionality either accepts the message by outputting message register M, or rejects it by outputting a fixed dummy state $\Omega_M$. The simulator may also modify the reference system $R$. The idealized process can be expressed as ideal channel $\mathcal{F}$, 
\bea
    \mathcal{F}^{MR \to MRF}: \quad & \rho_{MR} \mapsto & (\one_M \otimes \mathcal{U}_R^{\acc}) (\rho_{MR}) \otimes \ket{\acc}\bra{\acc} 
    \nn\\ &&
    + \Omega_M \otimes \tr_M\big[(\one_M \otimes \mathcal{U}_R^{\rej})(\rho_{MR}) \big]  \otimes \ket{\rej}\bra{\rej},
\label{Fgeneral}
\eea
 where for each attack $U_{CR}$ there exists two CP maps $\mathcal{U}_R^{\acc}$ and $\mathcal{U}_R^{\rej}$ acting only on the reference system $R$, satisfying $\mathcal{U}_R^{\acc} + \mathcal{U}_R^{\rej} = \one_R$.\\


\begin{definition}[Security of quantum message authentication \cite{broadbent2016efficient} ] 
\label{def:security}
Let $\{(\mathcal{E}_k^{M \to C}, \mathcal{D}_k^{C \to MF}) \mid k \in \mathcal{K}\}$ be a quantum message authentication scheme.
%with keys $k$ chosen from $\mathcal{K}$. 
The scheme is $\qh$-secure if for all attacks there exists a simulator $\mathcal{F}$ such that
\be
\forall \rho_{MR} \quad\quad
\Big\| \frac{1}{|\cK|} \sum_{k\in\cK}\mathcal{C}_k(\rho_{MR}) - \mathcal{F}(\rho_{MR})  \Big\|_{\rm tr} \leq \qh,
\ee
where the simulator has access only to the ideal functionality of the scheme. 
\end{definition}

