\subsection{Real World Channel}

We introduce shorthand notation
\be
    \qps=\text{Enc}(\rho_{MR}) \otimes \ket{X}\bra{X}^{\otimes z} \otimes \ket{P}\bra{P}^{\otimes z}.
\ee

Using the POVM for the accept case, the real world channel can be expressed as follows: 
\bea
&&\mathcal{C}^{MR \to MRF}: \rho_{MR} \mapsto  \Tr_{\rm trap}\EE_{k_1,k_2} \Bigg\{ \nn \\
    &&\text{Dec}   \Bigg( \sqrt{V^{\acc}_\epsilon} \pi_{k_1}^\dagger D_{k_2}^{\dagger} U_{CR}\Big(D_{k_2} \pi_{k_1} \qps
%    ( \text{Enc}(\rho_{MR}) \otimes  \ket{\xi_x}\bra{\xi_x}^{\otimes z} \otimes \ket{\xi_p}\bra{\xi_p}^{\otimes z} )
    \pi_{k_1}^\dagger D_{k_2}^{\dagger}\Big)U^{\dagger}_{CR} D_{k_2} \pi_{k_1} 
    \sqrt{V^{\acc\dagger}_\epsilon} \Bigg) 
    \otimes\ket{\text{acc}}\bra{\text{acc}} 
    \nn \\
    &&+\Omega_M \Tr_{M} \Bigg( \sqrt{V^{\rej}_\epsilon} \pi_{k_1}^\dagger D_{k_2}^{\dagger}  U_{CR}\Big(D_{k_2} \pi_{k_1} \qps
%    ( \text{Enc}(\rho_{MR}) \otimes \ket{\xi_x}\bra{\xi_x}^{\otimes z} \otimes \ket{\xi_p}\bra{\xi_p}^{\otimes z}) 
    \pi_{k_1}^\dagger D_{k_2}^{\dagger} \Big) U^{\dagger}_{CR}D_{k_2} \pi_{k_1} \sqrt{V^{\rej\dagger}_\epsilon} \Bigg)   
    \otimes \ket{\text{rej} } \bra{\text{rej}} \Bigg\}.
\eea
%We represent $\text{Enc}_M(\rho_{MR}) \otimes \ket{\xi_x}\bra{\xi_x}^{\otimes z} \otimes \ket{\xi_p}\bra{\xi_p}^{\otimes z}$ as $\qps$ and 
The attack is modeled as the unitary $U_{CR}$. 
Analogous to the approach in \cite{broadbent2016efficient},
we expand the attack as $U_{CR} = \int \rd^2\vec\alpha \, \chi(\vec{\alpha}) \, D_C(\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}}$ 
where $\int \rd^2 \vec\alpha$ stands for $\int \rd^2\alpha_1...\rd^2\alpha_{n+2z}$,
and $\int \rd^2\vec\alpha \, |\chi(\vec{\alpha})|^2 = 1$. 
Then the real world channel is given by   
\bea
&&\mathcal{C}^{MR \to MRF}: \rho_{MR} \mapsto  \Tr_{\rm trap}\EE_{k_1} 
    \int \rd^2 \vec\alpha \, \chi(\vec{\alpha}) \, 
    \int \rd^2\vec\alpha' \,\overline{\chi(\vec{\alpha}')}
    \EE_{k_2}\Bigg\{ \nn \\
    &&\text{Dec}   \Bigg( \sqrt{V^{\acc}_\epsilon} \pi_{k_1}^\dagger D_{k_2}^{\dagger} ( D_C(\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}})D_{k_2} \pi_{k_1}\qps\pi_{k_1}^\dagger D_{k_2}^{\dagger} 
     ( D_C(-\vec{\alpha}') \otimes U_{R}^{\vec{\alpha}'\dagger}) D_{k_2} \pi_{k_1} 
    \sqrt{V^{\acc\dagger}_\epsilon} \Bigg) \otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
    &&+\Omega_M \Tr_{M} \Bigg( \sqrt{V^{\rej}_\epsilon} \pi_{k_1}^\dagger D_{k_2}^{\dagger}  ( D_C(\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}})D_{k_2} \pi_{k_1}\qps\pi_{k_1}^\dagger D_{k_2}^{\dagger}
    ( D_C(-\vec{\alpha}') \otimes U_{R}^{\vec{\alpha}'\dagger})D_{k_2} \pi_{k_1} \sqrt{V^{\rej\dagger}_\epsilon} \Bigg)\otimes \ket{\text{rej} } \bra{\text{rej}} \nn \Bigg\}.
\eea
Here we have used that the QECC decoding is a linear operation.
The $\EE_{k_2}$ expectation gives rise to a CV twirl, which we evaluate using Lemma \ref{CV-twirl}.
We treat the Gaussian factor in the result of the Lemma as a Dirac delta function.
This yields
\bea
&&\mathcal{C}^{MR \to MRF}(\rho_{MR}) \propto  \Tr_{\rm trap}\EE_{k_1} \int \rd^2\vec{\alpha} |\chi(\vec{\alpha})|^2\Bigg\{ \nn \\
    &&\text{Dec}   \Bigg( \sqrt{V^{\acc}_\epsilon} \pi_{k_1}^\dagger  (D_C(\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}}) \pi_{k_1}\qps\pi_{k_1}^\dagger  (D_C(\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}})^\dagger  \pi_{k_1} 
    \sqrt{V^{\acc\dagger}_\epsilon} \Bigg) \otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
    &&+\Omega_M \Tr_{M} \Bigg( \sqrt{V^{\rej}_\epsilon} \pi_{k_1}^\dagger  (D_C(\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}}) \pi_{k_1}\qps\pi_{k_1}^\dagger  (D_C(\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}})^\dagger \pi_{k_1} \sqrt{V^{\rej\dagger}_\epsilon} \Bigg)\otimes \ket{\text{rej} } \bra{\text{rej}} \nn \Bigg\}.
\eea
Next we rewrite the permutation of the displacement $D_C(\vec\qa)$ as a displacement over the permuted~$\vec\qa$. 
\bea
&&\mathcal{C}^{MR \to MRF}(\rho_{MR}) \propto  \Tr_{\rm trap}\EE_{k_1}\int \rd^2\vec{\alpha} |\chi(\vec{\alpha})|^2 \Bigg\{ \nn \\
    &&\text{Dec}   \Bigg( \sqrt{V^{\acc}_\epsilon}   (D_C(\pi^{-1}_{k_1}\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}}) \qps (D_C(\pi^{-1}_{k_1}\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}})^\dagger  
    \sqrt{V^{\acc\dagger}_\epsilon} \Bigg) \otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
    &&+\Omega_M \Tr_{M} \Bigg( \sqrt{V^{\rej}_\epsilon}  (D_C(\pi^{-1}_{k_1}\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}}) \qps  (D_C(\pi^{-1}_{k_1}\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}})^\dagger  \sqrt{V^{\rej\dagger}_\epsilon} \Bigg)\otimes \ket{\text{rej} } \bra{\text{rej}} \nn \Bigg\}.
\eea
Next we explicitly write out the POVM V as specified in (\ref{POVM_V}).
For the C register we use label `msg' for the first $n$ modes, the label `X' for the $z$ trap modes after that,
and `P' for the final $z$ modes.
For conciseness we write only the Accept part.
The Reject part is analogous, and will be presented explicitly again at the end of the analysis.
\bea
&&\mathcal{E}^{MR \to MRF}(\rho_{MR}) \propto  \Tr_{\rm trap}\EE_{k_1} \int \rd^2\vec{\alpha} |\chi(\vec{\alpha})|^2 \Bigg\{ \nn \\
    &&\text{Dec}  \Bigg(  (\one^{\otimes n} \otimes 
    \Bigg[ \int_{-\epsilon}^\epsilon\!\! \rd x \, \ketbra x \Bigg]^{\otimes z} 
    \otimes 
    \Bigg[ \int_{-\epsilon}^\epsilon\!\! \rd p \, \ketbra p \Bigg]^{\otimes z} )
%     \bigotimes_{i=1}^{z} \int_{{|x_i|\leq \varepsilon}} dx_i \, \ket{x_i}\bra{x_i}
%    \bigotimes_{j=1}^{z} \int_{|p_j|\leq \varepsilon} dp_j \, \ket{p_j}\bra{p_j} 
    \nn \\ 
    &&({[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_{\rm msg} \otimes {[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_X \otimes {[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_P \otimes U_{R}^{\vec{\alpha}}) (\text{Enc}_M(\rho_{MR}) \otimes\ketbra X^{\otimes z} \otimes\ketbra P^{\otimes z})  \nn \\
    &&({[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_{\rm msg} \otimes {[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_X \otimes {[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_P \otimes U_{R}^{\vec{\alpha}})^\dagger   
    \Bigg) \otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
    &&+\mbox{Reject part}
    %    &&+\Omega_M \Tr_{M} \Bigg( \sqrt{M^{\rej}_{\cE}}  \int d^2\vec{\alpha} |\chi(\vec{\alpha})|^2 (D_C(\pi^{-1}_{k_1}\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}}) \qps  (D_C(\pi^{-1}_{k_1}\vec{\alpha}) \otimes U_{R}^{\vec{\alpha}})^\dagger  \sqrt{M^{\dagger \rej}_{\cE}} \Bigg)\otimes \ket{\text{rej} } \bra{\text{rej}} \nn \Bigg\}.
\eea
Next we evaluate the trace over all the trap modes.
In each trap mode independently we get an $x$-integral or $p$-integral
of a displaced squeezed state, with integration interval $(-\epsilon,\epsilon)$, i.e.
an integral of the form $\int_{-\epsilon}^\epsilon \! \rd x \, |\bra{x} D(\qb) \ket X|^2$ for some $\qb\in\CC$. 
It holds that
$|\bra{x} D(\qb) \ket X|^2 = (2\pi e^{-r})^{-1/2}\exp(-\frac{(x-\sqrt2 \Re \qb)^2}{2e^{-r}})$
and
$|\bra{p} D(\qb) \ket P|^2 = (2\pi e^{-r})^{-1/2}\exp(-\frac{(p-\sqrt2 \Im \qb)^2}{2e^{-r}})$.
We get
\bea
    g_1(\qb) &\isdef& \int_{-\epsilon}^\epsilon \! \rd x \, |\bra{x} D(\qb) \ket X|^2
    = \frac12{\rm Erf}\frac{e^{r/2}(\epsilon+\sqrt2 \Re \qb)}{\sqrt2}
    +\frac12{\rm Erf}\frac{e^{r/2}(\epsilon-\sqrt2 \Re \qb)}{\sqrt2}
    \\ 
    g_2(\qb) &\isdef& \int_{-\epsilon}^\epsilon \! \rd p \, |\bra{p} D(\qb) \ket P|^2
    = \frac12{\rm Erf}\frac{e^{r/2}(\epsilon+\sqrt2 \Im \qb)}{\sqrt2}
    +\frac12{\rm Erf}\frac{e^{r/2}(\epsilon-\sqrt2 \Im \qb)}{\sqrt2}
\eea
%$\int_{-\epsilon}^\epsilon \! \rd x \, |\bra{x} D(\qb) \ket X|^2$
%$=\frac12{\rm Erf}\frac{e^{r/2}(\epsilon+\sqrt2 \Re \qb)}{\sqrt2}$
%$+\frac12{\rm Erf}\frac{e^{r/2}(\epsilon-\sqrt2 \Re \qb)}{\sqrt2}$,
For $r\gg 1$ and properly tuned $\epsilon$ ($\epsilon > e^{-r/2}$), 
this combination of error functions acts as a selection function that 
equals (almost) 1 if $| {\rm displacement} | \leq \epsilon$  and (almost) 0 otherwise.
The product of all the contributions from the trap states yields an overall selection function $G$,
\be
    G(\pi,\vec\qa) \isdef \prod_{j=1}^z g_1\left( [\pi^{-1}\vec\qa]_{X_j} \right) \;
    g_2\left( [\pi^{-1}\vec\qa]_{P_j} \right).
\ee
Finally, we can write the real-world channel as
\bea
&&\mathcal{C}^{MR \to MRF}(\rho_{MR}) =  \EE_{k_1} \int \rd^2\vec{\alpha} |\chi(\vec{\alpha})|^2
\Bigg\{  G(\pi_{k_1},\vec{\alpha}) \nn \\ 
    &&\text{Dec}  \Bigg(({[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_{\rm msg} \otimes U_{R}^{\vec{\alpha}})\text{Enc}_M(\rho_{MR})({[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_{\rm msg} \otimes U_{R}^{\vec{\alpha}})^\dagger\Bigg)
     \otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
     &&+ [1-G(\pi_{k_1},\vec{\alpha})]   \Omega_M \Tr_{M} {\rm Dec}\Bigg(({[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_{\rm msg} \otimes U_{R}^{\vec{\alpha}})\text{Enc}_M(\rho_{MR})({[D_C(\pi_{k_1}^{-1}\vec{\alpha})]}_{\rm msg} \otimes U_{R}^{\vec{\alpha}})^\dagger \Bigg) \nn \\
     &&\otimes  \ket{\text{rej} } \bra{\text{rej}} \Bigg\}
\eea



