Using $G-I$ and $(1-G)-(1-I)= -(G-I)$, we combine all four terms into single integral $\int d^2\vec{\alpha}|\chi(\vec{\alpha})|^2(G-I)[\text{state diff}]$:
\bea
    &=& \Bigg\|\frac{1}{|\Pi_{n+2z}|}\sum_{\pi \in \Pi_{n+2z}}  \int d^2\vec{\alpha}|\chi(\vec{\alpha})|^2(G(\ldots) - I(\ldots)) \Bigg\{   \nn \\
    &&\text{Dec}  \Big(({[D_C(\pi^{-1}\vec{\alpha})]}_{msg} \otimes U_{R}^{\vec{\alpha}})\text{Enc}_M(\rho_{MR})({[D_C(\pi^{-1}\vec{\alpha})]}_{msg} \otimes U_{R}^{\vec{\alpha}})^\dagger\Big) \otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
    &-&\Omega_M \Tr_{MC_1C_2}\Big( (D_{C_1}(\pi^{-1}\vec{\alpha})  \otimes U_{R}^{\vec{\alpha}})
    \phi_{MRC_1C_2} (D_{C_1}^\dagger(\pi^{-1}\vec{\alpha}) \otimes U_{R}^{\dagger\vec{\alpha}}) \Big) \otimes \ket{\text{rej} } \bra{\text{rej}} \nn \\
    &&\Bigg\} \Bigg\|.
\eea
To further simplify, we apply the triangle inequality to take the summation and integration out :
\bea
    &\leq& \frac{1}{|\Pi_{n+2z}|}\sum_{\pi \in \Pi_{n+2z}}  \int d^2\vec{\alpha}|\chi(\vec{\alpha})|^2(G(\ldots) - I(\ldots))  \nn \\
    &\Bigg\|& \text{Dec}  \Big(({[D_C(\pi^{-1}\vec{\alpha})]}_{msg} \otimes U_{R}^{\vec{\alpha}})\text{Enc}_M(\rho_{MR})({[D_C(\pi^{-1}\vec{\alpha})]}_{msg} \otimes U_{R}^{\vec{\alpha}})^\dagger\Big) \otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
    &&-\Omega_M \Tr_{MC_1C_2}\Big( (D_{C_1}(\pi^{-1}\vec{\alpha})  \otimes U_{R}^{\vec{\alpha}})
    \phi_{MRC_1C_2} (D_{C_1}^\dagger(\pi^{-1}\vec{\alpha}) \otimes U_{R}^{\dagger\vec{\alpha}}) \Big) \otimes \ket{\text{rej} } \bra{\text{rej}} \Bigg\| \nn \\
\eea
Since the trace distance between any two quantum states is at most 1, we upper bound it by:
\bea
    &\leq& \frac{1}{|\Pi_{n+2z}|}\sum_{\pi \in \Pi_{n+2z}}  \int d^2\vec{\alpha}|\chi(\vec{\alpha})|^2(G(\ldots) - I(\ldots)) .
\eea

We express the trace distance between the average real channel and the ideal channel as:
\bea
    &&\Bigg\| \frac{1}{|\mathcal{K}|} \sum_{k \in \mathcal{K}} \mathcal{E}_k(\rho_{MR}) - \mathcal{F}(\rho_{MR}) \Bigg\| = \Bigg\|\frac{1}{|\Pi_{n+2z}|}\sum_{\pi \in \Pi_{n+2z}} \Bigg\{ \nn \\ 
    &&\int d^2\vec{\alpha} |\chi(\vec{\alpha})|^2 G(\vec{\alpha}_x, \vec{\alpha}_p, \varepsilon)\text{Dec}  \Big(({[D_C(\pi^{-1}\vec{\alpha})]}_{msg} \otimes U_{R}^{\vec{\alpha}})\text{Enc}_M(\rho_{MR})({[D_C(\pi^{-1}\vec{\alpha})]}_{msg} \otimes U_{R}^{\vec{\alpha}})^\dagger\Big) \nn \\ 
    &&\otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
    &+&\int d^2\vec{\alpha} |\chi(\vec{\alpha})|^2 \overline{G(\vec{\alpha}_x, \vec{\alpha}_p, \varepsilon)}   \Omega_M \Tr_{M} \Big(({[D_C(\pi^{-1}\vec{\alpha})]}_{msg} \otimes U_{R}^{\vec{\alpha}})\text{Enc}_M(\rho_{MR})({[D_C(\pi^{-1}\vec{\alpha})]}_{msg} \otimes U_{R}^{\vec{\alpha}})^\dagger \Big) \nn \\ 
    && \otimes  \ket{\text{rej} } \bra{\text{rej}} \nn \\
    &-&\Tr_{C_1C_2}\Big(\int\displaylimits_{} d^2\vec{\alpha} |\chi(\vec{\alpha})|^2 I(\pi^{-1} \vec{\alpha} \in \cD_{\cF}) (D_{C_1}(\pi^{-1}\vec{\alpha})  \otimes U_{R}^{\vec{\alpha}})
    \phi_{MRC_1C_2} (D_{C_1}^\dagger(\pi^{-1}\vec{\alpha}) \otimes U_{R}^{\dagger\vec{\alpha}}) \Big)\nn \\ 
    &&  \otimes\ket{\text{acc}}\bra{\text{acc}} \nn \\
    &-&\Omega_M \Tr_{MC_1C_2}\Big(\int\displaylimits_{} d^2\vec{\alpha} |\chi(\vec{\alpha})|^2 I(\pi^{-1} \vec{\alpha} \notin \cD_{\cF}) (D_{C_1}(\pi^{-1}\vec{\alpha})  \otimes U_{R}^{\vec{\alpha}})
    \phi_{MRC_1C_2} (D_{C_1}^\dagger(\pi^{-1}\vec{\alpha}) \otimes U_{R}^{\dagger\vec{\alpha}}) \Big) \nn \\ 
    &&  \otimes \ket{\text{rej} } \bra{\text{rej}} \Bigg\} \Bigg\|
\eea

We analyze three distinct scenarios to understand when the difference \( G - I \) can be nonzero:

\begin{itemize}
    \item \textbf{Case 1:} All displacements are small, i.e., \( |\alpha_i| \ll \varepsilon \) for all modes. In this case, both the real world case indicator \( G \) and the ideal function \( I \) evaluate to 1. Thus, \( G - I = 0 \).
    \item \textbf{Case 2:} At least one trap mode is displaced beyond the threshold, i.e., \( |\alpha_i| > \varepsilon \), while the message remains correct. Here, both \( G = 0 \) and \( I = 0 \), so again \( G - I = 0 \).
    \item \textbf{Case 3 (critical):} All trap modes pass verification (i.e., the displacements remain within the threshold \( \varepsilon \)), but the message has been altered in a way that exceeds the correction capability of the QECC (e.g., more than \( t \) modes are affected with an error ). In this case, the real world indicator function yields \( G = 1 \) while the ideal indicator gives \( I = 0 \), so \( G - I = 1 \). This corresponds to the critical scenario where the attack is detected in the ideal functionality (simulator), but not in the real-world channel.
\end{itemize}

The number of permutations that places these $u$ errors precisely in the $n$ message modes is given by
\be
    N_{\rm perm}(u) = \frac{1}{(n + 2z)!} \times \binom{n}{u} u! (n + 2z - u)!
\ee

$\frac{1}{(n + 2z)!} \times \binom{n}{u} (u)! (n + 2z - (u))!$. The first fraction \( \frac{1}{(n + 2z)!} \) accounts for the uniform probability over all possible permutations. The binomial coefficient \( \binom{n}{u} \) counts the number of ways to choose \( u \) corrupted message modes from the \( n \) message modes. The term \( u! \) accounts for the internal permutations among the corrupted modes. The final term \( (n + 2z - u)! \) accounts for the permutations of the remaining uncorrupted modes (including traps and uncorrupted message modes).





\subsection{Security Proof}
\begin{lemma}
\label{lem:Combi}
Let $n > t$ then it holds that:
\be
A = \binom{n}{t+1} \cdot (t+1)! \cdot (3n - t - 1)! \geq
\binom{n}{t+2} \cdot (t+2)! \cdot (3n - t - 2)! = B.
\ee
\end{lemma}

\textbf{Proof}
\bea
&&\frac{B}{A} = \frac{\binom{n}{t+2} \cdot (t+2)! \cdot (3n - t - 2)!}{\binom{n}{t+1} \cdot (t+1)! \cdot (3n - t - 1)!} \\
&&\frac{\binom{n}{t+2}}{\binom{n}{t+1}} = \frac{n - t - 1}{t + 2}, \quad \frac{(t+2)!}{(t+1)!} = t + 2, \quad \frac{(3n - t - 2)!}{(3n - t - 1)!} = \frac{1}{3n - t - 1}
\eea

Substituting these, we obtain:
\be
\frac{B}{A} = \left( \frac{n - t - 1}{t + 2} \right) \cdot (t + 2) \cdot \frac{1}{3n - t - 1} = \frac{n - t - 1}{3n - t - 1}.
\ee
\hfill$\square$\\

We focus on the final case and aim to compute the number of permutations that preserve this specific condition. Let \( \nu \) denote the number of permutations \( \pi \) for which both
$G(\vec{\alpha}_x, \vec{\alpha}_p, \varepsilon) = 1 \text{ and } I(\pi^{-1} \vec{\alpha} \notin \mathcal{D}_{\mathcal{F}}) = 1$ hold. This corresponds to the situation where there are more than $t$ displacements (errors) in the message modes, while no displacement larger than $\varepsilon$ occurs in any trap mode. The contribution of these permutations to the computation can be written as:
\be
    \frac{1}{|\Pi_{n+2z}|} \int d^2\vec{\alpha} \, |\chi(\vec{\alpha})|^2 \times \nu
\ee
Since the integral is normalized, $\int d^2\vec{\alpha} \, |\chi(\vec{\alpha})|^2 = 1$, the expression simplifies to:
\bea
    &=& \frac{1}{|\Pi_{n+2z}|} \times \nu
\eea

Assume there are $u$ message modes affected by errors. 

Thus, using Lemma~\ref{lem:Combi} we can bound the previous expression and compute further:
\bea
    \frac{1}{|\Pi_{n+2z}|} \times \nu &\leq& \frac{1}{(n + 2z)!} \times \binom{n}{t+1} (t+1)! (n + 2z - (t+1))! \\
    &=&\frac{n!}{(n - t - 1)!} \cdot \frac{(n + 2z - t - 1)!}{(n + 2z)!} \\
\eea
We write both factorial ratios as products: 
\bea
    &&\frac{n!}{(n - t - 1)!} = \prod_{i=0}^{t} (n - t + i), \quad \frac{(n + 2z - t - 1)!}{(n + 2z)!} = \prod_{i=0}^{t} \frac{1}{n + 2z - t + i}
\eea
Then we plug them into the expression: 
\bea
    &=& \prod_{i=0}^{t} \frac{n - t + i}{n + 2z - t + i} \\
    &\leq& \left( \frac{n}{n + 2z} \right)^{t+1}
\eea
\hfill$\square$\\

