\section{Idea}
\label{idea}
We illustrate the problems studied in the paper
 on the following examples: 

\begin{ex}[\cite{Sofronie-Fundamenta-Informaticae-2020}]
\label{ex1}
{\em 
We can model a water tank controller as a hybrid system, with
variable $L$ (water level) and two modes $s_1, s_2$ (state invariants 
$L \geq L_{\sf a}$ and $L < L_{\sf a}$, where $L_{\sf a}$ is an alarm
level). In mode $s_1$ we have inflow and outflow of water; in mode
$s_2$ only inflow.  
The water level, as well as the inflow and outflow are modeled using
unary functions $L$, ${\sf infl}, {\sf outfl}$, where
$L(t)$, ${\sf infl}(t)$ and ${\sf outfl}(t)$ are the water level,  the
inflow and  outflow at time $t$, respectively. 
 % 
We here assume that the inflow and outflow rates are constant 
and equal to ${\sf in}$, resp.\ ${\sf out}$ (i.e.\ the derivative of
${\sf infl}$ is equal to ${\sf in}$ at every point in time $t$ and the derivative of
${\sf outfl}$ is equal to ${\sf out}$ at every point in time $t$). 
% 
\begin{center}
{\scriptsize 
\begin{tikzpicture}
\node [square state] (1) {$\begin{array}{ll}
{\sf Inv}_{s_1}: \quad & L \geq L_{\sf a}\\
\hline 
{\sf Flow}_{s_1}: & \dot{L} = {\sf in} {-} {\sf out}\\
& \dot{{\sf infl}} = {\sf in}\\
& \dot{{\sf outfl}} = {\sf out}
\end{array}$}; 
\node [square state] (2) [right = of 1]{$\begin{array}{ll}
{\sf Inv}_{s_2}: \quad  & L <
L_{\sf a}\\
\hline 
{\sf Flow}_{s_2}: & \dot{L} = {\sf in}\\
& \dot{{\sf infl}} = {\sf in}\\
& {\sf out} = 0; \dot{{\sf
    outfl}} = 0
\end{array}$};

\path 
(1) edge [bend left=10,above] node  {$L \leq L_{\sf a}$} (2)
(2) edge [bend left=10,below] node  {$L \geq L_{\sf a}$} (1);  
\end{tikzpicture}
}
\end{center}

\noindent Clearly, after an evolution from time $t_0$ to time $t_1 > t_0$ in mode $s_1$ (resp. $s_2$) 
we have $L(t_1)  = L(t_0) + ({\sf in} - {\sf out})*(t_1 - t_0)$ (resp.\ $L(t_1) = L(t_0) +
{\sf in}*(t_1 - t_0)$). 


Consider the safety condition $\Psi = L \leq L_{\sf o}$ stating that
the water level always remains below an overflow level, $L_{\sf o}$. 
Since in the mode changes $L$ is not updated, $\Psi$ is clearly
invariant under jumps. 
$L \leq L_{\sf o}$ is invariant under flows iff the following
formulae are unsatisfiable w.r.t.\ the theory ${\cal T}_S$ of real numbers: 
\begin{itemize}
\item[(i)]  $\exists L, t (L {\leq} L_{\sf o} \wedge 0 {<} t
  \wedge L {\geq} L_{\sf a} \wedge \forall t'( 0 {\leq} t'
  {\leq} t {\rightarrow} L {+} {\sf in}'\!{*}t' \geq L_{\sf a})
  \wedge L {+} {\sf in}'\!{*}t {>} L_{\sf o})$,
\item[(ii)] $\exists L, t (L {\leq} L_{\sf o} \wedge 0 {<} t \wedge L {<} L_{\sf a} \wedge \forall t' (0 {\leq} t' {\leq} t {\rightarrow} L {+} {\sf in}{*}t' < L_{\sf a}) \wedge L {+} {\sf in}{*}t {>} L_{\sf o})$,
\end{itemize}
where in (i) ${\sf in}'$ is used as an abbreviation for ${\sf in} - {\sf
  out}$. 
In \cite{DammIS11} we proved that (i) and (ii) are unsatisfiable iff
(i') and (ii') are unsatisfiable: 
\begin{itemize}
\item[(i')] $\exists L, t (L {\leq} L_{\sf o} \wedge 0 {<} t
  \wedge L {\geq} L_{\sf a} \wedge  L {+} ({\sf in} {-} {\sf out}) {*}t \geq L_{\sf a}
  \wedge L {+} ({\sf in}{-}{\sf out}){*}t {>} L_{\sf o})$,
\item[(ii')]  $\exists L, t (L {\leq} L_{\sf o} \wedge 0 {<} t \wedge L {<} L_{\sf a} \wedge  L {+} {\sf in}{*}t < L_{\sf a} \wedge L {+} {\sf in}{*}t {>} L_{\sf o})$.
\end{itemize}
We can use quantifier elimination in the theory of real closed fields 
to obtain weakest constraints on the parameters ${\sf in}$ and ${\sf out}$
under which (i') and (ii') are unsatisfiable.
}
\end{ex}

\begin{ex} 
\label{ex2}
{\em 
Consider a family of $n$ water tanks with a uniform description, 
each modeled by a hybrid automaton $S(i)$ similar to the one described in Example~\ref{ex1}. 
Assume that for every $S(i)$ the water level in the tank is
represented by the continuous variable $L(i)$, and that the rate of
inflow and outflow for system $S(i)$ are constants depending on $i$, 
and are described by parameters 
${\sf in}(i)$ and ${\sf out}(i)$. 
Assume that, for every $i$, ${\sf in}(i) \geq 0$ and ${\sf out}(i) \geq 0$. 
%  
Assume that the water tanks are interconnected in such a way that 
the output of system $S(i)$ is the input of system $S(i+1)$.
% 
Our goal is to automatically obtain a weakest
universal condition on the parameters 
which guarantees that the formula 
$\forall i (L(i) \leq L_{\sf o})$, where $L_{\sf o}$ is an overflow level, is an
inductive invariant of this system of hybrid automata. 
For this we need a way of eliminating also function symbols.
}
\label{ex-water-tanks}
\end{ex}
% 
The way the systems in Example~\ref{ex-water-tanks} 
are interconnected does not change in time. The next example 
refers to a situation in which the interconnections between systems 
might change. 
\begin{ex}[\cite{DammHS15}]
{\em We consider a family of similar (but not identical) autonomous cars on a highway. 
A car can observe other cars through sensors. 
If the highway has one lane, every car should be able to observe the
closest car in front and possibly also in the back. 
In \cite{DammHS15} we considered highways with
two lanes;  for describing the
closest car in front, back, in the front on the other lane and in the
back on the other lane we use unary
functions
 $\back{}$, $\front{}$, $\sidefront{}$, $\sideback{}$. 
% 
We assume that the behavior of the cars $i \in I$ is controlled by similar hybrid
automata $S(i), i \in I$ such that for each $i$ the automaton $S(i)$ has
two modes: one mode in which the car $i$ tries to reduce the
distance to the car in front of it (${\sf front}(i)$) because the
distance between them is above a certain value 
$d_{\sf appr}$ and one mode in which car $i$ 
tries to increase the distance to the car in front of it (${\sf front}(i)$) because the
distance between them is below a certain value
$d_{\sf rec}$. 
% 
The topology of the system can change: The cars can change their lane, 
and in fixed intervals of time, the links $\back{}$, $\front{}$,
$\sidefront{}$, $\sideback{}$
are updated depending on the actual positions of the cars. 
% 
A verification task we considered in \cite{DammHS15} was to check whether the
distance between a car and the car in front of it on the same lane is
always larger than a safety distance $d_{\sf safe}$. 
If this is not possible, it might be useful  to  
obtain constraints on the functional parameters $d_{\sf appr}$, $d_{\sf
  rec}$ and $d_{\sf safe}$ such that this is guaranteed. 
}\end{ex}




\section{Preliminaries}
\label{Sec:Preliminaries}


We present the notions in logic needed in this paper.

\medskip
\noindent {\bf Logic.} We consider signatures of the form
$\Pi = (\Sigma, {\sf Pred})$ or many-sorted signatures of the form 
$\Pi = (S, \Sigma, {\sf Pred})$, 
where $S$ is a set of sorts, $\Sigma$ is a family of function symbols and ${\sf Pred}$
a family of predicate symbols. 
% 
If $\Pi$ is a signature and $C$ is a set of new constants, we will denote 
by $\Pi^C$ the expansion of $\Pi$ with constants in $C$, i.e.\ 
the signature $\Pi^C = (\Sigma \cup C, {\sf Pred})$. 
% 
We assume known standard definitions from first-order logic  
such as terms, atoms, formulae, $\Pi$-structures, logical entailment,  
model, satisfiability, unsatisfiability.  
A literal is an atom or the negation of an atom; a clause is a
(finite) disjunction of literals. In this paper we refer to (finite) conjunctions of
clauses also as ``sets of clauses'', and to (finite) conjunctions of formulae 
as ``sets of formulae''. Thus, if $N_1$ and $N_2$ are finite sets of
formula then $N_1 \cup N_2$ 
will stand for the conjunction of all formulae in $N_1 \cup N_2$. 
All free variables of a clause (resp. of a set
of clauses) are considered to be implicitly universally quantified. 
We denote ``verum'' with $\top$ and ``falsum'' with $\perp$. $\perp$ is also a notation 
for the empty clause. 

\medskip
\noindent 
{\bf Logical theories.} 
First-order theories are sets of formulae (closed under logical consequence), 
typically all consequences of a set of axioms. 
Alternatively, we may consider a set of models which defines a
theory.
Theories can be defined by specifying a set of axioms, or by specifying a
set of structures (the models of the theory). 
In this paper, (logical) theories are simply sets of sentences.

\smallskip
\noindent 
If $F, G$ are formulae and ${\mathcal T}$ is a theory we 
write $F \models G$ to express the fact that every model of $F$ is a
  model of $G$ and 
$F \models_{\mathcal T} G$ -- also written as ${\mathcal T} \cup F
  \models G$ and sometimes ${\mathcal T} \wedge F \models G$ -- 
to express the fact that every model of $F$ which is also a model of 
$\T$ is a model of $G$.
If $F \models G$ we say that {\em $F$ entails $G$}. If $F \models_{\mathcal T}
 G$ we say that {\em $F$ entails $G$ w.r.t.\ ${\mathcal T}$}. 
$F \models \perp$ means that $F$ is
unsatisfiable; $F \models_{\T} \perp$ means that there is no model of
$\T$ in which $F$ is true. 
% 
If there is a model of $\T$ which is also a
model of $F$ we say
that $F$ is satisfiable w.r.t.\ ${\mathcal T}$. 
If $F \models_{\mathcal T} G$ and $G \models_{\mathcal T} F$ we say that
 {\em $F$ and $G$ are equivalent w.r.t.\ ${\mathcal T}$}.



\section{Local theory extensions} 
\label{Sec:HierarchicalReasoning}
We now introduce a class of theories for which decidable fragments relevant 
to the tasks we consider exist.

Let ${\cal T}_0$ be a base theory with signature $\Sigma_0$. 
We consider extensions ${\cal T}_1 := {\cal T}_0 \cup {\cal K}$ of ${\cal T}_0$ with new 
function symbols in a set $\Sigma_1$ of {\em extension functions}
whose properties are axiomatized with a set ${\cal K}$ of 
{\em clauses}. 
In this case we refer to the (theory) extension ${\cal T}_0 \subseteq {\cal T}_0 \cup {\cal K}$. 
In \cite{Sofronie-cade-05} we introduced and studied local theory
extensions. In \cite{ihlemann-sofronie-ijcar10}, various notions of
locality of  theory extensions were introduced and studied. We present
some of these definitions and results below. 

\begin{defi}[Local theory extension]
An extension ${\cal T}_0 \subseteq {\cal T}_0 \cup {\cal K}$ is a
{\em local extension} 
if for every set $G$ of 
ground $\Pi^C$-clauses 
(where $C$ is a set of additional constants), 
if $G$ is unsatisfiable w.r.t.\ ${{\cal T}_0 {\cup} {\cal K}}$ then 
unsatisfiability can be detected using the set ${\cal K}[G]$ 
consisting of those instances 
of ${\cal K}$ in which the terms starting with 
extension functions are ground terms occurring in ${\cal K}$ or $G$.
\label{defi-loc}
\end{defi} 
\emph{Stably local} extensions are defined similarly, with the difference
that ${\cal K}[G]$ is replaced with ${\cal K}^{[G]}$, the set of 
instances of ${\cal K}$ in which the variables are instantiated 
with ground terms 
which occur in ${\cal K}$ or $G$.

In \cite{Sofronie-cade-05} we showed that 
local theory extensions can be 
recognized by showing that certain partial models embed into total
ones. If a theory extension has the property that each such partial
model embeds into a total model with the same universe, we talk 
about completability (we express this condition as {\sf Comp}). 



\medskip
\noindent {\bf Hierarchical reasoning in local theory extensions.}
For local theory extensions (or stably local theory extensions) 
hierarchical reasoning is possible. If ${\cal T}_0 \cup {\cal K}$ is a
(stably) local extension of ${\cal T}_0$ and $G$ is a set of 
ground $\Pi^C$-clauses 
then, by Definition~\ref{defi-loc}, 
$ {\cal T}_0 \cup {\cal K} \cup G$ is unsatisfiable iff 
$ {\cal T}_0 \cup {\cal K}[G] \cup G$ (or resp.\ 
$ {\cal T}_0 \cup {\cal K}^{[G]} \cup G$) is unsatisfiable. 
We can reduce this last satisfiability test to 
a satisfiability test w.r.t.\ ${\cal T}_0$. 
The idea is to purify 
${\cal K}[G] \cup G$ (resp.\ ${\cal K}^{[G]} \cup G$) 
by 
\begin{itemize}
\vspace{-1mm}
	\item introducing (bottom-up) new constants $c_t$ for subterms $t = f(g_1, \dots, g_n)$ with $f \in \Sigma_1$, $g_i$ ground $\Sigma_0 \cup \Sigma_c$-terms,
  \item replacing the terms $t$ with the constants $c_t$, and 
	\item adding the definitions $c_t = t$ to a set $D$. 
\vspace{-1mm}
\end{itemize}
 We denote by ${\cal K}_0 \cup 
G_0 \cup D$ the set of formulae obtained this way. 
Then $G$ is 
satisfiable w.r.t.\ ${\cal T}_0 \cup {\cal K}$ iff 
${\cal K}_0 \cup G_0 \cup {\sf Con}_0$ is satisfiable w.r.t.\
${\cal T}_0$, where 

\smallskip
${\sf Con}_0  = \{ (\bigwedge_{i = 1}^n c_i {=} d_i) \rightarrow c {=} d \mid 
  f(c_1, \dots, c_n) {=} c, f(d_1, \dots, d_n){=} d \in D \}.$

\begin{thm}[\cite{Sofronie-cade-05}] 
\label{lemma-rel-transl}
If ${\cal T}_0 \subseteq {\cal T}_0 \cup {\cal K}$ is a 
(stably) local extension and $G$ is a set of
 ground clauses 
then we can reduce the problem of checking whether $G$ is 
satisfiable w.r.t.\ ${\cal T}_0 \cup {\cal K}$ to checking 
the satisfiability 
w.r.t.\ ${\cal T}_0$ of the formula ${\cal K}_0 \cup G_0 \cup {\sf
  Con}_0$ constructed as explained above. 
% 
If ${\cal K}_0 \cup G_0 \cup {\sf Con}_0$ belongs to a decidable 
fragment ${\cal F}$ of ${\cal T}_0$ we can use the decision procedure for 
this fragment to decide whether $ {\cal T}_0 \cup {\cal K} \cup G$
is unsatisfiable. 
\end{thm}
As the size of  
${\cal K}_0 {\cup} G_0 {\cup} {\sf Con}_0$ is polynomial in the size of $G$
(for a given ${\cal K}$), locality allows us to express the complexity 
of the ground satisfiability problem w.r.t.\ ${\cal T}_1$  
as a function of the complexity of the satisfiability 
of formulae in ${\cal F}$ w.r.t.\ ${\cal T}_0$. 

\subsection{Examples of local theory extensions}
\label{examples}
In establishing the decidability results for the verification of
safety properties of the systems of linear hybrid automata we
consider, we will use locality results for updates and for
theories of pointers. Below are some of these locality results.

\medskip 
\noindent {\bf Uninterpreted functions:} The extension ${\cal T}_0
\cup {\sf UIF}_{\Sigma}$ of any theory
  ${\cal T}_0$ with a set $\Sigma$ of uninterpreted function 
symbols is local and satisfies condition ${\sf Comp}$. 



\smallskip
\noindent {\bf Boundedness \cite{sofronie-ihlemann-ismvl-07,Sofronie-Ihlemann-Jacobs-tacas08}:} Assume ${\cal T}_0$ contains a reflexive 
binary predicate $\leq$, and $f \not\in \Sigma_0$. Let $m \in {\mathbb N}$. 
For $1 \leq i \leq m$ let $t_i(x_1, \dots, x_n)$ and 
$s_i(x_1,\dots, x_n)$ 
be terms in the signature $\Pi_0$ 
and $\phi_i(x_1, \dots, x_n)$ 
be $\Pi_0$-formulae with (free) variables among $x_1, \dots, x_n$, 
such that (${\overline x}$ denotes the sequence $x_1, \dots,
x_n$): 
\begin{itemize}
\vspace{-1mm}
\item[(i)]${\cal T}_0 \models \forall {\overline x} 
(\phi_i({\overline x})\rightarrow s_i({\overline x}) \leq t_i({\overline x}))$, 
and 
\item[(ii)]
if $i \neq j$, $\phi_i \wedge \phi_j \models_{{\cal T}_0} \perp$.
\end{itemize}

\noindent Let ${\sf GB}_f  =  \bigwedge_{i = 1}^m {\sf GB}_f^{\phi_i}$ and  
${\sf Def}_f  =   \bigwedge_{i = 1}^n {\sf Def}_f^{\phi_i}$, where:

\smallskip
\noindent $({\sf GB}_f^{{\phi_i}})~~ \forall {\overline x}
(\phi_i({\overline x}) \rightarrow  s_i({\overline x}) \leq
f({\overline x}) \leq t_i({\overline x})) \quad 
({\sf Def}_f^{{\phi_i}})~~ \forall {\overline x} (\phi_i({\overline x}) \rightarrow  f({\overline x}) = t_i({\overline x}))$

\smallskip
\noindent The extensions 
${\cal T}_0 \subseteq {\cal T}_0 \cup {\sf GB}(f)$ and  ${\cal T}_0 \subseteq {\cal T}_0 \cup {\sf Def}(f)$ are both 
local \cite{sofronie-ihlemann-ismvl-07,Sofronie-Ihlemann-Jacobs-tacas08}.  


\smallskip
\noindent 
{\bf Updates \cite{JacobsKuncak,Sofronie-Ihlemann-Jacobs-tacas08}:}
Let ${\cal T}_0$ be a theory with signature $\Sigma_0$ and
$\Sigma \subseteq \Sigma_0$. Let $\Sigma' = \{ f' \mid f \in \Sigma
\}$, where $f'$ represents the value of the function $f$ after the update.
Consider a family ${\sf Update}(\Sigma, \Sigma')$ 
of update axioms of the form: 

\medskip
$\forall {\overline x} (\phi^f_i({\overline x}) \rightarrow
    F^f_i(f'({\overline x}), {\overline x})),  i =1, \dots, m,
    \quad f \in \Sigma$   

\medskip
\noindent which describe how the values of the $\Sigma$-func\-tions change,  
depending on a partition of the state space, described by a finite set $\{ \phi^f_i \mid i \in I \}$ of
$\Sigma_0$-formulae and using $\Sigma_0$-formulae $F^f_i$ such that
\begin{itemize}
\item[(i)] $\phi_i({\overline x}) \wedge \phi_j({\overline x})
  \models_{{\cal T}_0} \perp $  for $i {\neq} j$ and
\item[(ii)] ${\cal T}_0 \models \forall {\overline x} (\phi_i({\overline x})
  \rightarrow \exists y (F_i(y, {\overline x})))$ for all $i \in I$.
\end{itemize}
Then the extension of ${\cal T}_0$ with axioms ${\sf Update}(\Sigma, \Sigma')$
is local. 

\smallskip
\noindent 
{\bf Theory of pointers \cite{NeculaMcPeak,Sofronie-Ihlemann-Jacobs-tacas08}:}
Consider the language ${\cal L}_{{\sf index},{\sf num}}$ 
with sorts ${\sf index}$  and 
${\sf num}$,
with sets of unary pointer fields $P$ with arity ${\sf index}
\rightarrow {\sf index}$ and numeric fields $X$ with arity ${\sf
  index} \rightarrow {\sf num}$, and
with a constant $\nil$ of sort ${\sf index}$.
The only predicate of sort ${\sf index}$ is equality; the signature
$\Sigma_{\sf num}$ 
of sort ${\sf num}$ depends on the theory ${\cal T}_{\sf num}$ modeling the
scalar domain. A {\em guarded {\sf index}-positive extended clause} is 
a clause of the form: 
\begin{eqnarray}
\vspace{-5mm}
\forall i_1 \dots i_n ~~ {\cal E}(i_1, \dots, i_n) \vee {\cal
  C}({\overline x_i(i_1)}, \dots, {\overline x_i(i_n)}) \label{loc-ax}
\vspace{-5mm}
\end{eqnarray}
\noindent where ${\cal C}$ is a ${\cal T}_{\sf num}$-formula over terms
of sort ${\sf num}$, 
$x_i \in X$, and ${\cal E}$ is a disjunction of equalities between
terms of sort ${\sf index}$, containing all atoms of the form 
$i = \nil,  f_n(i) = \nil, \dots, 
f_2(\dots f_n(i)) = \nil$  for all terms $f_1(f_2(\dots f_n(i)))$ occurring in 
${\cal E} \vee {\cal C}$, where $f_1 \in P \cup X, f_2,\dots, f_n \in P$. 

\noindent Every set ${\cal K}$ of 
guarded {\sf index}-positive extended clauses defines a stably local 
extension of ${\cal T}_{\sf num} \cup {\sf Eq}_{\sf index}$, 
where ${\sf Eq}_{\sf index}$ is the pure theory
of equality.
\label{remark-pointers}

\medskip
\noindent Other examples which turned out to be useful in the study of 
parametric systems were e.g.\ theories of monotone functions
\cite{Sofronie-cade-05,sofronie-ihlemann-ismvl-07}
and 
theories of convex and concave functions defined on an interval $I$ of real
numbers or integers \cite{sofronie-ki08}. 

\medskip
\noindent {\bf Chains of local theory extensions.}
In many cases we need to perform reasoning tasks 
in an extension ${\cal T}_0 \subseteq
{\cal T}_0 \cup {\cal K}$ in which the set ${\cal
  K}$ of axioms of the extension can be written as a union 
${\cal  K} = {\cal  K}_1 \cup {\cal  K}_2$ such that

\smallskip
${\cal T}_0 \subseteq
{\cal T}_0 \cup {\cal K}_1$ and 
${\cal T}_0 \cup {\cal K}_1  \subseteq {\cal T}_0 \cup {\cal K}_1 \cup
{\cal K}_2$ 

\smallskip
\noindent are both (stably) local theory
extensions.
% 
In this case we say that we have a chain of (stably) local 
theory extensions; the reasoning task can be hierarchically reduced 
to reasoning in ${\cal T}_0$ in two steps: 
\begin{description}
\item[Step 1:]  In a first step, we reduce checking whether 
${\cal T}_0 \cup {\cal K}_1 \cup {\cal K}_2 \cup G$ is satisfiable
to checking whether ${\cal T}_0 \cup {\cal K}_1 \cup {\cal K}_2*[G]
\cup G$
is satisfiable (where ${\cal K}_2*[G]$ is ${\cal K}_2[G]$ if the
extension is local and ${\cal K}_2^{[G]}$ if it is stably
local). 
% 
We can further reduce this task to a satisfiability task in ${\cal T}_0
\cup {\cal K}_1$
as explained in Theorem~\ref{lemma-rel-transl}. 

\item[Step 2:]  If all variables in $\K_2$ occur below extension
  functions then $G_1 = ({\cal K}_2)_0 \cup G_0 \cup {\sf
  Con}_0$ is a set of ground clauses. If the theory extension 
${\cal T}_0 \subseteq
{\cal T}_0 \cup {\cal K}_1$ is (stably) local, we can again use  
Theorem~\ref{lemma-rel-transl} to reduce the problem of checking the 
satisfiability of 
${\cal T}_0 \cup {\cal K}_1 \cup G_1$ to a satisfiability test w.r.t.\
${\cal T}_0$. 
\end{description}
The idea can be used also for longer chains of (stably) local theory
extensions: 

${\cal T}_0 \subseteq {\cal T}_0 \cup {\cal K}_1 \subseteq {\cal
  T}_0 \cup {\cal K}_1 \cup {\cal K}_2 \subseteq \dots \subseteq  {\cal
  T}_0 \cup {\cal K}_1 \cup {\cal K}_2 \cup \dots \cup {\cal K}_n.$


\subsection{Symbol elimination in local theory extensions}
\label{symbol-elimination}

Let $\Pi_0 = (\Sigma_0, {\sf Pred})$. 
% 
Let ${\mathcal T}_0$ be a base theory with signature $\Pi_0$.  
We consider theory extensions $\T_0
\subseteq \T = \T_0 \cup \K$, in which among the extension functions
we identify a set of {\em parameters} $\Sigma_P$ (function and constant symbols). 
% 
Let $\Sigma$ be a signature consisting of extension symbols which are not
parameters (i.e.\ such that $\Sigma \cap (\Sigma_0 \cup \Sigma_P) =
\emptyset$). Let $\Pi = (\Sigma_0 \cup \Sigma_P \cup \Sigma, {\sf Pred})$.


\medskip
\begin{algorithm}[h!]
\caption{Algorithm for Symbol Elimination in Theory Extensions \cite{sofronie-ijcar2016,sofronie-lmcs-2018}}

\begin{tabular}{ll}
{\bf Input:} & \!\!\!\!Theory extension ${\cal T}_0 \subseteq {\cal T}_0 \cup
{\cal K}$ with signature $\Pi = \Pi_0 \cup (\Sigma_P \cup \Sigma)$\\
& ~~~where $\Sigma_P$ is a set of parameters and ${\cal K}$ is a set of
flat and linear clauses; \\
& \!\!\!\!$G$, a finite set of flat and linear ground clauses in the signature $\Pi^C$; \\
& \!\!\!\!$T$, a finite set of flat ground $\Pi^C$-terms  s.t.\ ${\sf
  est}({\cal K}, G) \subseteq T$ and ${\cal K}[T]$ is ground. \\

{\bf Output:} & Universal  $\Pi_0 \cup \Sigma_P$-formula 
$\forall y_1 \dots y_n \Gamma_T(y_1,
\dots, y_n)$. \\
\hline 
\end{tabular}



\begin{description}
\vspace{-1mm}
\item[Step 1] Compute the set of $\Pi_0^C$ clauses $\K_0 {\cup} G_0 {\cup}
  {\sf Con}_0$  from $\K[T] \cup G$  using the purification step
  described in  Thm.~\ref{lemma-rel-transl} (with set of extension
  symbols $\Sigma_1 = \Sigma_P \cup \Sigma$). 

% \medskip

\item[Step 2]  $G_1 := {\mathcal K}_0 \cup G_0\cup {\sf Con}_0$. 
Among the constants in $G_1$, identify 
\begin{enumerate}
\item[(i)] the constants
${\overline c_f}$, $f {\in} \Sigma_P$, where $c_f {=} f {\in}
\Sigma_P$ is a constant
parameter or $c_f$ is 
introduced by a definition $c_f {:=} f(c_1,\dots,c_k)$ in the hierarchical
reasoning method, % and 
\item[(ii)] all constants  ${\overline c_p}$ 
occurring as arguments of functions in $\Sigma_P$ in such definitions. 
\end{enumerate}
Let ${\overline  c}$ be the remaining constants.\\
Replace the constants in ${\overline  c}$
with existentially quantified variables ${\overline x}$ in $G_1$,
i.e.\ 
% 
replace $G_1({\overline c_p}, {\overline c_f}, {\overline c})$ 
with $G_1({\overline c_p}, {\overline c_f}, {\overline x})$, and
consider the formula
$\exists {\overline x} G_1({\overline c_p},{\overline c_f}, {\overline x})$.

% \medskip

\item[Step 3] Compute a quantifier-free formula 
$\Gamma_1({\overline c_p}, {\overline c_f})$  equivalent to 
$\exists {\overline x} G_1({\overline c_p}, {\overline c_f},{\overline
  x})$ w.r.t.\ $\T_0$ using a  method for quantifier elimination in 
${\mathcal T}_0$.  

% \medskip

\item[Step 4] Let $\Gamma_2({\overline c_p})$ be the formula 
obtained by replacing back in $\Gamma_1({\overline c_p}, {\overline c_f})$ 
the constants $c_f$ introduced by definitions $c_f := f(c_1, \dots,
c_k)$ with the terms $f(c_1, \dots,c_k)$. 

Replace ${\overline c_p}$ with existentially quantified variables ${\overline y}$. 

% \medskip

\item[Step 5] Let $\forall {\overline y} \Gamma_T({\overline y})$ be
  $\forall {\overline y} \neg \Gamma_2({\overline y})$. 
\vspace{-1mm}
\end{description}
\label{alg-symb-elim}
\end{algorithm}
% \medskip

\noindent 
We identify situations in which we can
generate, for every set of flat ground clauses $G$,   
a universal formula $\Gamma$ representing a family of
constraints on the parameters in $\Sigma_P$, such that $G$ is 
unsatisfiable w.r.t.\ ${\cal T}_0 \cup {\cal K} \cup {\Gamma}$.
 A possibility of doing this in a hierarchical way, by reducing 
the problem to quantifier elimination in the theory ${\cal T}_0$
is described in Algorithm~\ref{alg-symb-elim}. 



\begin{thm}[\cite{sofronie-lmcs-2018,PeuterSofronie2019}] 
Assume that ${\mathcal T}_0$ allows quantifier elimination.  
Let ${\mathcal T}_0 \subseteq {\mathcal T}_0 \cup \K$ be an extension
of the theory ${\mathcal T}_0$ with additional function symbols in a
set $\Sigma_1 = \Sigma_P \cup \Sigma$ satisfying a set $\K$ of flat
and linear\footnote{A clause is flat if the arguments of function
  symbols are variables; it is linear if whenever a variable is
  a proper subterm in 
  different terms, the terms are equal.} clauses. 
% 
Assume that $\K = \K_P \cup
\K_1$ such that $\K_P$ contains only function symbols in $\Sigma_0 \cup
\Sigma_P$ and $\K_1$ is a set of
   $\Pi$-clauses. Let $G$ be a set of flat and linear\footnote{A ground
  clause is flat if the arguments of function symbols are constants;
  it is linear if whenever a constant is a proper subterm in different terms,  the
  terms are equal.} ground $\Pi^C$-clauses such that parametric
constants do not occur below symbols in $\Sigma_1$ and $T$ a set of
flat $\Pi^C$-terms satisfying the conditions in Algorithm~1, and let  $\forall {\overline y}
\Gamma_T({\overline y})$ be the formula obtained applying Algorithm~\ref{alg-symb-elim}.
\begin{itemize}
\item[(1)] For every
$\Pi^C$-structure ${\mathcal A}$
which is a model of ${\mathcal T}_0 \cup {\mathcal K}$, 
if ${\mathcal A} \models \forall {\overline y}
\Gamma_T({\overline y})$ then ${\mathcal A} \models \neg G$, 
i.e.\  ${\mathcal T}_0 \cup {\mathcal K} \cup \forall {\overline y}
\Gamma_T({\overline y}) \cup 
  G$ is unsatisfiable. 
\item[(2)] 
Assume  that
${\cal T}_0 \subseteq {\cal T}_0 \cup {\cal K}_P \subseteq {\cal T}_0
\cup {\cal K}_P \cup \K_1$ 
is a chain of theory extensions both satisfying condition $({\sf
  Comp})$ and having the property that all variables occur below an
extension function, and such that $\K$ is flat and linear. 
% 
Let 
$\forall {\overline y} \Gamma_1({\overline  y})$ be the formula obtained by 
applying Algorithm 1 to $\T_0 \cup \K_1$, $G$ and $T := {\sf
  est}(\K, G)$.  
Then the formula 
$\K_P \wedge 
\forall {\overline y} \Gamma_1({\overline y})$ 
has the property 
that for every universal formula $\Gamma$ containing only parameters
in $\Sigma_P$ with 
  ${\cal T}_0 \cup (\K_P \cup
  \Gamma)  \cup G \models \perp$, we have 
$\K_P \wedge \Gamma  \models  \K_P \wedge \forall {\overline y} \Gamma_1({\overline y})$. 
\end{itemize}
\vspace{-3mm}
\label{symb-elim-simplif}
\label{inv-trans-qe}
\end{thm}
% 
A similar result can be established for $\Psi$-locality and 
for chains of local theory extensions, cf.\ also 
\cite{sofronie-lmcs-2018,PeuterSofronie2019,peuter-thesis-2024}. 

\begin{ex} Consider the extension of the theory of real numbers
 ${\mathbb R}$ with additional function symbols $L, L'$ satisfying axioms ${\cal K}$: 

\smallskip
${\cal K} = \{ \forall x (L(x) + m(x)*t \leq L'(x)), \quad \forall x
(L'(x) \leq L(x) + M(x)*t) \}.$

\smallskip
\noindent By the results in Section~\ref{examples} the theory extension satisfies condition ${\sf
  Comp}$.

Let $G := \{ t > 0, L(c) \leq l_{\sf max},  L'(c) > l_{\sf max} \}$.  
We use Algorithm~\ref{alg-symb-elim} with set of parameters $\Sigma_P
= \{ m, M \}$ to determine the weakest universal
condition $\Gamma$ on these parameters under which ${\mathbb R} \cup
{\cal K} \cup \Gamma \cup G  \models \perp$.

\begin{description}
\item[Step 1:] We instantiate all universally quantified variables in
  ${\cal K}$
with $c$. After replacing $L(c)$ with $d$, $L'(c)$ with $d'$, $m(c)$
with $e$ and $M(c)$ with $e'$ we obtain: ~~
$
(d + e*t \leq d') \wedge (d' \leq d + e'*t) \wedge t > 0 \wedge (d
\leq l_{\sf max}) \wedge (d' >  l_{\sf max}).
$

 \item[Step 2:] We distinguish the constants: (i) $e,
   e'$ introduced for terms starting with the parameter $m,
   M$, (ii) $c$ argument of parameters, and (iii) $t, d, d'$ which are
   regarded as existentially quantified variables.
   We consider the formula: 

$\exists t \exists d \exists d' ((d + e*t \leq d') \wedge (d' \leq d + e'*t) \wedge t > 0 \wedge (d
\leq l_{\sf max}) \wedge (d' >  l_{\sf max})).$

\item[Step 3:] We use quantifier elimination in ${\mathbb R}$  and obtain: $e \leq e' \wedge e' > 0$. 


\item[Step 4:] 
We replace $e, e'$ back with $m(c)$ resp.\ $M(c)$ and regard $c$ as  existentially
quantified variable and obtain: $\exists c \Gamma_2(c) := \exists c (m(c) \leq M(c)
\wedge M(c) > 0)$. 


\item[Step 5:] 
The negation is $\forall x (m(x) > M(x) \vee M(x) \leq 0)$. This is
the weakest universal additional condition under which $G$ does not hold. 

If ${\cal K}$ contains also $\forall x (m(x) \leq M(x))$, we can use this property to
simplify the formula computed in Step 4; so Step 5 would yield $\forall x (M(x) \leq 0)$. 
\end{description}
\end{ex}

\subsection{Tools}

\noindent {\bf H-PILoT.} The method for
hierarchical reasoning in local theory extensions described before
was implemented in the system \mbox{H-PILoT} \cite{hpilot}.
Standard SMT solvers such as CVC4, CVC5 or Z3 or specialized provers 
such as Redlog \cite{redlog} can be used for testing the satisfiability of the
formulae obtained after
the reduction to a satisfiability test w.r.t.\ the base theory.
The advantage in comparison with provers using heuristics for
instantiation directly is that knowing
the instances needed for a complete instantiation allows us to correctly detect
satisfiability (and generate models) in situations in which other SMT
provers return ``unknown''. Another advantage is that this complete 
instantiation can be further used for symbol elimination.

\medskip
\noindent {\bf SEH-PILoT.} 
SEH-PILoT (Symbol elimination with H-PILoT) is a tool that combines 
hierarchical reduction for local theory extensions with symbol 
elimination. This allows to automate the generation of constraints by 
implementing Algorithm 1, which can be further used for invariant strengthening 
(cf. e.g.\ \cite{PeuterSofronie2019}). 

SEH-PILoT is invoked with a YAML file that specifies tasks and
all options. A task is a description of a problem consisting, among other things
of a mode (satisfiability checking, constraint generation or invariant
strengthening); the base theory; 
 a list of parameters (or a list of symbols to be
eliminated);  task specific options such as a list of assumptions
which can be used for simplification; the formalization of the actual
problem in the syntax of H-PILoT. 
% 
For the hierarchical reduction (Step 1 of Algorithm 1) SEH-PILoT utilizes H-PILoT. 
The result of H-PILoT is processed according to the task and to 
selected options for a solver to perform the symbol elimination. For 
tasks to generate constraints or strengthen invariants SEH-PILoT is 
limited at the moment to Redlog to perform the symbol elimination. The 
base theories are currently limited to the theory of real closed fields 
and the theory of Presburger arithmetic. SEH-PILoT is developed at the 
present to transform the obtained result of H-PILoT into SMT-LIB 
(version 2.7) to utilize a variety of additional state of the art solvers.

For each task, SEH-PILoT forms an appropriate invocation of 
H-PILoT according to the specification in the YAML file. Then it 
processes the output of H-PILoT (Step 2 of Algorithm 1) 
to form an appropriate file for the invocation of Redlog for
quantifier elimination (Step 3). Depending on the task 
specific options this file will be extended with additional Redlog 
commands. An example is the simplification of formulas using Redlog's 
interface to the external QEPCAD-based simplifier SLFQ or with a list of 
assumptions. After the invocation of Redlog on the generated file, the 
output is processed by SEH-PILoT to extract the required results
(Steps 4 and 5): 
The extracted formula representing the constraints or invariants is 
translated from the syntax of Redlog back to the syntax of H-PILoT, 
and symbols H-PILoT has introduced during hierarchical reduction are 
replaced back, such that the obtained formula does not contain new 
symbols. Depending on the chosen mode this is then either the final 
result of the task (a constraint) or the input for the next 
iteration (invariant strengthening). SEH-PILoT can generate, upon
request, statistics for all subtasks and steps of the process. 
The statistics indicate the time needed for the subtasks as well as
the number of atoms in the generated constraints before and after 
simplification with the external QEPCAD-based simplifier SLFQ. 





\section{Parametric Linear Hybrid Automata}
\label{lha}

\label{Sec:HybridAutomata}

In this paper we present methods for the analysis of (families of) parametric linear
hybrid automata. We start in this section with a definition of hybrid automata and of
linear hybrid automata as given in \cite{Henzinger} and the
verification problems we consider. In Section~\ref{Sec:FamiliesLHA}  then we present
the way we defined systems of similar hybrid automata in
\cite{DammHS15}
and the related verification problems. 

Hybrid automata were introduced in \cite{Henzinger} to describe
systems with discrete control, such that in every control mode certain variables can
evolve continuously in time according to precisely specified rules.

\begin{defi}[Hybrid automaton \cite{Henzinger}]
A hybrid automaton is a tuple 

\smallskip 
$S = (X, Q, {\sf flow}, {\sf Inv}, {\sf Init}, E, {\sf guard}, {\sf jump})$

\smallskip
\noindent consisting of: 
\begin{itemize}
\vspace{-2mm}
\item[(1)] 
A finite set $X = \{ x_1, \dots, x_n \}$ of real valued variables
(whose values can change over time, and which are therefore regarded as functions
$x_i : {\mathbb R} \rightarrow {\mathbb R}$) and 
a finite set $Q$ of control modes; 
\item[(2)] A family $\{ {\sf flow}_q \mid q \in Q \}$ of 
predicates over the variables in
$X \cup {\dot X}$ (where ${\dot X} =\{ {\dot x_1}, \dots, {\dot x_n} \}$, 
where ${\dot x_i}$ is the derivative of $x_i$)  
specifying the 
continuous dynamics in each control mode\footnote{This means that we assume that the functions
$x_i : {\mathbb R} \rightarrow {\mathbb R}$ are differentiable during flows.}; 
a family $\{ {\sf Inv}_q \mid q \in Q \}$ of 
predicates over the variables in $X$ defining the  
invariant conditions for each control mode; 
and a family $\{ {\sf Init}_q \mid q \in Q \}$ of 
predicates over the variables in $X$, defining the initial 
states for each control mode. 
% 
\item[(3)] A finite multiset $E$ 
with elements in $Q {\times} Q$ (the control switches). 
Every $(q, q') \in E$ is a 
directed edge between $q$ (source mode) and $q'$ (target mode); 
a family of guards 
$\{ {\sf guard}_e \mid e \in E \}$ (predicates over $X$); and a family of 
jump conditions $\{ {\sf jump}_e \mid e \in E \}$ 
(predicates over $X \cup X'$, 
where $X' =\{ x'_1, \dots, x'_n \}$ is a copy of $X$ consisting of ``primed'' 
variables). 
\end{itemize}
\end{defi}
% 
A {\em state} of $S$ is a pair $(q, a)$ consisting
of a control mode $q \in Q$ and a vector $a = (a_1, \dots, a_n)$
that represents a value $a_i \in {\mathbb R}$ for each variable $x_i \in X$.
% 
A state $(q, a)$ is {\em admissible} if ${\sf Inv}_q$ 
is true when each $x_i$ is replaced by $a_i$.
% 
There are two types of {\em state change}: 
(i) A {\em jump} is an instantaneous transition 
that changes the control location and the values of variables in $X$ according
to the jump conditions;   
(ii) In a {\em flow}, the state can change due to the evolution in a 
given control mode over an interval of time: the values of the
variables in $X$  
change continuously according to the flow rules of the current
control location; all intermediate states are admissible.
% 
A {\em run} of $S$ is a finite
sequence $s_0 s_1 \dots s_k$ of  admissible states such that
(i) the first state $s_0$ is an initial state of $S$ (the values of 
the variables satisfy ${\sf Init}_q$ for some $q \in Q$),
(ii) each pair $(s_j, s_{j+1})$ is either a jump of $S$ or the endpoints of a 
flow of $S$.

\noindent {\em Notation.} In what follows we use the following notation.
If $x_1, \dots, x_n \in X$ we denote 
the sequence $x_1, \dots, x_n$ with ${\overline x}$, the sequence 
$\dot{x}_1, \dots, \dot{x}_n$ with $\overline{\dot{x}}$, and  
the sequence of values $x_1(t), \dots, x_n(t)$ of these variables 
at a time $t$ with ${\overline x}(t)$. 


\medskip

\noindent In \cite{Henzinger} a class of hybrid automata was introduced in which the
flow conditions, the guards and the invariants have a special form. 

\begin{defi}
Let $X = \{ x_1,
\dots, x_n \}$ be a set of variables. An (atomic) linear predicate on the variables $x_1,
\dots, x_n$ is a linear strict or non-strict
inequality
of the form 
$a_1 x_1 + \dots a_n x_n \rhd a$, 
where $a_1, \dots, a_n,
a \in {\mathbb R}$ and $\rhd \in \{ \leq, < , \geq, > \}$. 
% 
A convex linear predicate is a finite conjunction of linear
inequalities.
\end{defi} 

\begin{defi}[Linear hybrid automaton \cite{Henzinger}]
A hybrid automaton $S$  is
a linear hybrid automaton (LHA) if it satisfies the following
two requirements: 

\smallskip
\noindent {\em 1. Linearity:} For every control mode $q \in Q$, 
the flow condition ${\sf flow}_q$, the invariant condition ${\sf Inv}_q$, 
and the initial condition ${\sf Init}_q$ are convex linear 
predicates.
For every control switch $e = (q,q') \in E$, the jump condition
${\sf jump}_e$ and the guard ${\sf guard}_e$ are convex linear 
predicates.
% 
In addition, 
as in \cite{damm-ihlemann-sofronie-hscc11,DammIS11}, 
we assume that the 
flow conditions ${\sf flow}_q$ are conjunctions of {\em non-strict} 
linear inequalities. 

\smallskip
\noindent {\em 2. Flow independence:} For every control mode $q \in Q$, 
the flow condition ${\sf flow}_q$ is a predicate over the variables
in ${\dot X}$ only (and does not contain any variables from $X$).
This requirement ensures that the possible flows
are independent from the values of the variables, and only depend
on the control mode.
\end{defi} 

\medskip
\noindent 
\begin{defi}[Parametric linear hybrid automaton \cite{DammHS15}]
A parametric hybrid automaton (PLHA) is a
linear hybrid automaton for which a set $\Sigma_P = P_c \cup P_f$ of 
parameters is specified (consisting of parametric constants $P_c$ and 
parametric functions $P_f$)
with the difference that for every control mode $q \in Q$ and every mode 
switch $e$: 
\begin{itemize}
\item[(1)] the linear constraints in the invariant conditions ${\sf Inv}_q$, 
initial conditions ${\sf Init}_q$, and 
guard conditions ${\sf guard}_e$ are of the form: 
$g \leq \sum_{i = 1}^n a_i x_i \leq f$, 


\item[(2)] the inequalities in the 
flow conditions ${\sf flow}_q$ are of the form:  
$\sum_{i = 1}^n b_i {\dot x}_i \leq b$, 


\item[(3)] the linear constraints in ${\sf jump}_e$ are of the form 
$\sum_{i = 1}^n b_i x_i + c_i x'_i \leq d$,
\end{itemize}
\noindent (possibly relative to an interval $I$) 
where the coefficients $a_i, b_i, c_i$ and the bounds $b, d$ 
are either numerical constants or parametric constants in $P_c$; 
and $g$ and $f$ are (i) constants or parametric constants in $P_c$, or 
(ii) parametric functions in $P_f$ satisfying 
the convexity (for $g$) resp. concavity condition (for $f$), or 
terms with one free variable $t$ such that the associated functions
have these convexity/concavity properties 
and $\forall t (g(t) \leq f(t))$. 
The flow independence conditions hold as 
in the case of linear hybrid automata.
\end{defi}

\subsection{Verification}  
We consider 
the problem of checking whether a quan\-ti\-fier-free formula $\Phi$ 
in real arithmetic 
over the variables $X$ is an inductive invariant in a 
hybrid automaton $S$, i.e.: 
\begin{itemize}
\item[(1)] $\Phi$ holds in the initial states of mode $q$ for all $q \in Q$; 
\item[(2)] $\Phi$ is invariant under jumps and flows:
\begin{itemize}
\item For every flow in a mode $q$, 
the continuous variables satisfy 
$\Phi$ both during and at the end of the flow. 
% 
\item  For every jump, 
 if the values of the continuous variables satisfy 
$\Phi$ before the jump, they satisfy $\Phi$ after the jump.
\end{itemize}
\end{itemize}

\begin{thm}[\cite{DammIS11}]
Let $S$ be a LHA with real-valued variables $X$ and $\Phi$ a property
expressible as a convex linear predicate over $X$. The following are equivalent: 
\begin{itemize}
\vspace{-1mm}
\item[(1)] $\Phi$ is an inductive invariant of the hybrid automaton;  

\item[(2)] 
For every $q \in Q$ and $e = (q,q') \in E$, the following formulae are 
unsatisfiable:  
\end{itemize}

\noindent $\begin{array}{@{}ll@{}}
I_q  & {\sf Init}_q({\overline x})  \wedge \neg \Phi({\overline x}) \\[1ex] 

F_{\sf flow}(q) & \Phi({\overline x}(t_0)) \wedge {\sf Inv}_q({\overline x}(t_0)) \wedge 
{\underline {\sf flow}}_q(t_0, t) \wedge 
 {\sf Inv}_q({\overline x}(t)) \wedge 
\neg \Phi({\overline x}(t)) \wedge t \geq t_0 \\[1ex]

F_{\sf jump}(e)~~~~~ & 
\Phi({\overline x}(t)) \wedge {\sf jump}_e({\overline x}(t), {\overline x}'(0)) \wedge  
{\sf Inv}_{q'}({\overline x}'(0)) \wedge 
\neg \Phi({\overline x}'(0))
\end{array}$

\smallskip
\noindent where if ${\sf flow}_q  =  
\bigwedge_{j = 1}^{n_q} (\sum_{i = 1}^n c^q_{ij} {\dot x}_i \leq_j
c_j^q)$ then: 

\smallskip
\noindent ${\underline {\sf flow}}_q(t, t') = 
\bigwedge_{j = 1}^{n_q}  
(\sum_{i = 1}^n c^q_{ij} (x_i' - x_i) \leq_j c_j^q (t' - t))$, where
$x'_i = x_i(t'), x_i = x_i(t)$.
\vspace{-2mm}
\label{transl-invar-par}
\end{thm}
As a consequence of Theorem~\ref{transl-invar-par}, we can determine 
the complexity of verification of LHA, and the complexity of constraint
generation for PLHA.  
\begin{cor}
Let $S$ be a (P)LHA with real-valued variables $X$ and $\Phi$ a property
expressible as a convex linear predicate over $X$. 
\begin{itemize}
\item[(1)] {\bf Verification of LHA.} Assume that all coefficients used in the convex linear
  predicates in the description of $S$ are concrete constants.
Then the problem of checking whether $\Phi$ is an
inductive invariant  is decidable in PTIME \footnote{By
  Theorem~\ref{transl-invar-par}, the problem can be reduced to checking the satisfiability of a
family of conjunctions of linear inequalities in linear real
arithmetic which is linear in the size of the description of $S$ and
of $\Phi$; the satisfiability over ${\mathbb R}$ of conjunctions of linear inequalities can be checked in PTIME
\cite{khakian}.}.
\item[(2)] {\bf Verification/Constraint generation for PLHA.} Assume that some of the coefficients used in the convex linear
  predicates in the definition of $S$ are parametric constants,
  and additional constraints on these parameters are specified.\footnote{By
  Theorem~\ref{transl-invar-par}, the problem can be reduced to checking the satisfiability of a
family of conjunctions of non-linear atoms which is linear in the size of the description of $S$ and
of $\Phi$. Checking satisfiability of non-linear inequalities and
quantifier elimination can be done in exponential time.}
% 
The problem of checking whether $\Phi$ is an inductive
  invariant is decidable in exponential time. 
Determining constraints on the parameters under which
  $\Phi$ is guaranteed to be an inductive invariant can be done in
  exponential time by 
  quantifier elimination in the theory of real closed
  fields. 
\end{itemize}
\end{cor}

\subsection{Example: Verification and constraint generation}

We now illustrate the ideas presented before on variants of Example~\ref{ex1}.

\begin{ex}
{\em Consider a water tank modelled as described in
Example~\ref{ex1} using a hybrid system 
with variable $L$ (water level) and two modes $s_1, s_2$ (state invariants 
$L \geq L_{\sf a}$ and $L < L_{\sf a}$, where $L_{\sf a}$ is an alarm
level). 
The water level, as well as the inflow and outflow are modeled using
unary functions $L$, ${\sf infl}, {\sf outfl}$, where
$L(t)$, ${\sf infl}(t)$ and ${\sf outfl}(t)$ are the water level,  the
inflow and  outflow at time $t$, respectively. 
 % 
We here assume that the inflow and outflow rates are constant 
and equal to ${\sf in}$, resp.\ ${\sf out}$ (i.e.\ the derivative of
${\sf infl}$ is equal to ${\sf in}$ at every point in time $t$ and the derivative of
${\sf outfl}$ is equal to ${\sf out}$ at every point in time $t$). 
% 
\begin{center}
{\scriptsize 
\begin{tikzpicture}
\node [square state] (1) {$\begin{array}{ll}
{\sf Inv}_{s_1}: \quad & L \geq L_{\sf a}\\
\hline 
{\sf Flow}_{s_1}: & \dot{L} = {\sf in} {-} {\sf out}\\
& \dot{{\sf infl}} = {\sf in}\\
& \dot{{\sf outfl}} = {\sf out}
\end{array}$}; 
\node [square state] (2) [right = of 1]{$\begin{array}{ll}
{\sf Inv}_{s_2}: \quad  & L <
L_{\sf a}\\
\hline 
{\sf Flow}_{s_2}: & \dot{L} = {\sf in}\\
& \dot{{\sf infl}} = {\sf in}\\
& {\sf out} = 0; \dot{{\sf
    outfl}} = 0
\end{array}$};

\path 
(1) edge [bend left=10,above] node  {$L \leq L_{\sf a}$} (2)
(2) edge [bend left=10,below] node  {$L \geq L_{\sf a}$} (1);  
\end{tikzpicture}
}
\end{center}

\noindent Assume that  ${\sf Init}_{s_1} = (L {=} L_1) \wedge (L
{\geq} L_{\sf a})$ and ${\sf Init}_{s_2}
= (L {=} L_2) \wedge (L {<} L_{\sf a})$. 

\noindent Consider the safety condition $\Phi = L \leq L_{\sf o}$ stating that
the water level always remains below an overflow level, $L_{\sf o}$. 
% 
To prove that $\Phi$ is an inductive invariant, by
Theorem~\ref{transl-invar-par}, we need to prove that
the following formulae are unsatisfiable: 
\begin{itemize}
\item[(1)] ${\sf Init}_{s_1} \wedge \neg \Phi$ \\
${\sf Init}_{s_2} \wedge \neg \Phi$
\item[(2)] $\Phi(L(t_0)) \wedge {\sf Inv}_{s_1}(L(t_0)) \wedge
  {\underline {\sf flow}}_{s_1}(t_0, t) \wedge {\sf Inv}_{s_1}(L(t))
  \wedge \neg \Phi(L(t)) \wedge t \geq t_0$ \\
$\Phi(L(t_0)) \wedge {\sf Inv}_{s_2}(L(t_0)) \wedge
  {\underline {\sf flow}}_{s_2}(t_0, t) \wedge {\sf Inv}_{s_2}(L(t))
  \wedge \neg \Phi(L(t)) \wedge t \geq t_0$ 
\item[(3)] $\Phi(L) \wedge {\sf guard}_{s,s'}(L) \wedge L' = L \wedge
  \neg \Phi(L')$, where $s, s' \in \{ s_1, s_2 \}$ and $s \neq s'$,
\end{itemize}
\begin{tabular}{@{}l@{}l}
where~ & ${\underline {\sf flow}}_{s_1}(t_0, t) :=  L(t) - L(t_0) = ({\sf
  in} - {\sf out})*(t - t_0)$ and  \\
& ${\underline {\sf flow}}_{s_2}(t_0, t) :=  L(t) - L(t_0) = {\sf
  in}*(t - t_0)$. 
\end{tabular}

\medskip
\noindent (1) {\bf Checking whether $\Phi$ holds in the initial
  states.} To check that the formula $L \leq L_{\sf o}$ is an
inductive invariant, we first check
whether it holds in the initial states, i.e.\ check whether 
$L {=} L_1 \wedge L {\geq} L_{\sf a} \wedge L {>}  L_{\sf o}$ and 
$L {=} L_2 \wedge L {<} L_{\sf a} \wedge L {>}  L_{\sf o}$
are unsatisfiable. Without additional assumptions about $L_1, L_2,
L_{\sf a}$ and $L_{\sf o}$ these formulae are satisfiable, so if we consider
the constants $L_1, L_2, L_{\sf a}$ and $L_{\sf o}$ to be parameters, 
we can derive conditions on these parameters under which the 
formulae are guaranteed to be unsatisfiable i.e.\ $\Phi$ is guaranteed
to hold in the initial states. 

\noindent The conditions can be derived by eliminating the variable $L$, i.e.\ 
by computing:

\smallskip
$\exists L ((L = L_1) \wedge  (L
\geq L_{\sf a}) \wedge (L > L_{\sf o})) \equiv (L_1 > L_{\sf o}) \wedge
(L_1 \geq L_{\sf a})$


$\exists L ((L = L_2) \wedge  (L
< L_{\sf a}) \wedge (L > L_{\sf o})) \equiv (L_2 > L_{\sf o}) \wedge
(L_2 < L_{\sf a})$

\smallskip
\noindent and then negating the result. We obtain the conditions: 

\smallskip
$(L_1 \leq L_{\sf o}) \vee
(L_1 < L_{\sf a})$ and $(L_2 \leq L_{\sf o}) \vee
(L_2 \geq L_{\sf a})$. 

\smallskip
\noindent If we assume in addition that the initial states satisfy the
invariants of the respective modes, i.e.\ that $L_1 \geq L_{\sf a}$ and
$L_2 < L_{\sf a}$, then the condition on $L_1, L_2$ under which 
in the initial states the formula $\Phi$ holds is $(L_1 \leq L_{\sf o}) \wedge
(L_2 \leq L_{\sf o})$. 

\medskip
\noindent (2) {\bf Checking invariance under flows.} The formula $L \leq L_{\sf o}$ is invariant under flows iff the formulae in (2)
are unsatisfiable w.r.t.\ the extension of the theory ${\cal T}_S$ of
real numbers with a function symbol $L$ satisfying the axiom $\forall t\, L(t)
\geq 0$:  

\begin{itemize}
\item[(i)] $ L(t_0) \leq L_{\sf o} ~\wedge~ t_0 < t
 ~ \wedge~ L(t_0) \geq L_{\sf a}  ~\wedge~ L(t) \geq L_{\sf a}
  ~\wedge~ L(t) > L_{\sf o} ~\wedge \\
 L(t) - L(t_0) = ({\sf in} {-}
  {\sf out}) {*}(t - t_0) $,
\item[(ii)]  $L(t_0) \leq L_{\sf o} ~\wedge~ t_0 < t ~\wedge~ L(t_0) <
  L_{\sf a}  ~\wedge~ L(t) < L_{\sf a} ~\wedge~ L(t) > L_{\sf o}  ~\wedge \\
L(t) - L(t_0) = {\sf in}{*}(t - t_0) $.
\end{itemize}
% 
Since the extension of the theory ${\mathbb R}$ of real numbers with
the function symbol $L$ satisfying condition $\forall t\, L(t) \geq 0$
is local, we can use the method
for hierarchical reasoning described in Theorem~\ref{lemma-rel-transl} for checking
the satisfiability of these formulae. We proceed as follows: 
We introduce new constants $l, lp$ with their definitions: ${\sf
  Def} = \{ l = L(t_0), lp = L(t) \}$. 
Then the formulae in (i) and (ii) are
unsatisfiable iff the formulae (i') and (ii') below are unsatisfiable:

\begin{itemize}
\item[(i')] $ l \leq L_{\sf o} \wedge t_0 < t
  \wedge l \geq L_{\sf a} \wedge 
 lp - l = ({\sf in} {-}
  {\sf out}) {*}(t - t_0) \wedge lp \geq L_{\sf a}
  \wedge lp > L_{\sf o}$,
\item[(ii')]  $l \leq L_{\sf o} \wedge t_0 < t \wedge l <
  L_{\sf a} \wedge  
lp - l = {\sf in}{*}(t - t_0) \wedge lp < L_{\sf a} \wedge lp > L_{\sf o}$.
\end{itemize}
Note that $t_0 < t \models {\sf Con} = (t_0 = t
\rightarrow l = lp)$, so the instances of the congruence axioms 
are not needed in this case.
% 
The satisfiability of (i) and (ii) can be checked with H-PiLoT. 
The satisfiability of (i') and
(i'') can be checked with a prover for the theory of real
numbers. 

\noindent Since the formulae are satisfiable, $\Phi$ is
not invariant under flows without additional assumptions on 
$L_{\sf o}, L_{\sf a}, {\sf in}, {\sf out}$. 

\smallskip
\noindent We can use Algorithm~1 to determine the weakest conditions on the parameters 
$\Sigma_P = \{ L_{\sf o}, L_{\sf a}, {\sf in}, {\sf out} \}$ 
which guarantee the invariance of $\Phi$
under flows as follows:

\medskip
\noindent (2.i) {\bf Invariance under flows in mode $s_1$:} 
\begin{description}
\item[Step 1:] We start with the formula in (i') obtained after
  instantiation and purification.

\item[Step 2:] Among the constants in this formula, we identify 
the parameters in $\Sigma_P$ (which do not have to be eliminated) 
$ \{ L_{\sf o}, L_{\sf a}, {\sf in}, {\sf out} \}$,
and the constants $t_0, t, l, lp$, which have
to be eliminated.  

\item[Step 3:] To eliminate $t_0, t, l, lp$ note that: 
\end{description}

\noindent {\small $\exists t_0, t \exists l, lp ( l \leq L_{\sf o} \wedge t_0 < t
  \wedge l \geq L_{\sf a} \wedge 
 lp {-} l = ({\sf in} {-}
  {\sf out}) {*}(t {-} t_0) \wedge lp \geq L_{\sf a}
  \wedge lp > L_{\sf o})$} 

\noindent $\equiv  \exists t_0, t ( L_{\sf a} \leq L_{\sf o} \wedge t_0 < t \wedge L_{\sf a} \leq
L_{\sf o} \wedge$ \\
$~~~~~~~~~~~~L_{\sf a} - ({\sf in} - {\sf out})(t - t_0) \leq L_{\sf o}
\wedge L_{\sf o} - ({\sf in} - {\sf out})(t - t_0) < L_{\sf o})$ 

\noindent $\equiv (L_{\sf a} \leq L_{\sf o} \wedge {\sf in} - {\sf
  out} > 0)$

\begin{description}
\item[Step 4:] We negate the formula obtained in Step 3 and obtain: 

$L_{\sf o} < L_a \vee {\sf in} - {\sf out} \leq 0$.

If we assume that $L_{\sf a} \leq L_{\sf o}$, then the condition above
can be simplified to ${\sf in} - {\sf out} \leq 0$.
\end{description}


\noindent The tests with SEH-PILoT in which positivity conditions for 
$L_{\sf a},$ $L_{\sf o},$ ${\sf in}, {\sf out}$ are
included as assumptions (and can be used for the simplification of
formulae) can
be found below (we used {\sf i} instead of {\sf in} and {\sf o}
instead of {\sf out} because of syntactic restrictions in Redlog): 

