               Query :=
               t0 < t1; 
               l(t0) < lo;
               l(t0) >= la;
               l(t1) = l(t0) + ((i - o)*(t1 - t0));
               l(t1) >= la;
               % Negated safety condition:
               l(t1) > lo;
