\medskip
\noindent (2.ii) {\bf Invariance under flows in mode $s_2$, when
  $\Sigma_P = \{ L_{\sf o}, L_{\sf a}, {\sf in}, {\sf out} \}$:} 
\begin{description}
\item[Step 1:] We start with the formula in (ii') obtained after
  instantiation and purification.

\item[Step 2:] Among the constants in this formula, we identify 
the parameters in $\Sigma_P$ (which do not have to be eliminated) 
$ \{ L_{\sf o}, L_{\sf a}, {\sf in}, {\sf out} \}$,
and the constants $t_0, t, l, lp$, which have
to be eliminated.  

\item[Step 3:] A quantifier-free formula equivalent to 
\end{description}

\noindent $\exists t_0, t \,\exists l, lp \,(l \leq L_{\sf o} \wedge t_0 < t \wedge l <
  L_{\sf a} \wedge  
lp - l = {\sf in}{*}(t - t_0) \wedge lp < L_{\sf a} \wedge lp >
L_{\sf o})$

\noindent $\equiv \exists t_0, t (t_0 {<} t \wedge
{\sf in}*(t-t_0) > 0 \wedge L_{\sf o} - {\sf in}*(t-t_0) < L_{\sf a}
\wedge L_{\sf o} < L_{\sf a})$

\noindent $\equiv (L_{\sf o} < L_{\sf a} \wedge {\sf in} > 0)$

\begin{description}
\vspace{-2mm}
\item[Step 4:] We negate the condition obtained in Step 3 and obtain
  $L_{\sf a} \leq L_{\sf o} \vee {\sf in} \leq 0$, which is equivalent
  to $L_{\sf a} \leq L_{\sf o}$ under the additional assumption that
  ${\sf in} > 0$.
\end{description}
% 
Alternatively, we might decide to allow also $t_0, t$ as parameters. 
Then in Step 3 we do not eliminate $t_0$ and $t$. The constraint 
obtained in Step 3 is: 

\smallskip
$t_0 < t ~\wedge~
{\sf in}*(t-t_0) > 0 ~\wedge~ L_{\sf o} - {\sf in}*(t-t_0) < L_{\sf a}
~\wedge~ L_{\sf o} < L_{\sf a}.$

