\noindent Let $\Phi_{\sf safe} = \forall i \,({\sf pos}_{\sf front}(i) -
{\sf pos}(i) \geq d_{\sf safe})$, where $d_{\sf safe}$
is a parameter representing the safe distance between a car and the
next car in front of it.
The task is to determine relationships between the parameters 
$v_{\sf min}, v_{\sf max}, d_{\sf appr}, d_{\sf rec}$ and $d_{\sf safe}$ under which 
$\Phi_{\sf safe}$ is guaranteed to be
an inductive invariant of $S$.


\

\noindent {\bf Invariance under flows.} 
By Theorem~\ref{transl-invar-par}, $\Phi_{\sf safe}$ is invariant under flows iff the
following conjunctions are unsatisfiable: 

\medskip
\noindent {\small $t_0 {<} t_1 \wedge \forall i ({\sf pos}_{\sf front}(i)(t_0) {-} {\sf
  pos}(i)(t_0) {\geq} d_{\sf safe}) \wedge  \underline{{\sf flow}}(t_0, t_1)
\wedge  ({\sf pos}_{\sf front}(i_0)(t_1) {-} {\sf
  pos}(i_0)(t_1) {<} d_{\sf safe} )$,} 


\medskip 
\noindent {\small \begin{tabular}{@{}l@{}l@{}l}
where $\underline{{\sf flow}}(i) =$ & $\forall i ({\sf Inv}_{\sf appr}(t_0) {\rightarrow}$ & ${\sf pos}_{\sf front}(i)(t_1) {-} {\sf
  pos}(i)(t_1) \leq {\sf pos}_{\sf front}(i)(t_0) {-} {\sf pos}_{\sf
  front}(i)(t_0) \wedge $ \\
& & ${\sf pos}(i)(t_1) \leq {\sf pos}(i)(t_0) + v_{\sf max}*(t_1 - t_0)
\wedge {\sf Inv}_{\sf appr}(t_1)) ~\wedge $\\
& $\forall i ({\sf Inv}_{\sf rec}(t_0) {\rightarrow}$ & ${\sf pos}_{\sf front}(i)(t_1) {-} {\sf
  pos}(i)(t_1) \geq {\sf pos}_{\sf front}(i)(t_0) {-} {\sf pos}_{\sf
  front}(i)(t_0) \wedge $ \\
& & ${\sf pos}(i)(t_1) \geq {\sf pos}(i)(t_0) + v_{\sf min}*(t_1 - t_0)
\wedge {\sf Inv}_{\sf rec}(t_1)). $
\end{tabular}}

\
\noindent We present a test in which we used a slightly simplified description
of the problem, in which the part of the invariant mentioning ${\sf
  lane}(i)$ (which in this case does not change) 
is not included, and it is assumed that ${\sf front}(i) \neq {\sf
  nil}$.

\smallskip
\noindent We used the notation ${\sf p}(i)$ and ${\sf pf}(i)$ for ${\sf pos}(i)(t_0)$  resp.\ ${\sf
  pos}_{\sf front}(i)(t_0)$ and ${\sf pp}(i)$ and ${\sf pfp}(i)$ for ${\sf pos}(i)(t_1)$  resp.\ ${\sf
  pos}_{\sf front}(i)(t_1)$.

\smallskip
To check whether $\Phi_{\sf safe}$ is invariant under flows, we 
need to check that: 
$$\T_0 \cup {\cal K}_{\sf s}  \cup {\cal K}_{\sf u} \cup  G
\models \perp,$$ 
where: 
\begin{itemize}
\item $\T_0$ is the disjoint combination of linear integer arithmetic (for the
indices) with the theory ${\mathbb R}$ of real numbers (the theory of
real closed fields). 
\item ${\cal K}_{\sf s} = \{ \forall i ({\sf pf}(i) - {\sf p}(i) \geq d_{\sf
    safe}) \}$ is the clause form of the safety condition for ${\sf
    pf}, {\sf p}$; 
\item ${\cal K}_{\sf u} = {\cal K}_{\sf pp} \cup {\cal K}_{\sf pfp}
  \cup {\cal K}_{\sf inv}$ is the following set of update axioms: 

$\begin{array}{ll@{}c@{}l}
{\cal K}_{\sf pp} = \{ &   \forall i \,  ({\sf pf}(i)-{\sf p}(i) \geq d_{\sf appr}
& ~\rightarrow ~& {\sf pp}(i)
    \leq {\sf p}(i)+(v_{\sf max}*(t_1-t_0))),\\
     &   \forall i \,  ({\sf pf}(i)-{\sf p}(i) \leq d_{\sf rec} & ~\rightarrow  ~& {\sf pp}(i) 
     \geq {\sf p}(i)+(v_{\sf min}*(t_1-t_0))) \},\\
{\cal K}_{\sf pfp} = \{ & \forall i \, ({\sf pf}(i)-{\sf p}(i) \geq d_{\sf appr} & ~\rightarrow ~&
{\sf pfp}(i)-{\sf pp}(i) \leq {\sf pf}(i)-{\sf p}(i)), \\
        &    \forall i \, ({\sf pf}(i)-{\sf p}(i) \leq d_{\sf rec} & ~\rightarrow ~&
        {\sf pfp}(i)-{\sf pp}(i) \geq {\sf pf}(i) - {\sf p}(i)) \},\\
 {\cal K}_{\sf inv} = \{  &     \forall i \, ({\sf pf}(i)-{\sf p}(i) \geq d_{\sf appr} & ~\rightarrow ~&
        {\sf pfp}(i)-{\sf pp}(i) \geq d_{\sf appr}) \\
      &  \forall i \, ({\sf pf}(i)-{\sf p}(i) \leq d_{\sf rec} & ~\rightarrow ~& 
        {\sf pfp}(i)-{\sf pp}(i) \leq d_{\sf rec}) ~~~ \}
\end{array}$ 
\item $G$ corresponds to the Skolemized negation of $\Phi_{\sf safe}$
  for ${\sf pp}, {\sf pfp}$, i.e.: 

$G = \{ {\sf pfp}(i_0) - {\sf pp}(i_0) < d_{\sf safe} \}$. 
\end{itemize}
We have a chain of theory extensions 
$$ {\cal T}_0 \subseteq {\cal T}_0 \cup {\sf UIF}_{\{ {\sf p} \}} \subseteq
{\cal T}_0 \cup {\cal K}_{\sf s} \subseteq 
 {\cal T}_0 \cup {\cal K}_{\sf s} \cup {\cal K}_{\sf pp}
 \subseteq {\cal T}_0 \cup {\cal K}_{\sf s} \cup {\cal K}_{\sf
   pp} \cup ({\cal K}_{\sf pfp} \cup {\cal K}_{\sf inv})$$
\begin{itemize}
\item The extension $ {\cal T}_0 \subseteq {\cal T}_0 \cup {\sf
    UIF}_{\{ {\sf pp} \}}$ is an extension with a free function symbol, and
  hence local. 
\item The extension ${\cal T}_0 \cup {\sf UIF}_{\{ {\sf pp} \}} \subseteq
{\cal T}_0 \cup {\cal K}_{\sf s}$ is an extension with a function
symbol ${\sf pf}$ axiomatized with a 
boundedness condition $\forall i ({\sf pf}(i) \geq {\sf p}(i) + d_{\sf safe})$
hence it is local. 
\item The extension ${\cal T}_0 \cup {\cal K}_{\sf s} \subseteq 
 {\cal T}_0 \cup {\cal K}_{\sf s} \cup {\cal K}_{\sf pp}$ is an
 extension with a function ${\sf pp}$ axiomatized with boundedness axioms, 
and is therefore local.
\item The extension  ${\cal T}_0 \cup {\cal K}_{\sf s} \cup {\cal K}_{\sf pp}
 \subseteq {\cal T}_0 \cup {\cal K}_{\sf s} \cup {\cal K}_{\sf
   pp} \cup ({\cal K}_{\sf pfp} \cup {\cal K}_{\sf inv})$ is an
 extension with a function ${\sf pfp}$ axiomatized using boundedness axioms,
 and is therefore local.
\end{itemize}

