               (FORALL i, j). front(i)=j --> pos(j)-pos(i) >= dsafe; 
               Query := % Lane change for system i_0
               j0 = front(i0); 
               k0 = sidefront(i0); 
               pos(k0) - pos(i0) > dchange; 
               front1(i0) = sidefront(i0); 
               sidefront1(i0) = front(i0);
               % Negation of the safety property
               p0 = front1(i0);
               pos(p0) - pos(i0) < dsafe;
\end{lstlisting}
