\subsection{Virtual address abstraction and anti-abstraction}

We consider a simple case when the virtual address abstraction ought to hold:
under some conditions, the model with translation and the original model without
translations coincide. Here, we only consider the consistency of the
pre-executions, but not how these pre-executions arise.

\subsubsection{Abstraction}

\begin{definition}[VA abstraction subcondition]
  \verb!G! satisfies the \emph{VA abstraction subcondition} when it has no
  page-table-affecting instructions: no TLBI, no context-changing operations
  (for example via writing to registers, for example via MSR TTBR), etc.
\end{definition}

\begin{definition}[VA abstraction condition]
  \verb!Gtr! satisfies the \emph{VA abstraction condition} when it satisfies the
  VA abstraction subcondition, and has a static injective page table.
\end{definition}



\begin{theorem}[VA abstraction]
\label{thm:vaabstraction}
  For all
  (\verb!Gtr : concrete execution!) \\
  if \verb!Gtr! is consistent wrt. the model with translation \\
  and respects the VA abstraction condition, then \\
  let \verb!Gabs! = erase \verb!Gtr! in \\
  \verb!Gabs! is consistent wrt. the model without translation.
\end{theorem}
\begin{proof}
  First, the builtin \verb!addr! of the abstract model is assumed to coincide with
  the derived \verb!addr! of the concrete model by the erasure. Showing that the two
  definitions of pre-executions do relate in this way is outside of our scope.
  Given that the definitions \verb!addr! coincide, the definitions of all the other
  derived relations of the abstract model, including \verb!ob! in the translation
  model, are syntactically supersets of their definition in the concrete model,
  so a cycle in \verb!ob! in the abstract model is also a cycle in \verb!ob! in the
  concrete model.
\end{proof}


\subsubsection{Anti-abstraction}

For this direction, we need to be able to put the translation table somewhere.

\paragraph{Step 1: Building the candidate execution in the translation model}

\begin{definition}[translation extension condition]
  The \emph{translation extension condition} is the data of \\
  (\verb!Gabs : execution!) \\
  such that \verb!Gabs! is consistent wrt. the model without translation \\
  and has no TLBI, and no MSR TTBR \\
  and \\
  (\verb!va_space : va_address -> bool!) \\
  such that all the memory accesses of \verb!Gabs! are in \verb!va_space! \\
  and \\
  (\verb!pt_pa_space : pa_address -> bool!) \\
  (\verb!pt_initial_state : pa_address -> option (list byte)!), \\
  such that the domains of \verb!pt_pa_space! and \verb!pt_initial_state! coincide \\
  and \\
  (\verb!tr_ctxt : translation_context!), \\
  such that \verb!id_map_lifted va_space! and \verb!pt_pa_space! are disjoint address spaces \\
  and \\
  (\verb!translate : translation_function!), \\
  such that translating \verb!abstract_va_space! translate-reads from within \verb!pt_pa_space! and gives the injective map.
\end{definition}



\begin{definition}[translation extension]
  Given the translation extension condition, the \emph{translation extension} \verb!Gtr! of
  \verb!Gabs! is constructed by:
  \begin{itemize}
  \item adding all the initial writes for the page tables,
  \item adding all the translate reads obtained by running the \verb!translate! function
    with the \verb!tr_ctxt!,
  \item adding the translate reads in \verb!iio! between the fetch and the explicit event,
  \item adding \verb!tdata! to match \verb!addr!,
  \item adding \verb!trf! from the corresponding initial writes to the translates.
  \end{itemize}
\end{definition}

\begin{definition}[VA anti abstraction condition]
  \verb!Gtr! satisfies the \emph{VA anti-abstraction condition} when it is derived from a
  consistent execution which satisfies the VA abstraction subcondition by the
  translation extension.
\end{definition}




\begin{lemma}[VA abstraction condition for translation extension]
  If \verb!Gtr! satisfies the \emph{VA anti-abstraction condition}, then \verb!Gtr! satisfies the
  VA abstraction condition.
\end{lemma}
\begin{proof}
  The translation extension does not add any extra instructions, and sets up
  static injective page tables.
\end{proof}



\begin{lemma}[obtlbi-empty]
  If \verb!Gtr! satisfies the VA anti-abstraction condition, then \verb!obtlbi! is empty.
\end{lemma}
\begin{proof}
  \verb!obtlbi! has
  \begin{itemize}
  \item \verb!obtlbi_translate!
    which has
    \begin{itemize}
    \item \verb!tcache1! \\
      which is
      \verb![T & Stage1] ; tfr ; tseq1!
      \\
      the latter is
      \\
      \verb![W] ; (maybe_TLB_barriered_by_va & ob) ; [TLBI VA]!
      \\
      which requires a TLBI, so it is empty
    \item \verb!tcache2 & ...! \\
      which requires a TLBI, so it is empty
    \item \verb!(tcache2 ; ...) & ...! \\
      which requires a TLBI, so it is empty
   \end{itemize}
  \item \verb![M] ; iio^-1 ; obtlbi_translate!
  \\
    to which the same reasoning applies
    \end{itemize}
\end{proof}



\paragraph{Step 2: Consistency}

\begin{lemma}
  If \verb!Gtr! satisfies the VA anti-abstraction condition, then
  translation-internal is acylic.
\end{lemma}
\begin{proof}
  \verb!po-pa; [W]; trf! is empty
  \\
  because by the VA anti-abstraction condition there are no non-initial writes to page tables.
\end{proof}

So we only need to show \verb!external! is acyclic.

\begin{lemma}[ob-to-T]
  If \verb!G! satisfies the VA anti-abstraction condition, then, for all $n \geq 1$,
\begin{verbatim}
  imm(ob)^n ; [T] ==
    iio
    | imm(ob)^(n-1) ; trfe
    | imm(ob)^(n-1) ; [T] ; iio ; [T]
    | imm(ob)^(n-1) ; [CSE] ; instruction-order
    | imm(ob)^(n-1) ; po ; [ERET] ; instruction-order ; [T]
\end{verbatim}
\end{lemma}
\begin{proof}
\begin{itemize}
\item  The \verb!addr! clause
  \\
  \verb!| tdata ; [T_f]!
  \\
  is empty because there are no translation failures.

\item  \verb!tob! does not contribute: there are no faults, and no non-initial writes to
  page table entries.

\item  The first clause of \verb!ctxob! is empty because there are no \verb!MSR TTBR!.
  The third and fourth are also empty, because they do not end in a \verb![T]!.

\item  Given a static injective mapping, the new \verb!| (addr | data | ctrl) ; trfi!
  clause of \verb!dob! is empty.
\end{itemize}
\end{proof}



\begin{lemma}[no-cycle-ob-to-init]
  If \verb!Gtr! is well-formed and consistent (in either model),
  then there is cycle in \verb!ob! via the initial writes.
\end{lemma}
\begin{proof}
  By well-formedness, \verb!wco ; [INIT] = [INIT] ; wco ; [INIT]!, and \verb!wco! is acyclic.
\\
  By examination of the other edges.
\end{proof}

\begin{lemma}[ob-from-T]
  If \verb!Gtr! satisfies the VA anti-abstraction condition, then
\begin{verbatim}
[T] ; imm(ob) ==
  iio
  | [T] ; iio ; [M] ; po ; [W]
\end{verbatim}
\end{lemma}
\begin{proof}
  By examination of the edges.
\end{proof}

\begin{lemma}[instruction-order-compress]{\ }\\
  \verb!instruction-order ; [T] ; iio ; [M] ; po! $\subseteq$ \verb!instruction-order!
\end{lemma}
\begin{proof}
  If we unfold the definitions of \verb!instruction-order! and \verb!po!, we have
  \\
  \verb!iio^-1 ; fpo ; iio ; [T] ; iio ; [M] ; [M|F|C] ; iio^-1 ; fpo ; iio ; [M|F|C]!
  \\
  which we can simplify into
  \\
  \verb!iio^-1 ; fpo ; fpo ; iio ; [M|F|C]!
  \\
  which means we have
  \\
  \verb!instruction-order!.
\end{proof}

\begin{lemma}[instruction-order-compress-iio]
  \verb!instruction-order ; iio ; po! $\subseteq$ \verb!instruction-order!
\end{lemma}
\begin{proof}
  \verb!iio! is transitive, and is the RHS of \verb!instruction-order!.
\end{proof}



\begin{lemma}[ob-acyclic-preserved]
  If \verb!G! satisfies the VA anti-abstraction condition,
  if there is a cycle in translate-\verb!ob!,
  then there is a cycle in plain-\verb!ob!.
\end{lemma}
\begin{proof}

  Consider a minimal cycle in translate-\verb!imm(ob)! (that is, the transitive
  closure of the \verb!ob! of the model with translation). Let $n$ be its length.
  \\
  We show that there is a cycle in plain-\verb!ob!.
  \\
  Assume, for contradiction, that the cycle contains an edge that is not in
  plain-\verb!ob! (that is, the \verb!ob! of the model without translation):
  \begin{itemize}

  \item iio
  \\
    by case split:
    \begin{itemize}

\item    \verb![T] ; iio; [M]!:
      by Lemma ob-to-T, the \verb!ob! edge to the left has to be either
      \begin{itemize}
      \item \verb!iio!
        in which case, by transitivity of \verb!iio!, there is a shorter cycle, so we
        have a contradiction.
        \\
        Let us call this Case IIOtrans.
      \item \verb!trfe!, which is from an initial write by the VA abstraction condition,
      \\
        but by Lemma no-cycle-ob-to-init, the cycle cannot exist.
      \item \verb!imm(ob)^(n-2); [T]; iio; [T]; iio; [M]!
      \\
        then we have
        \verb!imm(ob)^(n-2); [T]; iio; [M]!, which involves one fewer translate,
        \\
        so we have a contradiction.
      \item \verb!imm(ob)^(n-2) ; [CSE] ; instruction-order!
      \\
        This is similar to IIOtrans.
      \item \verb!imm(ob)^(n-2) ; po ; [ERET] ; instruction-order ; [T]!
      \\
        This is similar to IIOtrans.
      \end{itemize}

\item    \verb![T] ; iio ; [T]!:
\\
      So the whole cycle looks like
      \verb!imm(ob)^(n-1) ; [T] ; iio ; [T]!

      By Lemma ob-to-T, we have either
      \begin{itemize}
      \item \verb!imm(ob)^(n-2) ; iio ; [T] ; iio ; [T]!
      \\
        See Case IIOtrans.
      \item \verb!imm(ob)^(n-2) ; trfe!
      \\
        the \verb!trfe! is from an initial write by the VA abstraction condition,
        \\
        and by Lemma no-cycle-ob-to-init, the cycle cannot exist.
      \item \verb!imm(ob)^(n-2); [T]; iio; [T]!
      \\
        but we already have \verb!iio! to the second T,
        \\
        so we have a cycle involving one fewer translate,
        \\
        so we have a contradiction.
      \item \verb!imm(ob)^(n-2) ; [CSE] ; instruction-order!
      \\
        This is similar to IIOtrans.
      \item \verb!imm(ob)^(n-2) ; po ; [ERET] ; instruction-order ; [T]!
      \\
        This is similar to IIOtrans.
      \end{itemize}
\end{itemize}

\item \verb!tob! has
     \begin{itemize}
    \item \verb![T_f] ; tfr!
    \\
      which has a fault, so we have a contradiction.

    \item \verb!([T_f] ; tfri) & (po ; [dsb.sy] ; instruction-order)^-1!
    \\
      which has a fault, so we have a contradiction.

    \item \verb!speculative ; trfi!
      which is empty, because of the static page table.
   \end{itemize}

\item \verb!obtlbi!, which is empty by Lemma obtlbi-empty.

\item \verb!ctxob! has
  \begin{itemize}
  \item \verb!speculative ; [MSR TTBR]!
  \\
      by the VA abstraction condition, there is no MSR TTBR
    \item \verb![CSE] ; instruction-order!
      \\
      So the whole cycle looks like
      \\
      \verb![CSE] ; instruction-order ; imm(ob)^(n-1)!
      \\
      Because \verb!instruction-order! is acyclic, $n \geq 1$, so we have
      \\
      \verb![CSE] ; instruction-order ; imm(ob) ; imm(ob)^(n-2)!
      \\
      By Lemma ob-from-T, we have either:
      \begin{itemize}
      \item \verb![CSE] ; instruction-order ; iio ; imm(ob)^(n-2)!
      \\
        which means that by Lemma instruction-order-compress, we have
        \\
        \verb![CSE] ; instruction-order ; imm(ob)^(n-2)!
        \\
        so we have a cycle involving one edge fewer, so we have a contradiction.
      \item \verb![CSE] ; instruction-order ; [T] ; iio ; [M] ; po ; [W] ; imm(ob)^(n-2)!
      \\
        which means that by Lemma instruction-order-compress, we have
        \\
        \verb![CSE] ; instruction-order ; imm(ob)^(n-2)!
        \\
        so we have a cycle involving one edge fewer, so we have a contradiction.
       \end{itemize}

     \item \verb![ContextChange] ; po ; [CSE]!
     \\
      by the VA abstraction condition, there is no \verb!ContextChange!.

    \item \verb!speculative ; [CSE]!
    \\
      The \verb!CSE! has to be an \verb!ISB!, because there are no exceptions,
      and the \verb!speculative! is either
      in \verb!dob! in the plain model, so we have a contradiction,
      or in \verb![T]; instruction-order!.
      \\
      So the whole cycle looks like
      \verb!imm(ob)^(n-1) ; [T] ; iio ; [M] ; po ; [ISB]!

      Because \verb!po | iio! is acyclic, $n-1$ has to be $\geq 1$, so by Lemma ob-to-T, we have either
      \begin{itemize}
      \item \verb!imm(ob)^(n-2); iio; [T]; iio; [M]; po; [ISB]!
      \\
        See Case IIOtrans.
      \item \verb!trfe!, which is from an initial write by the VA abstraction condition,
      \\
        but by Lemma no-cycle-ob-to-init, the cycle cannot exist
      \item \verb!imm(ob)^(n-2); [T]; iio; [T]; iio; [M]; po; [ISB]!
      \\
        but we already have \verb!iio! to the second T,
        \\
        so we have a cycle involving one fewer translate,
        \\
        so we have a contradiction.
      \item \verb!imm(ob)^(n-2); [CSE] ; instruction-order ; [T] ; iio ; [M] ; po ; [ISB]!
      \\
        which means that by Lemma instruction-order-compress, we have
        \\
        \verb!imm(ob)^(n-2); [CSE] ; instruction-order!
        \\
        so we have a cycle involving one edge fewer,
        \\
        so we have a contradiction.
      \item \verb!imm(ob)^(n-2) ; po ; [ERET] ; instruction-order ; [T] ; iio ; [M] ; po ; [ISB]!
      \\
        is similar
      \end{itemize}

  \item \verb!po ; [ERET] ; instruction-order ; [T]!
  \\
      So the whole cycle looks like
      \\
      \verb!po ; [ERET] ; instruction-order ; [T] ; imm(ob)^(n-1)!
      \\
      Because instruction-order is acyclic, $n \geq 1$, so we have
      \\
      \verb!po ; [ERET] ; instruction-order ; [T] ; imm(ob) ; imm(ob)^(n-2)!
      \\
      By Lemma ob-from-T, we have either:
      \begin{itemize}
      \item \verb!po ; [ERET] ; instruction-order ; [T] ; iio ; imm(ob)^(n-2)!
      \\
        which means that by Lemma instruction-order-compress-iio, we have
        \\
        \verb!po ; [ERET] ; instruction-order ; imm(ob)^(n-2)!
        \\
        so we have a cycle involving one edge fewer, so we have a contradiction.
      \item \verb!po ; [ERET] ; instruction-order ; [T] ; ([T] ; iio ; [M]; po ;! \verb! [W]) ; imm(ob)^(n-2)!
      \\
        which means that by Lemma instruction-order-compress, we have
        \\
        \verb!po ; [ERET] ; instruction-order ; imm(ob)^(n-2)!
        \\
        so we have a cycle involving one edge fewer, so we have a contradiction.
      \end{itemize}

    \end{itemize}
  \item extended \verb!dob!:
    \begin{itemize}
    \item involving \verb!trfi! from non-initial writes,
    which contradicts our assumption about static translation.
    \item or \verb![T] ; instruction-order ; [W]!,
    \\
    so \verb![T] ; iio ; [M] ; po ; [W]!
\\
      So the whole cycle looks like
      \verb!imm(ob)^(n-1) ; [T] ; iio ; [M] ; po ; [W]!

      Because \verb!po | iio! is acyclic, $n-1$ has to be $\geq 1$, so by Lemma ob-to-T, we have either
      \begin{itemize}
      \item \verb!imm(ob)^(n-2); iio; [T]; iio; [M]; po; [W]!
      \\
        See Case IIOtrans.
      \item \verb!trfe!, which is from an initial write by the VA abstraction condition,
      \\
        but by Lemma no-cycle-ob-to-init, the cycle cannot exist
      \item \verb!imm(ob)^(n-2); [T]; iio; [T]; iio; [M]; po; [W]!
      \\
        but we already have \verb!iio! to the second T,
        \\
        so we have a cycle involving one fewer translate,
        \\
        so we have a contradiction.
      \item \verb!imm(ob)^(n-2); [CSE] ; instruction-order ; [T] ; iio ; [M] ; po ; [W]!
      \\
        which means that by Lemma instruction-order-compress, we have
        \\
        \verb!imm(ob)^(n-2); [CSE] ; instruction-order!
        \\
        so we have a cycle involving one edge fewer,
        \\
        so we have a contradiction.
      \item \verb!imm(ob)^(n-2) ; po ; [ERET] ; instruction-order ; [T] ; iio ; [M] ; po ; [W]!
      \\
        is similar
      \end{itemize}
      \end{itemize}

  \item extended \verb!bob!, but only involving TLBI,
    which contradicts our assumption of no TLBI.

 \item extended \verb!obs!, but only involving \verb!trfe!,
    by the VA abstraction condition, the only writes to page tables are from
    initial writes, and by Lemma no-cycle-ob-to-init, there are no \verb!ob! cycles via
    initial writes, so there is no cycle.
  \item \verb!obfault!, which involves a fault, which contradicts our assumptions.
  \item \verb!obets!, which involves a fault or a TLBI, which contradicts our assumptions.
  \end{itemize}

  All the other edges are in plain-\verb!ob! by definition.
\end{proof}




\begin{theorem}[VA anti-abstraction]
\label{thm:vaantiabstraction}
  If the translation extension condition holds,
  then there exists a \verb!Gtr! that satisfies the VA anti-abstraction condition such that
  \verb!Gtr! is a stitching of \verb!Gabs! with the \verb!pt_initial_state! according to \verb!translate! in \verb!tr_ctxt! and
  \verb!Gtr! is consistent wrt. the model with translation.
\end{theorem}
\begin{proof}
  \verb!Gtr! exists by the translation extension construction,
  \\
  and it is consistent by Lemma ob-acyclic-preserved.
\end{proof}

