    \begin{equation}
        \begin{aligned}
            \min_{q, \gamma}&\ B \cdot \left( {\textstyle \max_{j \in M} \sum_{i\in N} e^{q_{ij}}} \right) + \sum_{i\in N} B_i \gamma_i \\
            \text{s.t. } & \log v_{ij} \leq q_{ij} + \gamma_i, \forall i\in N, j\in M
        \end{aligned}
        \label[program]{eq:dual EG max rewrite}
    \end{equation}

    Next we derive the dual of \eqref{eq:dual EG max rewrite}, again using the Fenchel dual from \cref{thm:fenchel dual}. 
    For $j \in M$, let $g_j(q) = \sum_{i\in N} e^{q_{ij}}$ and let $g(q) = B \cdot \max_{j\in M} g_j(q)$. Write $b_{ij}$ for the dual variables for the constraints in \cref{eq:dual EG max rewrite}. Then the dual of \eqref{eq:dual EG max rewrite} is
    \begin{equation}
        \begin{aligned}
            \max_{b \ge 0} &\ \sum_{ij} b_{ij} \log v_{ij} - g^*(b) \\
            \text{s.t. } & \sum_{j \in M} b_{ij} = B_i,\ \forall i\in N
        \end{aligned}
        \label[program]{eq:dual with conjugate}
    \end{equation}
    %
