        E[T]\leq &\left(1-\frac{1}{m'}\right)^{-1} \left(2+\frac{\ln(4)m'}{\ln(m')}\right)\frac{\ln(m')k\tau}{2}\\
        &\cdot\left(\frac{e^2 n}{k\left(1-\exp{\left(-\frac{\tau}{\mu}\right)}\right)}\right)^k.
    \end{align*}
    \label{lem:many second phase}
\end{lemma}
